#!/usr/bin/env bash
# Generated by build_installer.sh; edit src/install_mc_bundle.sh.in and lib/ instead.
# Self-contained MC target installer. Requires Bash, SQLcl, and standard archive/hash utilities.
set -euo pipefail
set +x
umask 077
# Never inherit/export application account inputs retained until access creation.
unset initial_app_secret_hex initial_app_email_hex initial_database_secret_hex MC_INITIAL_REPLACE_HASH

usage() {
  echo "INITIAL recovery: $0 --mode CLEANUP --admin-connection NAME --journal-directory PATH (no bundle required)"
  echo "Uninstall preview: $0 --mode UNINSTALL --admin-connection NAME --schema OWNER --workspace NAME --target-app-id ID --dry-run"
  echo "UNINSTALL needs no original journal or hostname. Optional --journal-directory retains progress only; --target-connection-name selects one saved connection; otherwise verified target-schema connections are discovered and removed."
  echo "Uninstall apply: replace --dry-run with --confirm-drop-schema OWNER --acknowledge-data-loss (permanently deletes target data)"
  echo "INITIAL requires --journal-directory NEW_ABSOLUTE_PRIVATE_PATH for real runs."
  echo "INITIAL prompts for the application administrator's password and email address during preparation."
  echo "INITIAL: --database-mode NEW|EXISTING (prompted if omitted; NEW authorizes prerequisite configuration, EXISTING requires separate approval)."
  echo "New workspaces: --workspace-admin USERNAME (prompted if omitted), separate from --first-admin. Builder authentication is detected; external identity passwords are never requested."
  echo "Usage: $0 --bundle FILE --mode INITIAL|UPDATE [--interactive] [--apply-missing-grants --admin-connection NAME] [INITIAL: --admin-connection NAME --target-connection-name NAME --schema OWNER --workspace NAME --workspace-mode CREATE|EXISTING --first-admin USERNAME [--target-app-id ID] --apex-offset AUTO|NUMBER [--default-tablespace NAME] [--temporary-tablespace NAME] --confirm-create-schema OWNER [--environment-prerequisites SQL_FILE]] [UPDATE: --connection TARGET_SQLCL_SAVED_CONNECTION] [--dry-run]"
}

fail() {
  echo "ERROR: $*" >&2
  exit 1
}

ask() {
  local variable="$1" prompt="$2" default_value="$3" value
  [[ "${MC_INITIAL_INPUTS_COMPLETE:-N}" != Y ]] || fail "Installation inputs are closed; rerun preparation to resolve: $prompt"
  if [[ -t 0 ]]; then
    read -r -p "$prompt${default_value:+ [$default_value]}: " value </dev/tty
  else
    read -r -p "$prompt${default_value:+ [$default_value]}: " value
  fi
  printf -v "$variable" '%s' "${value:-$default_value}"
}

initial_database_choice() {
  if [[ -z "$database_mode" && "$dry" != Y ]]; then
    echo 'Is this a new database or an existing/shared database?'
    echo 'NEW authorizes automatic configuration of database prerequisites, including resource-principal initialization. We trust your choice; these changes can affect other schemas. EXISTING keeps shared-database protections and asks before changing missing settings.'
    ask database_mode 'Database (NEW or EXISTING)' EXISTING || return 1
  fi
  database_mode="$(printf '%s' "${database_mode:-EXISTING}" | tr '[:lower:]' '[:upper:]')"
  [[ "$database_mode" == NEW || "$database_mode" == EXISTING ]] || { echo 'ERROR: database mode must be NEW or EXISTING.' >&2; return 1; }
}

connection=""; bundle=""; mode=""; workspace=""; workspace_mode=""
journal_directory=""
target_id=""; apex_offset=""; apex_offset_supplied="N"; admin_connection=""; target_connection=""
schema=""; prerequisites=""; confirm=""; data_ts="DATA"; temp_ts="TEMP"; first_admin=""
workspace_admin=""
database_mode=""
confirm_drop_schema=""; acknowledge_data_loss=N
interactive="N"; dry="N"; apply_missing_grants="N"
while (($#)); do
  case "$1" in
    --connection|--journal-directory|--bundle|--mode|--workspace|--workspace-mode|--database-mode|\
    --target-app-id|--apex-offset|--admin-connection|--target-connection-name|--schema|\
    --first-admin|--workspace-admin|--default-tablespace|--temporary-tablespace|\
    --environment-prerequisites|--confirm-create-schema|--confirm-drop-schema)
      (($#>=2)) && [[ -n "$2" && "$2" != --* && "$2" != -h ]] || fail "$1 requires a value" ;;
  esac
  case "$1" in
    --connection) connection="$2"; shift 2 ;;
    --journal-directory) journal_directory="$2"; shift 2 ;;
    --bundle) bundle="$2"; shift 2 ;;
    --mode) mode="$2"; shift 2 ;;
    --workspace) workspace="$2"; shift 2 ;;
    --workspace-mode) workspace_mode="$2"; shift 2 ;;
    --database-mode) database_mode="$2"; shift 2 ;;
    --target-app-id) target_id="$2"; shift 2 ;;
    --apex-offset) apex_offset="$2"; apex_offset_supplied="Y"; shift 2 ;;
    --admin-connection) admin_connection="$2"; shift 2 ;;
    --target-connection-name) target_connection="$2"; shift 2 ;;
    --schema) schema="$2"; shift 2 ;;
    --first-admin) first_admin="$2"; shift 2 ;;
    --workspace-admin) workspace_admin="$2"; shift 2 ;;
    --default-tablespace) data_ts="$2"; shift 2 ;;
    --temporary-tablespace) temp_ts="$2"; shift 2 ;;
    --environment-prerequisites) prerequisites="$2"; shift 2 ;;
    --confirm-create-schema) confirm="$2"; shift 2 ;;
    --confirm-drop-schema) confirm_drop_schema="$2"; shift 2 ;;
    --acknowledge-data-loss) acknowledge_data_loss=Y; shift ;;
    --interactive) interactive="Y"; shift ;;
    --apply-missing-grants) apply_missing_grants="Y"; shift ;;
    --dry-run) dry="Y"; shift ;;
    -h|--help) usage; exit 0 ;;
    *) usage; exit 2 ;;
  esac
done
[[ -z "$workspace_admin" || "$(printf '%s' "$mode" | tr '[:lower:]' '[:upper:]')" == INITIAL || "$interactive" == Y ]] || fail '--workspace-admin is INITIAL-only'

if [[ "$interactive" == Y ]]; then
  [[ -n "$mode" ]] || ask mode 'Mode (INITIAL or UPDATE)' INITIAL
  mode="$(printf '%s' "$mode" | tr '[:lower:]' '[:upper:]')"
  if [[ "$mode" == INITIAL ]]; then initial_database_choice || fail 'Database selection was not completed'; fi
  [[ -n "$bundle" ]] || ask bundle 'Bundle file' ''
  if [[ "$mode" == INITIAL ]]; then
    [[ -n "$admin_connection" ]] || ask admin_connection 'ADB ADMIN SQLcl saved connection' ''
    [[ -n "$schema" ]] || ask schema 'New target schema' ''
    [[ -n "$target_connection" ]] || ask target_connection 'New SQLcl target connection name' "MC_$schema"
    [[ -n "$workspace_mode" ]] || ask workspace_mode 'Workspace mode (CREATE or EXISTING)' CREATE
    [[ -n "$workspace" ]] || ask workspace 'Workspace name' ''
    [[ -n "$first_admin" ]] || ask first_admin 'First local APEX administrator username (new account)' ''
    [[ -n "$target_id" ]] || ask target_id 'Target application ID (blank inherits bundle source)' ''
    if [[ "$apex_offset_supplied" == N ]]; then
      ask apex_offset 'APEX offset (AUTO or non-negative number)' AUTO
      apex_offset_supplied="Y"
    fi
    [[ -n "$prerequisites" ]] || ask prerequisites 'Optional prerequisite SQL file (blank skips)' ''
    [[ -n "$confirm" ]] || ask confirm "Type schema name $schema to confirm creation" ''
    [[ -n "$journal_directory" || "$dry" == Y ]] || ask journal_directory 'New persistent INITIAL journal directory (absolute path)' ''
  else
    [[ -n "$connection" ]] || ask connection 'Target SQLcl saved connection' ''
  fi
fi
mode="$(printf '%s' "$mode" | tr '[:lower:]' '[:upper:]')"
workspace_mode="$(printf '%s' "$workspace_mode" | tr '[:lower:]' '[:upper:]')"
[[ -z "$database_mode" || "$mode" == INITIAL ]] || fail '--database-mode is INITIAL-only'
database_mode="$(printf '%s' "$database_mode" | tr '[:lower:]' '[:upper:]')"
[[ -z "$database_mode" || "$database_mode" =~ ^(NEW|EXISTING)$ ]] || fail '--database-mode must be NEW or EXISTING'
[[ "$mode" == UNINSTALL || ( -z "$confirm_drop_schema" && "$acknowledge_data_loss" == N ) ]] || fail 'Uninstall confirmation options require --mode UNINSTALL'
[[ -z "$workspace_admin" || ( "$mode" == INITIAL && "$workspace_mode" == CREATE ) ]] || fail '--workspace-admin requires INITIAL with --workspace-mode CREATE; existing workspace accounts are preserved'

[[ ( -f "$bundle" && "$mode" =~ ^(INITIAL|UPDATE)$ ) || "$mode" == CLEANUP || "$mode" == UNINSTALL ]] || { usage; exit 2; }
command -v sql >/dev/null 2>&1 || fail "SQLcl executable 'sql' is required"

tmp="$(mktemp -d "${TMPDIR:-/tmp}/mc-bundle.XXXXXX")"
# macOS /var and /tmp are system aliases; use the physical private directory.
tmp="$(cd "$tmp" && pwd -P)"
cleanup() {
  local exit_status=$?
  unset initial_app_secret_hex initial_app_email_hex initial_database_secret_hex
  trap - EXIT HUP INT TERM
  if [[ "$exit_status" -ne 0 && "${mode:-}" != UNINSTALL ]] && declare -F initial_finish_failure >/dev/null; then
    initial_finish_failure || true
  fi
  if declare -F runtime_work_close >/dev/null; then runtime_work_close; fi
  if declare -F initial_lock_close >/dev/null; then initial_lock_close; fi
  if [[ -n "${log:-}" && -f "$log" ]]; then
    echo "Diagnostic log: $log"
  fi
  if [[ -n "${tmp:-}" && -d "$tmp" ]]; then
    rm -rf -- "$tmp"
  fi
  exit "$exit_status"
}
trap cleanup EXIT
trap 'exit 129' HUP
trap 'exit 130' INT
trap 'exit 143' TERM

