mc_bundle_archive() {
  local archive="$1" work="$2" mode="$3" destination="$4" member="${5:-}" cap="${6:-0}"
  local java_bin='' candidate cache="$work/archive-reader" sql_path sql_home link hops=0
  sql_path="$(command -v sql || true)"
  while [[ -n "$sql_path" && -L "$sql_path" && "$hops" -lt 20 ]]; do
    link="$(readlink "$sql_path")" || return 1
    case "$link" in /*) sql_path="$link" ;; *) sql_path="${sql_path%/*}/$link" ;; esac
    hops=$((hops + 1))
  done
  sql_home=''
  [[ -z "$sql_path" ]] || sql_home="$(cd "${sql_path%/*}/.." 2>/dev/null && pwd -P)"
  # Match SQLcl's bundled-JDK preference, then its environment/runtime locations.
  for candidate in "${sql_home:-/nonexistent}"/jdk*/bin/java{,.exe} \
      "${sql_home:-/nonexistent}"/jdk*/Contents/Home/bin/java \
      "${JAVA_HOME:-/nonexistent}"/bin/java{,.exe} \
      "${ORACLE_HOME:-/nonexistent}"/jdk/bin/java{,.exe} \
      "${sql_home:-/nonexistent}"/../jdk/jre/bin/java{,.exe}; do
    if [[ -x "$candidate" ]]; then java_bin="$candidate"; break; fi
  done
  [[ -n "$java_bin" ]] || java_bin="$(command -v java || true)"
  [[ -n "$java_bin" ]] || { echo 'ERROR: ZIP reading requires the Java 17+ runtime used by SQLcl (bundled JDK, JAVA_HOME or PATH).' >&2; return 1; }
  if [[ ! -f "$cache/archive-reader.jar" ]]; then
    mkdir -p "$cache" || return 1
    mc_bundle_archive_payload | base64 -d > "$cache/archive-reader.jar" || {
      rm -f "$cache/archive-reader.jar"
      echo 'ERROR: Unable to prepare the bundled ZIP reader.' >&2; return 1;
    }
  fi
  "$java_bin" -Xmx64m -cp "$cache/archive-reader.jar" McBundleArchive "$mode" "$archive" "$destination" "$member" \
    "${MC_BUNDLE_MAX_ARCHIVE_BYTES:-268435456}" "${MC_BUNDLE_MAX_MEMBER_BYTES:-134217728}" \
    "${MC_BUNDLE_MAX_EXPANDED_BYTES:-1073741824}" "${MC_BUNDLE_MAX_ENTRIES:-20000}" "$cap"
}

mc_bundle_validation_error() {
  echo "ERROR: $*" >&2
  return 1
}

mc_bundle_sha256_file() {
  local file="$1" digest
  case "${MC_BUNDLE_HASH_TOOL:-}" in
    sha256sum) digest="$(sha256sum "$file" | awk '{print $1}')" ;;
    shasum) digest="$(shasum -a 256 "$file" | awk '{print $1}')" ;;
    openssl) digest="$(openssl dgst -sha256 "$file" | awk '{print $NF}')" ;;
    cksum) digest="$(cksum -a sha256 "$file" | awk '{print $1}')" ;;
    *) mc_bundle_validation_error "bundle SHA-256 tool was not initialized"; return 1 ;;
  esac
  printf '%s\n' "$digest" | tr '[:upper:]' '[:lower:]'
}

mc_bundle_safe_member_path() {
  local name="$1" component remainder
  [[ -n "$name" && "$name" != /* && "$name" != *\\* && "$name" != */ && "$name" =~ ^[A-Za-z0-9._/-]+$ ]] || return 1
  remainder="$name"
  while [[ "$remainder" == */* ]]; do
    component="${remainder%%/*}"
    [[ -n "$component" && "$component" != . && "$component" != .. ]] || return 1
    remainder="${remainder#*/}"
  done
  [[ -n "$remainder" && "$remainder" != . && "$remainder" != .. ]]
}

mc_bundle_validate() {
  local input_bundle="$1" work="$2" members normalized_members member
  local property_count key value extra checksum_paths checksum_line expected_hash checksum_path actual_hash
  local expected_checksum_paths required
  local -a required_files

  [[ -f "$input_bundle" ]] || { mc_bundle_validation_error "bundle file not found: $input_bundle"; return 1; }
  [[ -d "$work" ]] || { mc_bundle_validation_error "validation work directory not found: $work"; return 1; }

  if command -v sha256sum >/dev/null 2>&1; then
    MC_BUNDLE_HASH_TOOL="sha256sum"
  elif command -v shasum >/dev/null 2>&1; then
    MC_BUNDLE_HASH_TOOL="shasum"
  elif command -v openssl >/dev/null 2>&1; then
    MC_BUNDLE_HASH_TOOL="openssl"
  elif command -v cksum >/dev/null 2>&1 && cksum -a sha256 /dev/null >/dev/null 2>&1; then
    MC_BUNDLE_HASH_TOOL="cksum"
  else
    mc_bundle_validation_error "a SHA-256 utility is required (sha256sum, shasum, openssl, or cksum -a sha256)"; return 1
  fi

  MC_BUNDLE_INPUT_ABS="$(cd "$(dirname "$input_bundle")" && pwd -P)/$(basename "$input_bundle")"
  members="$work/members.txt"
  mc_bundle_archive "$MC_BUNDLE_INPUT_ABS" "$work" list - > "$members" || return 1

  normalized_members="$work/members-normalized.txt"
  : > "$normalized_members"
  while IFS= read -r member || [[ -n "$member" ]]; do
    member="${member%$'\r'}"
    mc_bundle_safe_member_path "$member" || { mc_bundle_validation_error "unsafe bundle member path: $member"; return 1; }
    case "$member" in
      db/deploy/groups/*|db/deploy/delta/*|db/bootstrap/product/*|\
      db/ddl/01_tables.sql|db/ddl/01a_table_alters.sql|db/ddl/02_sequences.sql|\
      db/ddl/03_keys_indexes.sql|db/ddl/03a_views.sql|db/ddl/04_pkg_specs.sql|\
      db/ddl/06_pkg_bodies.sql|db/ddl/07_procs_funcs.sql|db/ddl/08_mviews.sql|\
      db/ddl/08a_property_graphs.sql|db/ddl/09_triggers.sql|db/ddl/90_jobs.sql)
        mc_bundle_validation_error "retired grouped or delta object payload: $member"; return 1 ;;
    esac
    printf '%s\n' "$member" >> "$normalized_members"
  done < "$members"
  [[ -s "$normalized_members" ]] || { mc_bundle_validation_error "bundle ZIP is empty"; return 1; }
  if [[ "$(LC_ALL=C sort "$normalized_members" | uniq -d | wc -l | tr -d ' ')" != 0 ]]; then
    mc_bundle_validation_error "bundle contains duplicate ZIP members"; return 1
  fi
  members="$normalized_members"

  required_files=(
    bundle.properties checksums.sha256 manifest.json apex/f1200.sql
    db/deploy/plan.txt db/deploy/artifacts.json db/deploy/product-coverage.json
    db/deploy/product-plan.txt db/deploy/initial-objects.txt db/ddl/00_source_removals.sql
    db/ddl/05_contexts.sql db/ddl/95_app_config.sql db/ddl/96_chatbot_seed.sql
    db/ddl/97_semantic_seed.sql db/migrations/manifest.txt
    db/preflight/required_privileges.txt db/preflight/required_privileges.sql
    db/admin/apply_required_privileges.sql
  )
  for required in "${required_files[@]}"; do
    grep -Fqx "$required" "$members" || { mc_bundle_validation_error "missing MC bundle file: $required"; return 1; }
  done

  MC_BUNDLE_CONTENT_DIR="$work/content"
  mc_bundle_archive "$MC_BUNDLE_INPUT_ABS" "$work" extract "$MC_BUNDLE_CONTENT_DIR" || return 1
  [[ -z "$(find "$MC_BUNDLE_CONTENT_DIR" -type l -print -quit)" ]] || { mc_bundle_validation_error "bundle must not contain symbolic links"; return 1; }
  while IFS= read -r member; do
    [[ -f "$MC_BUNDLE_CONTENT_DIR/$member" ]] || { mc_bundle_validation_error "bundle member is not a regular file: $member"; return 1; }
  done < "$members"

  local nonportable_email
  nonportable_email="$({
    LC_ALL=C grep -EIRho '[[:alnum:]._%+-]+@[[:alnum:].-]+\.[[:alpha:]]{2,}' "$MC_BUNDLE_CONTENT_DIR" 2>/dev/null || true
  } | LC_ALL=C grep -Eiv '@example\.(com|org|net)$' | head -n 1 || true)"
  [[ -z "$nonportable_email" ]] || {
    mc_bundle_validation_error "bundle contains a non-portable email address; rebuild it from a sanitized Source Release"
    return 1
  }
  grep -Fq 'MC_PORTABLE_SEED=1' "$MC_BUNDLE_CONTENT_DIR/db/ddl/96_chatbot_seed.sql" || {
    mc_bundle_validation_error "chatbot seed has no portability marker; rebuild the Source Release"
    return 1
  }
  if LC_ALL=C grep -Eiq 'TO_TIMESTAMP[[:space:]]*\(' "$MC_BUNDLE_CONTENT_DIR/db/ddl/96_chatbot_seed.sql" ||
     LC_ALL=C grep -Eiq "[~]?'[)]?[[:space:]]+(VALUES_JSON|EXTRA_KEYWORDS_JSON|GENERATED_BY|CREATED_BY|UPDATED_BY)" "$MC_BUNDLE_CONTENT_DIR/db/ddl/96_chatbot_seed.sql"
  then
    mc_bundle_validation_error "chatbot seed contains runtime or source-timestamp seed data; rebuild the Source Release"
    return 1
  fi

  MC_BUNDLE_CONTRACT=""; MC_BUNDLE_LAYOUT=""; MC_BUNDLE_SUPPORTED_MODES=""
  MC_BUNDLE_SOURCE_ID=""; MC_BUNDLE_REGISTRY_RUN_ID=""; MC_BUNDLE_ENABLEMENT=""
  property_count=0
  while IFS='=' read -r key value extra || [[ -n "$key${value:-}${extra:-}" ]]; do
    key="${key%$'\r'}"; value="${value%$'\r'}"
    [[ -n "$key" && -z "${extra:-}" ]] || { mc_bundle_validation_error "invalid bundle.properties entry"; return 1; }
    case "$key" in
      MC_BUNDLE_CONTRACT) [[ -z "$MC_BUNDLE_CONTRACT" ]] || { mc_bundle_validation_error "duplicate bundle property: $key"; return 1; }; MC_BUNDLE_CONTRACT="$value" ;;
      MC_LAYOUT) [[ -z "$MC_BUNDLE_LAYOUT" ]] || { mc_bundle_validation_error "duplicate bundle property: $key"; return 1; }; MC_BUNDLE_LAYOUT="$value" ;;
      MC_SUPPORTED_MODES) [[ -z "$MC_BUNDLE_SUPPORTED_MODES" ]] || { mc_bundle_validation_error "duplicate bundle property: $key"; return 1; }; MC_BUNDLE_SUPPORTED_MODES="$value" ;;
      MC_SOURCE_APPLICATION_ID) [[ -z "$MC_BUNDLE_SOURCE_ID" ]] || { mc_bundle_validation_error "duplicate bundle property: $key"; return 1; }; MC_BUNDLE_SOURCE_ID="$value" ;;
      MC_REGISTRY_RUN_ID) [[ -z "$MC_BUNDLE_REGISTRY_RUN_ID" ]] || { mc_bundle_validation_error "duplicate bundle property: $key"; return 1; }; MC_BUNDLE_REGISTRY_RUN_ID="$value" ;;
      MC_ENABLEMENT) [[ -z "$MC_BUNDLE_ENABLEMENT" ]] || { mc_bundle_validation_error "duplicate bundle property: $key"; return 1; }; MC_BUNDLE_ENABLEMENT="$value" ;;
      *) mc_bundle_validation_error "unsupported bundle property: $key"; return 1 ;;
    esac
    property_count=$((property_count + 1))
  done < "$MC_BUNDLE_CONTENT_DIR/bundle.properties"
  [[ "$property_count" -eq 6 ]] || { mc_bundle_validation_error "bundle.properties must contain exactly six properties"; return 1; }
  [[ "$MC_BUNDLE_CONTRACT" == mc-bundle-1.13.0 ]] || {
    mc_bundle_validation_error "unsupported bundle contract: $MC_BUNDLE_CONTRACT; export a current Source Release"; return 1;
  }
  for required in runtime.properties db/runtime/runtime_dependencies.sql; do
    [[ -s "$MC_BUNDLE_CONTENT_DIR/$required" ]] || { mc_bundle_validation_error "missing MC bundle file: $required"; return 1; }
  done
  [[ "$MC_BUNDLE_LAYOUT" == application-bundles-v1 ]] || { mc_bundle_validation_error "unsupported bundle layout: $MC_BUNDLE_LAYOUT"; return 1; }
  [[ "$MC_BUNDLE_SUPPORTED_MODES" == INITIAL,UPDATE ]] || { mc_bundle_validation_error "bundle must support INITIAL and UPDATE"; return 1; }
  [[ "$MC_BUNDLE_SOURCE_ID" =~ ^[1-9][0-9]*$ ]] || { mc_bundle_validation_error "bundle source application must be a positive integer"; return 1; }
  [[ "$MC_BUNDLE_REGISTRY_RUN_ID" =~ ^[1-9][0-9]*$ ]] || { mc_bundle_validation_error "bundle has no approved registry run identity"; return 1; }
  [[ "$MC_BUNDLE_ENABLEMENT" == ADMIN_CONTROLLED_DISABLED ]] || { mc_bundle_validation_error "bundle attempts automatic enablement"; return 1; }

  checksum_paths="$work/checksum-paths.txt"
  : > "$checksum_paths"
  while IFS= read -r checksum_line || [[ -n "$checksum_line" ]]; do
    checksum_line="${checksum_line%$'\r'}"
    [[ "$checksum_line" =~ ^([0-9a-f]{64})\ \ (.+)$ ]] || { mc_bundle_validation_error "invalid checksums.sha256 entry"; return 1; }
    expected_hash="${BASH_REMATCH[1]}"; checksum_path="${BASH_REMATCH[2]}"
    mc_bundle_safe_member_path "$checksum_path" || { mc_bundle_validation_error "unsafe checksum path: $checksum_path"; return 1; }
    [[ "$checksum_path" != checksums.sha256 ]] || { mc_bundle_validation_error "checksums.sha256 must not checksum itself"; return 1; }
    [[ -f "$MC_BUNDLE_CONTENT_DIR/$checksum_path" ]] || { mc_bundle_validation_error "checksum references missing file: $checksum_path"; return 1; }
    actual_hash="$(mc_bundle_sha256_file "$MC_BUNDLE_CONTENT_DIR/$checksum_path")" || return 1
    [[ "$actual_hash" == "$expected_hash" ]] || { mc_bundle_validation_error "file checksum mismatch: $checksum_path"; return 1; }
    printf '%s\n' "$checksum_path" >> "$checksum_paths"
  done < "$MC_BUNDLE_CONTENT_DIR/checksums.sha256"
  if [[ "$(LC_ALL=C sort "$checksum_paths" | uniq -d | wc -l | tr -d ' ')" != 0 ]]; then
    mc_bundle_validation_error "checksums.sha256 contains duplicate paths"; return 1
  fi
  expected_checksum_paths="$work/expected-checksum-paths.txt"
  grep -Fxv checksums.sha256 "$members" | LC_ALL=C sort > "$expected_checksum_paths"
  LC_ALL=C sort "$checksum_paths" > "$work/checksum-paths-sorted.txt"
  cmp -s "$expected_checksum_paths" "$work/checksum-paths-sorted.txt" || { mc_bundle_validation_error "checksums.sha256 does not cover every bundle member exactly once"; return 1; }
  local runtime_protocol='' runtime_spec='' runtime_body='' runtime_count=0
  [[ -s "$MC_BUNDLE_CONTENT_DIR/runtime.properties" ]] || { mc_bundle_validation_error 'missing runtime.properties'; return 1; }
  while IFS='=' read -r key value extra || [[ -n "$key${value:-}${extra:-}" ]]; do
    [[ -n "$key" && -n "$value" && -z "${extra:-}" ]] || { mc_bundle_validation_error 'invalid runtime property'; return 1; }
    case "$key" in
      bootstrap.protocol) [[ -z "$runtime_protocol" ]] || return 1; runtime_protocol="$value" ;;
      runtime.spec.sha256) [[ -z "$runtime_spec" ]] || return 1; runtime_spec="$value" ;;
      runtime.body.sha256) [[ -z "$runtime_body" ]] || return 1; runtime_body="$value" ;;
      *) mc_bundle_validation_error 'unsupported runtime property'; return 1 ;;
    esac
    runtime_count=$((runtime_count + 1))
  done < "$MC_BUNDLE_CONTENT_DIR/runtime.properties"
  [[ "$runtime_count" == 3 && "$runtime_protocol" == mc-bootstrap-1 ]] || { mc_bundle_validation_error 'unsupported bootstrap protocol'; return 1; }
  local runtime_spec_path runtime_body_path
  runtime_spec_path="$(grep -Eo 'db/objects/[0-9]{6}_PACKAGE_DEPLOY_MGR_PKG_[0-9a-f]{12}[.]sql' "$MC_BUNDLE_CONTENT_DIR/db/deploy/product-plan.txt" || true)"
  runtime_body_path="$(grep -Eo 'db/objects/[0-9]{6}_PACKAGE_BODY_DEPLOY_MGR_PKG_[0-9a-f]{12}[.]sql' "$MC_BUNDLE_CONTENT_DIR/db/deploy/product-plan.txt" || true)"
  [[ "$runtime_spec_path" != *$'\n'* && "$runtime_body_path" != *$'\n'* &&
     -f "$MC_BUNDLE_CONTENT_DIR/$runtime_spec_path" && -f "$MC_BUNDLE_CONTENT_DIR/$runtime_body_path" &&
     "$runtime_spec" == "$(mc_bundle_sha256_file "$MC_BUNDLE_CONTENT_DIR/$runtime_spec_path")" &&
     "$runtime_body" == "$(mc_bundle_sha256_file "$MC_BUNDLE_CONTENT_DIR/$runtime_body_path")" ]] || {
    mc_bundle_validation_error 'runtime content identity mismatch'; return 1;
  }
  for required in db/deploy/artifacts.json db/deploy/product-coverage.json db/deploy/product-plan.txt; do
    [[ -s "$MC_BUNDLE_CONTENT_DIR/$required" ]] || { mc_bundle_validation_error "missing product member: $required"; return 1; }
  done
  # Validate this inventory before INITIAL makes any database changes. It is
  # also used to build read-only ADMIN checks for the referenced objects.
  local grant_owner grant_object grant_privilege grant_extra
  while IFS='|' read -r grant_owner grant_object grant_privilege grant_extra || [[ -n "$grant_owner${grant_object:-}${grant_privilege:-}${grant_extra:-}" ]]; do
    grant_privilege="${grant_privilege%$'\r'}"
    if [[ ! "$grant_owner" =~ ^[A-Za-z][A-Za-z0-9_\$#]{0,127}$ ||
          ! "$grant_object" =~ ^[A-Za-z][A-Za-z0-9_\$#]{0,127}$ ||
          ! "$grant_privilege" =~ ^(EXECUTE|SELECT)$ || -n "${grant_extra:-}" ]]; then
      mc_bundle_validation_error "invalid source-required direct privilege inventory"; return 1
    fi
  done < "$MC_BUNDLE_CONTENT_DIR/db/preflight/required_privileges.txt"
  local system_privilege seen_systems='|'
  if [[ -f "$MC_BUNDLE_CONTENT_DIR/db/preflight/required_system_privileges.txt" ]]; then
    while IFS= read -r system_privilege || [[ -n "$system_privilege" ]]; do
      system_privilege="${system_privilege%$'\r'}"
      case "$system_privilege" in
        'CREATE SESSION'|'CREATE TABLE'|'CREATE PROCEDURE'|'CREATE JOB'|'CREATE SEQUENCE'|'CREATE VIEW'|'CREATE MATERIALIZED VIEW'|'CREATE PROPERTY GRAPH'|'CREATE TRIGGER'|'CREATE TYPE'|'CREATE SYNONYM'|'CREATE ANY CONTEXT') ;;
        *) mc_bundle_validation_error 'unsupported system privilege inventory entry'; return 1 ;;
      esac
      [[ "$seen_systems" != *"|$system_privilege|"* ]] || { mc_bundle_validation_error 'duplicate system privilege inventory entry'; return 1; }
      seen_systems+="$system_privilege|"
    done < "$MC_BUNDLE_CONTENT_DIR/db/preflight/required_system_privileges.txt"
  fi
  if [[ -z "$(find "$MC_BUNDLE_CONTENT_DIR/db/objects" -maxdepth 1 -type f -name '*.sql' -print -quit 2>/dev/null)" ]]; then
    mc_bundle_validation_error "bundle contains no database source payload"; return 1
  fi

  # Reject reordered/omitted phases before connecting or provisioning a target.
  cat > "$work/expected-plan.txt" <<'MC_EXPECTED_PLAN'
MC_DATABASE_PLAN|3
PREFLIGHT_GRANTS|environment-prerequisites|db/preflight/required_privileges.sql|Y
REMOVALS|source-removals|db/ddl/00_source_removals.sql|Y
OBJECTS|objects-storage|db/deploy/product-plan.txt|Y
MIGRATIONS|migrations|db/migrations/manifest.txt|Y
OBJECTS|objects-code|db/deploy/product-plan.txt|Y
SCRIPT|05_contexts|db/ddl/05_contexts.sql|N
SCRIPT|95_app_config|db/ddl/95_app_config.sql|N
SCRIPT|96_chatbot_seed|db/ddl/96_chatbot_seed.sql|N
SCRIPT|97_semantic_seed|db/ddl/97_semantic_seed.sql|N
MC_EXPECTED_PLAN
  cmp -s "$work/expected-plan.txt" "$MC_BUNDLE_CONTENT_DIR/db/deploy/plan.txt" || {
    mc_bundle_validation_error "database deployment plan differs from required ordered plan"; return 1;
  }
  MC_BUNDLE_SHA256="$(mc_bundle_sha256_file "$MC_BUNDLE_INPUT_ABS")" || return 1
  return 0
}
# NEW is the operator's authorization to configure database prerequisites.
# EXISTING requires separate approval for missing database-wide settings.
initial_prerequisites_confirm() {
  local reply
  ask reply "$1 (yes/no)" no || return 1
  [[ "$reply" == [Yy] || "$reply" == [Yy][Ee][Ss] ]]
}

# Optional DBA policy decision, independent of NEW/EXISTING prerequisite consent.
# This shared profile change is deliberately retained after CLEANUP/UNINSTALL.
initial_password_profile_prepare() {
  MC_PASSWORD_UNLIMITED=N
  MC_PASSWORD_LIFE="$(sed -n 's/^MC_PASSWORD_LIFE|//p' "$tmp/initial-check.out" | tr -d '\r')"
  [[ "$MC_PASSWORD_LIFE" == UNLIMITED || "$MC_PASSWORD_LIFE" =~ ^[0-9]+([.][0-9]+)?$ ]] || {
    echo 'ERROR: DEFAULT password lifetime could not be verified.' >&2; return 1;
  }
  if [[ "$MC_PASSWORD_LIFE" == UNLIMITED ]]; then
    echo 'Database passwords using the DEFAULT profile do not expire.'
    return 0
  fi
  echo "The new schema $schema will use DEFAULT: its database password expires after $MC_PASSWORD_LIFE days."
  echo 'An expired database password can interrupt application connections and deployments unless it is rotated.'
  echo 'Optional: disable password expiry for all accounts using DEFAULT, not just this schema.'
  echo 'This database-wide profile change is retained after failed installation, cleanup or uninstall.'
  if initial_prerequisites_confirm 'Set DEFAULT PASSWORD_LIFE_TIME to UNLIMITED'; then
    MC_PASSWORD_UNLIMITED=Y
  else
    echo 'Keeping the current password lifetime. Plan database password rotation before expiry.'
  fi
}

initial_password_profile_apply() {
  [[ "${MC_PASSWORD_UNLIMITED:-N}" == Y ]] || return 0
  local script="$tmp/initial-password-profile.sql" fingerprint
  fingerprint="$(sed -n 's/^DATABASE|//p' "$journal_directory/events" | tail -1)"
  [[ "$fingerprint" =~ ^[0-9A-F]{64}$ ]] || return 1
  cat > "$script" <<SQL
whenever sqlerror exit failure rollback
whenever oserror exit failure rollback
set define off echo off verify off feedback off
set serveroutput on
declare v varchar2(128); h varchar2(64);
begin
 if sys_context('USERENV','SESSION_USER')<>'ADMIN' then raise_application_error(-20080,'ADMIN required'); end if;
 select rawtohex(standard_hash(sys_context('USERENV','DB_UNIQUE_NAME')||chr(10)||sys_context('USERENV','CON_NAME'),'SHA256')) into h from dual;
 if h<>'$fingerprint' then raise_application_error(-20080,'Password policy database identity mismatch'); end if;
 select limit into v from dba_profiles where profile='DEFAULT' and resource_name='PASSWORD_LIFE_TIME' and resource_type='PASSWORD';
 if v<>'$MC_PASSWORD_LIFE' then raise_application_error(-20080,'DEFAULT password lifetime changed since approval; review and retry'); end if;
 execute immediate 'alter profile DEFAULT limit PASSWORD_LIFE_TIME UNLIMITED';
 select limit into v from dba_profiles where profile='DEFAULT' and resource_name='PASSWORD_LIFE_TIME' and resource_type='PASSWORD';
 if v<>'UNLIMITED' then raise_application_error(-20080,'DEFAULT password lifetime change unconfirmed'); end if;
 dbms_output.put_line('MC_PASSWORD_PROFILE_OK');
end;
/
exit success
SQL
  initial_lock_check || return 1
  initial_event "PASSWORD_PROFILE_APPROVED|$MC_PASSWORD_LIFE" || return 1
  echo 'Setting DEFAULT database password lifetime to UNLIMITED (retained after cleanup/uninstall).'
  run_sqlcl_capture 'Database password policy' "$admin_connection" "$script" 'approved DEFAULT password lifetime change' "$tmp/password-profile.out" || return 1
  grep -qx MC_PASSWORD_PROFILE_OK "$tmp/password-profile.out" || return 1
  initial_event PASSWORD_PROFILE_UNLIMITED
}

initial_prerequisites_plan() {
  MC_PREREQ_INDEX=N MC_PREREQ_ENABLE_RP=N MC_PREREQ_RESET_RP=N MC_PREREQ_FIRST_INDEX=N
  [[ "$database_mode" =~ ^(NEW|EXISTING)$ && "$MC_PREREQ_MODE" =~ ^(OFF|IMPLEMENT|REPORT\ ONLY)$ &&
     "$MC_PREREQ_RP" =~ ^[01]$ ]] || {
    echo 'ERROR: prerequisite inspection is incomplete or unsupported; nothing authorized.' >&2; return 1;
  }
  echo "Database automatic indexing: $MC_PREREQ_MODE."
  if [[ "$MC_PREREQ_RP" == 1 ]]; then echo 'Database resource principal is already initialized.'
  else echo 'Database resource principal is not initialized.'; fi
  if [[ "$MC_PREREQ_MODE" != IMPLEMENT ]]; then
    if [[ "$database_mode" == NEW && "$MC_PREREQ_MODE" == OFF && "$MC_PREREQ_SCOPE" == 'ALL|' ]]; then
      MC_PREREQ_FIRST_INDEX=Y
      echo "Automatic indexing will be enabled for $schema only. Cleanup/uninstall restores OFF before removing its sole inclusion, provided the settings are unchanged."
    else
      echo 'Enabling automatic indexing changes database-wide policy and may affect other schemas eligible under the existing policy. Eligibility lists will be preserved.'
    fi
    if [[ "$database_mode" == EXISTING ]]; then
      initial_prerequisites_confirm 'Enable automatic indexing (IMPLEMENT)' || { echo 'ERROR: automatic indexing is required; enablement was not approved.' >&2; return 1; }
    fi
    MC_PREREQ_INDEX=Y
  fi
  if [[ "$MC_PREREQ_RP" == 0 ]]; then
    echo 'Resource principal will be initialized for ADMIN, then enabled for the new target schema. OCI IAM policies and dynamic groups must already be configured separately.'
    if [[ "$database_mode" == EXISTING ]]; then
      initial_prerequisites_confirm 'Initialize database resource principal' || { echo 'ERROR: resource principal is required; initialization was not approved.' >&2; return 1; }
    fi
    MC_PREREQ_ENABLE_RP=Y
    if [[ "$database_mode" == NEW ]]; then
      echo 'Initializing resource principal with an enable/disable/re-enable cycle before granting target access. OCI IAM access must be verified separately.'
      MC_PREREQ_RESET_RP=Y
    fi
  fi
}

initial_prerequisites_prepare() {
  # The snapshot transport has been validated by initial_snapshot. These extra
  # decision fields are not part of the legacy journal representation.
  MC_PREREQ_MODE="$(sed -n 's/^MC_PREREQ_MODE|//p' "$tmp/snapshot.out")"
  MC_PREREQ_RP="$(sed -n 's/^MC_STATE|ADMIN_RP|//p' "$journal_directory/shared-before")"
  MC_PREREQ_SCOPE="$(sed -n 's/^MC_STATE|INDEX_SCOPE|//p' "$journal_directory/shared-before")"
  if [[ "$database_mode" == EXISTING && "$MC_PREREQ_RP" == 0 ]] && grep -q '^MC_STATE|RP|' "$journal_directory/shared-before"; then
    echo 'ERROR: resource-principal grants exist without the ADMIN credential; DBA review required.' >&2; return 1
  fi
  initial_prerequisites_plan
}

# Emit guards for the exact database/schema and current reviewed shared state.
# All interpolated values below are validated identifiers, enums or receipts.
initial_prerequisites_guard() {
  local current_mode="$1" current_rp="$2" fingerprint schema_id raw_hash grants
  fingerprint="$(sed -n 's/^DATABASE|//p' "$journal_directory/events" | tail -1)"
  schema_id="$(sed -n 's/^SCHEMA|//p' "$journal_directory/events" | tail -1)"
  raw_hash="$(sed -n 's/^MC_STATE|INDEX_RAW|//p' "$tmp/shared-after")"
  grants="$(grep -c '^MC_STATE|RP|' "$tmp/shared-after" || true)"
  [[ "$fingerprint" =~ ^[0-9A-F]{64}$ && "$raw_hash" =~ ^[0-9A-F]{64}$ && "$schema_id" =~ ^[0-9]+$ &&
     "$current_mode" =~ ^(OFF|IMPLEMENT|REPORT\ ONLY)$ && "$current_rp" =~ ^[01]$ && "$grants" =~ ^[0-9]+$ ]] || return 1
  cat <<SQL
whenever sqlerror exit failure rollback
whenever oserror exit failure rollback
set define off
set serveroutput on
declare n number; h varchar2(64); m varchar2(30);
begin
 if user<>'ADMIN' then raise_application_error(-20080,'Prerequisite changes require ADMIN'); end if;
 select rawtohex(standard_hash(sys_context('USERENV','DB_UNIQUE_NAME')||chr(10)||sys_context('USERENV','CON_NAME'),'SHA256')) into h from dual;
 if h<>'$fingerprint' then raise_application_error(-20080,'Prerequisite database identity mismatch'); end if;
 select count(*) into n from dba_users where username='$schema' and user_id=$schema_id;
 if n<>1 then raise_application_error(-20080,'Prerequisite schema identity mismatch'); end if;
 select nvl(upper(trim(parameter_value)),'OFF') into m from dba_auto_index_config where parameter_name='AUTO_INDEX_MODE';
 if m<>'$current_mode' then raise_application_error(-20080,'Indexing mode changed since review'); end if;
 select rawtohex(standard_hash(nvl(parameter_value,chr(1))||'|'||nvl(dbms_lob.substr(parameter_value_clob,4000,1),chr(1)),'SHA256')) into h from dba_auto_index_config where parameter_name='AUTO_INDEX_SCHEMA';
 if h<>'$raw_hash' then raise_application_error(-20080,'Indexing scope changed since review'); end if;
 select count(*) into n from dba_credentials where owner='ADMIN' and credential_name='OCI\$RESOURCE_PRINCIPAL';
 if n<>$current_rp then raise_application_error(-20080,'Resource principal changed since review'); end if;
 select count(*) into n from dba_tab_privs where owner='ADMIN' and table_name='OCI\$RESOURCE_PRINCIPAL' and grantee<>'$schema';
 if n<>$grants then raise_application_error(-20080,'Resource-principal grants changed since review'); end if;
SQL
}

initial_prerequisites_run() {
  local script="$1" output="$2" intent="$3" status_=0
  # CLEANUP/UNINSTALL dispatch before normal deployment helpers are defined.
  # Check local readiness before recording an intent that may have reached DB.
  initial_lock_check || return 1
  initial_fence_script "$script" || return 1
  initial_event "$intent" || return 1
  sql -s -L -name "$admin_connection" "@$MC_FENCED_SCRIPT" > "$output" 2>&1 || status_=$?
  if [[ "$status_" != 0 ]] || ! grep -qx MC_PREREQUISITES_OK "$output" || grep -Eq 'ORA-|PLS-|SP2-' "$output"; then
    cp "$output" "$journal_directory/prerequisites-diagnostic.log" || true
    grep -E 'ORA-|PLS-|SP2-' "$output" >&2 || true
    echo "ERROR: prerequisite operation unconfirmed. Diagnostic: $journal_directory/prerequisites-diagnostic.log" >&2
    return 1
  fi
}

initial_prerequisites_compare() {
  local excluded='^MC_STATE\|(INDEX\|AUTO_INDEX_MODE\||ADMIN_RP\|)'
  if [[ "$MC_PREREQ_FIRST_INDEX" == Y ]]; then
    excluded='^MC_STATE\|(INDEX\|AUTO_INDEX_MODE\||ADMIN_RP\||INDEX_(RAW|SCOPE|TARGET)\|)'
  fi
  { grep -Ev "$excluded" "$journal_directory/shared-before" || true; } | LC_ALL=C sort > "$tmp/prereq-before"
  { grep -Ev "$excluded" "$journal_directory/shared-provisioned" || true; } | LC_ALL=C sort > "$tmp/prereq-after"
  : > "$tmp/prereq-accepted-additions"
  if [[ "$MC_PREREQ_ENABLE_RP" == Y ]]; then
    # Only new, exact service grants from an approved RP initialization. Require
    # live ORACLE_MAINTAINED evidence as well as the known privilege tuples.
    # Existing grants, removals and grant-option changes remain protected.
    sed -n 's/^MC_PREREQ_ORACLE_RP|/MC_STATE|RP|/p' "$tmp/snapshot.out" |
      grep -Ex 'MC_STATE\|RP\|(C##CLOUD\$SERVICE\|EXECUTE\|YES|GRAPH\$METADATA\|EXECUTE\|NO|ODI_REPO_USER\|EXECUTE\|NO)' > "$tmp/prereq-service-grants" || true
    LC_ALL=C comm -13 "$tmp/prereq-before" "$tmp/prereq-after" > "$tmp/prereq-additions"
    grep -Fx -f "$tmp/prereq-service-grants" "$tmp/prereq-additions" > "$tmp/prereq-accepted-additions" || true
  fi
  grep -Fvx -f "$tmp/prereq-accepted-additions" "$tmp/prereq-after" > "$tmp/prereq-normalized" || true
  if ! cmp -s "$tmp/prereq-before" "$tmp/prereq-normalized"; then
    diff -u "$tmp/prereq-before" "$tmp/prereq-normalized" > "$journal_directory/prerequisites-state.diff" || true
    echo 'ERROR: unexpected shared prerequisite changes; DBA review required.' >&2
    cat "$journal_directory/prerequisites-state.diff" >&2
    echo "State differences: $journal_directory/prerequisites-state.diff" >&2
    return 1
  fi
}

initial_prerequisites_apply() {
  [[ "$MC_PREREQ_INDEX$MC_PREREQ_ENABLE_RP" != NN ]] || return 0
  initial_verify_shared || return 1
  # Keep immutable before/after evidence. Unknown partial DDL is never treated
  # as successful or automatically undone based on an intent alone.
  local script="$tmp/initial-prerequisites-apply.sql" output="$tmp/prerequisites-apply.out"
  initial_prerequisites_guard "$MC_PREREQ_MODE" "$MC_PREREQ_RP" > "$script" || return 1
  if [[ "$MC_PREREQ_FIRST_INDEX" == Y ]]; then
    printf " dbms_auto_index.configure('AUTO_INDEX_SCHEMA','%s',true);\n" "$schema" >> "$script"
  fi
  if [[ "$MC_PREREQ_INDEX" == Y ]]; then
    printf '%s\n' " dbms_auto_index.configure('AUTO_INDEX_MODE','IMPLEMENT');" >> "$script"
  fi
  if [[ "$MC_PREREQ_ENABLE_RP" == Y ]]; then
    printf '%s\n' ' dbms_cloud_admin.enable_resource_principal();' >> "$script"
    if [[ "$MC_PREREQ_RESET_RP" == Y ]]; then
      printf '%s\n' ' dbms_cloud_admin.disable_resource_principal();' ' dbms_cloud_admin.enable_resource_principal();' >> "$script"
    fi
  fi
  printf '%s\n' " dbms_output.put_line('MC_PREREQUISITES_OK');" 'end;' / 'exit success' >> "$script"
  echo 'Applying the database prerequisites you approved.'
  initial_prerequisites_run "$script" "$output" INTENT_PREREQUISITES || return 1
  initial_snapshot "$journal_directory/shared-provisioned" || return 1
  [[ "$(sed -n 's/^MC_PREREQ_MODE|//p' "$tmp/snapshot.out")" == IMPLEMENT ]] || return 1
  grep -qx 'MC_STATE|ADMIN_RP|1' "$journal_directory/shared-provisioned" || return 1
  if [[ "$MC_PREREQ_FIRST_INDEX" == Y ]]; then
    grep -qx 'MC_STATE|INDEX_SCOPE|IN|' "$journal_directory/shared-provisioned" &&
      grep -qx 'MC_STATE|INDEX_TARGET|PRESENT' "$journal_directory/shared-provisioned" || return 1
  fi
  initial_prerequisites_compare || return 1
  if [[ "$MC_PREREQ_FIRST_INDEX" == Y ]]; then initial_event PREREQ_FIRST_INDEX || return 1; fi
  initial_event "PROVISIONED_SNAPSHOT|$(mc_bundle_sha256_file "$journal_directory/shared-provisioned")" || return 1
  echo 'Database prerequisites verified. Shared resource-principal initialization is retained if installation is later removed.'
}

initial_prerequisites_restore() {
  initial_verify_shared || return 1
  # Only the fresh OFF -> sole inclusion -> IMPLEMENT path owns this exception.
  grep -qx 'MC_STATE|INDEX_SCOPE|IN|' "$tmp/shared-after" && grep -qx 'MC_STATE|INDEX_TARGET|PRESENT' "$tmp/shared-after" || return 1
  local script="$tmp/initial-prerequisites-restore.sql" output="$tmp/prerequisites-restore.out"
  local rp
  rp="$(sed -n 's/^MC_STATE|ADMIN_RP|//p' "$tmp/shared-after")"
  initial_prerequisites_guard IMPLEMENT "$rp" > "$script" || return 1
  printf '%s\n' " dbms_auto_index.configure('AUTO_INDEX_MODE','OFF');" \
    " dbms_auto_index.configure('AUTO_INDEX_SCHEMA','$schema',null);" \
    " dbms_output.put_line('MC_PREREQUISITES_OK');" 'end;' / 'exit success' >> "$script"
  echo 'Restoring automatic indexing to OFF before removing the only installer-owned inclusion.'
  initial_prerequisites_run "$script" "$output" INTENT_PREREQ_RESTORE || return 1
  initial_snapshot "$journal_directory/shared-restored" || return 1
  [[ "$(sed -n 's/^MC_PREREQ_MODE|//p' "$tmp/snapshot.out")" == OFF ]] || return 1
  grep -qx 'MC_STATE|INDEX_SCOPE|ALL|' "$journal_directory/shared-restored" &&
    grep -qx 'MC_STATE|INDEX_TARGET|ABSENT' "$journal_directory/shared-restored" || return 1
  local excluded='^MC_STATE\|(INDEX\|AUTO_INDEX_MODE\||INDEX_(RAW|SCOPE|TARGET)\|)'
  grep -Ev "$excluded" "$journal_directory/shared-provisioned" > "$tmp/prereq-before" || true
  grep -Ev "$excluded" "$journal_directory/shared-restored" > "$tmp/prereq-after" || true
  cmp -s "$tmp/prereq-before" "$tmp/prereq-after" || return 1
  initial_event "RESTORED_SNAPSHOT|$(mc_bundle_sha256_file "$journal_directory/shared-restored")"
}
#!/usr/bin/env bash
# INITIAL-only orchestration. Sourced by install_mc_bundle.sh after ZIP validation.

initial_archive_stage_name() {
  local run_id
  run_id="$(cut -d '|' -f 1 "$journal_directory/provenance")"
  [[ "$run_id" =~ ^[0-9a-f]{32}$ ]] || fail 'INITIAL upload run identity is invalid'
  printf 'MC_INITIAL_UP_%s' "$(printf '%s' "${run_id:0:16}" | tr '[:lower:]' '[:upper:]')"
}

initial_archive_stage() {
  local kind="$1" saved="$2" bind="$3" script="$4" table csv encoded create_sql load_sql part=0 chunk bytes
  [[ "$kind" == ADMIN || "$kind" == TARGET ]] || fail 'Unknown INITIAL upload owner'
  [[ "$bind" == initial_zip || "$bind" == early_zip ]] || fail 'Unknown INITIAL archive bind'
  table="$(initial_archive_stage_name)"
  csv="$tmp/initial-load-$kind.csv"
  encoded="$tmp/initial-load-$kind.base64"
  create_sql="$tmp/initial-load-$kind-create.sql"
  load_sql="$tmp/initial-load-$kind.sql"
  (set -o pipefail; base64 < "$bundle" | tr -d '\r\n' | fold -w 4000) > "$encoded" \
    || fail 'INITIAL archive encoding failed before staging'
  initial_event "INTENT_UPLOAD_${kind}|$table"
  cat > "$create_sql" <<SQL
whenever sqlerror exit failure rollback
whenever oserror exit failure rollback
declare n number;
begin
  select count(*) into n from user_tables where table_name='$table';
  if n<>0 then raise_application_error(-20094,'INITIAL upload table name already exists.'); end if;
  execute immediate 'create table $table (part_no number not null primary key, encoded varchar2(4000) not null)';
end;
/
exit success
SQL
  run_sqlcl_capture "INITIAL $kind upload staging" "$saved" "$create_sql" 'installer-owned upload table' "$tmp/initial-load-$kind-create.out"
  initial_event "UPLOAD_${kind}|$table"
  printf 'PART_NO,ENCODED\n' > "$csv"
  while IFS= read -r chunk || [[ -n "$chunk" ]]; do
    [[ "$chunk" =~ ^[A-Za-z0-9+/]+={0,2}$ && ${#chunk} -le 4000 && $((${#chunk}%4)) -eq 0 ]] || fail 'Invalid INITIAL archive encoding'
    part=$((part+1))
    printf '%s,%s\n' "$part" "$chunk" >> "$csv"
  done < "$encoded"
  rm -f -- "$encoded"
  ((part>0)) || fail 'Empty INITIAL archive transfer'
  cat > "$load_sql" <<SQL
whenever sqlerror exit failure rollback
whenever oserror exit failure rollback
set echo off feedback off verify off
set load batch_rows 500
set load batches_per_commit 10
load $table $csv
exit success commit
SQL
  run_sqlcl_capture "INITIAL $kind archive LOAD" "$saved" "$load_sql" 'release archive transfer' "$tmp/initial-load-$kind.out"
  if grep -Eq '^ORA-[0-9]|^PLS-[0-9]|^SP2-[0-9]|[1-9][0-9]* - (ERROR|FAILURE): Load' "$tmp/initial-load-$kind.out"; then
    fail "INITIAL $kind archive LOAD reported an error; inspect the diagnostic log"
  fi
  bytes="$(wc -c < "$bundle" | tr -d '[:space:]')"
  printf 'Archive LOAD: %s bytes into %s staging.\n' "$bytes" "$kind"
  cat >> "$script" <<SQL
variable $bind blob
declare
  expected_part number:=1; decoded_bytes raw(32767);
begin
  dbms_lob.createtemporary(:$bind,true,dbms_lob.session);
  for row_value in (select part_no,encoded from $table order by part_no) loop
    if row_value.part_no<>expected_part or mod(length(row_value.encoded),4)<>0
      or not regexp_like(row_value.encoded,'^[A-Za-z0-9+/]+={0,2}$','c') then
      raise_application_error(-20175,'INITIAL archive upload row is malformed.');
    end if;
    decoded_bytes:=utl_encode.base64_decode(utl_raw.cast_to_raw(row_value.encoded));
    dbms_lob.writeappend(:$bind,utl_raw.length(decoded_bytes),decoded_bytes);
    expected_part:=expected_part+1;
  end loop;
  if expected_part<>$((part+1)) or dbms_lob.getlength(:$bind)<>$bytes
    or lower(rawtohex(dbms_crypto.hash(:$bind,dbms_crypto.hash_sh256)))<>'$bundle_hash' then
    raise_application_error(-20175,'INITIAL archive LOAD is incomplete or changed.');
  end if;
end;
/
SQL
}

initial_archive_stage_drop() {
  local kind="$1" saved="$2" table script
  table="$(initial_archive_stage_name)"
  script="$tmp/initial-load-$kind-drop.sql"
  cat > "$script" <<SQL
whenever sqlerror exit failure rollback
whenever oserror exit failure rollback
declare n number;
begin
  select count(*) into n from user_tables where table_name='$table';
  if n=1 then execute immediate 'drop table $table purge'; end if;
end;
/
exit success
SQL
  run_sqlcl_capture "INITIAL $kind upload cleanup" "$saved" "$script" 'installer-owned upload table cleanup' "$tmp/initial-load-$kind-drop.out"
  initial_event "UPLOAD_${kind}_DROPPED|$table"
}

initial_archive_admin_cleanup() {
  local table script output
  table="$(initial_archive_stage_name)"
  grep -Fqx "INTENT_UPLOAD_ADMIN|$table" "$journal_directory/events" || return 0
  grep -Fqx "UPLOAD_ADMIN_DROPPED|$table" "$journal_directory/events" && return 0
  script="$tmp/initial-load-ADMIN-recovery.sql"
  output="$tmp/initial-load-ADMIN-recovery.out"
  cat > "$script" <<SQL
whenever sqlerror exit failure rollback
whenever oserror exit failure rollback
declare n number;
begin
  select count(*) into n from user_tables where table_name='$table';
  if n=1 then execute immediate 'drop table $table purge'; end if;
end;
/
exit success
SQL
  if ! sql -s -L -name "$admin_connection" "@$script" < /dev/null > "$output" 2>&1; then
    echo 'RECOVERY_REQUIRED: ADMIN archive upload table remains; inspect the INITIAL journal.' >&2
    return 1
  fi
  initial_event "UPLOAD_ADMIN_DROPPED|$table"
}


initial_bootstrap_supported() {
