initial_product_coordinator_assertion() {
  # The archive verifier already binds every key to its UNIT payload and hash.
  # This runtime coordinator must also be an explicit canonical tool entry.
  cat <<'SQL'
declare
  coordinator_coverage clob; coordinator_count number:=0; coordinator_doc json_object_t;
  coordinator_entries json_array_t; coordinator_item json_object_t; coordinator_identity json_object_t;
begin
  verify_product_archive(:initial_zip,coordinator_coverage);
  coordinator_doc:=json_object_t.parse(coordinator_coverage);
  coordinator_entries:=coordinator_doc.get_object('inventory').get_array('entries');
  for i in 0..coordinator_entries.get_size-1 loop
    coordinator_item:=treat(coordinator_entries.get(i) as json_object_t);
    coordinator_identity:=coordinator_item.get_object('identity');
    if coordinator_item.get_string('lifecycle')='BOOTSTRAP' and coordinator_item.get_string('state')='PRESENT'
      and coordinator_identity.get_string('owner_role')='APPLICATION_SCHEMA'
      and coordinator_identity.get_string('object_type') in ('JOB','SCHEDULER JOB')
      and coordinator_identity.get_string('object_name')='MCSR_BUNDLE_RECONCILE'
      and coordinator_identity.get_string('parent_name') is null
      and coordinator_item.get_string('source_path')='db/source/release/jobs/mcsr_bundle_reconcile.sql' then
      coordinator_count:=coordinator_count+1;
    end if;
  end loop;
  if coordinator_count<>1 then
    raise_application_error(-20175,'INITIAL requires explicit canonical BOOTSTRAP coverage for MCSR_BUNDLE_RECONCILE.');
  end if;
  dbms_lob.freetemporary(coordinator_coverage);
end;
SQL
}

initial_revision_inspect() {
  [[ "$mode" == INITIAL && "$contract" == mc-bundle-1.13.0 && "$dry" == N ]] || return 0
  local script="$tmp/initial-archive-inspect.sql" output="$tmp/initial-archive-inspect.out"
  printf '%s\n' 'whenever sqlerror exit failure rollback' 'whenever oserror exit failure rollback' \
    'set define off echo off verify off feedback off' > "$script"
  initial_archive_stage ADMIN "$admin_connection" initial_zip "$script"
  printf '%s\n' 'prompt MC_INITIAL_ARCHIVE_VALIDATING' >> "$script"
  printf '%s\n' 'declare app_id number; version_value varchar2(64); registry_run number; spec_hash varchar2(64); body_hash varchar2(64);' >> "$script"
  mc_archive_inspector_sql >> "$script"
  printf "begin inspect(:initial_zip,'%s',app_id,version_value,registry_run,spec_hash,body_hash);\n" "$bundle_hash" >> "$script"
  initial_product_coordinator_assertion >> "$script"
  printf '%s\n' 'dbms_lob.freetemporary(:initial_zip); end;' / 'exit success rollback' >> "$script"
  echo 'Validating release archive before provisioning.'
  run_sqlcl_capture 'Release archive preflight' "$admin_connection" "$script" 'archive validation from staged bytes' "$output" || return $?
  initial_archive_stage_drop ADMIN "$admin_connection"

}

