initial_bootstrap_write_job_check() {
  # Shared by disabled-job creation and final admission. Names/actions are fixed;
  # an existing incompatible job is rejected rather than replaced or repurposed.
  cat <<'SQL'
declare n number;
begin
  select count(*) into n from user_scheduler_jobs
    where job_name='MCSR_BUNDLE_RECONCILE' and job_type='STORED_PROCEDURE'
      and (upper(job_action)='MC_BUNDLE_BOOTSTRAP_PKG.RECONCILE' or job_action='"MC_BUNDLE_BOOTSTRAP_PKG"."RECONCILE"') and number_of_arguments=0
      and repeat_interval='FREQ=MINUTELY;INTERVAL=1' and auto_drop='FALSE';
  if n<>1 then raise_application_error(-20175,'Coordinator reconciliation job identity is incompatible.'); end if;
end;
/
SQL
}

initial_bootstrap_verify() {
  initial_bootstrap_supported || return 0
  local script="$tmp/initial-bootstrap-verify.sql"
  cat > "$script" <<'SQL'
whenever oserror exit failure rollback
whenever sqlerror exit failure rollback
set define off
begin dbms_utility.compile_schema(schema=>user,compile_all=>false); end;
/
declare n number;
begin
  for p in (select column_value name from table(sys.odcivarchar2list(
    'MC_BUNDLE_ZIP_PKG','MC_BUNDLE_INTEGRITY_PKG','MC_RUNTIME_GUARD_PKG',
    'MC_BUNDLE_BOOTSTRAP_PKG','MC_BUNDLE_BOOTSTRAP_ASSETS_PKG','DEPLOY_MGR_PKG'))) loop
    select count(*) into n from user_objects where object_name=p.name
      and object_type in ('PACKAGE','PACKAGE BODY') and status='VALID';
    if n<>2 then raise_application_error(-20175,'INITIAL bootstrap is incomplete; inspect USER_ERRORS.'); end if;
  end loop;
  if nvl(mc_bundle_bootstrap_pkg.protocol,'?')<>'mc-bootstrap-1' or
     nvl(mc_bundle_integrity_pkg.protocol,'?')<>'mc-bootstrap-1' or
     nvl(mc_runtime_guard_pkg.protocol_version,'?')<>'mc-runtime-guard-1' or
     nvl(deploy_mgr_pkg.runtime_contract,'?')<>'mc-bundle-1.13.0' then
    raise_application_error(-20175,'INITIAL bootstrap protocols are incompatible.'); end if;
    for p in (select column_value name from table(sys.odcivarchar2list(
      'MC_ARTIFACT_SELECTION_PKG','MC_ARTIFACT_DEFINITION_PKG','MC_ARTIFACT_MANIFEST_PKG','MC_ARTIFACT_UPDATE_PKG'))) loop
      select count(*) into n from user_objects where object_name=p.name
        and object_type in ('PACKAGE','PACKAGE BODY') and status='VALID';
      if n<>2 then raise_application_error(-20175,'INITIAL revision helper is invalid: '||p.name); end if;
    end loop;
  select count(*) into n from mc_runtime_fence where id=1 and owner_run_id is null and generation is null;
  if n<>1 then raise_application_error(-20175,'INITIAL runtime fence is not idle.'); end if;
end;
/
SQL
  printf '@%s/content/db/runtime/runtime_dependencies.sql\n' "$tmp" >> "$script"
  initial_bootstrap_write_job_check >> "$script"
  run_script bootstrap-verify "$script"
}

initial_bootstrap_enable() {
  initial_bootstrap_supported || return 0
  local script="$tmp/initial-bootstrap-enable.sql"
  cat > "$script" <<'SQL'
whenever oserror exit failure rollback
whenever sqlerror exit failure rollback
set define off
SQL
  initial_bootstrap_write_job_check >> "$script"
  cat >> "$script" <<'SQL'
declare
  n number;
  lock_id integer:=dbms_utility.get_hash_value('MC_RUNTIME:'||user,0,1073741823);
  locked boolean:=false;
begin
  n:=dbms_lock.request(lock_id,dbms_lock.x_mode,timeout=>0,release_on_commit=>false);
  if n<>0 then raise_application_error(-20175,'Runtime is busy; INITIAL admission remains blocked.'); end if;
  locked:=true;
  select count(*) into n from mc_runtime_fence where id=1
    and owner_run_id is null and generation is null and installation_state in ('INSTALLING','READY');
  if n<>1 then raise_application_error(-20175,'INITIAL runtime admission is not ready.'); end if;
  update mc_runtime_fence set installation_state='INSTALLING' where id=1 and owner_run_id is null and generation is null;
  if sql%rowcount<>1 then raise_application_error(-20175,'INITIAL runtime ownership changed.'); end if;
  commit;
  select count(*) into n from user_scheduler_jobs where job_name='MCSR_BUNDLE_RECONCILE' and enabled='FALSE';
  if n=1 then dbms_scheduler.enable('MCSR_BUNDLE_RECONCILE'); end if;
  select count(*) into n from user_scheduler_jobs
    where job_name='MCSR_BUNDLE_RECONCILE' and job_type='STORED_PROCEDURE'
      and (upper(job_action)='MC_BUNDLE_BOOTSTRAP_PKG.RECONCILE' or job_action='"MC_BUNDLE_BOOTSTRAP_PKG"."RECONCILE"') and number_of_arguments=0
      and repeat_interval='FREQ=MINUTELY;INTERVAL=1' and auto_drop='FALSE' and enabled='TRUE';
  if n<>1 then raise_application_error(-20175,'INITIAL reconciliation job was not enabled as expected.'); end if;
  -- Scheduler metadata may commit: release admission only after enable succeeds.
  update mc_runtime_fence set installation_state='READY' where id=1 and owner_run_id is null and generation is null;
  if sql%rowcount<>1 then raise_application_error(-20175,'INITIAL runtime ownership changed.'); end if;
  commit;
  n:=dbms_lock.release(lock_id);
  if n<>0 then raise_application_error(-20175,'INITIAL admission lock release failed.'); end if;
  locked:=false;
exception when others then
  if locked then
    update mc_runtime_fence set installation_state='INSTALLING' where id=1 and owner_run_id is null and generation is null;
    commit;
    n:=dbms_lock.release(lock_id);
  end if;
  raise;
end;
/
SQL
  # Called only after initial_access and initial_verify_shared have succeeded.
  run_script bootstrap-enable "$script"
}

initial_registry_receipts() (
  [[ "$dry" == N ]] || return 0
  [[ "${initial_bundle_id:-}" =~ ^[1-9][0-9]*$ && "${initial_run_id:-}" =~ ^[1-9][0-9]*$ ]] || fail 'Retained INITIAL archive receipt is missing'
  local script="$tmp/initial-record-baseline.sql"
  cat > "$script" <<SQL
whenever sqlerror exit failure rollback
whenever oserror exit failure rollback
set define off echo off verify off serveroutput on
declare
  z blob; members mc_bundle_zip_pkg.t_members; manifest clob; artifacts clob; coverage clob;
  doc json_object_t; registry json_object_t; product json_object_t; entries json_array_t; item json_object_t;
  bytes blob; apex_hash varchar2(64); version_value varchar2(64); app_version varchar2(64); n number; locked boolean:=false;
  workspace_name varchar2(255); app number; off number; ws number; count_value number:=0;
  function member_text(name_value varchar2) return clob is
    b blob; t clob; d integer:=1; s integer:=1; ctx integer:=0; w integer;
  begin
    for i in 1..members.count loop
      if members(i).name=name_value then
        b:=mc_bundle_zip_pkg.get_member(z,members(i),16777216);
        dbms_lob.createtemporary(t,true);
        dbms_lob.converttoclob(t,b,dbms_lob.lobmaxsize,d,s,nls_charset_id('AL32UTF8'),ctx,w);
        dbms_lob.freetemporary(b);
        if w<>0 then raise_application_error(-20175,'Retained metadata encoding is invalid'); end if;
        return t;
      end if;
    end loop;
    raise_application_error(-20175,'Retained baseline metadata is missing');
  end;
  procedure publish(entry_value json_object_t,lineage varchar2) is
    ident json_object_t:=entry_value.get_object('identity'); identity_text varchar2(2000):=ident.to_string;
    state_value varchar2(10):=entry_value.get_string('state'); hash_value varchar2(64):=entry_value.get_string('definition_sha256');
    key_value varchar2(64):=entry_value.get_string('key'); rev number:=entry_value.get_number('revision');
    fmt varchar2(64):=entry_value.get_string('definition_format'); nm varchar2(128):=ident.get_string('object_name'); typ varchar2(64):=ident.get_string('object_type');
  begin
    -- Earlier compile validation permits non-critical warnings; do not give an
    -- invalid object an installed revision receipt. No definition re-extraction.
    if state_value='PRESENT' and typ in ('PACKAGE','PACKAGE BODY','TYPE','TYPE BODY','PROCEDURE','FUNCTION','VIEW','TRIGGER') then
      select count(*) into n from user_objects where object_name=nm
        and object_type=typ and status<>'VALID';
      if n>0 then return; end if;
    end if;
    insert into mc_artifact_receipts(artifact_key,lineage_id,identity_json,source_revision,artifact_state,
      definition_format,definition_hash,verified_hash,bundle_id,run_id)
      values(key_value,lineage,identity_text,rev,state_value,
        fmt,hash_value,hash_value,$initial_bundle_id,$initial_run_id);
    count_value:=count_value+1;
  end;
begin
  mc_runtime_guard_pkg.acquire_maintenance; locked:=true;
  select count(*) into n from mc_artifact_receipts;
  if n<>0 then raise_application_error(-20175,'INITIAL target already has object receipts'); end if;
  select count(*) into n from mc_apex_receipts;
  if n<>0 then raise_application_error(-20175,'INITIAL target already has APEX receipts'); end if;
  select b.bundle_zip,b.manifest_json,b.version_tag into z,manifest,version_value
    from deploy_bundles b join deploy_runs r on r.bundle_id=b.bundle_id
    where b.bundle_id=$initial_bundle_id and r.run_id=$initial_run_id and r.action='INITIAL' and r.status='RUNNING';
  -- This archive was validated and retained during the target helper upload.
  -- Read its registry metadata; do not inspect the archive or compare DDL again.
  mc_bundle_zip_pkg.inspect(z,members);
  artifacts:=member_text('db/deploy/artifacts.json'); registry:=json_object_t.parse(artifacts);
  entries:=registry.get_array('artifacts');
  for i in 0..entries.get_size-1 loop publish(treat(entries.get(i) as json_object_t),registry.get_string('lineage_id')); end loop;
  coverage:=member_text('db/deploy/product-coverage.json'); product:=json_object_t.parse(coverage).get_object('inventory');
  entries:=product.get_array('entries');
  for i in 0..entries.get_size-1 loop
    item:=treat(entries.get(i) as json_object_t);
    if item.get_string('lifecycle')='BOOTSTRAP' then publish(item,product.get_string('lineage_id')); end if;
  end loop;
  -- APEX transport hash is receipt metadata, read from the validated manifest.
  doc:=json_object_t.parse(manifest); apex_hash:=doc.get_object('files').get_string('apex/f1200.sql');
  select max(case when config_key='APEX_WORKSPACE_NAME' then config_value end),
    to_number(max(case when config_key='APEX_APP_ID' then config_value end)),
    to_number(max(case when config_key='APEX_APP_OFFSET' then config_value end))
    into workspace_name,app,off from app_config;
  ws:=apex_util.find_security_group_id(workspace_name);
  select version into app_version from apex_applications where workspace_id=ws and application_id=app and owner=user;
  mc_artifact_update_pkg.record_apex(null,app_version,ws,app,off,registry.get_string('lineage_id'),apex_hash,$initial_bundle_id,$initial_run_id);
  update deploy_runs set status='SUCCESS',ended_at=systimestamp where run_id=$initial_run_id and action='INITIAL' and status='RUNNING';
  if sql%rowcount<>1 then raise_application_error(-20175,'INITIAL baseline run changed'); end if;
  commit;
  dbms_lob.freetemporary(artifacts); dbms_lob.freetemporary(coverage);
  mc_runtime_guard_pkg.release_lock; locked:=false;
  dbms_output.put_line('MC_INITIAL_BASELINE|'||count_value);
exception when others then
  rollback;
  if locked then mc_runtime_guard_pkg.release_lock; end if;
  raise;
end;
/
SQL
  run_script initial-baseline "$script"

)

initial_read_password() {
  local destination="$1" prompt="$2" captured
  if captured="$(initial_password_input "$prompt")"; then
    printf -v "$destination" '%s' "$captured"
  else
    printf -v "$destination" '%s' ''
    return 1
  fi
}

# Runs in command substitution: stdout is the secret, stderr is terminal UI.
# Disable echo BEFORE showing the prompt, including between individual reads.
initial_password_input() (
  local prompt="$1" entered='' key='' masked=N
  if [[ -t 0 ]]; then
    MC_PASSWORD_TTY_STATE="$(stty -g)" || exit 1
    trap 'stty "$MC_PASSWORD_TTY_STATE" 2>/dev/null || true' EXIT
    trap 'exit 130' INT
    trap 'exit 143' TERM HUP
    stty -echo -icanon eof undef min 1 time 0 || exit 1
    [[ ! -t 2 ]] || masked=Y
  fi
  printf '%s: ' "$prompt" >&2
  while IFS= read -r -n 1 key; do
    case "$key" in
      '') printf '\n' >&2; printf '%s' "$entered"; exit 0 ;;
      $'\177'|$'\b')
        if [[ -n "$entered" ]]; then
          entered="${entered%?}"
          [[ "$masked" != Y ]] || printf '\b \b' >&2
        fi ;;
      $'\004') break ;;
      $'\025')
        while [[ -n "$entered" ]]; do
          entered="${entered%?}"
          [[ "$masked" != Y ]] || printf '\b \b' >&2
        done ;;
      *) entered+="$key"; [[ "$masked" != Y ]] || printf '*' >&2 ;;
    esac
  done
  printf '\n' >&2
  exit 1
)

initial_secret() {
  local prompt="$1" value confirm_value
  while :; do
    initial_read_password value "$prompt" || fail 'Password entry cancelled (end of input)'
    initial_read_password confirm_value 'Confirm password' || fail 'Password entry cancelled (end of input)'
    if [[ -n "$value" && "$value" == "$confirm_value" && ${#value} -le 128 && "$value" != *$'\r'* ]]; then
      break
    fi
    echo 'Passwords must match and contain 1–128 characters. Please try again.' >&2
    unset value confirm_value
  done
  # Hex is encoding, NOT encryption. The script and output stay in the private
  # temporary directory and are deleted immediately; never print either.
  secret_hex="$(printf '%s' "$value" | od -An -v -tx1 | tr -d ' \n')"
  unset value confirm_value
}

initial_app_email() {
  local value local_part
  local LC_ALL=C
  local pattern="^[A-Za-z0-9._%+'-]+@[A-Za-z0-9]([A-Za-z0-9-]{0,61}[A-Za-z0-9])?(\.[A-Za-z0-9]([A-Za-z0-9-]{0,61}[A-Za-z0-9])?)+$"
  while :; do
    printf 'Email address for application administrator %s: ' "$first_admin" >&2
    IFS= read -r value || fail 'Email entry cancelled (end of input)'
    local_part="${value%%@*}"
    if [[ ${#value} -le 254 && ${#local_part} -le 64 && "$value" =~ $pattern &&
          "$local_part" != .* && "$local_part" != *. && "$local_part" != *..* ]]; then
      break
    fi
    echo 'Please enter a valid email address.' >&2
  done
  # Encode as data for SQL, including addresses with apostrophes. Keep it out
  # of the recovery journal and diagnostics; the account is its durable home.
  initial_app_email_hex="$(printf '%s' "$value" | od -An -v -tx1 | tr -d ' \n')"
}

initial_clone_connection() {
  local clone_password='' character='' hex="$initial_database_secret_hex" status=0 output="$tmp/clone-sensitive.out"
  [[ -n "$hex" ]] || fail 'Database password was not collected during preparation'
  while [[ -n "$hex" ]]; do
    printf -v character '%b' "\\x${hex:0:2}"
    clone_password+="$character"; hex="${hex:2}"
  done
  unset initial_database_secret_hex character hex
  # Only stdin carries the secret. Never add it to SQL, argv or the diagnostic log.
  printf '%s\n' "$clone_password" | sql -s -name "$admin_connection" "@$MC_FENCED_SCRIPT" > "$output" 2>&1 || status=$?
  unset clone_password
  if [[ "$status" -ne 0 ]] || grep -Eq 'ORA-[0-9]+|PLS-[0-9]+|SP2-[0-9]+' "$output" ||
     ! grep -Fq "Connection $target_connection has been cloned" "$output"; then
    echo 'Unable to save the connection. Sensitive SQLcl output suppressed.' >&2
    grep -Eo 'ORA-[0-9]+|PLS-[0-9]+|SP2-[0-9]+' "$output" | sort -u >&2 || true
    rm -f -- "$output"
    fail 'Connection creation did not complete; preserve the journal for recovery.'
  fi
  rm -f -- "$output"
  echo "Connection $target_connection saved."
}

initial_builder_prepare() {
  cat > "$tmp/initial-builder-check.sql" <<SQL
whenever oserror exit failure rollback
whenever sqlerror exit sql.sqlcode rollback
set define off
set serveroutput on
declare disabled varchar2(4000);
begin
  disabled:=upper(regexp_replace(nvl(apex_instance_admin.get_parameter('DISABLE_APPS_LOGIN'),'N'),'[[:space:]]',''));
  if disabled='Y' or instr(','||disabled||',',',$target_id,')>0 then
    raise_application_error(-20080,'APEX application login is disabled for the target application; ask the APEX administrator to review');
  end if;
  if '$workspace_mode'='CREATE' and nvl(apex_instance_admin.get_parameter('DISABLE_WORKSPACE_LOGIN'),'N')='Y' then
    raise_application_error(-20080,'APEX Builder login is disabled; ask the APEX administrator to review');
  end if;
  dbms_output.put_line('MC_INITIAL_BUILDER|'||nvl(apex_instance_admin.get_parameter('APEX_BUILDER_AUTHENTICATION'),'APEX'));
end;
/
exit success
SQL
  run_sqlcl_capture 'Builder authentication preflight' "$admin_connection" "$tmp/initial-builder-check.sql" 'read-only Builder authentication' "$tmp/initial-builder-check.out"
  builder_auth="$(sed -n 's/^MC_INITIAL_BUILDER|//p' "$tmp/initial-builder-check.out" | tr -d '\r')"
  if [[ "$workspace_mode" == EXISTING ]]; then
    echo 'Existing workspace: Builder authentication and administrator accounts are preserved.'
    return
  fi
  printf 'Builder authentication: %s\n' "$builder_auth" >> "$log"
  case "$builder_auth" in
    APEX) echo 'APEX Builder uses local accounts. Choose a workspace administrator username.' ;;
    SOCIAL|SAML|SSO|HEADER)
      echo 'APEX Builder uses single sign-on. Enter your SSO username.' ;;
    LDAP) echo 'APEX Builder uses directory accounts. Enter your directory username.' ;;
    DB) echo 'APEX Builder uses database accounts. Enter an existing database username.' ;;
    ADB)
      echo 'APEX Builder uses Autonomous Database sign-in with a database username and database password.'
      echo "Use $schema (the new schema account), or an existing database account. This is separate from application login."
      ;;
    *) fail 'Unrecognized Builder authentication; ask the APEX administrator to review before provisioning' ;;
  esac
  if [[ -z "$workspace_admin" ]]; then
    if [[ "$builder_auth" == ADB ]]; then
      read -r -p "Workspace administrator username [$schema]: " workspace_admin || fail 'Workspace administrator entry cancelled'
      workspace_admin="${workspace_admin:-$schema}"
    else
      read -r -p 'Workspace administrator username: ' workspace_admin || fail 'Workspace administrator entry cancelled'
    fi
  fi
  initial_builder_validate
  if [[ "$builder_auth" == ADB || "$builder_auth" == DB ]]; then
    workspace_admin="$(printf '%s' "$workspace_admin" | tr '[:lower:]' '[:upper:]')"
    if [[ "$workspace_admin" != "$schema" ]]; then
      cat > "$tmp/initial-builder-identity.sql" <<SQL
whenever oserror exit failure rollback
whenever sqlerror exit sql.sqlcode rollback
set define off
declare n number;
begin
  select count(*) into n from dba_users where username='$workspace_admin'
    and account_status='OPEN' and authentication_type='PASSWORD';
  if n<>1 then raise_application_error(-20080,'Builder identity must be an existing open password-authenticated database account, or the new target schema'); end if;
  select count(*) into n from dba_sys_privs where privilege='CREATE SESSION'
    and (grantee in ('$workspace_admin','PUBLIC') or grantee in (
      select granted_role from dba_role_privs
      start with grantee='$workspace_admin' and default_role='YES'
      connect by nocycle prior granted_role=grantee));
  if n=0 then raise_application_error(-20080,'Existing Builder database account requires CREATE SESSION; no privileges were changed'); end if;
end;
/
exit success
SQL
      run_sqlcl_capture 'Builder database identity preflight' "$admin_connection" "$tmp/initial-builder-identity.sql" 'read-only Builder database identity' "$tmp/initial-builder-identity.out"
    fi
  fi
  if [[ "$builder_auth" == APEX ]]; then
    initial_secret "New Builder password for $workspace_admin"
    builder_secret_hex="$secret_hex"
    unset secret_hex
  fi
}

initial_builder_validate() {
  if [[ "${builder_auth:-}" == ADB || "${builder_auth:-}" == DB ]]; then
    [[ "$workspace_admin" =~ ^[A-Za-z][A-Za-z0-9_\$#]{0,127}$ ]] || fail 'Database Builder identity must be an unquoted database username (up to 128 characters)'
  elif [[ -z "${builder_auth:-}" && "$workspace_admin" =~ ^[A-Za-z][A-Za-z0-9_\$#]{0,127}$ ]]; then
    : # Early argument validation; provider-specific validation follows discovery.
  else
    [[ "$workspace_admin" =~ ^[A-Za-z0-9][A-Za-z0-9_.@+-]{0,99}$ ]] || fail 'Workspace administrator must be 1–100 letters, digits, _, ., @, + or -'
  fi
  [[ "$(printf '%s' "$workspace_admin" | tr '[:lower:]' '[:upper:]')" != "$first_admin" ]] || fail 'Builder administrator must differ from the local app administrator'
}

initial_builder_create() {
  [[ "$workspace_mode" == CREATE ]] || return 0
  # The receipted newly created workspace owns this account as a unit. Recovery
  # removes that workspace, never accounts from pre-existing workspaces.
  local password_sql="'Mc9!'||rawtohex(dbms_crypto.randombytes(32))"
  if [[ "$builder_auth" == APEX ]]; then
    password_sql="utl_i18n.raw_to_char(hextoraw('$builder_secret_hex'),'AL32UTF8')"
  fi
  cat > "$tmp/initial-builder-create.sql" <<SQL
whenever oserror exit failure rollback
whenever sqlerror exit sql.sqlcode rollback
set define off
set verify off
set echo off
set serveroutput on
declare n number; ws number;
begin
  if nvl(apex_instance_admin.get_parameter('APEX_BUILDER_AUTHENTICATION'),'APEX')<>'$builder_auth' then
    raise_application_error(-20080,'Builder authentication changed since preflight');
  end if;
  ws:=apex_util.find_security_group_id(p_workspace=>'$workspace');
  if nvl(ws,-1)<>$(sed -n 's/^WORKSPACE|//p' "$journal_directory/events" | tail -1) then
    raise_application_error(-20080,'New workspace ownership changed');
  end if;
  apex_util.set_security_group_id(ws);
  select count(*) into n from apex_workspace_apex_users where workspace_id=ws and upper(user_name)=upper('$workspace_admin');
  if n<>0 then raise_application_error(-20080,'Builder account already exists; refusing to change it'); end if;
  apex_util.create_user(p_user_name=>'$workspace_admin',
    p_web_password=>$password_sql,
    p_developer_privs=>'ADMIN:CREATE:DATA_LOADER:EDIT:HELP:MONITOR:SQL',
    p_default_schema=>'$schema',p_allow_access_to_schemas=>'$schema',
    p_account_locked=>'N',p_change_password_on_first_use=>'N',
    p_allow_app_building_yn=>'Y',p_allow_sql_workshop_yn=>'Y');
  select count(*) into n from apex_workspace_apex_users where workspace_id=ws
    and upper(user_name)=upper('$workspace_admin') and is_admin='Yes'
    and is_application_developer='Yes' and account_locked='No';
  if n<>1 then raise_application_error(-20080,'Workspace administrator creation was not confirmed'); end if;
  commit;
end;
/
prompt MC_INITIAL_SENSITIVE_OK
exit success
SQL
  unset builder_secret_hex password_sql
  initial_sensitive_sql 'workspace administrator creation' "$admin_connection" "$tmp/initial-builder-create.sql"
  echo 'Workspace administrator created.'
}

initial_sensitive_sql() {
  local label="$1" saved="$2" script="$3" output="$tmp/sensitive.out" status=0
  local original_script="$script"
  initial_lock_check || fail 'INITIAL coordination session was lost'
  initial_fence_script "$script" || fail 'Cannot prepare fenced sensitive operation'
  script="$MC_FENCED_SCRIPT"
  sql -name "$saved" "@$script" > "$output" 2>&1 || status=$?
  if [[ "$label" == 'schema creation' ]]; then
    initial_receipt SCHEMA "$output" || true
  else
    local receipt_kind
    for receipt_kind in APEX_USER GROUP_ADMIN GROUP_CONTRIBUTOR GROUP_USER; do
      initial_receipt "$receipt_kind" "$output" || true
    done
  fi
  if [[ "$status" -ne 0 ]] || grep -Eq 'ORA-[0-9]+|PLS-[0-9]+|SP2-[0-9]+' "$output" ||
     ! grep -Fqx 'MC_INITIAL_SENSITIVE_OK' "$output"; then
    # SQLcl echoes failing PL/SQL, even with ECHO OFF. Do not use the normal
    # full-output reporter for any script containing a password.
    echo "FAILED $label. Sensitive SQL output suppressed. Oracle error codes:" >&2
    grep -Eo 'ORA-[0-9]+|PLS-[0-9]+|SP2-[0-9]+' "$output" | sort -u >&2 || true
    rm -f -- "$script" "$original_script" "$output"
    fail "$label did not complete; cleanup will use only confirmed ownership receipts."
  fi
  rm -f -- "$script" "$original_script" "$output"
}

initial_write_package_check() {
  cat > "$1" <<'SQL'
declare
  procedure require_package(p_name varchar2) is
    l_owner varchar2(128); l_part1 varchar2(128); l_part2 varchar2(128);
    l_dblink varchar2(128); l_type number; l_object_id number; l_count number;
  begin
    -- Resolve as ADMIN would call it: private/public synonym chains and
    -- authorization belong to Oracle, not a literal-name dictionary search.
    dbms_utility.name_resolve(p_name,1,l_owner,l_part1,l_part2,l_dblink,l_type,l_object_id);
    if l_dblink is not null or nvl(l_type,-1)<>9 or l_object_id is null then
      raise_application_error(-20080,'Required name does not resolve to a local package: '||p_name);
    end if;
    select count(*) into l_count from dba_objects
      where object_id=l_object_id and owner=l_owner and object_name=l_part1
        and object_type='PACKAGE' and status='VALID';
    if l_count<>1 then
      raise_application_error(-20080,'Resolved package is not VALID: '||p_name||' -> '||l_owner||'.'||l_part1);
    end if;
    select count(*) into l_count from dba_objects
      where owner=l_owner and object_name=l_part1 and object_type='PACKAGE BODY' and status<>'VALID';
    if l_count<>0 then
      raise_application_error(-20080,'Resolved package body is not VALID: '||p_name||' -> '||l_owner||'.'||l_part1);
    end if;
    dbms_output.put_line('MC_INITIAL_PACKAGE '||p_name||' -> '||l_owner||'.'||l_part1||' VALID');
  exception when others then
    raise_application_error(-20080,substr('Required database package unavailable: '||p_name||'; '||sqlerrm,1,1900));
  end;
begin
  for p in (select column_value name from table(sys.odcivarchar2list('DBMS_CLOUD','DBMS_CLOUD_ADMIN','DBMS_AUTO_INDEX'))) loop
    require_package(p.name);
  end loop;
end;
/
SQL
}

initial_provision() {
  initial_database_choice || fail 'Database selection was not completed'
  if [[ "$dry" == Y ]]; then
    echo "DRY-RUN: would check database/APEX versions, ADMIN access, tablespaces, scheduler, indexing policy, schema/workspace/app/account collisions."
    echo "DRY-RUN: would create empty schema $schema with schema-only rights, apply prerequisites authorized by database mode or approval, map $workspace and clone $admin_connection as $target_connection."
    echo 'DRY-RUN: would detect Builder authentication and bootstrap a separate administrator only for a newly created workspace; no SSO password is collected.'
    echo 'DRY-RUN: would inspect DEFAULT password lifetime and optionally ask to disable expiry for all accounts using that profile (default No, including NEW).'
    if [[ "$database_mode" == NEW ]]; then
      echo 'DRY-RUN: NEW would automatically configure missing indexing/resource principal, including an enable/disable/re-enable cycle for an uninitialized resource principal. No database-occupancy check or additional prerequisite approval is required.'
    else
      echo 'DRY-RUN: EXISTING would inspect shared prerequisites and request separate approval for missing indexing/resource principal; existing shared-database protections remain in effect.'
    fi
    return
  fi
  initial_journal_open
  initial_connection_absent
  initial_lock_open || fail 'INITIAL coordination failed; inspect the SQLcl diagnostic above'
  local grant_owner grant_object grant_privilege
  printf '%s\n' 'declare n number; begin null;' > "$tmp/initial-object-check.sql"
  while IFS='|' read -r grant_owner grant_object grant_privilege || [[ -n "$grant_owner${grant_object:-}${grant_privilege:-}" ]]; do
    # The ZIP validator has already restricted identifiers/privileges.
    # initial-package-check resolves DBMS_CLOUD on this database, including
    # a source-specific physical package name, if present in the inventory.
    if [[ "$grant_owner|$grant_privilege" == 'C##CLOUD$SERVICE|EXECUTE' &&
          ( "$grant_object" == DBMS_CLOUD || "$grant_object" =~ ^DBMS_CLOUD\$PDBCS_[A-Z0-9_]+$ ) ]]; then
      continue
    fi
    printf "  select count(*) into n from dba_objects where owner=upper('%s') and object_name=upper('%s') and status='VALID';\n" "$grant_owner" "$grant_object" >> "$tmp/initial-object-check.sql"
    printf "  if n=0 then raise_application_error(-20080,'Source-required object unavailable: %s.%s; review database/APEX version and grants.'); end if;\n" "$grant_owner" "$grant_object" >> "$tmp/initial-object-check.sql"
  done < "$tmp/content/db/preflight/required_privileges.txt"
  printf '%s\n' 'end;' '/' >> "$tmp/initial-object-check.sql"
  initial_write_package_check "$tmp/initial-package-check.sql"
  cat > "$tmp/initial-check.sql" <<SQL
whenever oserror exit failure rollback
whenever sqlerror exit sql.sqlcode rollback
set define off
set verify off
set echo off
set serveroutput on
@$tmp/initial-package-check.sql
declare n number;
begin
 select count(*) into n from dba_tab_columns where owner='SYS' and table_name='DBA_AUTO_INDEX_CONFIG' and column_name='PARAMETER_VALUE_CLOB';
 if n<>1 then raise_application_error(-20080,'INITIAL safety checks require DBA_AUTO_INDEX_CONFIG.PARAMETER_VALUE_CLOB (23.7+).'); end if;
end;
/
declare
  n number; ws number; v varchar2(4000); fingerprint varchar2(64);
begin
  if user <> 'ADMIN' then raise_application_error(-20080,'INITIAL requires the Autonomous Database ADMIN connection.'); end if;
  if dbms_db_version.version < 23 then raise_application_error(-20080,'INITIAL requires Oracle Database 23ai/26ai or later.'); end if;
  select version_no into v from apex_release;
  if to_number(regexp_substr(v,'^[0-9]+')) < 26 or
     (to_number(regexp_substr(v,'^[0-9]+')) = 26 and to_number(regexp_substr(v,'[0-9]+',1,2)) < 1) then
    raise_application_error(-20080,'INITIAL requires APEX 26.1 or later.');
  end if;
  select count(*) into n from dba_registry where comp_id='APEX' and status='VALID';
  if n<>1 then raise_application_error(-20080,'APEX database component is not VALID.'); end if;
  select count(*) into n from dba_directories where directory_name='DATA_PUMP_DIR';
  if n<>1 then raise_application_error(-20080,'DATA_PUMP_DIR is required for ingestion.'); end if;
  select count(*) into n from dba_tablespaces where tablespace_name='$data_ts' and contents='PERMANENT' and status='ONLINE';
  if n<>1 then raise_application_error(-20080,'Requested permanent tablespace is unavailable.'); end if;
  select count(*) into n from dba_tablespaces where tablespace_name='$temp_ts' and contents='TEMPORARY' and status='ONLINE';
  if n<>1 then raise_application_error(-20080,'Requested temporary tablespace is unavailable.'); end if;
  select value into v from v\$parameter where name='job_queue_processes';
  if to_number(v)=0 then raise_application_error(-20080,'Scheduler is disabled at database level; DBA review required.'); end if;
  -- Shared prerequisites are authorized by NEW or separately approved for EXISTING after collision checks.
  select count(*) into n from all_users where username='$schema';
  if n<>0 then raise_application_error(-20080,'Refusing INITIAL: target schema already exists.'); end if;
  select count(*) into n from apex_applications where application_id=$target_id;
  if n<>0 then raise_application_error(-20080,'Refusing INITIAL: application ID already exists in this database.'); end if;
  ws:=apex_util.find_security_group_id(p_workspace=>'$workspace');
  if '$workspace_mode'='CREATE' and ws is not null then raise_application_error(-20081,'Refusing INITIAL: workspace already exists.'); end if;
  if '$workspace_mode'='EXISTING' and ws is null then raise_application_error(-20082,'Refusing INITIAL: workspace does not exist.'); end if;
  if ws is not null then
    apex_util.set_security_group_id(ws);
    select count(*) into n from apex_workspace_apex_users where workspace_id=ws and upper(user_name)='$first_admin';
    if n<>0 then raise_application_error(-20083,'First administrator already exists; choose a new account. Existing accounts are never changed.'); end if;
  end if;
  select rawtohex(standard_hash(sys_context('USERENV','DB_UNIQUE_NAME')||chr(10)||sys_context('USERENV','CON_NAME'),'SHA256')) into fingerprint from dual;
  dbms_output.put_line('MC_INITIAL_DB|'||fingerprint);
  select limit into v from dba_profiles where profile='DEFAULT' and resource_name='PASSWORD_LIFE_TIME' and resource_type='PASSWORD';
  dbms_output.put_line('MC_PASSWORD_LIFE|'||v);
end;
/
@$tmp/initial-object-check.sql
prompt MC_INITIAL_CHECK_OK
exit success
SQL
  run_sqlcl_capture "INITIAL database preflight" "$admin_connection" "$tmp/initial-check.sql" "read-only INITIAL checks" "$tmp/initial-check.out"
  grep -Fqx 'MC_INITIAL_CHECK_OK' "$tmp/initial-check.out" || fail "INITIAL preflight did not confirm success"
  local database_fingerprint
  database_fingerprint="$(sed -n 's/^MC_INITIAL_DB|//p' "$tmp/initial-check.out" | tr -d '\r')"
  [[ "$database_fingerprint" =~ ^[0-9A-F]{64}$ ]] || fail "ADMIN database identity was not confirmed"
  initial_event "DATABASE|$database_fingerprint"
  initial_snapshot "$journal_directory/shared-before" || fail 'Cannot snapshot shared prerequisites'
  initial_event "SNAPSHOT|$(mc_bundle_sha256_file "$journal_directory/shared-before")"
  initial_prerequisites_prepare || fail 'Database prerequisites were not approved'
  initial_password_profile_prepare || fail 'Database password policy could not be reviewed'
  initial_builder_prepare
  initial_secret "Create a local application password for $first_admin"
  initial_app_secret_hex="$secret_hex"
  unset secret_hex
  initial_app_email
  initial_secret "Create a database password for $schema"
  initial_database_secret_hex="$secret_hex"
  MC_INITIAL_INPUTS_COMPLETE=Y
  initial_revision_inspect
  cat > "$tmp/schema-create.sql" <<SQL
whenever oserror exit failure rollback
whenever sqlerror exit sql.sqlcode rollback
set define off
set verify off
set echo off
set serveroutput on
declare
  p varchar2(512):=utl_i18n.raw_to_char(hextoraw('$secret_hex'),'AL32UTF8');
  n number;
begin
  execute immediate 'create user "$schema" identified by "'||replace(p,'"','""')||'" default tablespace "$data_ts" temporary tablespace "$temp_ts"';
  select user_id into n from dba_users where username='$schema';
  dbms_output.put_line('MC_INITIAL_SCHEMA|'||to_char(n,'TM9'));
end;
/
alter user "$schema" quota unlimited on "$data_ts";
prompt MC_INITIAL_SENSITIVE_OK
exit success
SQL
  unset secret_hex
  initial_password_profile_apply || fail 'Database password policy change unconfirmed; review ADMIN settings and journal'
  initial_event INTENT_SCHEMA
  initial_sensitive_sql "schema creation" "$admin_connection" "$tmp/schema-create.sql"
  grep -q '^SCHEMA|' "$journal_directory/events" || fail 'Schema creation receipt missing'
  initial_prerequisites_apply || fail 'Database prerequisite setup failed; preserve the journal for review'
  initial_verify_shared || fail 'Shared prerequisites changed before schema rights'
  if grep -q '^MC_STATE|INDEX_SCOPE|IN|' "$journal_directory/shared-before" &&
     grep -qx 'MC_STATE|INDEX_TARGET|ABSENT' "$journal_directory/shared-before"; then
    initial_index_change ADD || fail 'Target indexing enrollment failed; preserve the journal for recovery'
  fi
  run_sqlcl_capture "schema rights" "$admin_connection" "$admin_rights_script" "target_admin_schema_rights.sql" "$tmp/schema-rights.out" "$schema"
  cat > "$tmp/workspace-apply.sql" <<SQL
whenever oserror exit failure rollback
whenever sqlerror exit sql.sqlcode rollback
set define off
set verify off
set echo off
set serveroutput on
begin
  if '$workspace_mode'='CREATE' then
    apex_instance_admin.add_workspace(p_workspace=>'$workspace',p_primary_schema=>'$schema');
  else
    apex_instance_admin.add_schema(p_workspace=>'$workspace',p_schema=>'$schema');
  end if;
  commit;
  dbms_output.put_line('MC_INITIAL_WORKSPACE|'||to_char(apex_util.find_security_group_id(p_workspace=>'$workspace'),'TM9'));
  apex_util.set_security_group_id(apex_util.find_security_group_id(p_workspace=>'$workspace'));
  for r in (select apex_util.get_user_id(user_name) user_id from apex_workspace_apex_users where workspace_id=apex_util.find_security_group_id(p_workspace=>'$workspace')) loop
    dbms_output.put_line('MC_INITIAL_BASE_USER|'||to_char(r.user_id,'TM9'));
  end loop;
  for r in (select apex_util.get_group_id(group_name) group_id from apex_workspace_groups where workspace_id=apex_util.find_security_group_id(p_workspace=>'$workspace')) loop
    dbms_output.put_line('MC_INITIAL_BASE_GROUP|'||to_char(r.group_id,'TM9'));
  end loop;
end;
/
exit success
SQL
  initial_event INTENT_WORKSPACE
  run_sqlcl_capture "workspace mapping" "$admin_connection" "$tmp/workspace-apply.sql" "workspace mapping" "$tmp/workspace-apply.out"
  initial_receipt WORKSPACE "$tmp/workspace-apply.out" || fail 'Workspace creation receipt missing'
  local baseline_kind baseline_value
  while IFS='|' read -r baseline_kind baseline_value; do
    [[ "$baseline_value" =~ ^[0-9]+$ ]] || fail 'Invalid workspace baseline receipt'
    initial_event "${baseline_kind#MC_INITIAL_}|$baseline_value"
  done < <(grep -E '^MC_INITIAL_BASE_(USER|GROUP)\|' "$tmp/workspace-apply.out" || true)
  initial_builder_create
  initial_connection_absent
  initial_connection_replace
  initial_event INTENT_CONNECTION
  printf '%s\n' 'set feedback off' "connmgr clone -original $admin_connection -username $schema $target_connection" 'exit success' > "$tmp/clone-connection.sql"
  initial_lock_check || fail 'INITIAL coordination session was lost'
  initial_fence_script "$tmp/clone-connection.sql" || fail 'Cannot prepare fenced connection creation'
  initial_clone_connection
  local connection_hash
  connection_hash="$(initial_connection_hash)" || fail 'Cannot fingerprint new saved connection'
  initial_event "CONNECTION|$connection_hash"
  cat > "$tmp/initial-identity.sql" <<SQL
whenever oserror exit failure rollback
whenever sqlerror exit sql.sqlcode rollback
set define off
set verify off
set echo off
set serveroutput on
declare n number; fingerprint varchar2(64);
begin
  if user<>'$schema' then raise_application_error(-20080,'Cloned connection has the wrong schema.'); end if;
  select rawtohex(standard_hash(sys_context('USERENV','DB_UNIQUE_NAME')||chr(10)||sys_context('USERENV','CON_NAME'),'SHA256')) into fingerprint from dual;
  if fingerprint<>'$database_fingerprint' then raise_application_error(-20080,'Cloned connection points to a different database/container.'); end if;
  select count(*) into n from user_objects;
  if n<>0 then raise_application_error(-20080,'INITIAL connection is not an empty schema.'); end if;
  if apex_util.find_security_group_id(p_workspace=>'$workspace') is null then
    raise_application_error(-20080,'New workspace is unavailable to target connection.');
  end if;
  dbms_output.put_line('MC_INITIAL_IDENTITY_OK');
end;
/
exit success
SQL
  run_sqlcl_capture "new schema identity" "$connection" "$tmp/initial-identity.sql" "new schema identity" "$tmp/initial-identity.out"
  grep -Fqx 'MC_INITIAL_IDENTITY_OK' "$tmp/initial-identity.out" || fail "new schema connection identity was not confirmed"
  if [[ -n "$prerequisites" ]]; then
    run_sqlcl_capture "additional prerequisites" "$admin_connection" "$prerequisites" "$prerequisites" "$tmp/additional-prerequisites.out"
  fi
  # INITIAL authorizes only the reviewed, missing release requirements. Never
  # execute arbitrary archive-supplied SQL as ADMIN.
  local apply_missing_grants=Y
  mc_grants_local
}

initial_access() {
  if [[ "$dry" == Y ]]; then
    echo "DRY-RUN initial-access: would create local end-user $first_admin, native groups and a protected administrator in workspace $target_workspace / app $target_id."
    return
  fi
  cat > "$tmp/initial-readiness.sql" <<SQL
whenever oserror exit failure rollback
whenever sqlerror exit sql.sqlcode rollback
set define off
set verify off
set serveroutput on
declare n number;
begin
  if nvl(deploy_mgr_pkg.runtime_contract,'missing')<>'$contract' then
    raise_application_error(-20093,'INITIAL deployment runtime version does not match the release.');
  end if;
  for p in (select column_value name from table(sys.odcivarchar2list(
    'DEPLOY_MGR_PKG','APPLICATION_BUNDLES_AJAX_PKG','MC_SETUP_CONFIG_PKG','MC_SETUP_PKG',
    'INITIAL_LOAD_PKG','OCI_AVAILABILITY_METRICS_PKG','APP_ACCESS_CONTEXT_PKG',
    'APP_ACCESS_IDENTITY_PKG','APP_ACCESS_LIFECYCLE_PKG','APP_ACCESS_ADMIN_PKG',
    'APP_ACCESS_AJAX_PKG','APP_ACCESS_PENDING_PKG','APP_AUTHORIZATION_PKG'))) loop
    select count(*) into n from user_objects where object_name=p.name
      and object_type in ('PACKAGE','PACKAGE BODY') and status='VALID';
    if n<>2 then raise_application_error(-20093,'INITIAL requires valid specification and body: '||p.name||'; inspect USER_ERRORS.'); end if;
  end loop;
  select count(*) into n from user_scheduler_jobs where enabled='TRUE';
  if n<>0 then raise_application_error(-20093,'INITIAL left scheduler jobs enabled.'); end if;
end;
/
exit success
SQL
  run_sqlcl_capture "INITIAL setup/access readiness" "$connection" "$tmp/initial-readiness.sql" "initial readiness" "$tmp/initial-readiness.out"
  [[ -n "${initial_app_secret_hex:-}" ]] || fail 'Application password was not collected during preparation'
  [[ -n "${initial_app_email_hex:-}" ]] || fail 'Application administrator email was not collected during preparation'
  progress_start initial-access
  cat > "$tmp/initial-access.sql" <<SQL
whenever oserror exit failure rollback
whenever sqlerror exit sql.sqlcode rollback
set define off
set verify off
set echo off
set serveroutput on
declare
  c app_access_context_pkg.t_context;
  n number; l_user_id number; l_realm_id number; l_principal_id number; group_id number;
begin
  apex_util.set_security_group_id(apex_util.find_security_group_id(p_workspace=>'$target_workspace'));
  c:=app_access_context_pkg.resolve;
  if c.provider_code<>'APEX_ACCOUNTS' or c.application_id<>$target_id then
    raise_application_error(-20080,'INITIAL access requires the imported native target application.');
  end if;
  select count(*) into n from app_access_realms;
  if n<>0 then raise_application_error(-20080,'Access realms already exist; refusing bootstrap.'); end if;
  select count(*) into n from apex_workspace_apex_users where workspace_id=c.workspace_id and upper(user_name)='$first_admin';
  if n<>0 then raise_application_error(-20080,'First administrator account already exists; refusing changes.'); end if;
  select count(*) into n from fr_authz_groups where
    (group_code='ADMIN' and apex_group='Administrators') or
    (group_code='CONTRIBUTOR' and apex_group='Contributors') or
    (group_code='USER' and apex_group='Users');
  if n<>3 then raise_application_error(-20080,'Release native role mappings are incomplete.'); end if;
  for g in (select column_value name from table(sys.odcivarchar2list('Administrators','Contributors','Users'))) loop
    group_id:=apex_util.get_group_id(p_group_name=>g.name);
    if group_id is null then
      apex_util.create_user_group(p_group_name=>g.name);
      dbms_output.put_line('MC_INITIAL_GROUP_'||case g.name when 'Administrators' then 'ADMIN' when 'Contributors' then 'CONTRIBUTOR' else 'USER' end||'|'||to_char(apex_util.get_group_id(g.name),'TM9'));
    end if;
  end loop;
  apex_util.create_user(p_user_name=>'$first_admin',
    p_email_address=>utl_i18n.raw_to_char(hextoraw('$initial_app_email_hex'),'AL32UTF8'),
    p_web_password=>utl_i18n.raw_to_char(hextoraw('$initial_app_secret_hex'),'AL32UTF8'),
    p_group_ids=>to_char(apex_util.get_group_id('Administrators')),
    p_developer_privs=>null,p_account_locked=>'N',p_change_password_on_first_use=>'N',
    p_allow_app_building_yn=>'N',p_allow_sql_workshop_yn=>'N',
    p_allow_websheet_dev_yn=>'N',p_allow_team_development_yn=>'N');
  l_user_id:=apex_util.get_user_id(p_username=>'$first_admin');
  dbms_output.put_line('MC_INITIAL_APEX_USER|'||to_char(l_user_id,'TM9'));
  select count(*) into n from apex_workspace_apex_users
    where workspace_id=c.workspace_id and user_name='$first_admin'
      and is_admin='No' and is_application_developer='No' and account_locked='No';
  if n<>1 then raise_application_error(-20080,'Bootstrap account is not an unlocked end-user without workspace privileges.'); end if;
  if l_user_id is null or app_access_lifecycle_pkg.native_role(to_char(l_user_id,'TM9'))<>'ADMIN' then
    raise_application_error(-20080,'Native administrator group membership was not established.');
  end if;
  insert into app_access_realms(workspace_id,application_id,authentication_scheme_id,provider_code,realm_key,state)
    values(c.workspace_id,c.application_id,c.authentication_scheme_id,'APEX_ACCOUNTS',standard_hash('APEX_ACCOUNTS','SHA256'),'ACTIVE') returning realm_id into l_realm_id;
  insert into app_access_principals(realm_id,provider_subject,display_name,bootstrap,observed_role,observed_at)
    values(l_realm_id,to_char(l_user_id,'TM9'),'$first_admin','Y','ADMIN',systimestamp) returning principal_id into l_principal_id;
  insert into app_access_audit(realm_id,actor_id,subject_id,event_code,after_state)
    values(l_realm_id,l_principal_id,l_principal_id,'INITIAL_BOOTSTRAP',json_object('role' value 'ADMIN','provider' value 'APEX_ACCOUNTS'));
  merge into app_config t using (select 'FIRST_SETUP_RUN' k,'Y' v from dual) s on(t.config_key=s.k)
    when matched then update set t.config_value=s.v when not matched then insert(config_key,config_value) values(s.k,s.v);
  commit;
end;
/
prompt MC_INITIAL_SENSITIVE_OK
exit success
SQL
  unset initial_app_secret_hex initial_app_email_hex
  MC_ACCESS_ATTEMPTED=1
  initial_event INTENT_ACCESS
  initial_sensitive_sql "initial administrator access" "$connection" "$tmp/initial-access.sql"
  progress_done initial-access
}

# Product statements are one native Oracle unit. The archive gate has already
# verified their bytes and plan; wrapping avoids SQLcl interpreting payload text.
initial_product_statement() {
  local member="$1" ordinal="$2" script="$tmp/product-unit-$ordinal.sql" encoded="$tmp/product-unit-$ordinal.b64" chunk
  local expected actual
  expected="$(awk -v path="$member" '$2==path {print $1}' "$tmp/content/checksums.sha256")"
  actual="$(mc_bundle_sha256_file "$tmp/content/$member")"
  [[ "$expected" =~ ^[0-9a-f]{64}$ && "$actual" == "$expected" ]] || fail 'Product statement changed after archive inspection'
  (set -o pipefail; base64 < "$tmp/content/$member" | tr -d '\r\n' | fold -w 4000) > "$encoded" || fail 'Product statement encoding failed'
  printf '%s\n' 'whenever sqlerror exit failure rollback' 'whenever oserror exit failure rollback' 'set define off' \
    'declare bytes_value blob; text_value clob; r raw(32767); c integer; n integer; d integer:=1; s integer:=1; ctx integer:=0; w integer;' \
    'begin dbms_lob.createtemporary(bytes_value,true);' > "$script"
  while IFS= read -r chunk || [[ -n "$chunk" ]]; do
    [[ "$chunk" =~ ^[A-Za-z0-9+/]+={0,2}$ && ${#chunk} -le 4000 ]] || fail 'Invalid product statement encoding'
    printf "r:=utl_encode.base64_decode(utl_raw.cast_to_raw('%s')); dbms_lob.writeappend(bytes_value,utl_raw.length(r),r);\n" "$chunk" >> "$script"
  done < "$encoded"
  cat >> "$script" <<'SQL'
 dbms_lob.createtemporary(text_value,true);
 dbms_lob.converttoclob(text_value,bytes_value,dbms_lob.lobmaxsize,d,s,nls_charset_id('AL32UTF8'),ctx,w);
 if w<>0 then raise_application_error(-20175,'Product payload encoding is invalid.'); end if;
 c:=dbms_sql.open_cursor; dbms_sql.parse(c,text_value,dbms_sql.native); n:=dbms_sql.execute(c); dbms_sql.close_cursor(c);
 dbms_lob.freetemporary(bytes_value); dbms_lob.freetemporary(text_value);
end;
/
SQL
  if [[ "${MC_INITIAL_RENDER_ONLY:-N}" == Y ]]; then MC_INITIAL_RENDERED_SCRIPT="$script";
  else run_script "product-unit-$ordinal" "$script"; fi
}

initial_product_definition_early() {
  [[ "$mode" == INITIAL && "$contract" == mc-bundle-1.13.0 ]] || return 0
  if [[ "$dry" == Y ]]; then echo 'DRY-RUN: would install or verify the two inventory-bound definition helper units before storage'; return 0; fi
  local script="$tmp/product-definition-early.sql" output="$tmp/product-definition-early.out" count
  printf '%s\n' 'whenever sqlerror exit failure rollback' 'whenever oserror exit failure rollback' 'set define off serveroutput on size unlimited' \
    > "$script"
  initial_archive_stage TARGET "$connection" early_zip "$script"
  printf '%s\n' 'prompt MC_INITIAL_DEFINITION_INSTALLING' >> "$script"
  printf '%s\n' 'declare' >> "$script"
  mc_archive_inspector_sql >> "$script"
  mc_product_definition_early_sql >> "$script"
  printf "begin install_product_definition(:early_zip,'%s');\n" "$bundle_hash" >> "$script"
  cat >> "$script" <<SQL
declare
  members t_members; bytes blob; manifest clob; doc json_object_t; bid number; rid number; app number; ver varchar2(64);
  d integer:=1; s integer:=1; ctx integer:=0; w integer;
  coverage clob; doc_coverage json_object_t; entries json_array_t; bindings json_array_t; item json_object_t; ident json_object_t; binding json_object_t;
  statement_text clob; c integer; ignored integer; table_count number:=0; found_count number; table_name_value varchar2(128);
  function text_member(name_value varchar2) return clob is
    b blob; t clob; dest integer:=1; src integer:=1; context_value integer:=0; warning integer;
  begin
    for j in 1..members.count loop
      if members(j).name=name_value then
        b:=get_member(:early_zip,members(j));dbms_lob.createtemporary(t,true);
        dbms_lob.converttoclob(t,b,dbms_lob.lobmaxsize,dest,src,nls_charset_id('AL32UTF8'),context_value,warning);
        dbms_lob.freetemporary(b);
        if warning<>0 then raise_application_error(-20175,'INITIAL metadata encoding is invalid'); end if;
        return t;
      end if;
    end loop;
    raise_application_error(-20175,'INITIAL tracking payload is missing');
  end;
SQL
  cat >> "$script" <<SQL
begin
  zip_inspect(:early_zip,members);
  -- The helpers are installed first. Retain the archive using exactly the two
  -- canonical tracking-table payloads; their keys are installed later in order.
  coverage:=text_member('db/deploy/product-coverage.json');doc_coverage:=json_object_t.parse(coverage);
  entries:=doc_coverage.get_object('inventory').get_array('entries');bindings:=doc_coverage.get_array('bindings');
  for pass in 1..2 loop
    table_name_value:=case pass when 1 then 'DEPLOY_BUNDLES' else 'DEPLOY_RUNS' end;found_count:=0;
    for i in 0..entries.get_size-1 loop
      item:=treat(entries.get(i) as json_object_t);ident:=item.get_object('identity');
      if ident.get_string('object_type')='TABLE' and ident.get_string('object_name')=table_name_value
        and item.get_string('lifecycle')='BOOTSTRAP' and item.get_string('state')='PRESENT' then
        for j in 0..bindings.get_size-1 loop
          binding:=treat(bindings.get(j) as json_object_t);
          if binding.get_string('key')=item.get_string('key') and binding.get_string('action')='STORAGE' then
            statement_text:=text_member(binding.get_string('member'));
            c:=dbms_sql.open_cursor;dbms_sql.parse(c,statement_text,dbms_sql.native);ignored:=dbms_sql.execute(c);dbms_sql.close_cursor(c);
            dbms_lob.freetemporary(statement_text);found_count:=found_count+1;
            dbms_output.put_line('MC_EARLY_STORAGE|'||binding.get_string('member')||'|'||binding.get_string('payload_sha256'));
          end if;
        end loop;
      end if;
    end loop;
    if found_count<>1 then raise_application_error(-20175,'INITIAL requires one canonical tracking-table payload: '||table_name_value); end if;
    table_count:=table_count+found_count;
  end loop;
  dbms_lob.freetemporary(coverage);
  for i in 1..members.count loop
    if members(i).name='manifest.json' then bytes:=get_member(:early_zip,members(i)); exit; end if;
  end loop;
  dbms_lob.createtemporary(manifest,true);
  dbms_lob.converttoclob(manifest,bytes,dbms_lob.lobmaxsize,d,s,nls_charset_id('AL32UTF8'),ctx,w);
  if w<>0 then raise_application_error(-20175,'INITIAL manifest encoding is invalid'); end if;
  doc:=json_object_t.parse(manifest); app:=doc.get_number('app_id'); ver:=doc.get_string('version');
  -- These tables are created above in this same block. Resolve their DML at
  -- execution time, after the canonical CREATE-only payloads have succeeded.
  execute immediate 'insert into deploy_bundles(app_id,version_tag,manifest_json,bundle_zip,sha256)
    values(:a,:v,:m,:z,:h) returning bundle_id into :b'
    using app,ver,manifest,:early_zip,'$bundle_hash',out bid;
  execute immediate q'~insert into deploy_runs(bundle_id,action,status,log_clob)
    values(:b,'INITIAL','RUNNING','Archive retained during verified helper installation; baseline pending') returning run_id into :r~'
    using bid,out rid;
  commit;
  dbms_output.put_line('MC_INITIAL_RETAINED|'||to_char(bid,'TM9')||'|'||to_char(rid,'TM9'));
  dbms_lob.freetemporary(bytes);dbms_lob.freetemporary(manifest);dbms_lob.freetemporary(:early_zip);
end;
end;
/
exit success rollback
SQL
  echo 'Installing definition helpers from the staged release archive.'
  run_sqlcl_capture 'Initial definition helper boundary' "$connection" "$script" 'verified inventory-bound helper units' "$output" || return $?
  awk -F'|' '$1=="MC_EARLY_DEFINITION" && NF==3 {print $2 "|" $3}' "$output" > "$tmp/product-definition-verified.txt"
  awk -F'|' '$1=="MC_PRODUCT_LABEL" && NF==3 {print $2 "|" $3}' "$output" > "$tmp/product-labels.txt"
  count="$(wc -l < "$tmp/product-definition-verified.txt" | tr -d ' ')"
  [[ "$count" == 2 ]] || fail 'Definition helper boundary produced incomplete receipts'
  awk -F'|' '$1=="MC_EARLY_STORAGE" && NF==3 {print $2 "|" $3}' "$output" > "$tmp/product-storage-verified.txt"
  [[ "$(wc -l < "$tmp/product-storage-verified.txt" | tr -d '[:space:]')" == 2 ]] || fail 'Early tracking-table receipts are incomplete'
  IFS='|' read -r initial_bundle_id initial_run_id < <(sed -n 's/^MC_INITIAL_RETAINED|//p' "$output")
  [[ "$initial_bundle_id" =~ ^[1-9][0-9]*$ && "$initial_run_id" =~ ^[1-9][0-9]*$ ]] || fail 'Target archive retention receipt is missing'
  initial_archive_stage_drop TARGET "$connection"
}

initial_product_plan() {
  local stage="$1" header action member extra ordinal=0 seen='|' early_seen=0 early_member early_hash expected actual
  local choices="$tmp/product-$stage-members" runner="$tmp/product-$stage.sql" total index=0 display label
  local MC_INITIAL_RENDER_ONLY=Y MC_INITIAL_PLAN_PROGRESS=Y
  [[ "$stage" == STORAGE || "$stage" == CODE || "$stage" == APPLICATION_STORAGE ]] || fail 'Unknown product installation stage'
  : > "$choices"
  local plan="$tmp/content/db/deploy/product-plan.txt"
  IFS= read -r header < "$plan" || fail 'Missing product installation plan'
  [[ "$header" == 'MC_PRODUCT_INSTALL_PLAN|2' ]] || fail 'Unsupported product installation plan'
  while IFS='|' read -r action member extra || [[ -n "$action${member:-}${extra:-}" ]]; do
    [[ "$action" == MC_PRODUCT_INSTALL_PLAN ]] && continue
    [[ -z "${extra:-}" && "$seen" != *"|$member|"* ]] || fail 'Duplicate product installation member'
    case "$action" in APPLICATION|APPLICATION_STORAGE|UNIT|STORAGE) ;; *) fail 'Unknown product installation boundary' ;; esac
    mc_bundle_safe_member_path "$member" && [[ "$member" == db/* && -f "$tmp/content/$member" && ! -L "$tmp/content/$member" ]] \
      || fail 'Invalid product installation member'
    seen+="$member|"; ordinal=$((ordinal+1))
    case "$stage" in
      STORAGE) [[ "$action" == STORAGE ]] || continue ;;
      APPLICATION_STORAGE) [[ "$action" == APPLICATION_STORAGE ]] || continue ;;
      CODE) [[ "$action" == APPLICATION || "$action" == UNIT ]] || continue ;;
    esac
    if [[ "$stage" == CODE && "${dry:-}" == N ]]; then
      [[ -f "$tmp/product-definition-verified.txt" ]] || fail 'Missing early definition helper receipts'
      early_hash=''
      while IFS='|' read -r early_member expected; do
        if [[ "$early_member" == "$member" ]]; then
          [[ -z "$early_hash" && "$action" == UNIT && "$expected" =~ ^[0-9a-f]{64}$ ]] || fail 'Invalid early definition helper receipt'
          early_hash="$expected"
        fi
      done < "$tmp/product-definition-verified.txt"
      if [[ -n "$early_hash" ]]; then
        [[ "$(mc_bundle_sha256_file "$tmp/content/$member")" == "$early_hash" ]] || fail 'Early definition helper payload changed'
        early_seen=$((early_seen+1)); continue
      fi
    fi
    if [[ "$stage" == STORAGE && -f "$tmp/product-storage-verified.txt" ]]; then
      early_hash="$(awk -F'|' -v path="$member" '$1==path {print $2}' "$tmp/product-storage-verified.txt")"
      if [[ -n "$early_hash" ]]; then
        [[ "$early_hash" =~ ^[0-9a-f]{64}$ && "$(mc_bundle_sha256_file "$tmp/content/$member")" == "$early_hash" ]] || fail 'Early tracking-table payload changed'
        continue
      fi
    fi
    expected="$(awk -v path="$member" '$2==path {print $1}' "$tmp/content/checksums.sha256")"
    actual="$(mc_bundle_sha256_file "$tmp/content/$member")"
    [[ "$expected" =~ ^[0-9a-f]{64}$ && "$actual" == "$expected" ]] || fail 'Product statement changed after archive inspection'
    printf '%s|%s|%s\n' "$action" "$member" "$ordinal" >> "$choices"
  done < "$plan"
  if [[ "$stage" == CODE && "${dry:-}" == N && "$early_seen" != 2 ]]; then fail 'Installation plan omitted verified definition helper units'; fi
  total="$(wc -l < "$choices" | tr -d '[:space:]')"
  printf '%s\n' 'whenever sqlerror exit failure rollback' 'whenever oserror exit failure rollback' \
    'set define off echo off verify off feedback off serveroutput on size unlimited' > "$runner"
  while IFS='|' read -r action member ordinal; do
    index=$((index+1)); display="$member"
    if [[ -f "$tmp/product-labels.txt" ]]; then
      label="$(awk -F'|' -v path="$member" '$1==path {print $2;exit}' "$tmp/product-labels.txt")"
      [[ -z "$label" ]] || display="$label"
    fi
    printf 'prompt MC_INITIAL_OBJECT_START|%s|%s|%s|%s\n' "$index" "$total" "$member" "$display" >> "$runner"
    if [[ "$action" == APPLICATION || "$action" == APPLICATION_STORAGE ]]; then
      printf '@"%s/content/%s"\n' "$tmp" "$member" >> "$runner"
    else
      initial_product_statement "$member" "$ordinal"
      printf '@"%s"\n' "$MC_INITIAL_RENDERED_SCRIPT" >> "$runner"
    fi
    printf 'prompt MC_INITIAL_OBJECT_DONE|%s|%s|%s|%s\n' "$index" "$total" "$member" "$display" >> "$runner"
  done < "$choices"
  printf 'prompt MC_INITIAL_PLAN_COMPLETE|%s|%s\n' "$stage" "$total" >> "$runner"
  run_script "product-$(printf '%s' "$stage" | tr '[:upper:]' '[:lower:]')" "$runner" || return $?
  if [[ "${dry:-}" == N ]]; then
    grep -Fqx "MC_INITIAL_PLAN_COMPLETE|$stage|$total" "$tmp/output-product_$(printf '%s' "$stage" | tr '[:upper:]' '[:lower:]').log" \
      || fail 'Product installation stopped before completing its verified plan'
  fi
  if [[ "$stage" == CODE && "${mode:-}" == INITIAL && "${dry:-}" == N ]]; then
    capture_scheduler_state "$scheduler_after"
    verify_initial_scheduler_state "$scheduler_after"
  fi
}
# Interpret dictionary text as data, never as executable SQL or shell syntax.
# Unsupported encodings fail closed. Ordinary enrollment never creates a first
# inclusion; only the operator-selected NEW prerequisite path may.
initial_index_policy() {
  local policy="$1" tables="$2" target="$3" mode_ members item kept='' seen=','
  local pattern='^schema (IN|NOT IN) \(([A-Z0-9_$#, ]+)\)$'
  MC_INDEX_ACTION=NONE MC_INDEX_PRESENT=ABSENT MC_INDEX_CANONICAL='ALL|'
  [[ -z "$tables" ]] || { echo 'ERROR: table-level automatic indexing policy requires DBA review; no policy changed.' >&2; return 1; }
  [[ -n "$policy" ]] || return 0
  [[ "$policy" =~ $pattern ]] || { echo 'ERROR: unsupported automatic indexing schema policy (wildcards/quoted names need DBA review); no policy changed.' >&2; return 1; }
  mode_="${BASH_REMATCH[1]}"; members="${BASH_REMATCH[2]}"
  [[ "$members" != ,* && "$members" != *, && "$members" != *,,* ]] || return 1
  local remaining="$members"
  while [[ -n "$remaining" ]]; do
    item="${remaining%%,*}"
    item="${item#"${item%%[! ]*}"}"
    item="${item%"${item##*[! ]}"}"
    [[ "$item" =~ ^[A-Z][A-Z0-9_\$#]{0,127}$ && "$seen" != *",$item,"* ]] || return 1
    seen="$seen$item,"
    if [[ "$item" == "$target" ]]; then MC_INDEX_PRESENT=PRESENT; else kept="$kept$item,"; fi
    [[ "$remaining" == *,* ]] || break
    remaining="${remaining#*,}"
  done
  if [[ "$mode_" == 'NOT IN' && "$MC_INDEX_PRESENT" == PRESENT ]]; then
    echo "ERROR: automatic indexing explicitly excludes $target; DBA review required." >&2; return 1
  fi
  [[ "$mode_" != IN || "$MC_INDEX_PRESENT" == PRESENT ]] || MC_INDEX_ACTION=ADD
  kept="$(printf '%s' "${kept%,}" | tr ',' '\n' | LC_ALL=C sort | paste -sd, -)"
  MC_INDEX_CANONICAL="$mode_|$kept"
}

initial_index_change() {
  local operation="$1" raw_hash schema_id fingerprint allow receipt status_=0
  initial_verify_shared || return 1
  raw_hash="$(sed -n 's/^MC_STATE|INDEX_RAW|//p' "$tmp/shared-after")"
  schema_id="$(sed -n 's/^SCHEMA|//p' "$journal_directory/events" | tail -1)"
  fingerprint="$(sed -n 's/^DATABASE|//p' "$journal_directory/events" | tail -1)"
  [[ "$raw_hash" =~ ^[0-9A-F]{64}$ && "$schema_id" =~ ^[0-9]+$ && "$fingerprint" =~ ^[0-9A-F]{64}$ ]] || return 1
  case "$operation" in
    ADD) allow=TRUE; receipt=INDEX_ADDED; initial_event INTENT_INDEX || return 1 ;;
    REMOVE) allow=NULL; receipt=INDEX_REMOVED ;;
    *) return 1 ;;
  esac
  printf 'INITIAL automatic indexing: %s installer-owned inclusion for %s (other entries preserved).\n' "$operation" "$schema" >> "${log:-/dev/null}"
  if [[ "$operation" == ADD ]]; then
    echo "Enabling automatic indexing for $schema."
  else
    echo "Removing the automatic indexing setting added for $schema."
  fi
  cat > "$tmp/initial-index-change.sql" <<SQL
whenever sqlerror exit failure rollback
whenever oserror exit failure rollback
set define off
set serveroutput on
declare n number; h varchar2(64);
begin
 if user<>'ADMIN' then raise_application_error(-20094,'Index scope change requires ADMIN'); end if;
 select rawtohex(standard_hash(sys_context('USERENV','DB_UNIQUE_NAME')||chr(10)||sys_context('USERENV','CON_NAME'),'SHA256')) into h from dual;
 if h<>'$fingerprint' then raise_application_error(-20094,'Index scope database identity mismatch'); end if;
 select count(*) into n from dba_users where username='$schema' and user_id=$schema_id;
 if n<>1 then raise_application_error(-20094,'Index scope schema identity mismatch'); end if;
 select rawtohex(standard_hash(nvl(parameter_value,chr(1))||'|'||nvl(dbms_lob.substr(parameter_value_clob,4000,1),chr(1)),'SHA256')) into h
 from dba_auto_index_config where parameter_name='AUTO_INDEX_SCHEMA';
 if h<>'$raw_hash' then raise_application_error(-20094,'Index scope changed concurrently; retained for DBA review'); end if;
 dbms_auto_index.configure('AUTO_INDEX_SCHEMA','$schema',$allow);
 dbms_output.put_line('MC_INDEX_CHANGED');
end;
/
exit success
SQL
  initial_lock_check || return 1
  initial_fence_script "$tmp/initial-index-change.sql" || return 1
  sql -s -L -name "$admin_connection" "@$MC_FENCED_SCRIPT" > "$tmp/index-change.out" 2>&1 || status_=$?
  if [[ "$status_" != 0 ]] || ! grep -qx MC_INDEX_CHANGED "$tmp/index-change.out" || grep -Eq 'ORA-|PLS-|SP2-' "$tmp/index-change.out"; then
    grep -E 'ORA-|PLS-|SP2-' "$tmp/index-change.out" >&2 || true
    echo "ERROR: indexing $operation for $schema was not confirmed; preserve the journal for DBA review." >&2
    return 1
  fi
  initial_event "$receipt" || return 1
  initial_verify_shared
}
# INITIAL-only, private durable receipts. Journal files are DATA, never shell code.
# Recovery is compensating cleanup; uncertain ownership always fails closed.
initial_fence_script() {
  local source="$1"
  MC_FENCED_SCRIPT="$tmp/fenced-$(basename "$source")"
  {
    printf '%s\n' 'set feedback off' 'whenever sqlerror exit failure rollback' 'whenever oserror exit failure rollback' \
      "declare r number; begin r:=dbms_lock.request(dbms_utility.get_hash_value('MC_INITIAL_MUTATION',100000,1000000000),dbms_lock.x_mode,0,false); if r<>0 then raise_application_error(-20094,'INITIAL worker still active; retry recovery after it ends'); end if; end;" /
    cat "$source"
  } > "$MC_FENCED_SCRIPT"
}

initial_lock_append_frames() {
  local i
  # Sequential script includes avoid recursive @ nesting. Each FIFO writer
  # closes its frame; SQLcl stdin itself is EOF from startup. Bound exhaustion
  # fails closed rather than silently dropping the coordination session.
  for ((i=0;i<4096;i++)); do
    printf '@"%s/initial-lock.in.sql"\n' "$tmp"
  done >> "$1"
  printf '%s\n' 'prompt MC_INITIAL_COORDINATION_FRAME_LIMIT' 'exit failure' >> "$1"
}

initial_lock_wait() {
  local marker="$1" limit="$2" waited=0
  until grep -qx "$marker" "$tmp/initial-lock.out"; do
    kill -0 "$MC_INITIAL_LOCK_PID" 2>/dev/null && ((waited<limit)) || return 1
    sleep 0.1; waited=$((waited+1))
  done
}

initial_lock_send() {
  local writer waited=0
  initial_lock_cancel_send
  (printf '%s\n' "$1" > "$tmp/initial-lock.in.sql") &
  writer=$!
  MC_INITIAL_WRITER_PID=$writer
  while kill -0 "$writer" 2>/dev/null; do
    if ! kill -0 "$MC_INITIAL_LOCK_PID" 2>/dev/null || ((waited>=100)); then
      kill "$writer" 2>/dev/null || true
      wait "$writer" 2>/dev/null || true
      MC_INITIAL_WRITER_PID=''
      return 1
    fi
    sleep 0.1; waited=$((waited+1))
  done
  local status=0
  wait "$writer" || status=$?
  MC_INITIAL_WRITER_PID=''
  return "$status"
}

initial_lock_cancel_send() {
  if [[ -n "${MC_INITIAL_WRITER_PID:-}" ]]; then
    kill "$MC_INITIAL_WRITER_PID" 2>/dev/null || true
    wait "$MC_INITIAL_WRITER_PID" 2>/dev/null || true
    MC_INITIAL_WRITER_PID=''
  fi
}

initial_lock_diagnostic() {
  echo 'ERROR: INITIAL SQLcl coordination did not become ready (session exited or timed out).' >&2
  if [[ -f "$tmp/initial-lock.out" ]]; then
    # This session receives only fixed coordination SQL: never password SQL.
    tail -c 16384 "$tmp/initial-lock.out" >&2
    if [[ "${mode:-}" == UNINSTALL && -n "${log:-}" && -f "$log" ]]; then
      tail -c 16384 "$tmp/initial-lock.out" >> "$log" || true
    fi
    if [[ "${mode:-}" != UNINSTALL && -n "${journal_directory:-}" && -d "$journal_directory" ]]; then
      tail -c 16384 "$tmp/initial-lock.out" > "$journal_directory/coordination.log"
      echo "Coordination diagnostic: $journal_directory/coordination.log" >&2
    fi
  fi
}

initial_lock_launch() {
  local monitor_was_on=N
  [[ $- != *m* ]] || monitor_was_on=Y
  # Give only this coordinator its own process group. SQLcl is a shell
  # launcher, so stopping $! alone can orphan its JVM and database session.
  set -m
  sql "$@" < /dev/null > "$tmp/initial-lock.out" 2>&1 &
  MC_INITIAL_LOCK_PID=$!
  MC_INITIAL_LOCK_PGID=$MC_INITIAL_LOCK_PID
  [[ "$monitor_was_on" == Y ]] || set +m
}

initial_lock_open() {
  mkfifo "$tmp/initial-lock.in.sql" || return 1
  printf '%s\n' 'whenever sqlerror exit failure rollback' 'whenever oserror exit failure rollback' 'set serveroutput on' \
    "declare r number; begin if user<>'ADMIN' then raise_application_error(-20094,'ADMIN required'); end if; r:=dbms_lock.request(dbms_utility.get_hash_value('MC_INITIAL_INSTALL',100000,1000000000),dbms_lock.x_mode,0,false); if r<>0 then raise_application_error(-20094,'INITIAL coordination lock unavailable; DBMS_LOCK result='||r); end if; end;" / 'prompt MC_INITIAL_LOCK_READY' > "$tmp/initial-lock.sql"
  initial_lock_append_frames "$tmp/initial-lock.sql"
  if [[ "${mode:-}" == UNINSTALL ]]; then
    # Hold the same schema runtime lock used by release/update/maintenance for
    # the whole uninstall, including across committed DDL and schema removal.
    local runtime_lock="$tmp/uninstall-runtime-lock.sql"
    printf '%s\n' 'whenever sqlerror exit failure rollback' 'whenever oserror exit failure rollback' \
      "declare r number; begin r:=dbms_lock.request(dbms_utility.get_hash_value('MC_RUNTIME:$schema',0,1073741823),dbms_lock.x_mode,0,false); if r<>0 then raise_application_error(-20094,'Application deployment or maintenance is active'); end if; end;" / > "$runtime_lock"
    { printf '@%s\n' "$runtime_lock"; cat "$tmp/initial-lock.sql"; } > "$tmp/uninstall-lock.sql"
    mv "$tmp/uninstall-lock.sql" "$tmp/initial-lock.sql"
  fi
  initial_lock_launch -s -L -name "$admin_connection" "@$tmp/initial-lock.sql"
  initial_lock_wait MC_INITIAL_LOCK_READY 300 || { initial_lock_diagnostic; return 1; }
}

initial_lock_check() {
  [[ -n "${MC_INITIAL_LOCK_PID:-}" ]] || return 1
  kill -0 "$MC_INITIAL_LOCK_PID" 2>/dev/null || return 1
  # Reserve a blocked frame so the final acknowledged heartbeat cannot release
  # the coordination lock before the next deployment worker starts.
  (( ${MC_INITIAL_PING:-0} < 4095 )) || { echo 'ERROR: INITIAL coordination frame limit reached; refusing further work.' >&2; return 1; }
  MC_INITIAL_PING=$((${MC_INITIAL_PING:-0}+1))
  initial_lock_send "begin dbms_output.put_line('MC_INITIAL_PING_$MC_INITIAL_PING'); end;
/" || return 1
  initial_lock_wait "MC_INITIAL_PING_$MC_INITIAL_PING" 100
}

initial_lock_close() {
  local waited=0 group="${MC_INITIAL_LOCK_PGID:-}"
  initial_lock_cancel_send
  if [[ -n "${MC_INITIAL_LOCK_PID:-}" ]]; then
    if kill -0 "$MC_INITIAL_LOCK_PID" 2>/dev/null && [[ -p "$tmp/initial-lock.in.sql" ]]; then
      # End the JDBC session normally, releasing its session-owned lock.
      initial_lock_send 'exit success rollback' || true
    fi
    if [[ "$group" =~ ^[0-9]+$ ]] && ((group>1)); then
      while kill -0 -- "-$group" 2>/dev/null && ((waited<50)); do
        sleep .1; waited=$((waited+1))
      done
      if kill -0 -- "-$group" 2>/dev/null; then
        echo 'WARNING: SQLcl coordinator did not exit normally; stopping its process group.' >&2
        kill -TERM -- "-$group" 2>/dev/null || true
        waited=0
        while kill -0 -- "-$group" 2>/dev/null && ((waited<20)); do
          sleep .1; waited=$((waited+1))
        done
        kill -KILL -- "-$group" 2>/dev/null || true
      fi
    else
      kill "$MC_INITIAL_LOCK_PID" 2>/dev/null || true
    fi
    wait "$MC_INITIAL_LOCK_PID" 2>/dev/null || true
    MC_INITIAL_LOCK_PID=''
    MC_INITIAL_LOCK_PGID=''
  fi
}

initial_event() {
  if [[ -f "$journal_directory/seal" ]]; then initial_journal_verify || return 1; fi
  printf '%s\n' "$1" >> "$journal_directory/events" || return 1
  initial_journal_seal || return 1
  sync
}

# Integrity detects truncation and accidental edits, not a malicious administrator
# who can rewrite both files. The journal remains private trusted operator input.
initial_journal_seal() {
  { mc_bundle_sha256_file "$journal_directory/identity"; mc_bundle_sha256_file "$journal_directory/events"; mc_bundle_sha256_file "$journal_directory/process"; mc_bundle_sha256_file "$journal_directory/provenance"; } > "$tmp/journal-seal" || return 1
  cp "$tmp/journal-seal" "$journal_directory/seal.new" || return 1
  mv "$journal_directory/seal.new" "$journal_directory/seal" || return 1
}

initial_journal_verify() {
  local f
  initial_private_directory "$journal_directory" || return 1
  for f in identity events process provenance seal; do
    [[ -f "$journal_directory/$f" && ! -L "$journal_directory/$f" && -O "$journal_directory/$f" ]] || return 1
  done
  { mc_bundle_sha256_file "$journal_directory/identity"; mc_bundle_sha256_file "$journal_directory/events"; mc_bundle_sha256_file "$journal_directory/process"; mc_bundle_sha256_file "$journal_directory/provenance"; } > "$tmp/journal-check" || return 1
  cmp -s "$tmp/journal-check" "$journal_directory/seal"
}

initial_private_directory() {
  local dir="$1" mode_ cursor="$1"
  [[ "$dir" =~ ^/[A-Za-z0-9_./-]+$ && "$dir" != / && "$dir" != *'/../'* && "$dir" != */.. && "$dir" != */. ]] || return 1
  while [[ "$cursor" != / ]]; do
    [[ ! -L "$cursor" ]] || return 1
    cursor="$(dirname "$cursor")"
  done
  [[ -d "$dir" && -O "$dir" && ! -L "$dir" ]] || return 1
  mode_="$(stat -f '%Lp' "$dir" 2>/dev/null)" || mode_="$(stat -c '%a' "$dir")"
  [[ "$mode_" == 700 ]]
}

initial_journal_open() {
  [[ -n "$journal_directory" ]] || fail 'INITIAL requires --journal-directory with a new persistent private directory'
  [[ "$journal_directory" =~ ^/[A-Za-z0-9_./-]+$ && "$journal_directory" != / && "$journal_directory" != *'/../'* && "$journal_directory" != */.. && "$journal_directory" != */. ]] || fail 'Use an absolute journal path without traversal or SQLcl metacharacters'
  local cursor="$journal_directory"
  while [[ "$cursor" != / ]]; do
    [[ ! -L "$cursor" ]] || fail 'Journal paths must not contain symlink components'
    cursor="$(dirname "$cursor")"
  done
  [[ ! -e "$journal_directory" && ! -L "$journal_directory" ]] || fail 'Journal directory already exists; use CLEANUP for an interrupted installation'
  [[ -d "$(dirname "$journal_directory")" ]] || fail 'Journal parent directory must already exist'
  mkdir -m 700 "$journal_directory" || fail 'Cannot create journal directory'
  initial_private_directory "$journal_directory" || fail 'Journal requires an absolute private non-symlink path (mode 700)'
  printf 'MC_INITIAL_JOURNAL|1\n%s|%s|%s|%s|%s|%s\n' "$schema" "$workspace" "$workspace_mode" "$target_id" "$target_connection" "$first_admin" > "$journal_directory/identity"
  : > "$journal_directory/events"
  printf '%s|%s\n' "$(hostname)" "$$" > "$journal_directory/process"
  local run_id
  run_id="$(od -An -N16 -tx1 /dev/urandom | tr -d ' \n')"
  [[ "$run_id" =~ ^[0-9a-f]{32}$ ]] || fail 'Cannot generate installation run ID'
  printf '%s|%s\n' "$run_id" "$bundle_hash" > "$journal_directory/provenance"
  initial_event 'STARTED'
  MC_INITIAL_ACTIVE=Y
  echo "Recovery records: $journal_directory"
}

initial_receipt() {
  local kind="$1" output="$2" value
  value="$(sed -n "s/^MC_INITIAL_${kind}|//p" "$output" | tr -d '\r')"
  [[ "$value" =~ ^[0-9]+$ ]] || return 1
  initial_event "$kind|$value"
}

initial_connection_list() {
  printf '%s\n' 'set echo off' 'prompt MC_CONNECTIONS_BEGIN' 'connmgr list -flat' 'prompt MC_CONNECTIONS_END' 'exit success' > "$tmp/initial-connections.sql"
  sql -s /nolog "@$tmp/initial-connections.sql" > "$tmp/initial-connections.out" 2>&1 || return 1
  # Unknown SQLcl commands can return exit zero. Require a recognizable envelope
  # and reject diagnostic output rather than treating it as a connection name.
  grep -qx MC_CONNECTIONS_BEGIN "$tmp/initial-connections.out" &&
    grep -qx MC_CONNECTIONS_END "$tmp/initial-connections.out" || return 1
  if grep -Eiq 'error|unknown command|usage:|ORA-|SP2-|PLS-' "$tmp/initial-connections.out"; then return 1; fi
  sed -n '/^MC_CONNECTIONS_BEGIN$/,/^MC_CONNECTIONS_END$/p' "$tmp/initial-connections.out" |
    sed '1d;$d;/^[[:space:]]*$/d' > "$tmp/connection-names"
}

initial_connection_absent() {
  initial_connection_list || fail 'Cannot establish saved-connection inventory; no provisioning performed'
  if ! grep -Fqx "$target_connection" "$tmp/connection-names"; then return 0; fi
  local current_hash answer=''
  current_hash="$(initial_connection_hash)" || fail 'Cannot inspect existing target saved connection'
  if [[ -n "${MC_INITIAL_REPLACE_HASH:-}" ]]; then
    [[ "$current_hash" == "$MC_INITIAL_REPLACE_HASH" ]] || fail 'Target saved connection changed after replacement confirmation'
    return 0
  fi
  [[ "${MC_INITIAL_INPUTS_COMPLETE:-N}" != Y ]] || fail 'Target saved connection appeared after preparation; rerun INITIAL to review replacement'
  printf 'Saved connection %s already exists. Replace it for this installation? [y/N]: ' "$target_connection" >&2
  IFS= read -r answer || answer=''
  case "$answer" in
    y|Y|yes|YES|Yes) MC_INITIAL_REPLACE_HASH="$current_hash" ;;
    *) echo 'INITIAL cancelled; existing saved connection retained.'; exit 0 ;;
  esac
}

initial_connection_hash() {
  local name="${1:-$target_connection}"
  printf '%s\n' 'set echo off' "connmgr show $name" 'exit success' > "$tmp/initial-connection-show.sql"
  sql -s /nolog "@$tmp/initial-connection-show.sql" > "$tmp/connection-details" 2>&1 || return 1
  [[ -s "$tmp/connection-details" ]] || return 1
  if grep -Eiq 'error|not found|does not exist|unknown command|usage:|ORA-|SP2-' "$tmp/connection-details"; then return 1; fi
  mc_bundle_sha256_file "$tmp/connection-details"
}

# Keep the old encrypted connection in SQLcl's own store until installation
# succeeds. The journal contains only its name and metadata fingerprints.
initial_connection_replace() {
  [[ -n "${MC_INITIAL_REPLACE_HASH:-}" ]] || return 0
  initial_connection_absent
  grep -Fqx "$target_connection" "$tmp/connection-names" || return 0
  local backup="MC_INIT_PREVIOUS_$(cut -d '|' -f 1 "$journal_directory/provenance")" backup_hash
  ! grep -Fqx "$backup" "$tmp/connection-names" || fail 'Saved connection backup name already exists'
  printf '%s\n' "connmgr clone -original $target_connection $backup" 'exit success' > "$tmp/initial-connection-backup.sql"
  sql -s /nolog "@$tmp/initial-connection-backup.sql" > "$tmp/connection-backup.out" 2>&1 || fail 'Cannot back up existing saved connection'
  initial_connection_list || fail 'Cannot verify saved connection backup'
  grep -Fqx "$backup" "$tmp/connection-names" || fail 'Saved connection backup was not created'
  backup_hash="$(initial_connection_hash "$backup")" || fail 'Cannot fingerprint saved connection backup'
  initial_event "CONNECTION_BACKUP|$backup|$backup_hash|$MC_INITIAL_REPLACE_HASH"
  [[ "$(initial_connection_hash)" == "$MC_INITIAL_REPLACE_HASH" ]] || fail 'Target saved connection changed before replacement'
  printf '%s\n' "connmgr delete -conn $target_connection" 'exit success' > "$tmp/initial-connection-delete.sql"
  sql -s /nolog "@$tmp/initial-connection-delete.sql" > "$tmp/connection-delete.out" 2>&1 || fail 'Cannot replace existing saved connection'
  initial_connection_list || fail 'Cannot verify saved connection deletion'
  ! grep -Fqx "$target_connection" "$tmp/connection-names" || fail 'Existing saved connection could not be removed'
}

initial_connection_backup_finish() {
  local restore="$1" record backup backup_hash original_hash extra restored_hash
  record="$(sed -n 's/^CONNECTION_BACKUP|//p' "$journal_directory/events" | tail -1)"
  [[ -n "$record" ]] || return 0
  IFS='|' read -r backup backup_hash original_hash extra <<< "$record"
  restored_hash="$(sed -n 's/^CONNECTION_RESTORED|//p' "$journal_directory/events" | tail -1)"
  [[ -z "$restored_hash" ]] || original_hash="$restored_hash"
  initial_connection_list || return 1
  # A missing backup is valid after completed restoration/discard on a retry.
  if ! grep -Fqx "$backup" "$tmp/connection-names"; then
    [[ "$restore" == N || "$(initial_connection_hash)" == "$original_hash" ]]
    return $?
  fi
  [[ "$(initial_connection_hash "$backup")" == "$backup_hash" ]] || { echo 'Saved connection backup changed; retained for recovery.' >&2; return 1; }
  if [[ "$restore" == Y ]]; then
    if ! grep -Fqx "$target_connection" "$tmp/connection-names"; then
      printf '%s\n' "connmgr clone -original $backup $target_connection" 'exit success' > "$tmp/initial-connection-restore.sql"
      sql -s /nolog "@$tmp/initial-connection-restore.sql" > "$tmp/connection-restore.out" 2>&1 || return 1
      grep -Fq "Connection $target_connection has been cloned" "$tmp/connection-restore.out" || return 1
      # Cloning restores settings/credentials but can assign new wallet paths;
      # record the restored metadata rather than requiring its previous bytes.
      original_hash="$(initial_connection_hash)" || return 1
      initial_event "CONNECTION_RESTORED|$original_hash" || return 1
    fi
    [[ "$(initial_connection_hash)" == "$original_hash" ]] || { echo 'Existing saved connection differs; backup retained for recovery.' >&2; return 1; }
  fi
  printf '%s\n' "connmgr delete -conn $backup" 'exit success' > "$tmp/initial-connection-backup-delete.sql"
  sql -s /nolog "@$tmp/initial-connection-backup-delete.sql" > "$tmp/connection-backup-delete.out" 2>&1 || return 1
  initial_connection_list || return 1
  ! grep -Fqx "$backup" "$tmp/connection-names"
}

initial_snapshot() {
  local destination="$1"
  cat > "$tmp/initial-snapshot.sql" <<SQL
whenever sqlerror exit failure rollback
whenever oserror exit failure rollback
set define off
set echo off
set feedback off
set heading off
set pagesize 0
set linesize 32767
set trimspool on
declare n number; begin
 select count(*) into n from dba_auto_index_config where dbms_lob.getlength(parameter_value_clob)>4000;
 if n<>0 then raise_application_error(-20094,'Indexing configuration exceeds snapshot limit; DBA review required'); end if;
end;
/
select 'MC_STATE|INDEX|'||parameter_name||'|'||rawtohex(standard_hash(nvl(parameter_value,chr(1))||'|'||nvl(dbms_lob.substr(parameter_value_clob,4000,1),chr(1)),'SHA256'))
 from dba_auto_index_config where parameter_name<>'AUTO_INDEX_SCHEMA' order by parameter_name;
select 'MC_INDEX_SCHEMA|'||nvl(dbms_lob.substr(parameter_value_clob,4000,1),parameter_value)
 from dba_auto_index_config where parameter_name='AUTO_INDEX_SCHEMA';
select 'MC_INDEX_TABLE|'||nvl(dbms_lob.substr(parameter_value_clob,4000,1),parameter_value)
 from dba_auto_index_config where parameter_name='AUTO_INDEX_TABLE';
select 'MC_STATE|INDEX_RAW|'||rawtohex(standard_hash(nvl(parameter_value,chr(1))||'|'||nvl(dbms_lob.substr(parameter_value_clob,4000,1),chr(1)),'SHA256'))
 from dba_auto_index_config where parameter_name='AUTO_INDEX_SCHEMA';
select 'MC_STATE|RP|'||grantee||'|'||privilege||'|'||grantable from dba_tab_privs
 where owner='ADMIN' and table_name='OCI\$RESOURCE_PRINCIPAL' and grantee<>'$schema'
 order by grantee,privilege,grantable;
-- Supplementary evidence only: keep the journal snapshot format unchanged.
select 'MC_PREREQ_ORACLE_RP|'||p.grantee||'|'||p.privilege||'|'||p.grantable
 from dba_tab_privs p join dba_users u on u.username=p.grantee
 where p.owner='ADMIN' and p.table_name='OCI\$RESOURCE_PRINCIPAL' and u.oracle_maintained='Y'
 order by p.grantee,p.privilege,p.grantable;
select 'MC_STATE|ADMIN_RP|'||count(*) from dba_credentials
 where owner='ADMIN' and credential_name='OCI\$RESOURCE_PRINCIPAL';
select 'MC_PREREQ_MODE|'||nvl(upper(trim(parameter_value)),'OFF') from dba_auto_index_config where parameter_name='AUTO_INDEX_MODE';
prompt MC_SNAPSHOT_OK
exit success
SQL
  sql -s -name "$admin_connection" "@$tmp/initial-snapshot.sql" > "$tmp/snapshot.out" 2>&1 || return 1
  # SQLcl pads concatenated query columns even with TRIMSPOOL enabled when
  # stdout is redirected rather than spooled. Normalize transport whitespace.
  sed 's/[[:space:]]*$//' "$tmp/snapshot.out" > "$tmp/snapshot-trimmed"
  mv "$tmp/snapshot-trimmed" "$tmp/snapshot.out"
  grep -qx MC_SNAPSHOT_OK "$tmp/snapshot.out" || return 1
  ! grep -Eq 'ORA-|PLS-|SP2-' "$tmp/snapshot.out" || return 1
  [[ $(grep -c '^MC_INDEX_SCHEMA|' "$tmp/snapshot.out") == 1 && $(grep -c '^MC_INDEX_TABLE|' "$tmp/snapshot.out") == 1 ]] || return 1
  initial_index_policy "$(sed -n 's/^MC_INDEX_SCHEMA|//p' "$tmp/snapshot.out")" "$(sed -n 's/^MC_INDEX_TABLE|//p' "$tmp/snapshot.out")" "$schema" || return 1
  grep '^MC_STATE|' "$tmp/snapshot.out" > "$destination" || return 1
  printf 'MC_STATE|INDEX_SCOPE|%s\nMC_STATE|INDEX_TARGET|%s\n' "$MC_INDEX_CANONICAL" "$MC_INDEX_PRESENT" >> "$destination"
  grep -q '^MC_STATE|INDEX|AUTO_INDEX_MODE|' "$destination" && grep -Eq '^MC_STATE\|ADMIN_RP\|[01]$' "$destination"
}

initial_verify_shared() {
  local expected target_state baseline="$journal_directory/shared-before" event=SNAPSHOT
  if grep -q '^PROVISIONED_SNAPSHOT|' "$journal_directory/events"; then baseline="$journal_directory/shared-provisioned"; event=PROVISIONED_SNAPSHOT; fi
  if grep -q '^RESTORED_SNAPSHOT|' "$journal_directory/events"; then baseline="$journal_directory/shared-restored"; event=RESTORED_SNAPSHOT; fi
  expected="$(sed -n "s/^$event|//p" "$journal_directory/events" | tail -1)"
  [[ "$expected" =~ ^[0-9a-f]{64}$ && ! -L "$baseline" ]] || return 1
  [[ "$(mc_bundle_sha256_file "$baseline")" == "$expected" ]] || return 1
  initial_snapshot "$tmp/shared-after" || return 1
  # Journals from before schema enrollment hashed AUTO_INDEX_SCHEMA directly.
  # They cannot own an indexing change; compare their original representation.
  if ! grep -q '^MC_STATE|INDEX_SCOPE|' "$baseline"; then
    if grep -qx INTENT_INDEX "$journal_directory/events"; then return 1; fi
    { grep -Ev '^MC_STATE\|INDEX_(RAW|TARGET|SCOPE)\|' "$tmp/shared-after"
      sed -n 's/^MC_STATE|INDEX_RAW|/MC_STATE|INDEX|AUTO_INDEX_SCHEMA|/p' "$tmp/shared-after"
    } | LC_ALL=C sort > "$tmp/shared-observed"
    sed 's/[[:space:]]*$//' "$baseline" | LC_ALL=C sort > "$tmp/shared-expected"
    cmp -s "$tmp/shared-expected" "$tmp/shared-observed"
    return
  fi
  target_state="$(sed -n 's/^MC_STATE|INDEX_TARGET|//p' "$baseline")"
  if grep -qx INDEX_ADDED "$journal_directory/events" && ! grep -qx INDEX_REMOVED "$journal_directory/events"; then target_state=PRESENT; fi
  [[ "$(sed -n 's/^MC_STATE|INDEX_TARGET|//p' "$tmp/shared-after")" == "$target_state" ]] || {
    echo 'ERROR: target indexing membership changed unexpectedly; DBA review required.' >&2; return 1;
  }
  grep -Ev '^MC_STATE\|INDEX_(RAW|TARGET)\|' "$baseline" > "$tmp/shared-expected"
  grep -Ev '^MC_STATE\|INDEX_(RAW|TARGET)\|' "$tmp/shared-after" > "$tmp/shared-observed"
  cmp -s "$tmp/shared-expected" "$tmp/shared-observed" || {
    echo 'ERROR: shared indexing/resource-principal state changed; refusing to restore over DBA changes.' >&2
    return 1
  }
}

initial_cleanup_owned() {
  local schema_id workspace_id fingerprint extra status_=0 connection_hash expected_hash restored_connection_hash
  initial_journal_verify || { echo 'RECOVERY_REQUIRED: journal integrity failure; no cleanup attempted.' >&2; return 1; }
  initial_archive_admin_cleanup || return 1
  if grep -qx INTENT_PREREQUISITES "$journal_directory/events" && ! grep -q '^PROVISIONED_SNAPSHOT|' "$journal_directory/events"; then
    echo 'RECOVERY_REQUIRED: prerequisite changes are unconfirmed; DBA review required before cleanup.' >&2; return 1
  fi
  if grep -qx INTENT_PREREQ_RESTORE "$journal_directory/events" && ! grep -q '^RESTORED_SNAPSHOT|' "$journal_directory/events"; then
    echo 'RECOVERY_REQUIRED: indexing restoration is unconfirmed; DBA review required before cleanup.' >&2; return 1
  fi
  if [[ "${mode:-}" == UNINSTALL ]]; then uninstall_preflight || return 1; fi
  # Confirmed IDs are the only destructive authority. An intent is not a receipt.
  schema_id="$(sed -n 's/^SCHEMA|//p' "$journal_directory/events" | tail -1)"
  workspace_id="$(sed -n 's/^WORKSPACE|//p' "$journal_directory/events" | tail -1)"
  fingerprint="$(sed -n 's/^DATABASE|//p' "$journal_directory/events" | tail -1)"
  if [[ -z "$schema_id" ]]; then
    if grep -qx 'INTENT_SCHEMA' "$journal_directory/events"; then
      echo 'RECOVERY_REQUIRED: schema creation has no confirmed ownership receipt; inspect it manually.' >&2
      return 1
    fi
    return 0
  fi
  initial_lock_check || { echo 'RECOVERY_REQUIRED: coordination session lost; cleanup deferred.' >&2; return 1; }
  [[ "$schema_id" =~ ^[0-9]+$ && "$fingerprint" =~ ^[0-9A-F]{64}$ ]] || return 1
  [[ -z "$workspace_id" || "$workspace_id" =~ ^[0-9]+$ ]] || return 1
  if grep -qx INTENT_WORKSPACE "$journal_directory/events" && [[ -z "$workspace_id" ]]; then
    echo 'RECOVERY_REQUIRED: workspace operation has no receipt; schema retained for review.' >&2
    return 1
  fi
  # A failed/partial APEX import without a receipt is deliberately not attributed
  # to this run just because the requested ID now exists.
  local app_hash base_users base_groups user_id group_admin group_contributor group_user
  app_hash="$(sed -n 's/^APP|//p' "$journal_directory/events" | tail -1)"
  [[ -z "$app_hash" || "$app_hash" =~ ^[0-9A-F]{64}$ ]] || return 1
  base_users="$(sed -n 's/^BASE_USER|//p' "$journal_directory/events" | paste -sd, -)"
  base_groups="$(sed -n 's/^BASE_GROUP|//p' "$journal_directory/events" | paste -sd, -)"
  user_id="$(sed -n 's/^APEX_USER|//p' "$journal_directory/events" | tail -1)"
  group_admin="$(sed -n 's/^GROUP_ADMIN|//p' "$journal_directory/events" | tail -1)"
  group_contributor="$(sed -n 's/^GROUP_CONTRIBUTOR|//p' "$journal_directory/events" | tail -1)"
  group_user="$(sed -n 's/^GROUP_USER|//p' "$journal_directory/events" | tail -1)"
  for extra in "$base_users" "$base_groups" "$user_id" "$group_admin" "$group_contributor" "$group_user"; do
    [[ -z "$extra" || "$extra" =~ ^[0-9]+(,[0-9]+)*$ ]] || return 1
  done
  if grep -qx INTENT_INDEX "$journal_directory/events" && ! grep -qx INDEX_ADDED "$journal_directory/events"; then
    echo 'RECOVERY_REQUIRED: indexing enrollment has no confirmed receipt; no cleanup attempted.' >&2; return 1
  fi
  if grep -qx PREREQ_FIRST_INDEX "$journal_directory/events" && ! grep -q '^RESTORED_SNAPSHOT|' "$journal_directory/events"; then
    initial_prerequisites_restore || { echo 'RECOVERY_REQUIRED: indexing restoration failed; schema retained.' >&2; return 1; }
  fi
  if grep -qx INDEX_ADDED "$journal_directory/events" && ! grep -qx INDEX_REMOVED "$journal_directory/events"; then
    initial_index_change REMOVE || { echo 'RECOVERY_REQUIRED: target indexing removal unconfirmed; owned schema retained.' >&2; return 1; }
  fi
  cat > "$tmp/initial-cleanup.sql" <<SQL
whenever sqlerror exit failure rollback
whenever oserror exit failure rollback
set define off
set echo off
set verify off
set serveroutput on
${MC_UNINSTALL_GUARD_INCLUDE:-}
declare
 n number; actual_id number; ws number; fp varchar2(64); actual_hash varchar2(64);
 procedure verify_schema is
 begin
  select max(user_id) into actual_id from dba_users where username='$schema';
  if actual_id is not null and actual_id<>$schema_id then raise_application_error(-20094,'Schema identity changed'); end if;
 end;
 procedure verify_workspace is
 begin
  if nvl(apex_util.find_security_group_id(p_workspace=>'$workspace'),-1)<>${workspace_id:-0} then
   raise_application_error(-20094,'Workspace identity changed');
  end if;
 end;
 procedure remove_group_(p_name varchar2,p_id number) is
 begin
  if p_id=0 then return; end if;
  n:=apex_util.get_group_id(p_name);
  if n is null then return; end if;
  if n<>p_id then raise_application_error(-20094,'Group identity changed'); end if;
  select count(*) into n from apex_workspace_group_users where workspace_id=ws and group_name=p_name;
  if n<>0 then raise_application_error(-20094,'Group has foreign members; retained'); end if;
  apex_util.delete_user_group(p_group_id=>p_id);
 end;
begin
 if user<>'ADMIN' then raise_application_error(-20094,'Cleanup requires ADMIN'); end if;
 select rawtohex(standard_hash(sys_context('USERENV','DB_UNIQUE_NAME')||chr(10)||sys_context('USERENV','CON_NAME'),'SHA256')) into fp from dual;
 if fp<>'$fingerprint' then raise_application_error(-20094,'Cleanup database identity mismatch'); end if;
 verify_schema;
 ws:=apex_util.find_security_group_id(p_workspace=>'$workspace');
 if ws is not null and ${workspace_id:-0}<>0 then
   verify_workspace;
   apex_util.set_security_group_id(ws);
   if '$workspace_mode'='CREATE' then
     -- CREATE plus a confirmed, matching workspace ID owns this disposable
     -- workspace as a unit, including a partially imported application.
     verify_workspace;
     apex_instance_admin.remove_workspace(p_workspace=>'$workspace',p_drop_users=>'N',p_drop_tablespaces=>'N');
   else
   select count(*) into n from apex_applications where application_id=$target_id;
   if n>0 then
     if '$app_hash' is null then raise_application_error(-20094,'Application ownership is unconfirmed; manual review required'); end if;
     select count(*) into n from apex_applications where application_id=$target_id and workspace_id=ws and owner='$schema';
     if n<>1 then raise_application_error(-20094,'Application identity mismatch'); end if;
     select rawtohex(standard_hash(to_char(created_on,'YYYYMMDDHH24MISS')||'|'||to_char(last_updated_on,'YYYYMMDDHH24MISS')||'|'||owner||'|'||to_char(workspace_id,'TM9'),'SHA256')) into actual_hash
       from apex_applications where application_id=$target_id;
     if actual_hash<>'$app_hash' then raise_application_error(-20094,'Application changed since import; retained'); end if;
     verify_workspace;
     apex_application_install.set_workspace('$workspace');
     apex_application_install.remove_application($target_id);
     commit;
   end if;
   -- An existing workspace is never removed; require individual receipts.
   n:=apex_util.get_user_id(p_username=>'$first_admin');
   if n is not null then
     if n<>${user_id:-0} then raise_application_error(-20094,'First-account ownership uncertain; retained'); end if;
     apex_util.remove_user(p_user_id=>n);
   end if;
   remove_group_('Administrators',${group_admin:-0});
   remove_group_('Contributors',${group_contributor:-0});
   remove_group_('Users',${group_user:-0});
     verify_workspace;
     select count(*) into n from apex_workspace_schemas where workspace_id=${workspace_id:-0} and schema='$schema';
     if n>0 then
       apex_instance_admin.remove_schema(p_workspace=>'$workspace',p_schema=>'$schema');
     end if;
   end if;
   commit;
 end if;
 verify_schema;
 if actual_id is not null then
   select count(*) into n from apex_workspace_schemas where schema='$schema';
   if n<>0 then raise_application_error(-20094,'Schema still has APEX workspace mappings; retained'); end if;
   select count(*) into n from dba_tab_privs where owner='$schema' and grantee<>owner;
   if n<>0 then raise_application_error(-20094,'Schema has grants to other principals; retained for review'); end if;
   select count(*) into n from dba_tab_privs where owner='ADMIN' and table_name='OCI\$RESOURCE_PRINCIPAL' and grantee='$schema' and privilege='EXECUTE';
   if n>0 then dbms_cloud_admin.disable_resource_principal(username=>'$schema'); end if;
   verify_schema;
   execute immediate 'drop user "$schema" cascade';
 end if;
 dbms_output.put_line('MC_CLEANUP_DB_OK');
end;
/
exit success
SQL
  initial_fence_script "$tmp/initial-cleanup.sql" || return 1
  sql -s -name "$admin_connection" "@$MC_FENCED_SCRIPT" > "$tmp/cleanup.out" 2>&1 || status_=$?
  if [[ "$status_" != 0 ]] || ! grep -qx MC_CLEANUP_DB_OK "$tmp/cleanup.out" || grep -Eq 'ORA-|PLS-|SP2-' "$tmp/cleanup.out"; then
    grep -Eo 'ORA-[0-9]+|PLS-[0-9]+|SP2-[0-9]+' "$tmp/cleanup.out" | sort -u >&2 || true
    echo 'RECOVERY_REQUIRED: database cleanup was incomplete; owned resources may remain.' >&2
    echo "Inspect workspace $workspace, schema $schema and saved connection $target_connection against the journal before manual recovery." >&2
    return 1
  fi
  initial_event DB_CLEANED || return 1
  if grep -qx INTENT_CONNECTION "$journal_directory/events"; then
    initial_connection_list || return 1
    if grep -Fqx "$target_connection" "$tmp/connection-names"; then
      restored_connection_hash="$(sed -n 's/^CONNECTION_RESTORED|//p' "$journal_directory/events" | tail -1)"
      connection_hash="$(initial_connection_hash)" || return 1
      if [[ -z "$restored_connection_hash" || "$connection_hash" != "$restored_connection_hash" ]]; then
        expected_hash="$(sed -n 's/^CONNECTION|//p' "$journal_directory/events" | tail -1)"
        [[ "$expected_hash" =~ ^[0-9a-f]{64}$ ]] || { echo 'RECOVERY_REQUIRED: saved connection ownership unconfirmed.' >&2; return 1; }
        [[ "$connection_hash" == "$expected_hash" ]] || { echo 'RECOVERY_REQUIRED: saved connection changed; retained.' >&2; return 1; }
        printf '%s\n' "connmgr delete -conn $target_connection" 'exit success' > "$tmp/initial-connection-delete.sql"
        sql -s /nolog "@$tmp/initial-connection-delete.sql" > "$tmp/connection-delete.out" 2>&1 || return 1
        initial_connection_list || return 1
        ! grep -Fqx "$target_connection" "$tmp/connection-names" || return 1
      fi
    fi
  fi
  initial_connection_backup_finish Y || return 1
  initial_verify_shared
}

initial_finish_failure() {
  initial_lock_cancel_send
  [[ "${MC_INITIAL_ACTIVE:-N}" == Y ]] || return 0
  MC_INITIAL_ACTIVE=N
  initial_event FAILED || { echo 'RECOVERY_REQUIRED: cannot record failure safely; no cleanup attempted.' >&2; return 1; }
  if initial_cleanup_owned; then
    initial_event CLEANED || return 1
    if grep -qx INTENT_SCHEMA "$journal_directory/events"; then
      echo "INITIAL cleanup complete. Journal retained: $journal_directory" >&2
    else
      echo "No target resources were created. Journal retained: $journal_directory" >&2
    fi
  else
    initial_event RECOVERY_REQUIRED || return 1
    echo "Keep the journal. Recovery: bash install_mc_bundle.sh --mode CLEANUP --admin-connection $admin_connection --journal-directory $journal_directory" >&2
  fi
}

initial_load_journal() {
  local header extra key value line schema_id original_host original_pid current_host directory_mode upload_table
  if ! initial_private_directory "$journal_directory"; then
    [[ -e "$journal_directory" || -L "$journal_directory" ]] || fail "Recovery journal directory does not exist: $journal_directory. Use the original successful installation journal; do not create an empty replacement."
    [[ ! -L "$journal_directory" ]] || fail "Recovery journal directory must not be a symlink: $journal_directory"
    [[ -d "$journal_directory" ]] || fail "Recovery journal path is not a directory: $journal_directory"
    [[ -O "$journal_directory" ]] || fail "Recovery journal directory is not owned by the current operating-system user: $journal_directory"
    directory_mode="$(stat -f '%Lp' "$journal_directory" 2>/dev/null)" || directory_mode="$(stat -c '%a' "$journal_directory" 2>/dev/null)" || fail 'Cannot read recovery journal directory permissions'
    [[ "$directory_mode" == 700 ]] || fail "Recovery journal permissions must be 700; found $directory_mode: $journal_directory. Review ownership before changing permissions."
    fail 'Recovery journal path must be absolute, without traversal or symlink components'
  fi
  initial_journal_verify || fail 'Journal integrity check failed; no cleanup attempted'
  for key in identity events process provenance; do
    [[ -f "$journal_directory/$key" && ! -L "$journal_directory/$key" && -O "$journal_directory/$key" ]] || fail "Missing or unsafe journal file: $key"
    [[ $(wc -c < "$journal_directory/$key") -le 65536 ]] || fail 'Oversized journal'
  done
  IFS='|' read -r original_host original_pid extra < "$journal_directory/process"
  [[ -n "$original_host" && "$original_pid" =~ ^[1-9][0-9]*$ && -z "$extra" ]] || fail 'Recovery journal host/process record is malformed; retain the original journal for review'
  current_host="$(hostname)" || fail 'Cannot read the current hostname for recovery-journal validation'
  [[ "$original_host" == "$current_host" ]] || fail "Recovery journal hostname mismatch: recorded '$original_host', current '$current_host'. This check requires the original hostname, even on a renamed machine. No database checks or removal were performed. Do not edit the sealed journal; verify the original machine before retrying."
  if [[ "$mode" != UNINSTALL ]]; then
    ! kill -0 "$original_pid" 2>/dev/null || fail 'Original installer process is still active; cleanup refused'
  fi
  [[ $(wc -l < "$journal_directory/identity") -eq 2 ]] || fail 'Invalid journal identity'
  { IFS= read -r header; IFS='|' read -r schema workspace workspace_mode target_id target_connection first_admin extra; } < "$journal_directory/identity"
  [[ "$header" == 'MC_INITIAL_JOURNAL|1' && -z "$extra" ]] || fail 'Unsupported journal'
  [[ "$schema" =~ ^[A-Z][A-Z0-9_\$#]{0,127}$ && "$workspace" =~ ^[A-Z][A-Z0-9_]{0,254}$ && "$workspace_mode" =~ ^(CREATE|EXISTING)$ && "$target_id" =~ ^[1-9][0-9]*$ && "$target_connection" =~ ^[A-Za-z][A-Za-z0-9_.-]{0,127}$ ]] || fail 'Invalid journal identifiers'
  [[ "$first_admin" =~ ^[A-Z][A-Z0-9_.@-]{0,99}$ ]] || fail 'Invalid account identifier'
  upload_table="$(initial_archive_stage_name)" || fail 'Invalid INITIAL archive staging identity'
  while IFS= read -r line; do
    case "$line" in
      STARTED|FAILED|CLEANED|RECOVERY_REQUIRED|DB_CLEANED|INTENT_SCHEMA|INTENT_WORKSPACE|INTENT_CONNECTION|INTENT_APP|INTENT_ACCESS|INTENT_INDEX|INDEX_ADDED|INDEX_REMOVED|INTENT_PREREQUISITES|PREREQ_FIRST_INDEX|INTENT_PREREQ_RESTORE) ;;
      INTENT_UPLOAD_ADMIN\|*|UPLOAD_ADMIN\|*|UPLOAD_ADMIN_DROPPED\|*|INTENT_UPLOAD_TARGET\|*|UPLOAD_TARGET\|*|UPLOAD_TARGET_DROPPED\|*)
        [[ "${line#*|}" == "$upload_table" ]] || fail 'INITIAL upload journal identity mismatch' ;;
      SUCCEEDED) [[ "$mode" == UNINSTALL ]] || fail 'Refusing cleanup of a successful installation' ;;
      UNINSTALL_STARTED|UNINSTALL_FAILED|UNINSTALLED|UNINSTALL_JOBS_STARTED|UNINSTALL_JOBS_DRAINED) [[ "$mode" == UNINSTALL ]] || fail 'Use UNINSTALL to resume removal of a successful installation' ;;
      DATABASE\|*|APP\|*) [[ "${line#*|}" =~ ^[0-9A-F]{64}$ ]] || fail 'Invalid database/application receipt' ;;
      SCHEMA\|*|WORKSPACE\|*|BASE_USER\|*|BASE_GROUP\|*|APEX_USER\|*|GROUP_ADMIN\|*|GROUP_CONTRIBUTOR\|*|GROUP_USER\|*) [[ "${line#*|}" =~ ^[0-9]+$ ]] || fail 'Invalid object receipt' ;;
      CONNECTION_BACKUP\|*)
        IFS='|' read -r backup_kind backup_name backup_hash original_hash backup_extra <<< "$line"
        [[ "$backup_name" =~ ^MC_INIT_PREVIOUS_[0-9a-f]{32}$ && "$backup_hash" =~ ^[0-9a-f]{64}$ && "$original_hash" =~ ^[0-9a-f]{64}$ && -z "$backup_extra" ]] || fail 'Invalid saved connection backup receipt' ;;
      CONNECTION_RESTORED\|*|CONNECTION\|*|SNAPSHOT\|*|PROVISIONED_SNAPSHOT\|*|RESTORED_SNAPSHOT\|*) [[ "${line#*|}" =~ ^[0-9a-f]{64}$ ]] || fail 'Invalid connection/snapshot receipt' ;;
      *) fail 'Unknown journal record' ;;
    esac
  done < "$journal_directory/events"
}

initial_recover() {
  initial_load_journal
  MC_ACCESS_ATTEMPTED=0
  grep -qx INTENT_ACCESS "$journal_directory/events" && MC_ACCESS_ATTEMPTED=1
  if grep -qx CLEANED "$journal_directory/events"; then echo 'INITIAL was already cleaned.'; return; fi
  initial_lock_open || fail 'Another installation/cleanup is active or ADMIN coordination unavailable'
  initial_cleanup_owned || { initial_event RECOVERY_REQUIRED; fail 'Cleanup incomplete; preserve journal and inspect target resources'; }
  initial_event CLEANED
  echo 'INITIAL cleanup complete; journal retained.'
}
# ADMIN-authorized removal of an explicit live target. INITIAL journals are not
# read or used as authority. Per-run IDs protect against replacement during DDL.
uninstall_sql() {
  local script="$1" marker="$2" status_=0 output
  output="$tmp/$(basename "$script").out"
  sql -s -L -name "$admin_connection" "@$script" > "$output" 2>&1 || status_=$?
  sed 's/[[:space:]]*$//' "$output" > "$output.trimmed"
  mv "$output.trimmed" "$output"
  cat "$output" >> "$log"
  if [[ "$status_" != 0 ]] || ! grep -qx "$marker" "$output" || grep -Eq 'ORA-|PLS-|SP2-' "$output"; then
    cat "$output" >&2
    return 1
  fi
  MC_UNINSTALL_OUTPUT="$output"
}

uninstall_discover() {
  cat > "$tmp/uninstall-discover.sql" <<SQL
whenever sqlerror exit failure rollback
whenever oserror exit failure rollback
set define off echo off verify off feedback off serveroutput on
declare
 sid number; ws number; apps number; others number; protected number; fp varchar2(64); dedicated varchar2(1):='N';
begin
 if user<>'ADMIN' or sys_context('USERENV','SESSION_USER')<>user or sys_context('USERENV','PROXY_USER') is not null then
  raise_application_error(-20096,'Direct ADMIN connection required'); end if;
 select count(*) into protected from dba_users where username='$schema' and (oracle_maintained='Y' or common='YES');
 if protected<>0 then raise_application_error(-20096,'Oracle-maintained/common schemas cannot be uninstalled'); end if;
 select nvl(max(user_id),0) into sid from dba_users where username='$schema';
 ws:=nvl(apex_util.find_security_group_id(p_workspace=>'$workspace'),0);
 select count(*) into apps from apex_applications where application_id=$target_id;
 if apps>0 then
  select count(*) into others from apex_applications where application_id=$target_id and workspace_id=ws and owner='$schema';
  if others<>1 then raise_application_error(-20096,'Application does not belong to the selected schema/workspace'); end if;
 end if;
 if ws<>0 then
  select count(*) into others from apex_applications where workspace_id=ws and application_id<>$target_id;
  select others+count(*) into others from apex_workspace_schemas where workspace_id=ws and schema<>'$schema';
  if others=0 then dedicated:='Y'; end if;
 end if;
 select rawtohex(standard_hash(sys_context('USERENV','DB_UNIQUE_NAME')||chr(10)||sys_context('USERENV','CON_NAME'),'SHA256')) into fp from dual;
 dbms_output.put_line('MC_UNINSTALL_SCOPE|DB|'||fp);
 dbms_output.put_line('MC_UNINSTALL_SCOPE|SCHEMA|'||to_char(sid,'TM9'));
 dbms_output.put_line('MC_UNINSTALL_SCOPE|WORKSPACE|'||to_char(ws,'TM9'));
 dbms_output.put_line('MC_UNINSTALL_SCOPE|APP|'||to_char(apps,'TM9'));
 dbms_output.put_line('MC_UNINSTALL_SCOPE|DEDICATED|'||dedicated);
end;
/
prompt MC_UNINSTALL_DISCOVERY_OK
exit success rollback
SQL
  uninstall_sql "$tmp/uninstall-discover.sql" MC_UNINSTALL_DISCOVERY_OK || return 1
  local key value
  for key in DB SCHEMA WORKSPACE APP DEDICATED; do
    [[ $(grep -c "^MC_UNINSTALL_SCOPE|$key|" "$MC_UNINSTALL_OUTPUT") == 1 ]] || return 1
    value="$(sed -n "s/^MC_UNINSTALL_SCOPE|$key|//p" "$MC_UNINSTALL_OUTPUT" | tr -d '\r')"
    case "$key" in
      DB) [[ "$value" =~ ^[0-9A-F]{64}$ ]] || return 1; MC_UNINSTALL_DB="$value" ;;
      SCHEMA|WORKSPACE) [[ "$value" =~ ^(0|[1-9][0-9]*)$ ]] || return 1; printf -v "MC_UNINSTALL_$key" '%s' "$value" ;;
      APP) [[ "$value" =~ ^[01]$ ]] || return 1; MC_UNINSTALL_APP="$value" ;;
      DEDICATED) [[ "$value" =~ ^[YN]$ ]] || return 1; MC_UNINSTALL_DEDICATED="$value" ;;
    esac
  done
}

uninstall_write_guard() {
  local allow_jobs="${1:-N}"
  cat > "$tmp/uninstall-guard.sql" <<SQL
-- MC_UNINSTALL_GUARD: repeat live scope checks before every mutation.
declare
 n number; sid number; ws number; h varchar2(64);
 procedure zero_(v number,reason varchar2) is begin
  if v<>0 then raise_application_error(-20096,reason||' ('||v||'). Removal stopped; review the target.'); end if;
 end;
 procedure pending_(tbl varchar2,p_column varchar2 default 'STATUS') is
  cols number;
 begin
  select count(*) into cols from dba_tab_columns where owner='$schema' and table_name=tbl and column_name=p_column;
  if cols=0 then return; end if;
  if p_column='PHASE' then
   execute immediate 'select count(*) from '||dbms_assert.enquote_name('$schema',false)||'.'||dbms_assert.enquote_name(tbl,false)||
    ' where phase not in (''SUCCEEDED'',''REJECTED'',''FAILED_RESTORED'',''BLOCKED'') or phase is null' into n;
  else
   execute immediate 'select count(*) from '||dbms_assert.enquote_name('$schema',false)||'.'||dbms_assert.enquote_name(tbl,false)||
    ' where status in (''RUNNING'',''QUEUED'',''PENDING'')' into n;
  end if;
  zero_(n,'Queued or active deployment work in '||tbl);
 end;
begin
 if user<>'ADMIN' or sys_context('USERENV','SESSION_USER')<>user or sys_context('USERENV','PROXY_USER') is not null then
  raise_application_error(-20096,'Direct ADMIN connection required'); end if;
 select rawtohex(standard_hash(sys_context('USERENV','DB_UNIQUE_NAME')||chr(10)||sys_context('USERENV','CON_NAME'),'SHA256')) into h from dual;
 if h<>'$MC_UNINSTALL_DB' then raise_application_error(-20096,'Database identity changed during uninstall'); end if;
 select nvl(max(user_id),0) into sid from dba_users where username='$schema';
 if sid<>0 and sid<>$MC_UNINSTALL_SCHEMA then raise_application_error(-20096,'Schema identity changed during uninstall'); end if;
 select count(*) into n from dba_users where username='$schema' and (oracle_maintained='Y' or common='YES');
 zero_(n,'Protected schema');
 ws:=nvl(apex_util.find_security_group_id(p_workspace=>'$workspace'),0);
 if ws<>0 and ws<>$MC_UNINSTALL_WORKSPACE then raise_application_error(-20096,'Workspace identity changed during uninstall'); end if;
 select count(*) into n from apex_applications where application_id=$target_id;
 if n<>0 then
  if $MC_UNINSTALL_APP=0 then raise_application_error(-20096,'Application appeared after discovery'); end if;
  select count(*) into n from apex_applications where application_id=$target_id and workspace_id=ws and owner='$schema';
  if n<>1 then raise_application_error(-20096,'Application ownership changed during uninstall'); end if;
 end if;
 select count(*) into n from apex_applications where owner='$schema' and application_id<>$target_id;
 zero_(n,'Other applications use the target schema');
 select count(*) into n from apex_workspace_schemas where schema='$schema' and workspace_id<>ws;
 zero_(n,'Other workspaces use the target schema');
 if '$MC_UNINSTALL_DEDICATED'='Y' and ws<>0 then
  select count(*) into n from apex_applications where workspace_id=ws and application_id<>$target_id;
  zero_(n,'Other applications appeared in the dedicated workspace');
  select count(*) into n from apex_workspace_schemas where workspace_id=ws and schema<>'$schema';
  zero_(n,'Other schemas appeared in the dedicated workspace');
 end if;
 if ws<>0 then
  select count(*) into n from apex_workspace_apex_users where workspace_id=ws;
  dbms_output.put_line('Workspace accounts: '||n||case when '$MC_UNINSTALL_DEDICATED'='Y' then ' (removed with dedicated workspace)' else ' (retained)' end);
 end if;
 select count(*) into n from gv\$session s where (username='$schema' or schemaname='$schema') and type='USER'
  and not ('$allow_jobs'='Y' and exists(select 1 from dba_scheduler_running_jobs j where j.owner='$schema' and j.session_id=s.sid and j.running_instance=s.inst_id));
 zero_(n,'Open target sessions; stop traffic and disconnect them');
 if '$allow_jobs'='Y' then
  for j in(select job_name from dba_scheduler_jobs where owner='$schema' and enabled='TRUE' union select job_name from dba_scheduler_running_jobs where owner='$schema') loop
   dbms_output.put_line('MC_UNINSTALL_JOB '||replace(replace(replace(j.job_name,chr(10),'?'),chr(13),'?'),chr(27),'?'));
  end loop;
 else
  select count(*) into n from dba_scheduler_running_jobs where owner='$schema';zero_(n,'Running target scheduled tasks');
  select count(*) into n from dba_scheduler_jobs where owner='$schema' and enabled='TRUE';zero_(n,'Enabled target scheduled tasks');
 end if;
 select count(*) into n from dba_jobs j join dba_jobs_running r on r.job=j.job where '$schema' in(j.log_user,j.priv_user,j.schema_user);zero_(n,'Running legacy jobs');
 select count(*) into n from dba_jobs where '$schema' in(log_user,priv_user,schema_user) and broken='N';zero_(n,'Enabled legacy jobs require DBA review');
 select count(*) into n from dba_dependencies where referenced_owner='$schema' and owner<>'$schema';zero_(n,'External database dependencies');
 select count(*) into n from dba_constraints where r_owner='$schema' and owner<>'$schema';zero_(n,'External foreign keys');
 select count(*) into n from dba_synonyms where table_owner='$schema' and owner<>'$schema';zero_(n,'External synonyms');
 select count(*) into n from dba_tab_privs where owner='$schema' and grantee<>owner;zero_(n,'Other principals have grants on target objects');
 select count(*) into n from dba_col_privs where owner='$schema' and grantee<>owner;zero_(n,'Other principals have column grants on target objects');
 select count(*) into n from dba_scheduler_jobs where owner<>'$schema' and instr(upper(job_action),'$schema.')>0;zero_(n,'External scheduled consumers');
 if sid<>0 then pending_('DEPLOY_RUNS');pending_('DEPLOY_UPLOADS');pending_('MC_BUNDLE_UPDATE_STATE','PHASE'); end if;
 select count(*) into n from dba_objects where owner='$schema';dbms_output.put_line('Schema objects to remove: '||n);
end;
/
SQL
  printf '%s\n' 'whenever sqlerror exit failure rollback' 'whenever oserror exit failure rollback' \
    'set define off echo off verify off feedback off serveroutput on' "@$tmp/uninstall-guard.sql" \
    'prompt MC_UNINSTALL_CHECK_OK' 'exit success rollback' > "$tmp/uninstall-check.sql"
}

uninstall_preflight() {
  uninstall_sql "$tmp/uninstall-check.sql" MC_UNINSTALL_CHECK_OK || return 1
  cp "$MC_UNINSTALL_OUTPUT" "$tmp/uninstall-check.out"
}

uninstall_confirm() {
  local answer=''; printf '%s ' "$1"; IFS= read -r answer || return 1; [[ "$answer" == "$2" ]]
}

uninstall_event() {
  printf 'UNINSTALL progress: %s\n' "$1" >> "$log"
  # Optional progress is never read as identity/authorization. A bad or absent
  # directory cannot block removal; the private diagnostic log is the fallback.
  [[ "$dry" != Y && -n "$journal_directory" ]] || return 0
  if initial_private_directory "$journal_directory" && [[ ! -L "$journal_directory/uninstall-progress.log" ]]; then
    if [[ ! -e "$journal_directory/uninstall-progress.log" || ( -f "$journal_directory/uninstall-progress.log" && -O "$journal_directory/uninstall-progress.log" ) ]]; then
      printf '%s|%s|%s|%s\n' "$schema" "$workspace" "$target_id" "$1" >> "$journal_directory/uninstall-progress.log" 2>/dev/null || true
    fi
  fi
  return 0
}

uninstall_drain_jobs() {
  grep -q '^MC_UNINSTALL_JOB ' "$tmp/uninstall-check.out" || return 0
  echo "Enabled or running scheduled tasks in $schema:"
  sed -n 's/^MC_UNINSTALL_JOB /  /p' "$tmp/uninstall-check.out"
  uninstall_confirm "Disable this schema's scheduled tasks and wait up to five minutes for active runs to finish? Type yes to continue:" yes || return 1
  initial_lock_check || return 1
  uninstall_event JOBS_STARTED
  cat > "$tmp/uninstall-jobs.sql" <<SQL
whenever sqlerror exit failure rollback
whenever oserror exit failure rollback
set define off echo off verify off feedback off serveroutput on
@$tmp/uninstall-guard.sql
declare n number; started number; remaining number;
begin
 select count(*) into n from dba_scheduler_jobs where owner='$schema' and enabled='TRUE' and not regexp_like(job_name,'^[A-Za-z0-9_\$#]+$');
 if n<>0 then raise_application_error(-20096,'Unusual job names require DBA review'); end if;
 for j in(select job_name from dba_scheduler_jobs where owner='$schema' and enabled='TRUE') loop
  dbms_scheduler.disable(dbms_assert.enquote_name('$schema',false)||'.'||dbms_assert.enquote_name(j.job_name,false),force=>true);
  dbms_output.put_line('Disabled scheduled task: '||j.job_name);
 end loop;
 started:=dbms_utility.get_time;
 loop
  select count(*) into n from dba_scheduler_running_jobs where owner='$schema';exit when n=0;
  remaining:=300-mod(dbms_utility.get_time-started+4294967296,4294967296)/100;
  if remaining<=0 then raise_application_error(-20096,'Scheduled tasks still running after five minutes. Resources retained; retry UNINSTALL after review.');end if;
  dbms_session.sleep(least(10,remaining));
 end loop;
 select count(*) into n from dba_scheduler_jobs where owner='$schema' and enabled='TRUE';
 if n<>0 then raise_application_error(-20096,'Scheduled tasks were re-enabled; removal stopped');end if;
end;
/
prompt MC_UNINSTALL_JOBS_OK
exit success rollback
SQL
  initial_fence_script "$tmp/uninstall-jobs.sql" || return 1
  echo 'Disabling scheduled tasks; checking active runs every 10 seconds for up to five minutes...'
  uninstall_sql "$MC_FENCED_SCRIPT" MC_UNINSTALL_JOBS_OK || return 1
  uninstall_event JOBS_DRAINED
}

uninstall_connection_check() {
  local before_hash after_hash
  MC_UNINSTALL_CONNECTION_PRESENT=N
  [[ -n "$target_connection" ]] || return 0
  initial_connection_list || return 1
  if ! grep -Fqx "$target_connection" "$tmp/connection-names"; then
    echo "Saved connection $target_connection not found; check --target-connection-name." >&2
    return 1
  fi
  before_hash="$(initial_connection_hash)" || return 1
  cat > "$tmp/uninstall-connection-verify.sql" <<'SQL'
whenever sqlerror exit failure rollback
whenever oserror exit failure rollback
set define off echo off verify off feedback off heading off pagesize 0
select 'MC_UNINSTALL_CONNECTION|'||sys_context('USERENV','SESSION_USER')||'|'||rawtohex(standard_hash(sys_context('USERENV','DB_UNIQUE_NAME')||chr(10)||sys_context('USERENV','CON_NAME'),'SHA256')) from dual;
exit success rollback
SQL
  sql -s -L -name "$target_connection" "@$tmp/uninstall-connection-verify.sql" > "$tmp/uninstall-connection.out" 2>&1 || return 1
  sed 's/[[:space:]]*$//' "$tmp/uninstall-connection.out" > "$tmp/uninstall-connection.trimmed"
  mv "$tmp/uninstall-connection.trimmed" "$tmp/uninstall-connection.out"
  grep -Fqx "MC_UNINSTALL_CONNECTION|$schema|$MC_UNINSTALL_DB" "$tmp/uninstall-connection.out" || return 1
  after_hash="$(initial_connection_hash)" || return 1
  [[ "$before_hash" == "$after_hash" ]] || return 1
  MC_UNINSTALL_CONNECTION_HASH="$after_hash"
  MC_UNINSTALL_CONNECTION_PRESENT=Y
}

uninstall_connections_prepare() {
  local selected="$target_connection" target_connection candidate owner observed_db
  : > "$tmp/uninstall-connections-verified"
  initial_connection_list || return 1
  cp "$tmp/connection-names" "$tmp/uninstall-connection-candidates"
  if [[ -n "$selected" ]]; then
    target_connection="$selected"
    uninstall_connection_check || return 1
    printf '%s|%s\n' "$target_connection" "$MC_UNINSTALL_CONNECTION_HASH" > "$tmp/uninstall-connections-verified"
  else
    while IFS= read -r candidate; do
      [[ "$candidate" =~ ^[A-Za-z][A-Za-z0-9_.-]{0,127}$ && "$candidate" != "$admin_connection" ]] || continue
      initial_connection_hash "$candidate" >/dev/null || return 1
      owner="$(sed -n 's/^[[:space:]]*User:[[:space:]]*//p' "$tmp/connection-details" | sed 's/[[:space:]]*$//')"
      [[ "$owner" == "$schema" ]] || continue
      target_connection="$candidate"
      if ! uninstall_connection_check; then
        # Same schema name on a different database is outside this uninstall.
        observed_db="$(grep -F "MC_UNINSTALL_CONNECTION|$schema|" "$tmp/uninstall-connection.out" | cut -d '|' -f 3 || true)"
        if [[ "$observed_db" =~ ^[0-9A-F]{64}$ && "$observed_db" != "$MC_UNINSTALL_DB" ]]; then continue; fi
        echo "Cannot verify saved connection $candidate; select the intended --target-connection-name explicitly." >&2
        return 1
      fi
      printf '%s|%s\n' "$candidate" "$MC_UNINSTALL_CONNECTION_HASH" >> "$tmp/uninstall-connections-verified"
    done < "$tmp/uninstall-connection-candidates"
  fi
  while IFS='|' read -r candidate owner; do
    echo "Saved connection selected for removal: $candidate"
  done < "$tmp/uninstall-connections-verified"
}

uninstall_remove() {
  local candidate expected_hash
  while IFS='|' read -r candidate expected_hash; do
    [[ "$(initial_connection_hash "$candidate")" == "$expected_hash" ]] || { echo "Saved connection $candidate changed; no resources removed." >&2; return 1; }
  done < "$tmp/uninstall-connections-verified"
  cat > "$tmp/uninstall-remove.sql" <<SQL
whenever sqlerror exit failure rollback
whenever oserror exit failure rollback
set define off echo off verify off feedback off serveroutput on
@$tmp/uninstall-guard.sql
declare n number; ws number;
begin
 ws:=nvl(apex_util.find_security_group_id(p_workspace=>'$workspace'),0);
 if ws<>0 then
  apex_util.set_security_group_id(ws);
  if '$MC_UNINSTALL_DEDICATED'='Y' then
   apex_instance_admin.remove_workspace(p_workspace=>'$workspace',p_drop_users=>'N',p_drop_tablespaces=>'N');
  else
   select count(*) into n from apex_applications where application_id=$target_id and owner='$schema' and workspace_id=ws;
   if n=1 then apex_application_install.set_workspace('$workspace');apex_application_install.remove_application($target_id);end if;
   select count(*) into n from apex_workspace_schemas where workspace_id=ws and schema='$schema';
   if n>0 then apex_instance_admin.remove_schema(p_workspace=>'$workspace',p_schema=>'$schema');end if;
  end if;
  commit;
 end if;
end;
/
@$tmp/uninstall-guard.sql
declare n number; policy varchar2(4000); members varchar2(4000); other_members varchar2(4000);
begin
 select count(*) into n from apex_workspace_schemas where schema='$schema';
 if n<>0 then raise_application_error(-20096,'Target schema still has workspace mappings');end if;
 select count(*) into n from dba_users where username='$schema';
 if n<>0 then
  -- Shared indexing mode is never restored from historical installation state.
  -- Only remove this inclusion if another inclusion remains; removing the sole
  -- member would make IMPLEMENT unrestricted across unrelated schemas.
  begin
   select nvl(dbms_lob.substr(parameter_value_clob,4000,1),parameter_value) into policy from dba_auto_index_config where parameter_name='AUTO_INDEX_SCHEMA';
   if regexp_like(policy,'^schema IN \([A-Z0-9_\$#, ]+\)$') then
    members:=replace(substr(policy,12,length(policy)-12),' ','');
    if instr(','||members||',',',$schema,')>0 then
     other_members:=replace(','||members||',',',$schema,',',');other_members:=trim(both ',' from other_members);
     if other_members is not null then dbms_auto_index.configure('AUTO_INDEX_SCHEMA','$schema',null);
     else dbms_output.put_line('Automatic indexing eligibility retained: removing its sole inclusion would broaden shared policy. Ask the DBA to review.');end if;
    end if;
   end if;
  exception when no_data_found then null;when others then
   if sqlcode not in (-942,-1031) then raise;end if;
   dbms_output.put_line('Automatic indexing eligibility retained; dictionary access requires DBA review.');
  end;
  select count(*) into n from dba_tab_privs where owner='ADMIN' and table_name='OCI\$RESOURCE_PRINCIPAL' and grantee='$schema' and privilege='EXECUTE';
  if n>0 then dbms_cloud_admin.disable_resource_principal(username=>'$schema');end if;
 end if;
end;
/
@$tmp/uninstall-guard.sql
declare n number;
begin
 select count(*) into n from dba_users where username='$schema';
 if n<>0 then execute immediate 'drop user '||dbms_assert.enquote_name('$schema',false)||' cascade';end if;
end;
/
prompt MC_UNINSTALL_REMOVE_OK
exit success rollback
SQL
  initial_lock_check || return 1
  initial_fence_script "$tmp/uninstall-remove.sql" || return 1
  uninstall_sql "$MC_FENCED_SCRIPT" MC_UNINSTALL_REMOVE_OK || return 1
  grep '^Automatic indexing' "$MC_UNINSTALL_OUTPUT" || true
  while IFS='|' read -r candidate expected_hash; do
    [[ "$(initial_connection_hash "$candidate")" == "$expected_hash" ]] || { echo "Saved connection $candidate changed; retained for manual removal." >&2; return 1; }
    printf '%s\n' "connmgr delete -conn $candidate" 'exit success' > "$tmp/initial-connection-delete.sql"
    sql -s /nolog "@$tmp/initial-connection-delete.sql" > "$tmp/uninstall-connection-delete.out" 2>&1 || return 1
    initial_connection_list || return 1
    ! grep -Fqx "$candidate" "$tmp/connection-names" || return 1
    echo "Saved connection removed: $candidate"
  done < "$tmp/uninstall-connections-verified"
}

uninstall_run() {
  echo "Uninstall target: schema $schema, workspace $workspace, application $target_id."
  echo 'The schema and ALL its data will be permanently deleted. Dedicated workspace accounts/content will also be removed; shared workspaces are retained.'
  echo 'Back up anything needed. Stop application traffic and keep DBA/deployment changes paused throughout removal.'
  if [[ "$dry" != Y ]]; then
    echo 'WARNING: This operation is destructive and irreversible. Deleted data cannot be recovered by this script.'
    [[ "$confirm_drop_schema" == "$schema" && "$acknowledge_data_loss" == Y ]] || fail "Supply --confirm-drop-schema $schema --acknowledge-data-loss"
    uninstall_confirm "Type UNINSTALL $schema to permanently delete the selected environment:" "UNINSTALL $schema" || fail 'Uninstall cancelled; no database calls made'
  fi
  if [[ -n "$target_connection" ]]; then
    initial_connection_list || fail 'Cannot inspect saved connections; no resources removed'
    grep -Fqx "$target_connection" "$tmp/connection-names" || fail "Saved connection $target_connection not found; check --target-connection-name. No resources removed."
  fi
  uninstall_discover || fail 'Uninstall discovery failed; no resources removed'
  if [[ "$MC_UNINSTALL_SCHEMA" == 0 && "$MC_UNINSTALL_WORKSPACE" == 0 && "$MC_UNINSTALL_APP" == 0 ]]; then
    echo 'The selected database/APEX resources are already absent. No database action taken.'
    [[ -z "$target_connection" ]] || echo "Saved connection $target_connection retained: the absent schema cannot verify its identity. Review/remove it through SQLcl."
    return
  fi
  if [[ "$MC_UNINSTALL_DEDICATED" == Y ]]; then echo 'Dedicated workspace: its accounts and content will be removed.';
  else echo 'Shared or absent workspace: accounts and groups will be retained.';fi
  uninstall_write_guard Y
  uninstall_preflight || fail 'Uninstall checks did not pass; no resources removed'
  grep -E '^(Workspace accounts:|Schema objects to remove:)' "$tmp/uninstall-check.out" || true
  # Capture verified local aliases before dropping the schema they connect to.
  uninstall_connections_prepare || fail 'Saved connection verification failed; no resources removed'
  if [[ "$dry" == Y ]]; then
    sed -n 's/^MC_UNINSTALL_JOB /Would request permission to disable or wait for scheduled task: /p' "$tmp/uninstall-check.out"
    echo 'Uninstall preview complete. No target changes or progress records were made.';return
  fi
  initial_lock_open || fail 'Another installation, removal or deployment is active'
  uninstall_preflight || fail 'Uninstall checks changed; no resources removed'
  uninstall_drain_jobs || fail 'Job preparation did not finish; no environment resources removed'
  uninstall_write_guard N
  uninstall_event STARTED
  if ! uninstall_remove; then
    uninstall_event FAILED
    fail 'Uninstall incomplete. Inspect diagnostics, resolve the blocker and retry with the same explicit target options; no original journal is required.'
  fi
  uninstall_event COMPLETED
  echo 'Uninstall completed. Shared database settings and unrelated environments were preserved.'
}
mc_privilege_policy_sql() {
cat <<'MC_PRIVILEGE_POLICY'
  -- Canonical anonymous declarations; embedded in integrity package and installer.
  -- No DDL is executed. This recognizes the exporter's bounded phase dialect,
  -- not arbitrary dynamic SQL inside application package bodies.
  FUNCTION policy_allowed(p_priv VARCHAR2) RETURN BOOLEAN IS
  BEGIN
    RETURN p_priv IN ('CREATE SESSION','CREATE TABLE','CREATE PROCEDURE','CREATE JOB',
      'CREATE SEQUENCE','CREATE VIEW','CREATE MATERIALIZED VIEW','CREATE PROPERTY GRAPH',
      'CREATE TRIGGER','CREATE TYPE','CREATE SYNONYM','CREATE ANY CONTEXT');
  END;
  PROCEDURE policy_report(p_required sys.odcivarchar2list,p_objects CLOB,
    o_missing OUT PLS_INTEGER,o_sql OUT CLOB) IS
    n NUMBER; pos PLS_INTEGER:=1; eol PLS_INTEGER; a PLS_INTEGER; b PLS_INTEGER;
    line VARCHAR2(4000); owner_name VARCHAR2(128); object_name VARCHAR2(128); priv VARCHAR2(32);
    grant_name VARCHAR2(300);
  BEGIN
    o_missing:=0;
    dbms_lob.createtemporary(o_sql,true);
    FOR i IN 1..p_required.count LOOP
      IF NOT policy_allowed(p_required(i)) THEN raise_application_error(-20070,'Unsupported system grant.'); END IF;
      SELECT count(*) INTO n FROM user_sys_privs WHERE privilege=p_required(i);
      IF n=0 THEN
        dbms_output.put_line('MC_GRANT|SYSTEM|'||p_required(i)); o_missing:=o_missing+1;
        dbms_lob.append(o_sql,'GRANT '||p_required(i)||' TO '||dbms_assert.enquote_name(sys_context('USERENV','CURRENT_USER'),false)||';'||chr(10));
      END IF;
    END LOOP;
    WHILE pos<=NVL(dbms_lob.getlength(p_objects),0) LOOP
      eol:=dbms_lob.instr(p_objects,chr(10),pos);
      IF eol=0 THEN eol:=dbms_lob.getlength(p_objects)+1; END IF;
      IF eol-pos>4000 THEN raise_application_error(-20070,'Invalid object grant inventory.'); END IF;
      line:=rtrim(dbms_lob.substr(p_objects,eol-pos,pos),chr(13));
      a:=instr(line,'|'); b:=instr(line,'|',a+1);
      owner_name:=substr(line,1,a-1); object_name:=substr(line,a+1,b-a-1); priv:=substr(line,b+1);
      IF a=0 OR b=0 OR owner_name IS NULL OR object_name IS NULL OR NOT regexp_like(owner_name,'^[A-Z][A-Z0-9_$#]{0,127}$','c')
         OR NOT regexp_like(object_name,'^[A-Z][A-Z0-9_$#]{0,127}$','c')
         OR priv IS NULL OR priv NOT IN ('EXECUTE','SELECT') THEN
        raise_application_error(-20070,'Invalid object grant inventory.');
      END IF;
      grant_name:=dbms_assert.enquote_name(owner_name,false)||'.'||dbms_assert.enquote_name(object_name,false);
      -- Oracle patches replace the physical DBMS_CLOUD package independently
      -- on each database. Also accept inventories from pre-portability bundles.
      IF owner_name='C##CLOUD$SERVICE' AND priv='EXECUTE' AND
         (object_name='DBMS_CLOUD' OR regexp_like(object_name,'^DBMS_CLOUD\$PDBCS_[A-Z0-9_]+$','c')) THEN
        SELECT count(*) INTO n FROM user_objects WHERE object_name='DBMS_CLOUD'
          AND object_type IN ('SYNONYM','PACKAGE','PROCEDURE','FUNCTION','TABLE','VIEW','TYPE','SEQUENCE','MATERIALIZED VIEW');
        IF n<>0 THEN raise_application_error(-20070,'Local DBMS_CLOUD object shadows the Oracle public synonym; DBA review required.'); END IF;
        BEGIN
          SELECT table_owner,table_name INTO owner_name,object_name FROM all_synonyms
            WHERE owner='PUBLIC' AND synonym_name='DBMS_CLOUD' AND db_link IS NULL
              AND table_owner='C##CLOUD$SERVICE';
        EXCEPTION WHEN NO_DATA_FOUND THEN
          raise_application_error(-20070,'Oracle public DBMS_CLOUD synonym unavailable; DBA review required.');
        END;
        grant_name:='DBMS_CLOUD';
      END IF;
      SELECT count(*) INTO n FROM all_tab_privs WHERE table_schema=owner_name AND table_name=object_name
        AND privilege=priv AND grantee IN (sys_context('USERENV','CURRENT_USER'),'PUBLIC');
      IF n=0 THEN
        dbms_output.put_line('MC_GRANT|OBJECT|'||owner_name||'|'||case when grant_name='DBMS_CLOUD' then 'DBMS_CLOUD' else object_name end||'|'||priv); o_missing:=o_missing+1;
        dbms_lob.append(o_sql,'GRANT '||priv||' ON '||grant_name||' TO '||dbms_assert.enquote_name(sys_context('USERENV','CURRENT_USER'),false)||';'||chr(10));
      END IF;
      pos:=eol+1;
    END LOOP;
    dbms_output.put_line('MC_GRANT_TARGET|'||sys_context('USERENV','CURRENT_USER')||'|'||
      sys_context('USERENV','DB_UNIQUE_NAME')||'|'||sys_context('USERENV','CON_NAME'));
    dbms_output.put_line('MC_GRANT_COUNT|'||o_missing);
  EXCEPTION WHEN OTHERS THEN
    IF dbms_lob.istemporary(o_sql)=1 THEN dbms_lob.freetemporary(o_sql); END IF;
    RAISE;
  END;
  FUNCTION policy_baseline RETURN sys.odcivarchar2list IS
  BEGIN
    RETURN sys.odcivarchar2list('CREATE SESSION','CREATE TABLE','CREATE PROCEDURE','CREATE JOB');
  END;
  PROCEDURE policy_finish(p_required sys.odcivarchar2list,p_context_found BOOLEAN) IS
  BEGIN
    FOR i IN 1..p_required.count LOOP
      IF p_required(i)='CREATE ANY CONTEXT' AND NOT p_context_found THEN
        raise_application_error(-20070,'CREATE ANY CONTEXT requires actual context creation in the release context phase.');
      END IF;
    END LOOP;
  END;
  PROCEDURE policy_add(p_priv VARCHAR2,p_required IN OUT NOCOPY sys.odcivarchar2list) IS
  BEGIN
    IF p_priv IS NULL OR NOT policy_allowed(p_priv) THEN
      raise_application_error(-20070,'Unsupported deployment system privilege.');
    END IF;
    FOR i IN 1..p_required.count LOOP IF p_required(i)=p_priv THEN RETURN; END IF; END LOOP;
    p_required.extend; p_required(p_required.count):=p_priv;
  END;
  FUNCTION policy_has_create(p_sql CLOB,p_kind VARCHAR2,p_depth PLS_INTEGER DEFAULT 0) RETURN BOOLEAN IS
    pos PLS_INTEGER:=1; len PLS_INTEGER:=NVL(dbms_lob.getlength(p_sql),0);
    cache VARCHAR2(32767); cache_start PLS_INTEGER:=0;
    token VARCHAR2(32767); literal VARCHAR2(32767); c VARCHAR2(4); closing VARCHAR2(4);
    prev VARCHAR2(32); before_prev VARCHAR2(32); state VARCHAR2(64);
    lob_append BOOLEAN:=FALSE;
    FUNCTION ch(n PLS_INTEGER) RETURN VARCHAR2 IS
    BEGIN
      IF n>len THEN RETURN NULL; END IF;
      IF n<cache_start OR n>=cache_start+NVL(length(cache),0) THEN
        cache_start:=n; cache:=dbms_lob.substr(p_sql,8000,n);
      END IF;
      RETURN substr(cache,n-cache_start+1,1);
    END;
  BEGIN
    WHILE pos<=len LOOP
      c:=ch(pos); token:=NULL; literal:=NULL;
      IF c IN (' ',chr(9),chr(10),chr(13)) THEN pos:=pos+1; CONTINUE;
      ELSIF c='-' AND ch(pos+1)='-' THEN
        WHILE pos<=len AND ch(pos)<>chr(10) LOOP pos:=pos+1; END LOOP; CONTINUE;
      ELSIF c='/' AND ch(pos+1)='*' THEN
        pos:=pos+2;
        WHILE pos<=len AND NOT(ch(pos)='*' AND ch(pos+1)='/') LOOP pos:=pos+1; END LOOP;
        pos:=pos+2; CONTINUE;
      ELSIF c='"' THEN
        pos:=pos+1;
        WHILE pos<=len LOOP
          IF ch(pos)='"' THEN
            IF ch(pos+1)='"' THEN pos:=pos+2; ELSE pos:=pos+1; EXIT; END IF;
          ELSE pos:=pos+1; END IF;
        END LOOP;
        token:='#IDENTIFIER#';
      ELSIF c='''' OR (upper(c)='Q' AND ch(pos+1)='''') THEN
        IF upper(c)='Q' THEN
          closing:=ch(pos+2);
          closing:=CASE closing WHEN '[' THEN ']' WHEN '(' THEN ')' WHEN '{' THEN '}' WHEN '<' THEN '>' ELSE closing END;
          pos:=pos+3;
          WHILE pos<=len AND NOT(ch(pos)=closing AND ch(pos+1)='''') LOOP
            IF NVL(length(literal),0)<8000 THEN literal:=literal||ch(pos); END IF;
            pos:=pos+1;
          END LOOP;
          pos:=pos+2;
        ELSE
          pos:=pos+1;
          WHILE pos<=len LOOP
            IF ch(pos)='''' THEN
              IF ch(pos+1)='''' THEN pos:=pos+1; ELSE pos:=pos+1; EXIT; END IF;
            END IF;
            IF NVL(length(literal),0)<8000 THEN literal:=literal||ch(pos); END IF;
            pos:=pos+1;
          END LOOP;
        END IF;
        -- Canonical view/MV/graph adapters assemble their CREATE statement in
        -- a CLOB. Infer its existing allowed privilege from the literal chunk;
        -- ordinary strings (including DBMS_OUTPUT) remain non-executable.
        IF p_depth=0 AND lob_append AND policy_has_create(to_clob(literal),p_kind,1) THEN
          RETURN TRUE;
        END IF;
        IF p_depth=0 AND before_prev='EXECUTE' AND prev='IMMEDIATE' THEN
          IF policy_has_create(to_clob(literal),p_kind,1) THEN RETURN TRUE; END IF;
          IF regexp_like(literal,'^[[:space:]]*CREATE([[:space:]]|$)','i') THEN
            raise_application_error(-20070,'Unsupported dynamic CREATE in deployment phase; use the canonical exporter.');
          END IF;
        END IF;
        token:='#LITERAL#';
      ELSIF instr('ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789_$#',c)>0 THEN
        WHILE pos<=len AND instr('ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789_$#',ch(pos))>0 LOOP
          IF NVL(length(token),0)<8000 THEN token:=token||upper(ch(pos)); END IF;
          pos:=pos+1;
        END LOOP;
      ELSE token:=c; pos:=pos+1;
      END IF;
      IF p_depth=0 AND before_prev='EXECUTE' AND prev='IMMEDIATE' AND token<>'#LITERAL#' THEN
        raise_application_error(-20070,'Computed deployment DDL requires explicit reviewed privilege support.');
      END IF;
      IF token='WRITEAPPEND' AND before_prev='DBMS_LOB' AND prev='.' THEN
        lob_append:=TRUE;
      ELSIF token=';' THEN lob_append:=FALSE;
      END IF;
      IF token='CREATE' THEN state:='CREATE';
      ELSIF state='CREATE' AND token IN ('OR','REPLACE','FORCE','EDITIONABLE','NONEDITIONABLE') THEN NULL;
      ELSIF state='CREATE' THEN
        IF token=p_kind THEN RETURN TRUE;
        ELSIF token IN ('PROPERTY','MATERIALIZED') THEN state:=token;
        ELSE state:=NULL; END IF;
      ELSIF state||' '||token=p_kind THEN RETURN TRUE;
      ELSE state:=NULL;
      END IF;
      before_prev:=prev; prev:=substr(token,1,32);
    END LOOP;
    RETURN FALSE;
  END;
  PROCEDURE policy_add_file(p_path VARCHAR2,p_sql CLOB,
    p_required IN OUT NOCOPY sys.odcivarchar2list) IS
    kind VARCHAR2(32); priv VARCHAR2(32); pos PLS_INTEGER:=1; eol PLS_INTEGER;
    line VARCHAR2(128); seen sys.odcivarchar2list:=sys.odcivarchar2list();
  BEGIN
    IF p_path='db/preflight/required_system_privileges.txt' THEN
      WHILE pos<=NVL(dbms_lob.getlength(p_sql),0) LOOP
        eol:=dbms_lob.instr(p_sql,chr(10),pos);
        IF eol=0 THEN eol:=dbms_lob.getlength(p_sql)+1; END IF;
        IF eol-pos>128 THEN raise_application_error(-20070,'Invalid system privilege inventory.'); END IF;
        line:=rtrim(dbms_lob.substr(p_sql,eol-pos,pos),chr(13));
        FOR i IN 1..seen.count LOOP
          IF seen(i)=line THEN raise_application_error(-20070,'Duplicate system privilege inventory entry.'); END IF;
        END LOOP;
        policy_add(line,seen); policy_add(line,p_required); pos:=eol+1;
      END LOOP;
      RETURN;
    END IF;
    kind:=CASE p_path
      WHEN 'db/ddl/02_sequences.sql' THEN 'SEQUENCE'
      WHEN 'db/ddl/03a_views.sql' THEN 'VIEW'
      WHEN 'db/ddl/05_contexts.sql' THEN 'CONTEXT'
      WHEN 'db/ddl/08_mviews.sql' THEN 'MATERIALIZED VIEW'
      WHEN 'db/ddl/08a_property_graphs.sql' THEN 'PROPERTY GRAPH'
      WHEN 'db/ddl/09_triggers.sql' THEN 'TRIGGER' END;
    IF kind IS NOT NULL AND policy_has_create(p_sql,kind) THEN
      priv:=CASE kind WHEN 'CONTEXT' THEN 'CREATE ANY CONTEXT' ELSE 'CREATE '||kind END;
      policy_add(priv,p_required);
    END IF;
  END;
MC_PRIVILEGE_POLICY
}
mc_archive_inspector_sql() {
cat <<'MC_ARCHIVE_INSPECTOR'
-- GENERATED by db/deployer/build_bundle_inspector.py; do not edit.

  TYPE t_member IS RECORD (
    name VARCHAR2(1000), compressed_size NUMBER, uncompressed_size NUMBER,
    method PLS_INTEGER, flags PLS_INTEGER, data_offset NUMBER, crc32 RAW(4)
  );
  TYPE t_members IS TABLE OF t_member INDEX BY PLS_INTEGER;

  PROCEDURE zip_fail(p_reason VARCHAR2) IS
  BEGIN
    raise_application_error(-20030, 'Invalid bundle ZIP: ' || p_reason);
  END;

  FUNCTION zip_uint(p_zip BLOB, p_offset NUMBER, p_width PLS_INTEGER) RETURN NUMBER IS
    r RAW(4); n NUMBER := 0;
  BEGIN
    IF p_offset < 1 OR p_width NOT IN (2,4)
       OR p_offset+p_width-1 > dbms_lob.getlength(p_zip) THEN zip_fail('truncated header'); END IF;
    r := dbms_lob.substr(p_zip,p_width,p_offset);
    FOR i IN REVERSE 1..p_width LOOP
      n := n*256 + to_number(rawtohex(utl_raw.substr(r,i,1)),'XX');
    END LOOP;
    RETURN n;
  END;

  PROCEDURE zip_extra(p_zip BLOB,p_offset NUMBER,p_length NUMBER) IS
    pos NUMBER:=p_offset; len NUMBER;
  BEGIN
    WHILE pos < p_offset+p_length LOOP
      IF pos+4 > p_offset+p_length THEN zip_fail('truncated extra field'); END IF;
      IF zip_uint(p_zip,pos,2)=1 THEN zip_fail('ZIP64 unsupported'); END IF;
      len:=zip_uint(p_zip,pos+2,2);
      pos:=pos+4+len;
      IF pos>p_offset+p_length THEN zip_fail('invalid extra field'); END IF;
    END LOOP;
  END;

  PROCEDURE zip_inspect(p_zip BLOB, p_members OUT NOCOPY t_members) IS
    len NUMBER:=dbms_lob.getlength(p_zip); eocd NUMBER; cd NUMBER; cd_size NUMBER;
    pos NUMBER; next_local NUMBER:=1; local_pos NUMBER; data_pos NUMBER;
    count_files PLS_INTEGER; name_len PLS_INTEGER; extra_len PLS_INTEGER; comment_len PLS_INTEGER;
    local_name_len PLS_INTEGER; local_extra_len PLS_INTEGER; total_size NUMBER:=0;
    r t_member; name_raw RAW(1000);
    TYPE t_seen IS TABLE OF BOOLEAN INDEX BY VARCHAR2(1000);
    seen t_seen;
  BEGIN
    p_members.delete;
    IF len IS NULL OR len<22 OR len>268435456 THEN zip_fail('archive size limit'); END IF;
    eocd:=len-21;
    WHILE eocd>=greatest(1,len-65556) LOOP
      EXIT WHEN dbms_lob.substr(p_zip,4,eocd)=hextoraw('504B0506')
        AND eocd+21+zip_uint(p_zip,eocd+20,2)=len;
      eocd:=eocd-1;
    END LOOP;
    IF eocd<greatest(1,len-65556) THEN zip_fail('missing end record'); END IF;
    IF zip_uint(p_zip,eocd+4,2)<>0 OR zip_uint(p_zip,eocd+6,2)<>0
       OR zip_uint(p_zip,eocd+8,2)<>zip_uint(p_zip,eocd+10,2) THEN zip_fail('multidisk unsupported'); END IF;
    count_files:=zip_uint(p_zip,eocd+10,2);
    IF count_files<1 OR count_files>20000 THEN zip_fail('member count limit'); END IF;
    cd_size:=zip_uint(p_zip,eocd+12,4); cd:=zip_uint(p_zip,eocd+16,4)+1;
    IF cd_size=4294967295 OR cd=4294967296 OR cd+cd_size<>eocd THEN zip_fail('invalid central directory'); END IF;
    pos:=cd;
    FOR i IN 1..count_files LOOP
      IF pos+46>eocd OR dbms_lob.substr(p_zip,4,pos)<>hextoraw('504B0102') THEN zip_fail('invalid directory entry'); END IF;
      IF zip_uint(p_zip,pos+6,2)>20 OR zip_uint(p_zip,pos+34,2)<>0 THEN zip_fail('unsupported ZIP version or disk'); END IF;
      r.flags:=zip_uint(p_zip,pos+8,2); r.method:=zip_uint(p_zip,pos+10,2);
      -- Classic exporter dialect: optional UTF-8 and deflate tuning bits only.
      IF bitand(r.flags,65535-2054)<>0 OR r.method NOT IN (0,8)
         OR (r.method=0 AND bitand(r.flags,6)<>0) THEN zip_fail('unsupported flags or method'); END IF;
      r.crc32:=dbms_lob.substr(p_zip,4,pos+16);
      r.compressed_size:=zip_uint(p_zip,pos+20,4); r.uncompressed_size:=zip_uint(p_zip,pos+24,4);
      IF r.compressed_size>268435456 OR r.uncompressed_size>134217728 THEN zip_fail('member size limit'); END IF;
      IF r.method=0 AND r.compressed_size<>r.uncompressed_size THEN zip_fail('stored size mismatch'); END IF;
      total_size:=total_size+r.uncompressed_size;
      IF total_size>1073741824 THEN zip_fail('total extracted size limit'); END IF;
      name_len:=zip_uint(p_zip,pos+28,2); extra_len:=zip_uint(p_zip,pos+30,2); comment_len:=zip_uint(p_zip,pos+32,2);
      IF name_len<1 OR name_len>1000 OR pos+46+name_len+extra_len+comment_len>eocd THEN zip_fail('invalid member name or entry length'); END IF;
      name_raw:=dbms_lob.substr(p_zip,name_len,pos+46);
      r.name:=utl_raw.cast_to_varchar2(name_raw);
      IF NOT regexp_like(r.name,'^[A-Za-z0-9._/-]+$','c') OR lengthb(r.name)<>name_len
         OR substr(r.name,1,1)='/' OR substr(r.name,-1)='/'
         OR instr(r.name,'//')>0 OR instr('/'||r.name||'/','/./')>0
         OR instr('/'||r.name||'/','/../')>0 THEN zip_fail('unsafe member path'); END IF;
      IF seen.exists(lower(r.name)) THEN zip_fail('duplicate or case-colliding member'); END IF;
      seen(lower(r.name)):=true;
      zip_extra(p_zip,pos+46+name_len,extra_len);
      local_pos:=zip_uint(p_zip,pos+42,4)+1;
      IF local_pos<>next_local OR local_pos+30>cd
         OR dbms_lob.substr(p_zip,4,local_pos)<>hextoraw('504B0304') THEN zip_fail('invalid local header layout'); END IF;
      local_name_len:=zip_uint(p_zip,local_pos+26,2); local_extra_len:=zip_uint(p_zip,local_pos+28,2);
      data_pos:=local_pos+30+local_name_len+local_extra_len;
      IF data_pos+r.compressed_size>cd OR local_name_len<>name_len
         OR dbms_lob.substr(p_zip,name_len,local_pos+30)<>name_raw
         OR zip_uint(p_zip,local_pos+4,2)<>zip_uint(p_zip,pos+6,2)
         OR zip_uint(p_zip,local_pos+6,2)<>r.flags
         OR zip_uint(p_zip,local_pos+8,2)<>r.method
         OR dbms_lob.substr(p_zip,4,local_pos+14)<>r.crc32
         OR zip_uint(p_zip,local_pos+18,4)<>r.compressed_size
         OR zip_uint(p_zip,local_pos+22,4)<>r.uncompressed_size THEN zip_fail('local and central headers disagree'); END IF;
      zip_extra(p_zip,local_pos+30+local_name_len,local_extra_len);
      r.data_offset:=data_pos; p_members(i):=r;
      next_local:=data_pos+r.compressed_size;
      pos:=pos+46+name_len+extra_len+comment_len;
    END LOOP;
    IF pos<>eocd OR next_local<>cd THEN zip_fail('unaccounted archive bytes'); END IF;
  EXCEPTION WHEN OTHERS THEN
    p_members.delete;
    IF sqlcode BETWEEN -20039 AND -20030 THEN RAISE; END IF;
    zip_fail('malformed archive');
  END;

  FUNCTION get_member(p_zip BLOB,p_member t_member,
    p_max_bytes NUMBER DEFAULT 134217728) RETURN BLOB IS
    output_blob BLOB; gzip_blob BLOB; handle BINARY_INTEGER;
    piece RAW(32767); size_le RAW(4); remaining NUMBER; part NUMBER;
    budget NUMBER; total NUMBER:=0;
    PROCEDURE cleanup IS
    BEGIN
      IF handle IS NOT NULL THEN
        BEGIN utl_compress.lz_uncompress_close(handle); EXCEPTION WHEN OTHERS THEN NULL; END;
        handle:=NULL;
      END IF;
      IF dbms_lob.istemporary(gzip_blob)=1 THEN dbms_lob.freetemporary(gzip_blob); END IF;
    END;
  BEGIN
    budget:=least(p_max_bytes,134217728,p_member.uncompressed_size);
    IF budget IS NULL OR budget<0 OR p_member.uncompressed_size>least(p_max_bytes,134217728)
       OR p_member.compressed_size<0 OR p_member.compressed_size>268435456
       OR p_member.data_offset<1
       OR p_member.data_offset+p_member.compressed_size-1>dbms_lob.getlength(p_zip)
       OR p_member.method NOT IN (0,8) THEN zip_fail('invalid extraction budget'); END IF;
    dbms_lob.createtemporary(output_blob,true,dbms_lob.call);
    IF p_member.method=0 THEN
      IF p_member.compressed_size<>p_member.uncompressed_size THEN zip_fail('stored size mismatch'); END IF;
      -- Stored members have no inflater CRC check; the integrity layer verifies SHA-256.
      IF p_member.compressed_size>0 THEN
        dbms_lob.copy(output_blob,p_zip,p_member.compressed_size,1,p_member.data_offset);
      END IF;
    ELSE
      dbms_lob.createtemporary(gzip_blob,true,dbms_lob.call);
      dbms_lob.writeappend(gzip_blob,10,hextoraw('1F8B0800000000000003'));
      IF p_member.compressed_size>0 THEN dbms_lob.copy(gzip_blob,p_zip,p_member.compressed_size,11,p_member.data_offset); END IF;
      remaining:=p_member.uncompressed_size; size_le:=NULL;
      FOR i IN 1..4 LOOP
        part:=mod(remaining,256); remaining:=trunc(remaining/256);
        size_le:=utl_raw.concat(size_le,hextoraw(to_char(part,'FM0X')));
      END LOOP;
      dbms_lob.writeappend(gzip_blob,8,utl_raw.concat(p_member.crc32,size_le));
      -- Oracle's gzip decoder rejects CRC mismatches (see --crc fixture).
      -- The bundle integrity layer additionally verifies exact SHA-256 bytes.
      handle:=utl_compress.lz_uncompress_open(gzip_blob);
      LOOP
        BEGIN
          piece:=NULL;
          utl_compress.lz_uncompress_extract(handle,piece);
        EXCEPTION WHEN no_data_found THEN EXIT;
        END;
        EXIT WHEN piece IS NULL;
        -- Check actual output before retaining each bounded RAW chunk in a LOB.
        -- This controls application output allocation, not Oracle inflater internals.
        IF total+utl_raw.length(piece)>budget THEN zip_fail('actual extracted size limit'); END IF;
        dbms_lob.writeappend(output_blob,utl_raw.length(piece),piece);
        total:=total+utl_raw.length(piece);
      END LOOP;
      cleanup;
    END IF;
    IF dbms_lob.getlength(output_blob)<>p_member.uncompressed_size THEN zip_fail('extracted size mismatch'); END IF;
    RETURN output_blob;
  EXCEPTION WHEN OTHERS THEN
    cleanup;
    IF dbms_lob.istemporary(output_blob)=1 THEN dbms_lob.freetemporary(output_blob); END IF;
    IF sqlcode BETWEEN -20039 AND -20030 THEN RAISE; END IF;
    zip_fail('corrupt member');
    RETURN NULL;
  END;

-- BEGIN ANONYMOUS ARTIFACT MANIFEST
    procedure artifact_fail(p_text varchar2) is
    begin raise_application_error(-20864,'Artifact manifest: '||p_text); end;
    procedure exact_fields(p_doc json_object_t,p_fields varchar2) is ks json_key_list;
    begin
      ks:=p_doc.get_keys;
      if ks.count<>regexp_count(p_fields,'\|')-1 then artifact_fail('Missing or unknown fields.'); end if;
      for i in 1..ks.count loop
        if instr(p_fields,'|'||ks(i)||'|')=0 then artifact_fail('Unknown field.'); end if;
      end loop;
    end;
    function string_value(p_doc json_object_t,p_field varchar2,p_limit number,p_nullable boolean default false) return varchar2 is
      e json_element_t; result varchar2(32767);
    begin
      e:=p_doc.get(p_field);
      if e is null then artifact_fail('Missing field '||p_field); end if;
      if e.is_null and p_nullable then return null; end if;
      if not e.is_string then artifact_fail('Expected string '||p_field); end if;
      result:=p_doc.get_string(p_field);
      if result is null or lengthb(result)>p_limit then artifact_fail('Invalid length '||p_field); end if;
      return result;
    end;
    function positive_integer(p_doc json_object_t,p_field varchar2,p_nullable boolean default false) return number is
      e json_element_t; result number;
    begin
      e:=p_doc.get(p_field);
      if e is null then artifact_fail('Missing field '||p_field); end if;
      if e.is_null and p_nullable then return null; end if;
      if not e.is_number then artifact_fail('Expected integer '||p_field); end if;
      result:=p_doc.get_number(p_field);
      if result is null or result<1 or result>9007199254740991 or result<>trunc(result) then artifact_fail('Invalid integer '||p_field); end if;
      return result;
    end;
    procedure assert_hash(p_hash varchar2) is
    begin if p_hash is null or not regexp_like(p_hash,'^[0-9a-f]{64}$','c') then artifact_fail('Invalid SHA-256.'); end if; end;
    function canonical_member(p_ordinal number,p_type varchar2,p_name varchar2,p_key varchar2) return varchar2 is
      type_label varchar2(100); name_label varchar2(100);
    begin
      if p_ordinal is null or p_ordinal<>trunc(p_ordinal) or p_ordinal<1 or p_ordinal>999999 then
        artifact_fail('Invalid object application ordinal.'); end if;
      assert_hash(p_key);
      type_label:=trim(both '_' from regexp_replace(upper(p_type),'[^A-Z0-9]+','_'));
      name_label:=trim(both '_' from regexp_replace(upper(p_name),'[^A-Z0-9]+','_'));
      if type_label is null or name_label is null then artifact_fail('Empty normalized object identity.'); end if;
      return 'db/objects/'||to_char(p_ordinal,'FM000000')||'_'||substr(type_label,1,80)||'_'||
        substr(name_label,1,100)||'_'||substr(p_key,1,12)||'.sql';
    end;
    procedure assert_member(p_member varchar2) is
    begin
      if p_member is null or not regexp_like(p_member,
        '^db/objects/[0-9]{6}_[A-Z0-9_]+_[A-Z0-9_]+_[0-9a-f]{12}[.]sql$','c') then
        artifact_fail('Unsafe or unknown object member.'); end if;
    end;
    function expected_phase(p_type varchar2) return varchar2 is
    begin
      return case p_type when 'TABLE' then '01_tables' when 'SEQUENCE' then '02_sequences'
        when 'INDEX' then '03_keys_indexes' when 'CONSTRAINT' then '03_keys_indexes' when 'FOREIGN KEY' then '03_keys_indexes'
        when 'VIEW' then '03a_views' when 'PACKAGE' then '04_pkg_specs' when 'TYPE' then '04_pkg_specs'
        when 'PACKAGE BODY' then '06_pkg_bodies' when 'TYPE BODY' then '06_pkg_bodies'
        when 'PROCEDURE' then '07_procs_funcs' when 'FUNCTION' then '07_procs_funcs'
        when 'MATERIALIZED VIEW' then '08_mviews' when 'PROPERTY GRAPH' then '08a_property_graphs'
        when 'TRIGGER' then '09_triggers' when 'JOB' then '90_jobs' when 'SCHEDULER JOB' then '90_jobs'
        else null end;
    end;
    function infrastructure_name(p_name varchar2) return boolean is
    begin
      return upper(p_name) in ('DEPLOY_MGR_PKG','MC_RUNTIME_GUARD_PKG','MC_RUNTIME_FENCE','MCSR_BUNDLE_RECONCILE',
        'MC_BUNDLE_UPDATE_STATE','MC_RUNTIME_BACKUPS','MC_BUNDLE_ZIP_PKG','MC_BUNDLE_INTEGRITY_PKG',
        'MC_BUNDLE_BOOTSTRAP_PKG','MC_BUNDLE_BOOTSTRAP_ASSETS_PKG','MC_ARTIFACT_UPDATE_PKG',
        'MC_ARTIFACT_SELECTION_PKG','MC_ARTIFACT_DEFINITION_PKG','MC_ARTIFACT_MANIFEST_PKG',
        'MC_ARTIFACT_RECEIPTS','MC_APEX_RECEIPTS','MC_DELTA_REQUEST','MC_DELTA_UPLOAD_ROWS',
        'DEP_REGISTRY_REVISIONS_PKG',
        'MC_REGISTRY_REVISION_CAPTURE_PKG','MC_REGISTRY_SOURCE_ARCHIVE_PKG',
        'MC_PRODUCT_REGISTRY_PKG','MC_REGISTRY_BASELINE_PKG','DEP_REV_PARITY',
        'DEP_REV_LINEAGE','DEP_REV_IDENTITIES','DEP_REV_HISTORY','DEP_REV_RUNS','DEP_REV_APPROVALS',
        'MC_BUNDLE_RECOVERY_STORE_PKG','MC_BUNDLE_RECOVERY_BOUNDARY_PKG','MC_BUNDLE_RECOVERY_SCHEDULER_PKG',
        'MCBR_REQUEST_IMMUTABLE','MCBR_EVENT_IMMUTABLE','MCBR_RECEIPT_IMMUTABLE');
    end;
  -- BEGIN REGISTRY RETIREMENT IDENTITIES
  function retired_registry_identity(p_type varchar2,p_name varchar2,p_parent varchar2) return boolean is
  begin
    return (p_type='TABLE' and p_name='DEP_REV_APPROVALS' and p_parent is null)
      or (p_type='PACKAGE' and p_name='MC_REGISTRY_BASELINE_PKG' and p_parent is null)
      or (p_type='PACKAGE BODY' and p_name='MC_REGISTRY_BASELINE_PKG' and p_parent is null)
      or (p_type='TABLE' and p_name='DEP_REV_PARITY' and p_parent is null)
      or (p_type='CONSTRAINT' and p_name='DEP_REV_PARITY_PK' and p_parent='DEP_REV_PARITY')
      or (p_type='INDEX' and p_name='DEP_REV_PARITY_PK' and p_parent='DEP_REV_PARITY')
      or (p_type='CONSTRAINT' and p_name='DEP_REV_PARITY_JSON_CK' and p_parent='DEP_REV_PARITY')
      or (p_type='FOREIGN KEY' and p_name='DEP_REV_PARITY_RUN_FK' and p_parent='DEP_REV_PARITY')
      or (p_type='INDEX' and p_name='DEP_REV_APPROVALS_PK' and p_parent='DEP_REV_APPROVALS')
      or (p_type='FOREIGN KEY' and p_name='DEP_REV_APPROVALS_RUN_FK' and p_parent='DEP_REV_APPROVALS')
      or (p_type='CONSTRAINT' and p_name='DEP_REV_APPROVALS_PK' and p_parent='DEP_REV_APPROVALS');
  end;
  -- END REGISTRY RETIREMENT IDENTITIES
  -- BEGIN PRODUCT LIFECYCLE GATE
  procedure assert_product_lifecycle(p_inventory clob) is
    doc json_object_t; entries json_array_t; entry json_object_t; el json_element_t;
    lifecycle varchar2(30); owner_key varchar2(64); valid number;
  begin
    if p_inventory is null or dbms_lob.getlength(p_inventory)>8388608 then
      artifact_fail('Product inventory size limit.'); end if;
    select case when p_inventory is json strict with unique keys then 1 else 0 end into valid from dual;
    if valid<>1 then artifact_fail('Malformed product inventory.'); end if;
    doc:=json_object_t.parse(p_inventory);
    if string_value(doc,'format',40)<>'mc-product-inventory-1' then artifact_fail('Unsupported product inventory.'); end if;
    el:=doc.get('unreviewed_count');
    if el is null or not el.is_number or doc.get_number('unreviewed_count')<>0 then
      artifact_fail('Unreviewed product candidates block export.'); end if;
    el:=doc.get('entries');
    if el is null or not el.is_array then artifact_fail('Product entries must be an array.'); end if;
    entries:=treat(el as json_array_t);
    if entries.get_size>10000 then artifact_fail('Too many product entries.'); end if;
    for i in 0..entries.get_size-1 loop
      el:=entries.get(i);
      if not el.is_object then artifact_fail('Product entry must be an object.'); end if;
      entry:=treat(el as json_object_t);
      lifecycle:=string_value(entry,'lifecycle',30,true);
      if lifecycle='BOOTSTRAP' then
        artifact_fail('Release contract 1.11 has no verified BOOTSTRAP installation boundary; product tool coverage is incomplete.');
      elsif lifecycle='APPLICATION' then null;
      elsif lifecycle is null and entry.has('implementation_of') then
        owner_key:=string_value(entry,'implementation_of',64,true);
        assert_hash(owner_key);
      else
        artifact_fail('Unknown product lifecycle.');
      end if;
    end loop;
  exception when others then
    if sqlcode=-20864 then raise; end if;
    raise_application_error(-20864,'Artifact manifest: malformed product inventory.');
  end;
  -- END PRODUCT LIFECYCLE GATE
  procedure validate_manifest(p_manifest clob,p_payloads clob) is
    doc json_object_t; payloads json_object_t; entries json_array_t;
    entry json_object_t; ident json_object_t; canonical json_object_t;
    deps json_array_t; el json_element_t; names json_key_list;
    key_value varchar2(64); state_value varchar2(16); phase_value varchar2(40);
    member_value varchar2(300); type_value varchar2(64); name_value varchar2(128); parent_value varchar2(128);
    hash_value varchar2(64); dep varchar2(64); valid number; edge_count number:=0; ordinal number;
    type text_map is table of varchar2(300) index by varchar2(300);
    states text_map; members text_map; seen_deps text_map; ordinals text_map;
  begin
    if p_manifest is null or dbms_lob.getlength(p_manifest)>8388608 or p_payloads is null
      or dbms_lob.getlength(p_payloads)>4194304 then artifact_fail('Metadata size limit.'); end if;
    select case when p_manifest is json strict with unique keys then 1 else 0 end into valid from dual;
    if valid<>1 then artifact_fail('Invalid manifest JSON.'); end if;
    select case when p_payloads is json strict with unique keys then 1 else 0 end into valid from dual;
    if valid<>1 then artifact_fail('Invalid payload JSON.'); end if;
    el:=json_element_t.parse(p_manifest);
    if not el.is_object then artifact_fail('Manifest must be an object.'); end if;
    doc:=treat(el as json_object_t);
    el:=json_element_t.parse(p_payloads);
    if not el.is_object then artifact_fail('Payload inventory must be an object.'); end if;
    payloads:=treat(el as json_object_t);
    exact_fields(doc,'|format|lineage_id|registry_run_id|artifacts|');
    if string_value(doc,'format',40)<>'mc-artifact-manifest-1' then artifact_fail('Unsupported format.'); end if;
    if not regexp_like(string_value(doc,'lineage_id',64),'^[a-zA-Z0-9][a-zA-Z0-9._-]*$','c') then artifact_fail('Invalid lineage.'); end if;
    valid:=positive_integer(doc,'registry_run_id');
    el:=doc.get('artifacts');
    if el is null or not el.is_array then artifact_fail('Artifacts must be an array.'); end if;
    entries:=treat(el as json_array_t);
    if entries.get_size>10000 then artifact_fail('Too many artifacts.'); end if;
    names:=payloads.get_keys;
    if names.count>10000 then artifact_fail('Too many payloads.'); end if;
    for i in 1..names.count loop
      assert_member(names(i)); assert_hash(string_value(payloads,names(i),64));
    end loop;
    for i in 0..entries.get_size-1 loop
      el:=entries.get(i);
      if not el.is_object then artifact_fail('Artifact must be an object.'); end if;
      entry:=treat(el as json_object_t);
      exact_fields(entry,'|key|revision|state|identity|definition_format|definition_sha256|member|payload_sha256|phase|depends_on|removal_decision_id|apply_ordinal|');
      key_value:=string_value(entry,'key',64); assert_hash(key_value);
      if states.exists(key_value) then artifact_fail('Duplicate or conflicting identity.'); end if;
      valid:=positive_integer(entry,'revision');
      state_value:=string_value(entry,'state',16);
      if state_value not in ('PRESENT','REMOVED') then artifact_fail('Unknown artifact state.'); end if;
      el:=entry.get('identity');
      if el is null or not el.is_object then artifact_fail('Identity must be an object.'); end if;
      ident:=treat(el as json_object_t);
      exact_fields(ident,'|owner_role|object_type|object_name|parent_name|');
      if string_value(ident,'owner_role',30)<>'APPLICATION_SCHEMA' then artifact_fail('Unsupported owner role.'); end if;
      type_value:=string_value(ident,'object_type',64); name_value:=string_value(ident,'object_name',128);
      parent_value:=string_value(ident,'parent_name',128,true);
      if (infrastructure_name(name_value) or infrastructure_name(parent_value))
        and not (state_value='REMOVED' and retired_registry_identity(type_value,name_value,parent_value)) then
        artifact_fail('Deployment infrastructure cannot be application-managed; review its ownership policy.'); end if;
      if (type_value in ('INDEX','CONSTRAINT','FOREIGN KEY') and parent_value is null)
        or (type_value not in ('INDEX','CONSTRAINT','FOREIGN KEY') and parent_value is not null) then artifact_fail('Invalid parent identity.'); end if;
      canonical:=json_object_t(); canonical.put('owner_role','APPLICATION_SCHEMA');
      canonical.put('object_type',type_value); canonical.put('object_name',name_value);
      if parent_value is null then canonical.put_null('parent_name'); else canonical.put('parent_name',parent_value); end if;
      hash_value:=lower(rawtohex(dbms_crypto.hash(utl_i18n.string_to_raw(canonical.to_string,'AL32UTF8'),dbms_crypto.hash_sh256)));
      if hash_value<>key_value then artifact_fail('Identity key mismatch.'); end if;
      phase_value:=string_value(entry,'phase',40);
      if expected_phase(type_value) is null or phase_value<>expected_phase(type_value) then artifact_fail('Unsupported type/phase.'); end if;
      if string_value(entry,'definition_format',40)<>'mc-artifact-definition-1' and not
        (string_value(entry,'definition_format',40)='mc-artifact-definition-2' and type_value in ('JOB','SCHEDULER JOB')) then
        artifact_fail('Unsupported definition format.'); end if;
      member_value:=string_value(entry,'member',300,true);
      if state_value='PRESENT' then
        ordinal:=positive_integer(entry,'apply_ordinal');
        if ordinal>999999 or ordinals.exists(to_char(ordinal,'TM9')) then artifact_fail('Duplicate or invalid application ordinal.'); end if;
        ordinals(to_char(ordinal,'TM9')):=key_value;
        if member_value<>canonical_member(ordinal,type_value,name_value,key_value) then artifact_fail('Object member and identity/order differ.'); end if;
        assert_hash(string_value(entry,'definition_sha256',64));
        assert_member(member_value);
        hash_value:=string_value(entry,'payload_sha256',64); assert_hash(hash_value);
        if not payloads.has(member_value) or hash_value<>string_value(payloads,member_value,64) then artifact_fail('Missing or mismatched payload.'); end if;
        if positive_integer(entry,'removal_decision_id',true) is not null then artifact_fail('Present artifact has removal approval.'); end if;
        if members.exists(member_value) then artifact_fail('Object payload shared between identities.'); end if;
        members(member_value):=phase_value;
      else
        ordinal:=positive_integer(entry,'apply_ordinal',true);
        if ordinal is not null then artifact_fail('Removal cannot have an application ordinal.'); end if;
        if member_value is not null or string_value(entry,'definition_sha256',64,true) is not null
          or string_value(entry,'payload_sha256',64,true) is not null then artifact_fail('Removal cannot contain executable payload.'); end if;
        valid:=positive_integer(entry,'removal_decision_id');
      end if;
      el:=entry.get('depends_on');
      if el is null or not el.is_array then artifact_fail('Dependencies must be an array.'); end if;
      deps:=treat(el as json_array_t);
      edge_count:=edge_count+deps.get_size;
      if deps.get_size>1000 or edge_count>100000 then artifact_fail('Dependency limit.'); end if;
      states(key_value):=state_value;
    end loop;
    for i in 1..names.count loop
      if not members.exists(names(i)) then artifact_fail('Unreferenced object payload.'); end if;
    end loop;
    for i in 0..entries.get_size-1 loop
      entry:=treat(entries.get(i) as json_object_t); key_value:=entry.get_string('key');
      deps:=entry.get_array('depends_on'); seen_deps.delete;
      for d in 0..deps.get_size-1 loop
        el:=deps.get(d);
        if not el.is_string then artifact_fail('Dependency must be a key string.'); end if;
        dep:=deps.get_string(d); assert_hash(dep);
        if not states.exists(dep) or dep=key_value or seen_deps.exists(dep) then artifact_fail('Unknown, self or duplicate dependency.'); end if;
        if states(key_value)='PRESENT' and states(dep)='REMOVED' then artifact_fail('Present artifact depends on a removal.'); end if;
        seen_deps(dep):='Y';
      end loop;
    end loop;
  exception when others then
    if sqlcode=-20864 then raise; end if;
    raise_application_error(-20864,'Artifact manifest: malformed or unsupported metadata.');
  end;
  function build_manifest(p_snapshot clob,p_bindings clob,p_payloads clob) return clob is
    source_doc json_object_t; output_doc json_object_t; entry json_object_t; binding json_object_t;
    source_entries json_array_t; bindings json_array_t; output_entries json_array_t:=json_array_t();
    element json_element_t; key_value varchar2(64); state_value varchar2(16); valid number;
    result clob;
    type index_map is table of pls_integer index by varchar2(64);
    binding_index index_map; source_keys index_map;
  begin
    if p_snapshot is null or dbms_lob.getlength(p_snapshot)>8388608 or p_bindings is null
      or dbms_lob.getlength(p_bindings)>8388608 then artifact_fail('Assembly metadata size limit.'); end if;
    select case when p_snapshot is json strict with unique keys then 1 else 0 end into valid from dual;
    if valid<>1 then artifact_fail('Invalid snapshot JSON.'); end if;
    select case when p_bindings is json strict with unique keys then 1 else 0 end into valid from dual;
    if valid<>1 then artifact_fail('Invalid bindings JSON.'); end if;
    element:=json_element_t.parse(p_snapshot);
    if not element.is_object then artifact_fail('Snapshot must be an object.'); end if;
    source_doc:=treat(element as json_object_t);
    exact_fields(source_doc,'|format|lineage_id|registry_run_id|artifacts|');
    element:=source_doc.get('artifacts');
    if element is null or not element.is_array then artifact_fail('Snapshot artifacts must be an array.'); end if;
    source_entries:=treat(element as json_array_t);
    element:=json_element_t.parse(p_bindings);
    if not element.is_array then artifact_fail('Bindings must be an array.'); end if;
    bindings:=treat(element as json_array_t);
    if source_entries.get_size>10000 or bindings.get_size>10000 then artifact_fail('Assembly artifact limit.'); end if;
    for i in 0..bindings.get_size-1 loop
      element:=bindings.get(i);
      if not element.is_object then artifact_fail('Extraction binding must be an object.'); end if;
      binding:=treat(element as json_object_t);
      exact_fields(binding,'|key|member|payload_sha256|phase|depends_on|apply_ordinal|');
      key_value:=string_value(binding,'key',64); assert_hash(key_value);
      if binding_index.exists(key_value) then artifact_fail('Duplicate extraction binding.'); end if;
      binding_index(key_value):=i;
    end loop;
    for i in 0..source_entries.get_size-1 loop
      element:=source_entries.get(i);
      if not element.is_object then artifact_fail('Source artifact must be an object.'); end if;
      entry:=treat(element as json_object_t);
      exact_fields(entry,'|key|identity|revision|state|definition_format|definition_sha256|removal_decision_id|');
      key_value:=string_value(entry,'key',64); assert_hash(key_value);
      if source_keys.exists(key_value) then artifact_fail('Duplicate source identity.'); end if;
      source_keys(key_value):=i;
      state_value:=string_value(entry,'state',16);
      if state_value='PRESENT' then
        if not binding_index.exists(key_value) then artifact_fail('Missing extraction binding.'); end if;
        binding:=treat(bindings.get(binding_index(key_value)) as json_object_t);
        entry.put('member',binding.get('member')); entry.put('payload_sha256',binding.get('payload_sha256'));
        entry.put('phase',binding.get('phase')); entry.put('depends_on',binding.get('depends_on'));
        entry.put('apply_ordinal',binding.get('apply_ordinal'));
      elsif state_value='REMOVED' then
        if binding_index.exists(key_value) then artifact_fail('Removal has extraction binding.'); end if;
        element:=entry.get('identity');
        if element is null or not element.is_object then artifact_fail('Identity must be an object.'); end if;
        binding:=treat(element as json_object_t);
        entry.put_null('member'); entry.put_null('payload_sha256');
        entry.put_null('apply_ordinal');
        entry.put('phase',expected_phase(string_value(binding,'object_type',64)));
        entry.put('depends_on',json_array_t());
      else artifact_fail('Unknown artifact state.'); end if;
      output_entries.append(entry);
    end loop;
    key_value:=binding_index.first;
    while key_value is not null loop
      if not source_keys.exists(key_value) then artifact_fail('Unknown extraction binding.'); end if;
      key_value:=binding_index.next(key_value);
    end loop;
    output_doc:=source_doc; output_doc.put('artifacts',output_entries); result:=output_doc.to_clob;
    validate_manifest(result,p_payloads);
    return result;
  exception when others then
    if result is not null and dbms_lob.istemporary(result)=1 then dbms_lob.freetemporary(result); end if;
    if sqlcode=-20864 then raise; end if;
    raise_application_error(-20864,'Artifact manifest: malformed or unsupported assembly metadata.');
  end;
  function execution_order(p_manifest clob,p_payloads clob) return clob is
    doc json_object_t; entries json_array_t; entry json_object_t;
    deps json_array_t; output json_array_t:=json_array_t();
    type index_map is table of pls_integer index by varchar2(601);
    type number_list is table of pls_integer index by pls_integer;
    type adjacency_map is table of json_array_t index by pls_integer;
    type name_list is table of varchar2(300) index by pls_integer;
    groups index_map; identities index_map; seen_edges index_map;
    artifact_group number_list; incoming number_list; ranks number_list; completed number_list;
    outgoing adjacency_map; labels name_list;
    group_count pls_integer:=0; group_id pls_integer; other_id pls_integer;
    from_id pls_integer; to_id pls_integer; selected pls_integer; chosen_rank pls_integer;
    group_name varchar2(300); edge_name varchar2(601); list_value json_array_t;
    function rank_value(p_phase varchar2,p_state varchar2,p_type varchar2) return pls_integer is
    begin
      -- Deleted source objects no longer have live key/backing-index metadata.
      -- Keep the existing removal classes as a tie-breaker; explicit captured
      -- dependency edges always take precedence over this deterministic rank.
      if p_state='REMOVED' then return case p_type when 'FOREIGN KEY' then -100
        when 'CONSTRAINT' then -90 when 'INDEX' then -80
        when 'PACKAGE BODY' then -70 when 'TYPE BODY' then -70
        when 'TABLE' then -50 else -60 end; end if;
      return case p_phase when '01_tables' then 10 when '02_sequences' then 20
        when '03_keys_indexes' then case p_type when 'INDEX' then 30
          when 'CONSTRAINT' then 31 when 'FOREIGN KEY' then 32 else 33 end
        when '03a_views' then 40 when '04_pkg_specs' then 50
        when '06_pkg_bodies' then 60 when '07_procs_funcs' then 70 when '08_mviews' then 80
        when '08a_property_graphs' then 90 when '09_triggers' then 100 when '90_jobs' then 110 end;
    end;
  begin
    validate_manifest(p_manifest,p_payloads);
    doc:=json_object_t.parse(p_manifest); entries:=doc.get_array('artifacts');
    for i in 0..entries.get_size-1 loop
      entry:=treat(entries.get(i) as json_object_t);
      group_name:=entry.get_string('key');
      if not groups.exists(group_name) then
        group_count:=group_count+1; groups(group_name):=group_count;
        incoming(group_count):=0; outgoing(group_count):=json_array_t();
        ranks(group_count):=rank_value(entry.get_string('phase'),entry.get_string('state'),
          entry.get_object('identity').get_string('object_type'));
        labels(group_count):=group_name;
      end if;
      artifact_group(i):=groups(group_name); identities(entry.get_string('key')):=i;
    end loop;
    for i in 0..entries.get_size-1 loop
      entry:=treat(entries.get(i) as json_object_t); deps:=entry.get_array('depends_on'); group_id:=artifact_group(i);
      for d in 0..deps.get_size-1 loop
        other_id:=artifact_group(identities(deps.get_string(d)));
        if other_id<>group_id then
          if entry.get_string('state')='REMOVED' then from_id:=group_id; to_id:=other_id;
          else from_id:=other_id; to_id:=group_id; end if;
          edge_name:=labels(from_id)||'|'||labels(to_id);
          if not seen_edges.exists(edge_name) then
            seen_edges(edge_name):=1; incoming(to_id):=incoming(to_id)+1;
            list_value:=outgoing(from_id); list_value.append(to_id); outgoing(from_id):=list_value;
          end if;
        end if;
      end loop;
    end loop;
    for wave in 1..group_count loop
      selected:=null; chosen_rank:=null;
      for candidate in 1..group_count loop
        if not completed.exists(candidate) and incoming(candidate)=0 and
          (selected is null or ranks(candidate)<chosen_rank or
           (ranks(candidate)=chosen_rank and labels(candidate)<labels(selected))) then
          selected:=candidate; chosen_rank:=ranks(candidate);
        end if;
      end loop;
      if selected is null then artifact_fail('Dependency cycle requires an explicit operation group.'); end if;
      completed(selected):=1;
      for i in 0..entries.get_size-1 loop
        if artifact_group(i)=selected then entry:=treat(entries.get(i) as json_object_t); output.append(entry.get('key')); end if;
      end loop;
      list_value:=outgoing(selected);
      for d in 0..list_value.get_size-1 loop
        to_id:=list_value.get_number(d); incoming(to_id):=incoming(to_id)-1;
      end loop;
    end loop;
    return output.to_clob;
  end;
  function initial_plan(p_manifest clob,p_payloads clob) return clob is
    ordering_text clob; result clob; ordering json_array_t; entries json_array_t;
    doc json_object_t; entry json_object_t; dependency json_object_t; deps json_array_t;
    type index_map is table of pls_integer index by varchar2(300);
    keys index_map; emitted index_map; member_name varchar2(300); phase_name varchar2(40);
  begin
    ordering_text:=execution_order(p_manifest,p_payloads);
    ordering:=json_array_t.parse(ordering_text); dbms_lob.freetemporary(ordering_text); ordering_text:=null;
    doc:=json_object_t.parse(p_manifest); entries:=doc.get_array('artifacts');
    for i in 0..entries.get_size-1 loop
      entry:=treat(entries.get(i) as json_object_t); keys(entry.get_string('key')):=i;
    end loop;
    dbms_lob.createtemporary(result,true);
    dbms_lob.append(result,'MC_INITIAL_OBJECT_PLAN|1'||chr(10));
    for i in 0..ordering.get_size-1 loop
      entry:=treat(entries.get(keys(ordering.get_string(i))) as json_object_t);
      if entry.get_string('state')<>'PRESENT' then continue; end if;
      phase_name:=entry.get_string('phase'); member_name:=entry.get_string('member');
      if phase_name in ('01_tables','02_sequences','03_keys_indexes') then
        -- This mandatory prelude establishes the coordinator's storage before
        -- installing its body. Never silently discard an edge into later code.
        deps:=entry.get_array('depends_on');
        for d in 0..deps.get_size-1 loop
          dependency:=treat(entries.get(keys(deps.get_string(d))) as json_object_t);
          if dependency.get_string('phase') not in ('01_tables','02_sequences','03_keys_indexes') then
            artifact_fail('INITIAL storage prelude depends on later code; an authored bootstrap migration is required.'); end if;
        end loop;
      end if;
      if not emitted.exists(member_name) then
        dbms_lob.append(result,phase_name||'|'||member_name||chr(10)); emitted(member_name):=1;
      end if;
    end loop;
    return result;
  exception when others then
    if dbms_lob.istemporary(ordering_text)=1 then dbms_lob.freetemporary(ordering_text); end if;
    if dbms_lob.istemporary(result)=1 then dbms_lob.freetemporary(result); end if;
    raise;
  end;
  -- Product coverage is separate from the strict application manifest. It binds
  -- every reviewed identity to its installation boundary and actual ZIP bytes.
  procedure validate_product_coverage(p_coverage clob,p_artifacts clob,p_payloads clob) is
    doc json_object_t; inventory json_object_t; payloads json_object_t; appdoc json_object_t;
    entries json_array_t; bindings json_array_t; generators json_array_t; appentries json_array_t;
    item json_object_t; binding json_object_t; ident json_object_t; canonical json_object_t;
    proof json_object_t; generator json_object_t; constituents json_array_t; el json_element_t;
    app_payloads json_object_t:=json_object_t(); names json_key_list; deps json_array_t; dep json_object_t;
    key_value varchar2(64); owner_key varchar2(64); lifecycle varchar2(30); state_value varchar2(16);
    type_value varchar2(64); name_value varchar2(128); parent_value varchar2(128); member_value varchar2(300);
    action_value varchar2(30); hash_value varchar2(64); ordinal number; n number; valid number;
    type idx_map is table of pls_integer index by varchar2(300);
    item_index idx_map; binding_index idx_map; ordered_binding_index idx_map; app_index idx_map; used_members idx_map; orders idx_map;
    global_orders idx_map;
    generator_keys idx_map; input_members idx_map;
    procedure strict_json(p_text clob,p_limit number) is
    begin
      if p_text is null or dbms_lob.getlength(p_text)>p_limit then artifact_fail('Product metadata size limit.'); end if;
      select case when p_text is json strict with unique keys then 1 else 0 end into valid from dual;
      if valid<>1 then artifact_fail('Product metadata requires strict unique JSON.'); end if;
    end;
    procedure bind_bytes(p_member varchar2,p_hash varchar2) is
    begin
      assert_hash(p_hash);
      if not payloads.has(p_member) or string_value(payloads,p_member,64)<>p_hash then
        artifact_fail('Missing or mismatched product payload.'); end if;
      used_members(p_member):=1;
    end;
    procedure input_proof(p_input json_object_t) is path_value varchar2(300);
    begin
      exact_fields(p_input,'|member|sha256|source_path|');
      path_value:=string_value(p_input,'member',300);
      if not regexp_like(path_value,'^db/bootstrap/provenance/[A-Za-z0-9_-]+[.](py|sql|json)$','c') then
        artifact_fail('Unsafe generator input member.'); end if;
      if input_members.exists(path_value) then artifact_fail('Duplicate generator input.'); end if;
      input_members(path_value):=1;
      if not regexp_like(string_value(p_input,'source_path',300),'^(db|tools)/[A-Za-z0-9_./-]+$','c')
        or instr(p_input.get_string('source_path'),'..')>0 then artifact_fail('Unsafe canonical input path.'); end if;
      bind_bytes(path_value,string_value(p_input,'sha256',64));
    end;
  begin
    strict_json(p_coverage,16777216); strict_json(p_artifacts,8388608); strict_json(p_payloads,4194304);
    doc:=json_object_t.parse(p_coverage); payloads:=json_object_t.parse(p_payloads);
    exact_fields(doc,'|format|registry_run_id|inventory|bindings|generators|');
    if string_value(doc,'format',40)<>'mc-product-coverage-1' then artifact_fail('Unsupported product coverage format.'); end if;
    n:=positive_integer(doc,'registry_run_id'); inventory:=doc.get_object('inventory');
    if string_value(inventory,'format',40)<>'mc-product-inventory-1' or positive_integer(inventory,'registry_run_id')<>n then
      artifact_fail('Product inventory run/format mismatch.'); end if;
    el:=inventory.get('unreviewed_count');
    if el is null or not el.is_number or inventory.get_number('unreviewed_count')<>0 then artifact_fail('Unreviewed product inventory.'); end if;
    entries:=inventory.get_array('entries'); bindings:=doc.get_array('bindings'); generators:=doc.get_array('generators');
    if entries.get_size>10000 or bindings.get_size>10000 or generators.get_size>100 then artifact_fail('Product inventory limit.'); end if;
    appdoc:=json_object_t.parse(p_artifacts);
    if string_value(inventory,'lineage_id',64)<>string_value(appdoc,'lineage_id',64) then artifact_fail('Application/product lineage mismatch.'); end if;
    if positive_integer(appdoc,'registry_run_id')<>n then artifact_fail('Application/product run mismatch.'); end if;
    appentries:=appdoc.get_array('artifacts');
    for i in 0..appentries.get_size-1 loop
      item:=treat(appentries.get(i) as json_object_t); key_value:=string_value(item,'key',64);
      if app_index.exists(key_value) then artifact_fail('Duplicate application key.'); end if;
      app_index(key_value):=i;
      member_value:=string_value(item,'member',300,true);
      if member_value is not null then
        ordinal:=to_number(substr(member_value,12,6));
        if global_orders.exists(to_char(ordinal,'TM9')) then artifact_fail('Duplicate global application ordinal.'); end if;
        global_orders(to_char(ordinal,'TM9')):=1;
        bind_bytes(member_value,string_value(item,'payload_sha256',64));
        app_payloads.put(member_value,payloads.get_string(member_value));
      end if;
    end loop;
    validate_manifest(p_artifacts,app_payloads.to_clob);
    for i in 0..bindings.get_size-1 loop
      binding:=treat(bindings.get(i) as json_object_t);
      exact_fields(binding,'|key|member|payload_sha256|action|install_order|');
      key_value:=string_value(binding,'key',64); assert_hash(key_value);
      if binding_index.exists(key_value) then artifact_fail('Duplicate product binding.'); end if;
      binding_index(key_value):=i; ordered_binding_index(key_value):=i;
    end loop;
    for i in 0..entries.get_size-1 loop
      item:=treat(entries.get(i) as json_object_t); key_value:=string_value(item,'key',64); assert_hash(key_value);
      if item_index.exists(key_value) then artifact_fail('Duplicate product identity.'); end if;
      item_index(key_value):=i; ident:=item.get_object('identity');
      exact_fields(ident,'|owner_role|object_type|object_name|parent_name|');
      if string_value(ident,'owner_role',30)<>'APPLICATION_SCHEMA' then artifact_fail('Unsupported product owner role.'); end if;
      type_value:=string_value(ident,'object_type',64); name_value:=string_value(ident,'object_name',128);
      parent_value:=string_value(ident,'parent_name',128,true);
      canonical:=json_object_t(); canonical.put('owner_role','APPLICATION_SCHEMA');
      canonical.put('object_type',type_value); canonical.put('object_name',name_value); canonical.put('parent_name',parent_value);
      hash_value:=lower(rawtohex(dbms_crypto.hash(utl_i18n.string_to_raw(canonical.to_string,'AL32UTF8'),dbms_crypto.hash_sh256)));
      if hash_value<>key_value then artifact_fail('Product identity key mismatch.'); end if;
      lifecycle:=string_value(item,'lifecycle',30,true);
      if lifecycle is null then
        assert_hash(string_value(item,'implementation_of',64));
        if binding_index.exists(key_value) then artifact_fail('Implementation storage cannot have executable binding.'); end if;
        continue;
      end if;
      if not binding_index.exists(key_value) then artifact_fail('Missing product identity binding.'); end if;
      binding:=treat(bindings.get(binding_index(key_value)) as json_object_t);
      state_value:=string_value(item,'state',16); valid:=positive_integer(item,'revision');
      if string_value(item,'definition_format',40)<>'mc-artifact-definition-1' and not
        (item.get_string('definition_format')='mc-artifact-definition-2' and type_value in ('JOB','SCHEDULER JOB')) then
        artifact_fail('Unsupported product definition format.'); end if;
      member_value:=string_value(binding,'member',300,true); action_value:=string_value(binding,'action',30);
      ordinal:=positive_integer(binding,'install_order',true);
      if lifecycle='APPLICATION' then
        if not app_index.exists(key_value) or action_value<>'APPLICATION' or ordinal is not null then artifact_fail('Application coverage mismatch.'); end if;
        proof:=treat(appentries.get(app_index(key_value)) as json_object_t);
        if proof.get_string('state')<>state_value or proof.get_number('revision')<>item.get_number('revision')
          or proof.get_string('definition_format')<>item.get_string('definition_format')
          or nvl(proof.get_string('definition_sha256'),'!')<>nvl(item.get_string('definition_sha256'),'!')
          or nvl(proof.get_string('member'),'!')<>nvl(member_value,'!')
          or nvl(proof.get_string('payload_sha256'),'!')<>nvl(string_value(binding,'payload_sha256',64,true),'!') then
          artifact_fail('Application definition/payload differs from product coverage.'); end if;
        app_index.delete(key_value);
      elsif lifecycle='BOOTSTRAP' then
        if state_value<>'PRESENT' then artifact_fail('Tool removal needs a supported recovery contract.'); end if;
        assert_hash(string_value(item,'definition_sha256',64));
        if ordinal is null or orders.exists(to_char(ordinal,'TM9')) then artifact_fail('Duplicate or missing bootstrap install order.'); end if;
        orders(to_char(ordinal,'TM9')):=1;
        if member_value is null or not regexp_like(member_value,'^db/objects/[0-9]{6}_','c') or
          member_value<>canonical_member(to_number(substr(member_value,12,6)),type_value,name_value,key_value) then
          artifact_fail('Unsafe bootstrap payload member.'); end if;
        if global_orders.exists(to_char(to_number(substr(member_value,12,6)),'TM9')) then
          artifact_fail('Duplicate global object ordinal.'); end if;
        global_orders(to_char(to_number(substr(member_value,12,6)),'TM9')):=1;
        if type_value in ('TABLE','INDEX','CONSTRAINT','FOREIGN KEY') then
          if action_value<>'STORAGE' then artifact_fail('Tool storage requires the storage boundary.'); end if;
          if type_value in ('INDEX','CONSTRAINT','FOREIGN KEY') and parent_value is null then artifact_fail('Storage parent required.'); end if;
        elsif type_value in ('PACKAGE','PACKAGE BODY','PROCEDURE','FUNCTION','TRIGGER','TYPE','TYPE BODY','VIEW','SEQUENCE','JOB','SCHEDULER JOB') then
          if action_value<>'UNIT' then artifact_fail('Tool code requires the unit boundary.'); end if;
        else artifact_fail('Unsupported bootstrap object family.'); end if;
        if used_members.exists(member_value) then artifact_fail('Bootstrap payload sharing is not permitted.'); end if;
        bind_bytes(member_value,string_value(binding,'payload_sha256',64));
      else artifact_fail('Unknown product lifecycle.'); end if;
      binding_index.delete(key_value);
    end loop;
    if app_index.count<>0 or binding_index.count<>0 then artifact_fail('Uninventoried application or bootstrap binding.'); end if;
    for i in 0..entries.get_size-1 loop
      item:=treat(entries.get(i) as json_object_t); key_value:=item.get_string('key');
      if item.get_string('lifecycle') is null then
        owner_key:=string_value(item,'implementation_of',64);
        if not item_index.exists(owner_key) or owner_key=key_value then artifact_fail('Missing implementation owner.'); end if;
        proof:=treat(entries.get(item_index(owner_key)) as json_object_t);
        if proof.get_string('lifecycle') is null or proof.get_string('state')<>'PRESENT' then artifact_fail('Invalid implementation owner.'); end if;
      end if;
      deps:=item.get_array('dependencies');
      for d in 0..deps.get_size-1 loop
        dep:=treat(deps.get(d) as json_object_t);
        if dep.has('key') then
          owner_key:=string_value(dep,'key',64);
          if not item_index.exists(owner_key) then artifact_fail('Product dependency omitted.'); end if;
          proof:=treat(entries.get(item_index(owner_key)) as json_object_t);
          if proof.get_string('lifecycle') is null then owner_key:=proof.get_string('implementation_of'); proof:=treat(entries.get(item_index(owner_key)) as json_object_t); end if;
          if item.get_string('lifecycle')='BOOTSTRAP' and proof.get_string('lifecycle')='BOOTSTRAP'
            and nvl(dep.get_string('kind'),'!') not in ('IMPLEMENTATION_BODY','STRUCTURAL_COMPONENT') then
            binding:=treat(bindings.get(ordered_binding_index(key_value)) as json_object_t);
            generator:=treat(bindings.get(ordered_binding_index(owner_key)) as json_object_t);
            if binding.get_string('member')<>generator.get_string('member')
              and generator.get_number('install_order')>=binding.get_number('install_order') then
              artifact_fail('Bootstrap install order violates reviewed dependencies.'); end if;
          end if;
        elsif nvl(dep.get_string('policy'),'!')<>'EXTERNAL_PREREQUISITE' then artifact_fail('Unknown product dependency policy.'); end if;
      end loop;
    end loop;
    for i in 0..generators.get_size-1 loop
      generator:=treat(generators.get(i) as json_object_t);
      exact_fields(generator,'|key|generator|constituents|'); key_value:=string_value(generator,'key',64);
      if generator_keys.exists(key_value) or not item_index.exists(key_value) then artifact_fail('Unknown or duplicate generated identity.'); end if;
      generator_keys(key_value):=1; item:=treat(entries.get(item_index(key_value)) as json_object_t);
      if item.get_string('lifecycle')<>'BOOTSTRAP' or item.get_string('state')<>'PRESENT' then artifact_fail('Invalid generated-container lifecycle.'); end if;
      input_members.delete; input_proof(generator.get_object('generator'));
      if generator.get_object('generator').get_string('source_path')=item.get_string('source_path') then
        artifact_fail('Generated output cannot be its own generator.'); end if;
      constituents:=generator.get_array('constituents');
      if constituents.get_size=0 or constituents.get_size>100 then artifact_fail('Generated constituent count.'); end if;
      for c in 0..constituents.get_size-1 loop
        proof:=treat(constituents.get(c) as json_object_t);
        if proof.get_string('source_path')=item.get_string('source_path') then artifact_fail('Generated output cannot be its own constituent.'); end if;
        input_proof(proof);
      end loop;
      ident:=item.get_object('identity');
      if ident.get_string('object_name')='MC_BUNDLE_BOOTSTRAP_ASSETS_PKG' and ident.get_string('object_type')='PACKAGE BODY' then
        if generator.get_object('generator').get_string('source_path')<>'db/deployer/build_bootstrap_assets.py'
          or constituents.get_size<>3 then artifact_fail('Bootstrap generator provenance is incomplete.'); end if;
        for k in 1..3 loop
          member_value:=case k when 1 then 'db/source/release/mc_bundle_bootstrap_ddl.sql'
            when 2 then 'db/source/release/mc_artifact_update_ddl.sql' else 'db/source/release/mc_product_bootstrap_driver.sql' end;
          n:=0;
          for c in 0..constituents.get_size-1 loop
            proof:=treat(constituents.get(c) as json_object_t);
            if proof.get_string('source_path')=member_value then n:=n+1; end if;
          end loop;
          if n<>1 then artifact_fail('Bootstrap constituent provenance is incomplete.'); end if;
        end loop;
      end if;
    end loop;
    names:=payloads.get_keys;
    for i in 1..names.count loop
      if not used_members.exists(names(i)) then artifact_fail('Uninventoried product payload.'); end if;
    end loop;
  exception when others then
    if sqlcode=-20864 then raise; end if;
    raise_application_error(-20864,'Artifact manifest: malformed product coverage.');
  end;
  function build_product_coverage(p_inventory clob,p_bindings clob,p_generators clob,
    p_artifacts clob,p_payloads clob) return clob is
    doc json_object_t:=json_object_t(); inventory json_object_t; result clob; valid number;
  begin
    select case when p_inventory is json strict with unique keys and p_bindings is json strict with unique keys
      and p_generators is json strict with unique keys then 1 else 0 end into valid from dual;
    if valid<>1 then artifact_fail('Product builder inputs require unique strict JSON.'); end if;
    inventory:=json_object_t.parse(p_inventory);
    doc.put('format','mc-product-coverage-1'); doc.put('registry_run_id',inventory.get_number('registry_run_id'));
    doc.put('inventory',inventory); doc.put('bindings',json_array_t.parse(p_bindings));
    doc.put('generators',json_array_t.parse(p_generators)); result:=doc.to_clob;
    validate_product_coverage(result,p_artifacts,p_payloads); return result;
  exception when others then
    if dbms_lob.istemporary(result)=1 then dbms_lob.freetemporary(result); end if;
    raise;
  end;
  function product_initial_plan(p_coverage clob,p_artifacts clob,p_payloads clob) return clob is
    doc json_object_t; entries json_array_t; bindings json_array_t; item json_object_t; binding json_object_t;
    dependency json_object_t; target json_object_t; deps json_array_t; result clob;
    app_order_text clob; app_order json_array_t; app_entries json_array_t;
    app_payloads json_object_t:=json_object_t(); all_payloads json_object_t; app_entry json_object_t;
    type number_map is table of pls_integer index by varchar2(300);
    type integer_list is table of pls_integer index by pls_integer;
    type key_list is table of varchar2(64) index by pls_integer;
    entry_index number_map; binding_index number_map; finished number_map; emitted number_map;
    ordered_entries integer_list; entry_ranks integer_list; entry_keys key_list;
    key_value varchar2(64); dependency_key varchar2(64); owner_key varchar2(64); member_value varchar2(300);
    typ varchar2(64); boundary varchar2(30); remaining number; progress_count number; ready boolean;
    slot pls_integer; previous_index pls_integer; i pls_integer;
    function storage(p_item json_object_t) return boolean is family varchar2(64):=p_item.get_object('identity').get_string('object_type');
    begin return family in ('TABLE','CONSTRAINT','FOREIGN KEY','INDEX','SEQUENCE'); end;
    function install_rank(p_item json_object_t) return pls_integer is
      family varchar2(64):=p_item.get_object('identity').get_string('object_type');
    begin
      -- Use the former grouped boundaries as a deterministic fallback for
      -- every inventory member. Captured dependencies still gate readiness.
      if family not in ('TABLE','SEQUENCE','INDEX','CONSTRAINT','FOREIGN KEY',
        'VIEW','TYPE','PACKAGE','TYPE BODY','PACKAGE BODY','PROCEDURE','FUNCTION',
        'MATERIALIZED VIEW','PROPERTY GRAPH','TRIGGER','JOB','SCHEDULER JOB') then
        artifact_fail('Unsupported product object type in INITIAL plan: '||nvl(family,'NULL'));
      end if;
      return case family when 'TABLE' then 10 when 'SEQUENCE' then 20
        when 'INDEX' then 30 when 'CONSTRAINT' then 31 when 'FOREIGN KEY' then 32
        when 'VIEW' then 40 when 'TYPE' then 45 when 'PACKAGE' then 50
        when 'TYPE BODY' then 60 when 'PACKAGE BODY' then 60
        when 'PROCEDURE' then 70 when 'FUNCTION' then 70
        when 'MATERIALIZED VIEW' then 80 when 'PROPERTY GRAPH' then 90
        when 'TRIGGER' then 100 when 'JOB' then 110 when 'SCHEDULER JOB' then 110 end;
    end;
    function ready_to_install(p_item json_object_t,p_member varchar2) return boolean is dependencies json_array_t; dep json_object_t; k varchar2(64); candidate json_object_t; owner json_object_t;
    begin
      dependencies:=p_item.get_array('dependencies');
      for d in 0..dependencies.get_size-1 loop
        dep:=treat(dependencies.get(d) as json_object_t);
        if dep.has('key') and nvl(dep.get_string('kind'),'!') not in ('IMPLEMENTATION_BODY','STRUCTURAL_COMPONENT') then
          k:=dep.get_string('key'); candidate:=treat(entries.get(entry_index(k)) as json_object_t);
          if candidate.get_string('lifecycle') is null then k:=candidate.get_string('implementation_of'); end if;
          if not finished.exists(k) then
            if not binding_index.exists(k) then return false; end if;
            owner:=treat(bindings.get(binding_index(k)) as json_object_t);
            if nvl(owner.get_string('member'),'!')<>nvl(p_member,'?') then return false; end if;
          end if;
        end if;
      end loop;
      return true;
    end;
  begin
    validate_product_coverage(p_coverage,p_artifacts,p_payloads);
    doc:=json_object_t.parse(p_coverage); entries:=doc.get_object('inventory').get_array('entries'); bindings:=doc.get_array('bindings');
    for i in 0..bindings.get_size-1 loop binding:=treat(bindings.get(i) as json_object_t); binding_index(binding.get_string('key')):=i; end loop;
    for entry_pos in 0..entries.get_size-1 loop
      item:=treat(entries.get(entry_pos) as json_object_t);
      key_value:=item.get_string('key'); entry_index(key_value):=entry_pos;
      entry_ranks(entry_pos):=install_rank(item); entry_keys(entry_pos):=key_value;
      slot:=entry_pos;
      while slot>0 loop
        previous_index:=ordered_entries(slot-1);
        exit when entry_ranks(previous_index)<entry_ranks(entry_pos)
          or (entry_ranks(previous_index)=entry_ranks(entry_pos)
            and entry_keys(previous_index)<=key_value);
        ordered_entries(slot):=previous_index; slot:=slot-1;
      end loop;
      ordered_entries(slot):=entry_pos;
    end loop;
    dbms_lob.createtemporary(result,true); dbms_lob.append(result,'MC_PRODUCT_INSTALL_PLAN|2'||chr(10));
    -- Storage identities are individually applied in the same order as their
    -- manifest. The early tool boundary follows application storage.
    app_entries:=json_object_t.parse(p_artifacts).get_array('artifacts');
    all_payloads:=json_object_t.parse(p_payloads);
    for i in 0..app_entries.get_size-1 loop
      app_entry:=treat(app_entries.get(i) as json_object_t);
      if app_entry.get_string('state')='PRESENT' then
        app_payloads.put(app_entry.get_string('member'),all_payloads.get_string(app_entry.get_string('member')));
      end if;
    end loop;
    app_order_text:=execution_order(p_artifacts,app_payloads.to_clob);
    app_order:=json_array_t.parse(app_order_text); dbms_lob.freetemporary(app_order_text); app_order_text:=null;
    for i in 0..entries.get_size-1 loop
      item:=treat(entries.get(i) as json_object_t); key_value:=item.get_string('key');
      if item.get_string('state')='REMOVED' then finished(key_value):=1; end if;
    end loop;
    for a in 0..app_order.get_size-1 loop
      key_value:=app_order.get_string(a);
      item:=treat(entries.get(entry_index(key_value)) as json_object_t);
      if item.get_string('state')='PRESENT' and item.get_string('lifecycle')='APPLICATION' and storage(item) then
        deps:=item.get_array('dependencies');
        for d in 0..deps.get_size-1 loop
          dependency:=treat(deps.get(d) as json_object_t);
          if dependency.has('key') and nvl(dependency.get_string('kind'),'!') not in ('IMPLEMENTATION_BODY','STRUCTURAL_COMPONENT') then
            target:=treat(entries.get(entry_index(dependency.get_string('key'))) as json_object_t);
            if target.get_string('lifecycle')<>'APPLICATION' or not storage(target) then
              artifact_fail('INITIAL application storage needs an authored earlier tool migration.'); end if;
          end if;
        end loop;
        binding:=treat(bindings.get(binding_index(key_value)) as json_object_t);
        dbms_lob.append(result,'APPLICATION_STORAGE|'||binding.get_string('member')||chr(10));
        finished(key_value):=1;
      end if;
    end loop;
    -- Tool storage must complete before application code; then use the full
    -- reviewed graph to interleave APPLICATION and BOOTSTRAP code safely.
    for stage in 1..2 loop
      loop
        remaining:=0; progress_count:=0;
        for plan_pos in 0..entries.get_size-1 loop
          i:=ordered_entries(plan_pos);
          item:=treat(entries.get(i) as json_object_t); key_value:=item.get_string('key');
          if item.get_string('lifecycle') is null or finished.exists(key_value) then continue; end if;
          binding:=treat(bindings.get(binding_index(key_value)) as json_object_t);
          if stage=1 and not (item.get_string('lifecycle')='BOOTSTRAP' and storage(item)) then continue; end if;
          remaining:=remaining+1; member_value:=binding.get_string('member'); ready:=ready_to_install(item,member_value);
          -- Every identity sharing a group must be ready before its one operation.
          for g in 0..entries.get_size-1 loop
            target:=treat(entries.get(g) as json_object_t); owner_key:=target.get_string('key');
            if binding_index.exists(owner_key) then
              dependency:=treat(bindings.get(binding_index(owner_key)) as json_object_t);
              if dependency.get_string('member')=member_value and not ready_to_install(target,member_value) then ready:=false; end if;
            end if;
          end loop;
          if ready then
            if not emitted.exists(member_value) then
              boundary:=case when item.get_string('lifecycle')='APPLICATION' then 'APPLICATION'
                when storage(item) then 'STORAGE' else 'UNIT' end;
              dbms_lob.append(result,boundary||'|'||member_value||chr(10)); emitted(member_value):=1;
            end if;
            finished(key_value):=1; progress_count:=progress_count+1;
          end if;
        end loop;
        exit when remaining=0;
        if progress_count=0 then artifact_fail('Product installation graph cycles or crosses an unavailable boundary.'); end if;
      end loop;
    end loop;
    return result;
  exception when others then
    if dbms_lob.istemporary(app_order_text)=1 then dbms_lob.freetemporary(app_order_text); end if;
    if dbms_lob.istemporary(result)=1 then dbms_lob.freetemporary(result); end if;
    raise;
  end;
-- END ANONYMOUS ARTIFACT MANIFEST
  procedure verify_archive(p_zip blob,p_manifest out nocopy clob,p_payloads out nocopy clob,
    p_contracts out nocopy clob) is
    members t_members; payloads json_object_t:=json_object_t();
    application_payloads json_object_t:=json_object_t();
    contracts json_object_t:=json_object_t(); contract_hashes json_object_t:=json_object_t();
    document json_object_t; entries json_array_t; entry json_object_t; identity json_object_t;
    contract_text clob; key_value varchar2(64); names json_key_list; valid number; total_contract_bytes number:=0;
    bytes blob; d integer:=1; s integer:=1; context_value integer:=0; warning_value integer;
    original_code number; original_message varchar2(1000);
  begin
    p_manifest:=null; p_payloads:=null; p_contracts:=null;
    zip_inspect(p_zip,members);
    for i in 1..members.count loop
      if members(i).name='db/deploy/artifacts.json' then
        bytes:=get_member(p_zip,members(i),8388608);
        d:=1; s:=1; context_value:=0;
        dbms_lob.createtemporary(p_manifest,true);
        dbms_lob.converttoclob(p_manifest,bytes,dbms_lob.lobmaxsize,d,s,nls_charset_id('AL32UTF8'),context_value,warning_value);
        if warning_value<>0 then artifact_fail('Manifest is not valid UTF-8.'); end if;
        dbms_lob.freetemporary(bytes);
      elsif substr(members(i).name,1,11)='db/objects/' then
        assert_member(members(i).name);
        bytes:=get_member(p_zip,members(i));
        payloads.put(members(i).name,lower(rawtohex(dbms_crypto.hash(bytes,dbms_crypto.hash_sh256))));
        dbms_lob.freetemporary(bytes);
      elsif substr(members(i).name,1,17)='db/deploy/tables/' then
        if not regexp_like(members(i).name,'^db/deploy/tables/[0-9a-f]{64}[.]json$','c') then artifact_fail('Invalid table contract member.'); end if;
        key_value:=substr(members(i).name,18,64);
        bytes:=get_member(p_zip,members(i),8388608);
        total_contract_bytes:=total_contract_bytes+dbms_lob.getlength(bytes);
        if total_contract_bytes>8388608 then artifact_fail('Table contract inventory size limit.'); end if;
        contract_hashes.put(key_value,lower(rawtohex(dbms_crypto.hash(bytes,dbms_crypto.hash_sh256))));
        d:=1; s:=1; context_value:=0;
        dbms_lob.createtemporary(contract_text,true);
        dbms_lob.converttoclob(contract_text,bytes,dbms_lob.lobmaxsize,d,s,nls_charset_id('AL32UTF8'),context_value,warning_value);
        if warning_value<>0 then artifact_fail('Table contract is not valid UTF-8.'); end if;
        select case when contract_text is json strict with unique keys then 1 else 0 end into valid from dual;
        if valid<>1 then artifact_fail('Invalid source table contract JSON.'); end if;
        contracts.put(key_value,json_object_t.parse(contract_text));
        dbms_lob.freetemporary(bytes); dbms_lob.freetemporary(contract_text);
      end if;
    end loop;
    if p_manifest is null then artifact_fail('Missing artifact manifest.'); end if;
    document:=json_object_t.parse(p_manifest); entries:=document.get_array('artifacts');
    for i in 0..entries.get_size-1 loop
      entry:=treat(entries.get(i) as json_object_t);
      if entry.get_string('state')='PRESENT' then
        application_payloads.put(entry.get_string('member'),payloads.get_string(entry.get_string('member')));
      end if;
    end loop;
    validate_manifest(p_manifest,application_payloads.to_clob);
    p_payloads:=application_payloads.to_clob;
    for i in 0..entries.get_size-1 loop
      entry:=treat(entries.get(i) as json_object_t); identity:=entry.get_object('identity'); key_value:=entry.get_string('key');
      if entry.get_string('state')='PRESENT' and identity.get_string('object_type')='TABLE' then
        if not contracts.has(key_value) or contract_hashes.get_string(key_value)<>entry.get_string('definition_sha256') then
          artifact_fail('Missing or unbound source table contract.'); end if;
        contract_hashes.remove(key_value);
      end if;
    end loop;
    names:=contract_hashes.get_keys;
    if names.count<>0 then artifact_fail('Unreferenced source table contract.'); end if;
    p_contracts:=contracts.to_clob;
  exception when others then
    original_code:=sqlcode; original_message:=sqlerrm;
    if dbms_lob.istemporary(bytes)=1 then dbms_lob.freetemporary(bytes); end if;
    if dbms_lob.istemporary(p_manifest)=1 then dbms_lob.freetemporary(p_manifest); end if;
    if dbms_lob.istemporary(p_payloads)=1 then dbms_lob.freetemporary(p_payloads); end if;
    if dbms_lob.istemporary(p_contracts)=1 then dbms_lob.freetemporary(p_contracts); end if;
    if dbms_lob.istemporary(contract_text)=1 then dbms_lob.freetemporary(contract_text); end if;
    p_manifest:=null; p_payloads:=null; p_contracts:=null;
    if original_code=-20030 then artifact_fail('Invalid object archive: '||original_message); end if;
    raise;
  end;
  procedure verify_product_archive(p_zip blob,p_coverage out nocopy clob) is
    members t_members; payloads json_object_t:=json_object_t();
    artifacts clob; application_payloads clob; application_contracts clob; bytes blob;
    plan_text clob; expected_plan clob;
    d integer; s integer; ctx integer; warning_value integer;
  begin
    p_coverage:=null;
    verify_archive(p_zip,artifacts,application_payloads,application_contracts);
    payloads:=json_object_t.parse(application_payloads);
    zip_inspect(p_zip,members);
    for i in 1..members.count loop
      if members(i).name='db/deploy/product-coverage.json' then
        bytes:=get_member(p_zip,members(i),16777216);
        d:=1; s:=1; ctx:=0; dbms_lob.createtemporary(p_coverage,true);
        dbms_lob.converttoclob(p_coverage,bytes,dbms_lob.lobmaxsize,d,s,nls_charset_id('AL32UTF8'),ctx,warning_value);
        if warning_value<>0 then artifact_fail('Product coverage is not UTF-8.'); end if;
        dbms_lob.freetemporary(bytes); bytes:=null;
      elsif members(i).name='db/deploy/product-plan.txt' then
        bytes:=get_member(p_zip,members(i),8388608);
        d:=1; s:=1; ctx:=0; dbms_lob.createtemporary(plan_text,true);
        dbms_lob.converttoclob(plan_text,bytes,dbms_lob.lobmaxsize,d,s,nls_charset_id('AL32UTF8'),ctx,warning_value);
        if warning_value<>0 then artifact_fail('Product installation plan is not UTF-8.'); end if;
        dbms_lob.freetemporary(bytes); bytes:=null;
      elsif substr(members(i).name,1,11)='db/objects/' and
        not payloads.has(members(i).name) or substr(members(i).name,1,13)='db/bootstrap/' then
        bytes:=get_member(p_zip,members(i));
        payloads.put(members(i).name,lower(rawtohex(dbms_crypto.hash(bytes,dbms_crypto.hash_sh256))));
        dbms_lob.freetemporary(bytes); bytes:=null;
      end if;
    end loop;
    if p_coverage is null then artifact_fail('Missing product coverage.'); end if;
    validate_product_coverage(p_coverage,artifacts,payloads.to_clob);
    expected_plan:=product_initial_plan(p_coverage,artifacts,payloads.to_clob);
    if plan_text is null or dbms_lob.compare(plan_text,expected_plan)<>0 then artifact_fail('Product installation plan differs from reviewed dependencies.'); end if;
    dbms_lob.freetemporary(plan_text); dbms_lob.freetemporary(expected_plan);
    dbms_lob.freetemporary(artifacts); dbms_lob.freetemporary(application_payloads); dbms_lob.freetemporary(application_contracts);
  exception when others then
    if dbms_lob.istemporary(bytes)=1 then dbms_lob.freetemporary(bytes); end if;
    if dbms_lob.istemporary(artifacts)=1 then dbms_lob.freetemporary(artifacts); end if;
    if dbms_lob.istemporary(application_payloads)=1 then dbms_lob.freetemporary(application_payloads); end if;
    if dbms_lob.istemporary(application_contracts)=1 then dbms_lob.freetemporary(application_contracts); end if;
    if dbms_lob.istemporary(plan_text)=1 then dbms_lob.freetemporary(plan_text); end if;
    if dbms_lob.istemporary(expected_plan)=1 then dbms_lob.freetemporary(expected_plan); end if;
    if dbms_lob.istemporary(p_coverage)=1 then dbms_lob.freetemporary(p_coverage); end if;
    p_coverage:=null; raise;
  end;
  procedure verify_archive(p_zip blob,p_manifest out nocopy clob,p_payloads out nocopy clob) is contracts clob;
  begin
    verify_archive(p_zip,p_manifest,p_payloads,contracts);
    dbms_lob.freetemporary(contracts);
  exception when others then
    if dbms_lob.istemporary(contracts)=1 then dbms_lob.freetemporary(contracts); end if;
    raise;
  end;
  FUNCTION protocol RETURN VARCHAR2 IS
  BEGIN RETURN 'mc-bootstrap-1'; END;
  FUNCTION blob_to_clob(p_blob IN BLOB) RETURN CLOB IS
    l_clob    CLOB;
    l_dst_ofs INTEGER := 1;
    l_src_ofs INTEGER := 1;
    l_langctx INTEGER := DBMS_LOB.DEFAULT_LANG_CTX;
    l_warn    INTEGER;
  BEGIN
    IF p_blob IS NULL THEN
      RETURN NULL;
    END IF;

    DBMS_LOB.CREATETEMPORARY(l_clob, TRUE);
    DBMS_LOB.CONVERTTOCLOB(
      dest_lob     => l_clob,
      src_blob     => p_blob,
      amount       => DBMS_LOB.LOBMAXSIZE,
      dest_offset  => l_dst_ofs,
      src_offset   => l_src_ofs,
      blob_csid    => NLS_CHARSET_ID('AL32UTF8'),
      lang_context => l_langctx,
      warning      => l_warn
    );
    IF l_warn <> 0 THEN raise_application_error(-20030,'Invalid UTF-8 metadata.'); END IF;
    RETURN l_clob;
  EXCEPTION WHEN OTHERS THEN
    IF DBMS_LOB.ISTEMPORARY(l_clob)=1 THEN DBMS_LOB.FREETEMPORARY(l_clob); END IF;
    RAISE;
  END;
  -- Lexical envelope only: Oracle compiles the complete single DDL unit later.
  -- Never parse DDL here: DBMS_SQL.PARSE executes DDL during parsing.
  PROCEDURE frame_runtime_unit(p_sql CLOB,p_body BOOLEAN,
    o_name_end OUT PLS_INTEGER,o_unit_end OUT PLS_INTEGER) IS
    pos PLS_INTEGER:=1; len PLS_INTEGER:=DBMS_LOB.GETLENGTH(p_sql);
    cache VARCHAR2(32767); cache_start PLS_INTEGER:=0;
    token VARCHAR2(32767);
    TYPE t_blocks IS TABLE OF VARCHAR2(16) INDEX BY PLS_INTEGER;
    blocks t_blocks; depth PLS_INTEGER:=0; closing_block VARCHAR2(16);
    routine_header BOOLEAN:=FALSE;
    FUNCTION ch(n PLS_INTEGER) RETURN VARCHAR2 IS
    BEGIN
      IF n>len THEN RETURN NULL; END IF;
      IF n<cache_start OR n>=cache_start+NVL(LENGTH(cache),0) THEN
        cache_start:=n; cache:=DBMS_LOB.SUBSTR(p_sql,8000,n);
      END IF;
      RETURN SUBSTR(cache,n-cache_start+1,1);
    END;
    PROCEDURE fail IS BEGIN raise_application_error(-20030,'Runtime payload must contain one unqualified manager package unit.'); END;
    FUNCTION next_token RETURN VARCHAR2 IS
      c VARCHAR2(1); d VARCHAR2(1); closing VARCHAR2(1); result VARCHAR2(32767);
    BEGIN
      LOOP
        c:=ch(pos); d:=ch(pos+1);
        IF c IS NULL THEN RETURN NULL;
        ELSIF c IN (' ',CHR(9),CHR(10),CHR(13)) THEN pos:=pos+1;
        ELSIF c='-' AND d='-' THEN
          pos:=pos+2;
          WHILE ch(pos) IS NOT NULL AND ch(pos)<>CHR(10) LOOP pos:=pos+1; END LOOP;
        ELSIF c='/' AND d='*' THEN
          pos:=pos+2;
          WHILE ch(pos) IS NOT NULL AND NOT(ch(pos)='*' AND ch(pos+1)='/') LOOP pos:=pos+1; END LOOP;
          IF ch(pos) IS NULL THEN fail; END IF;
          pos:=pos+2;
        ELSE EXIT;
        END IF;
      END LOOP;
      IF UPPER(c)='N' AND UPPER(d)='Q' AND ch(pos+2)='''' THEN pos:=pos+1; c:=ch(pos); d:=ch(pos+1); END IF;
      IF UPPER(c)='Q' AND d='''' THEN
        closing:=ch(pos+2);
        closing:=CASE closing WHEN '[' THEN ']' WHEN '(' THEN ')' WHEN '{' THEN '}' WHEN '<' THEN '>' ELSE closing END;
        pos:=pos+3;
        WHILE ch(pos) IS NOT NULL AND NOT(ch(pos)=closing AND ch(pos+1)='''') LOOP pos:=pos+1; END LOOP;
        IF ch(pos) IS NULL THEN fail; END IF;
        pos:=pos+2; RETURN '#LITERAL#';
      END IF;
      IF UPPER(c)='N' AND d='''' THEN pos:=pos+1; c:=ch(pos); END IF;
      IF c='''' THEN
        pos:=pos+1;
        LOOP
          IF ch(pos) IS NULL THEN fail; END IF;
          IF ch(pos)='''' THEN
            IF ch(pos+1)='''' THEN pos:=pos+2; ELSE pos:=pos+1; EXIT; END IF;
          ELSE pos:=pos+1;
          END IF;
        END LOOP;
        RETURN '#LITERAL#';
      END IF;
      IF c='"' THEN
        pos:=pos+1;
        WHILE ch(pos) IS NOT NULL AND ch(pos)<>'"' LOOP result:=result||ch(pos); pos:=pos+1; END LOOP;
        IF ch(pos) IS NULL THEN fail; END IF;
        pos:=pos+1;
        -- Quoted object names are case-sensitive: only uppercase is allowed.
        RETURN '"'||result||'"';
      END IF;
      IF INSTR('ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789_$#',c)>0 THEN
        WHILE ch(pos) IS NOT NULL AND INSTR('ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789_$#',ch(pos))>0 LOOP
          result:=result||ch(pos); pos:=pos+1;
        END LOOP;
        RETURN UPPER(result);
      END IF;
      pos:=pos+1; RETURN c;
    END;
    PROCEDURE expect(p_token VARCHAR2) IS
    BEGIN IF NVL(next_token,'?')<>p_token THEN fail; END IF; END;
    PROCEDURE finish_unit IS
    BEGIN
      expect(';'); o_unit_end:=pos-1; token:=next_token;
      IF token='/' THEN token:=next_token; END IF;
      IF token IS NOT NULL THEN fail; END IF;
    END;
  BEGIN
    expect('CREATE'); expect('OR'); expect('REPLACE');
    token:=next_token;
    IF token IN ('EDITIONABLE','NONEDITIONABLE') THEN token:=next_token; END IF;
    IF NVL(token,'?')<>'PACKAGE' THEN fail; END IF;
    IF p_body THEN expect('BODY'); END IF;
    token:=next_token;
    IF token IS NULL OR token NOT IN ('DEPLOY_MGR_PKG','"DEPLOY_MGR_PKG"') THEN fail; END IF;
    o_name_end:=pos-1;
    token:=next_token;
    IF token IS NULL OR token NOT IN ('AS','IS','AUTHID') THEN fail; END IF;
    -- This is a conservative block-aware envelope, not a PL/SQL compiler.
    -- In particular it refuses an unnamed package END before any trailing SQL.
    -- Oracle still compiles syntax in the installation worker, not inspection.
    LOOP
      IF token IS NULL THEN fail; END IF;
      IF token='CREATE' THEN fail; END IF;
      IF token IN ('FUNCTION','PROCEDURE') THEN
        routine_header:=TRUE;
      ELSIF token IN ('IS','AS') AND routine_header THEN
        depth:=depth+1; blocks(depth):='ROUTINE'; routine_header:=FALSE;
      ELSIF token=';' THEN
        routine_header:=FALSE; -- A forward declaration has no routine block.
      ELSIF token='BEGIN' AND depth=0 THEN
        IF NOT p_body THEN fail; END IF;
        depth:=depth+1; blocks(depth):='PACKAGE_INIT';
      ELSIF token IN ('BEGIN','IF','LOOP','CASE') THEN
        depth:=depth+1; blocks(depth):=token;
      ELSIF token='END' THEN
        token:=next_token;
        IF depth=0 THEN
          IF token IS NULL OR token NOT IN ('DEPLOY_MGR_PKG','"DEPLOY_MGR_PKG"') THEN fail; END IF;
          finish_unit; RETURN;
        END IF;
        closing_block:=blocks(depth); blocks.DELETE(depth); depth:=depth-1;
        IF closing_block='PACKAGE_INIT' THEN
          IF depth<>0 OR token IS NULL OR token NOT IN ('DEPLOY_MGR_PKG','"DEPLOY_MGR_PKG"') THEN fail; END IF;
          finish_unit; RETURN;
        END IF;
        IF closing_block='BEGIN' AND depth>0 AND blocks(depth)='ROUTINE' THEN
          blocks.DELETE(depth); depth:=depth-1;
        END IF;
        IF closing_block IN ('IF','LOOP') THEN
          IF NVL(token,'?')<>closing_block THEN fail; END IF;
          token:=next_token;
        ELSIF closing_block='CASE' AND token='CASE' THEN
          token:=next_token;
        END IF;
        CONTINUE;
      END IF;
      token:=next_token;
    END LOOP;
  END frame_runtime_unit;
  PROCEDURE assert_runtime_unit(p_sql CLOB,p_body BOOLEAN) IS
    l_name_end PLS_INTEGER; l_unit_end PLS_INTEGER;
  BEGIN frame_runtime_unit(p_sql,p_body,l_name_end,l_unit_end); END;
  PROCEDURE prepare_runtime_unit(p_sql IN CLOB,p_body IN BOOLEAN,
    o_ddl OUT CLOB,o_source OUT CLOB) IS
    l_name_end PLS_INTEGER; l_unit_end PLS_INTEGER; l_header VARCHAR2(100);
  BEGIN
    frame_runtime_unit(p_sql,p_body,l_name_end,l_unit_end);
    DBMS_LOB.CREATETEMPORARY(o_ddl,TRUE);
    DBMS_LOB.COPY(o_ddl,p_sql,l_unit_end,1,1);
    -- Oracle's export quotes/uppercases the object name while USER_SOURCE
    -- retains its original spelling. Normalize only that header and envelope;
    -- whitespace, comments and literals inside the unit remain byte-for-byte.
    l_header:='PACKAGE '||CASE WHEN p_body THEN 'BODY ' END||'DEPLOY_MGR_PKG';
    DBMS_LOB.CREATETEMPORARY(o_source,TRUE);
    DBMS_LOB.WRITEAPPEND(o_source,LENGTH(l_header),l_header);
    DBMS_LOB.COPY(o_source,p_sql,l_unit_end-l_name_end,LENGTH(l_header)+1,l_name_end+1);
  EXCEPTION WHEN OTHERS THEN
    IF DBMS_LOB.ISTEMPORARY(o_ddl)=1 THEN DBMS_LOB.FREETEMPORARY(o_ddl); END IF;
    IF DBMS_LOB.ISTEMPORARY(o_source)=1 THEN DBMS_LOB.FREETEMPORARY(o_source); END IF;
    RAISE;
  END;
  PROCEDURE inspect(
    p_zip              IN BLOB,
    p_expected_sha256  IN VARCHAR2,
    o_app_id           OUT NUMBER,
    o_version_tag      OUT VARCHAR2,
    o_registry_run_id  OUT NUMBER,
    o_spec_sha256 OUT VARCHAR2,
    o_body_sha256 OUT VARCHAR2
  ) IS
    TYPE t_name_set IS TABLE OF PLS_INTEGER INDEX BY VARCHAR2(1000);
    l_members          apex_zip.t_files;
    l_entries t_members;
    l_normalized t_name_set;
    l_runtime CLOB;
    l_runtime_protocol VARCHAR2(100);
    l_runtime_spec VARCHAR2(64);
    l_runtime_body VARCHAR2(64);
    l_member_set       t_name_set;
    l_checksum_set     t_name_set;
    l_property_set     t_name_set;
    l_required         sys.odcivarchar2list := sys.odcivarchar2list(
      'bundle.properties', 'checksums.sha256', 'manifest.json', 'apex/f1200.sql',
      'db/deploy/plan.txt', 'db/deploy/artifacts.json',
      'db/deploy/product-coverage.json', 'db/deploy/product-plan.txt',
      'db/deploy/initial-objects.txt', 'db/ddl/00_source_removals.sql',
      'db/ddl/05_contexts.sql', 'db/ddl/95_app_config.sql',
      'db/ddl/96_chatbot_seed.sql', 'db/ddl/97_semantic_seed.sql',
      'db/migrations/manifest.txt',
      'db/preflight/required_privileges.txt',
      'db/preflight/required_privileges.sql',
      'db/admin/apply_required_privileges.sql',
      'runtime.properties', 'db/runtime/runtime_dependencies.sql'
    );
    l_properties       CLOB;
    l_checksums        CLOB;
    l_manifest         CLOB;
    l_position         PLS_INTEGER;
    l_line             VARCHAR2(4000);
    l_separator        PLS_INTEGER;
    l_key              VARCHAR2(100);
    l_value            VARCHAR2(1000);
    l_contract         VARCHAR2(100);
    l_layout           VARCHAR2(100);
    l_modes            VARCHAR2(100);
    l_source_id_text   VARCHAR2(100);
    l_registry_text    VARCHAR2(100);
    l_enablement       VARCHAR2(100);
    l_property_count   PLS_INTEGER := 0;
    l_checksum_count   PLS_INTEGER := 0;
    l_expected_hash    VARCHAR2(64);
    l_actual_hash      VARCHAR2(64);
    l_checksum_path    VARCHAR2(1000);
    l_member_blob      BLOB;
    l_member_clob      CLOB;
    l_manifest_schema  VARCHAR2(100);
    l_manifest_source  NUMBER;
    l_manifest_app     NUMBER;
    l_manifest_version VARCHAR2(64);
    l_manifest_run     NUMBER;
    l_manifest_enable  VARCHAR2(100);
    l_manifest_valid PLS_INTEGER;

    FUNCTION safe_member_path(p_path IN VARCHAR2) RETURN BOOLEAN IS
      l_start PLS_INTEGER := 1;
      l_slash PLS_INTEGER;
      l_part  VARCHAR2(1000);
    BEGIN
      IF p_path IS NULL OR LENGTH(p_path) > 1000 OR SUBSTR(p_path, 1, 1) = '/'
         OR SUBSTR(p_path, -1, 1) = '/' OR INSTR(p_path, '\') > 0
         OR NOT REGEXP_LIKE(p_path, '^[A-Za-z0-9._/-]+$')
      THEN
        RETURN FALSE;
      END IF;
      LOOP
        l_slash := INSTR(p_path, '/', l_start);
        IF l_slash = 0 THEN
          l_part := SUBSTR(p_path, l_start);
        ELSE
          l_part := SUBSTR(p_path, l_start, l_slash - l_start);
        END IF;
        IF l_part IS NULL OR l_part IN ('.', '..') THEN
          RETURN FALSE;
        END IF;
        EXIT WHEN l_slash = 0;
        l_start := l_slash + 1;
      END LOOP;
      RETURN TRUE;
    END safe_member_path;

    FUNCTION next_line(p_text IN CLOB, p_pos IN OUT PLS_INTEGER) RETURN VARCHAR2 IS
      l_length PLS_INTEGER;
      l_newline PLS_INTEGER;
      l_amount PLS_INTEGER;
    BEGIN
      IF p_text IS NULL THEN
        RETURN NULL;
      END IF;
      l_length := DBMS_LOB.GETLENGTH(p_text);
      IF p_pos > l_length THEN
        RETURN NULL;
      END IF;
      l_newline := DBMS_LOB.INSTR(p_text, CHR(10), p_pos);
      l_amount := CASE WHEN l_newline = 0 THEN l_length - p_pos + 1 ELSE l_newline - p_pos END;
      IF l_amount > 4000 THEN
        raise_application_error(-20032, 'Bundle metadata line exceeds 4000 characters.');
      END IF;
      l_line := DBMS_LOB.SUBSTR(p_text, l_amount, p_pos);
      p_pos := CASE WHEN l_newline = 0 THEN l_length + 1 ELSE l_newline + 1 END;
      RETURN RTRIM(l_line, CHR(13));
    END next_line;

    FUNCTION member_blob(p_name VARCHAR2) RETURN BLOB IS
    BEGIN
      RETURN get_member(p_zip,l_entries(l_member_set(p_name)));
    END;
    FUNCTION member_text(p_name VARCHAR2) RETURN CLOB IS
      b BLOB; c CLOB;
    BEGIN
      b:=member_blob(p_name); c:=blob_to_clob(b);
      IF DBMS_LOB.ISTEMPORARY(b)=1 THEN DBMS_LOB.FREETEMPORARY(b); END IF;
      RETURN c;
    EXCEPTION WHEN OTHERS THEN
      IF DBMS_LOB.ISTEMPORARY(b)=1 THEN DBMS_LOB.FREETEMPORARY(b); END IF;
      RAISE;
    END;
    PROCEDURE cleanup IS
    BEGIN
      IF DBMS_LOB.ISTEMPORARY(l_member_blob)=1 THEN DBMS_LOB.FREETEMPORARY(l_member_blob); END IF;
      IF DBMS_LOB.ISTEMPORARY(l_member_clob)=1 THEN DBMS_LOB.FREETEMPORARY(l_member_clob); END IF;
      IF DBMS_LOB.ISTEMPORARY(l_properties)=1 THEN DBMS_LOB.FREETEMPORARY(l_properties); END IF;
      IF DBMS_LOB.ISTEMPORARY(l_checksums)=1 THEN DBMS_LOB.FREETEMPORARY(l_checksums); END IF;
      IF DBMS_LOB.ISTEMPORARY(l_manifest)=1 THEN DBMS_LOB.FREETEMPORARY(l_manifest); END IF;
      IF DBMS_LOB.ISTEMPORARY(l_runtime)=1 THEN DBMS_LOB.FREETEMPORARY(l_runtime); END IF;
    END;
  BEGIN
    o_spec_sha256 := NULL;
    o_body_sha256 := NULL;
    o_app_id := NULL;
    o_version_tag := NULL;
    o_registry_run_id := NULL;
    IF p_zip IS NULL OR DBMS_LOB.GETLENGTH(p_zip) = 0 THEN
      raise_application_error(-20030, 'Bundle ZIP is empty.');
    END IF;

    zip_inspect(p_zip,l_entries);
    FOR i IN 1..l_entries.COUNT LOOP
      l_members(i) := l_entries(i).name;
    END LOOP;
    IF l_members.COUNT = 0 THEN
      raise_application_error(-20030, 'Bundle ZIP contains no files.');
    END IF;
    FOR i IN 1 .. l_members.COUNT LOOP
      IF NOT safe_member_path(l_members(i)) THEN
        raise_application_error(-20030, 'Unsafe bundle member path: ' || SUBSTR(l_members(i), 1, 1000));
      END IF;
      IF l_member_set.EXISTS(l_members(i)) THEN
        raise_application_error(-20030, 'Duplicate ZIP member: ' || l_members(i));
      END IF;
      IF l_normalized.EXISTS(LOWER(l_members(i))) THEN
        raise_application_error(-20030,'Case-colliding ZIP members.');
      END IF;
      l_normalized(LOWER(l_members(i))) := 1;
      IF l_members(i) LIKE 'db/runtime/%' AND
        l_members(i)<>'db/runtime/runtime_dependencies.sql' THEN
        raise_application_error(-20030,'Unsupported runtime payload.');
      END IF;
      IF l_members(i) LIKE 'db/deploy/groups/%' OR l_members(i) LIKE 'db/deploy/delta/%'
        OR l_members(i) LIKE 'db/bootstrap/product/%' OR l_members(i) IN
        ('db/ddl/01_tables.sql','db/ddl/01a_table_alters.sql','db/ddl/02_sequences.sql',
         'db/ddl/03_keys_indexes.sql','db/ddl/03a_views.sql','db/ddl/04_pkg_specs.sql',
         'db/ddl/06_pkg_bodies.sql','db/ddl/07_procs_funcs.sql','db/ddl/08_mviews.sql',
         'db/ddl/08a_property_graphs.sql','db/ddl/09_triggers.sql','db/ddl/90_jobs.sql') THEN
        raise_application_error(-20030,'Retired grouped or delta object payload.');
      END IF;
      l_member_set(l_members(i)) := i;
    END LOOP;
    FOR i IN 1 .. l_required.COUNT LOOP
      IF NOT l_member_set.EXISTS(l_required(i)) THEN
        raise_application_error(-20030, 'Missing MC bundle file: ' || l_required(i));
      END IF;
    END LOOP;

    l_properties := member_text('bundle.properties');
    l_position := 1;
    LOOP
      EXIT WHEN l_position>DBMS_LOB.GETLENGTH(l_properties);
      l_line := next_line(l_properties, l_position);
      IF l_line IS NULL OR l_line = '' THEN
        raise_application_error(-20030,'Empty bundle property.');
      END IF;
      l_separator := INSTR(l_line, '=');
      IF l_separator < 2 OR INSTR(l_line, '=', l_separator + 1) > 0 THEN
        raise_application_error(-20030, 'Invalid bundle.properties entry: ' || SUBSTR(l_line, 1, 500));
      END IF;
      l_key := SUBSTR(l_line, 1, l_separator - 1);
      l_value := SUBSTR(l_line, l_separator + 1);
      IF l_property_set.EXISTS(l_key) THEN
        raise_application_error(-20030, 'Duplicate bundle property: ' || l_key);
      END IF;
      l_property_set(l_key) := 1;
      l_property_count := l_property_count + 1;
      CASE l_key
        WHEN 'MC_BUNDLE_CONTRACT' THEN l_contract := l_value;
        WHEN 'MC_LAYOUT' THEN l_layout := l_value;
        WHEN 'MC_SUPPORTED_MODES' THEN l_modes := l_value;
        WHEN 'MC_SOURCE_APPLICATION_ID' THEN l_source_id_text := l_value;
        WHEN 'MC_REGISTRY_RUN_ID' THEN l_registry_text := l_value;
        WHEN 'MC_ENABLEMENT' THEN l_enablement := l_value;
        ELSE raise_application_error(-20030, 'Unsupported bundle property: ' || l_key);
      END CASE;
    END LOOP;
    IF l_property_count <> 6 THEN
      raise_application_error(-20030, 'bundle.properties must contain exactly six properties.');
    END IF;
    IF l_contract<>'mc-bundle-1.13.0' THEN
      raise_application_error(-20030, 'Unsupported bundle contract: ' || NVL(l_contract, '<missing>'));
    END IF;
    IF l_layout IS NULL OR l_modes IS NULL OR l_enablement IS NULL OR l_layout <> 'application-bundles-v1' OR l_modes <> 'INITIAL,UPDATE'
       OR l_enablement <> 'ADMIN_CONTROLLED_DISABLED'
    THEN
      raise_application_error(-20030, 'Bundle properties do not match the supported deployment policy.');
    END IF;
    IF l_source_id_text IS NULL OR NOT REGEXP_LIKE(l_source_id_text, '^[1-9][0-9]*$') THEN
      raise_application_error(-20030, 'Bundle source application must be a positive integer.');
    END IF;
    IF l_registry_text IS NULL OR NOT REGEXP_LIKE(l_registry_text, '^[1-9][0-9]*$') THEN
      raise_application_error(-20030, 'Bundle has no approved registry run identity.');
    END IF;

    l_checksums := member_text('checksums.sha256');
    l_position := 1;
    LOOP
      EXIT WHEN l_position>DBMS_LOB.GETLENGTH(l_checksums);
      l_line := next_line(l_checksums, l_position);
      IF l_line IS NULL OR l_line = '' THEN
        raise_application_error(-20031,'Empty checksum entry.');
      END IF;
      IF NOT REGEXP_LIKE(l_line, '^[0-9a-f]{64}  [A-Za-z0-9._/-]+$') THEN
        raise_application_error(-20031, 'Invalid checksums.sha256 entry: ' || SUBSTR(l_line, 1, 500));
      END IF;
      l_expected_hash := SUBSTR(l_line, 1, 64);
      l_checksum_path := SUBSTR(l_line, 67);
      IF NOT safe_member_path(l_checksum_path) OR l_checksum_path = 'checksums.sha256' THEN
        raise_application_error(-20031, 'Unsafe checksum path: ' || l_checksum_path);
      END IF;
      IF NOT l_member_set.EXISTS(l_checksum_path) THEN
        raise_application_error(-20031, 'Checksum references missing file: ' || l_checksum_path);
      END IF;
      IF l_checksum_set.EXISTS(l_checksum_path) THEN
        raise_application_error(-20031, 'checksums.sha256 contains duplicate path: ' || l_checksum_path);
      END IF;
      l_member_blob := member_blob(l_checksum_path);
      l_actual_hash := LOWER(RAWTOHEX(DBMS_CRYPTO.HASH(l_member_blob, DBMS_CRYPTO.HASH_SH256)));
      IF l_actual_hash <> l_expected_hash THEN
        raise_application_error(-20031,
          'Bundle checksum mismatch for member ' || l_checksum_path ||
          ': expected=' || l_expected_hash || ' actual=' || l_actual_hash);
      END IF;
      IF DBMS_LOB.ISTEMPORARY(l_member_blob)=1 THEN DBMS_LOB.FREETEMPORARY(l_member_blob); END IF;
      l_checksum_set(l_checksum_path) := 1;
      l_checksum_count := l_checksum_count + 1;
    END LOOP;
    IF l_checksum_count <> l_members.COUNT - 1 THEN
      raise_application_error(-20031, 'Bundle checksum coverage mismatch.');
    END IF;
    FOR i IN 1 .. l_members.COUNT LOOP
      IF l_members(i) <> 'checksums.sha256' AND NOT l_checksum_set.EXISTS(l_members(i)) THEN
        raise_application_error(-20031, 'Bundle checksum coverage mismatch for member ' || l_members(i));
      END IF;
    END LOOP;

    l_manifest := member_text('manifest.json');
    SELECT CASE WHEN l_manifest IS JSON STRICT WITH UNIQUE KEYS THEN 1 ELSE 0 END
      INTO l_manifest_valid FROM dual;
    IF l_manifest_valid<>1 THEN raise_application_error(-20031,'Manifest must be strict JSON with unique keys.'); END IF;
    l_manifest_schema := JSON_VALUE(l_manifest, '$.bundle_schema_version' RETURNING VARCHAR2(100) ERROR ON ERROR);
    l_manifest_source := JSON_VALUE(l_manifest, '$.source_application_id' RETURNING NUMBER ERROR ON ERROR);
    l_manifest_app := JSON_VALUE(l_manifest, '$.app_id' RETURNING NUMBER ERROR ON ERROR);
    l_manifest_version := JSON_VALUE(l_manifest, '$.version' RETURNING VARCHAR2(64) ERROR ON ERROR);
    l_manifest_run := JSON_VALUE(l_manifest, '$.registry_run_id' RETURNING NUMBER ERROR ON ERROR);
    l_manifest_enable := JSON_VALUE(l_manifest, '$.enablement' RETURNING VARCHAR2(100) ERROR ON ERROR);
    IF l_manifest_schema IS NULL OR l_manifest_source IS NULL OR l_manifest_app IS NULL
       OR l_manifest_run IS NULL OR l_manifest_enable IS NULL OR l_manifest_version IS NULL
       OR l_manifest_schema <> l_contract OR l_manifest_source <> TO_NUMBER(l_source_id_text)
       OR l_manifest_app <> l_manifest_source OR l_manifest_run <> TO_NUMBER(l_registry_text)
       OR l_manifest_enable <> l_enablement
       OR NOT REGEXP_LIKE(l_manifest_version, '^[A-Za-z0-9._-]{1,64}$')
    THEN
      raise_application_error(-20031, 'manifest.json does not agree with bundle.properties.');
    END IF;

    IF p_expected_sha256 IS NOT NULL THEN
      IF NOT REGEXP_LIKE(LOWER(TRIM(p_expected_sha256)), '^[0-9a-f]{64}$') THEN
        raise_application_error(-20031, 'Stored bundle SHA-256 is invalid.');
      END IF;
      l_actual_hash := LOWER(RAWTOHEX(DBMS_CRYPTO.HASH(p_zip, DBMS_CRYPTO.HASH_SH256)));
      IF l_actual_hash <> LOWER(TRIM(p_expected_sha256)) THEN
        raise_application_error(-20031,
          'Stored bundle SHA-256 mismatch: expected=' || LOWER(TRIM(p_expected_sha256)) ||
          ' actual=' || l_actual_hash);
      END IF;
    END IF;

    DECLARE
      coverage_text CLOB; coverage_doc JSON_OBJECT_T; inventory_entries JSON_ARRAY_T; bindings JSON_ARRAY_T;
      inventory_item JSON_OBJECT_T; binding_item JSON_OBJECT_T; ident JSON_OBJECT_T;
    BEGIN
      coverage_text:=member_text('db/deploy/product-coverage.json');
      coverage_doc:=JSON_OBJECT_T.parse(coverage_text);
      inventory_entries:=coverage_doc.get_object('inventory').get_array('entries');
      bindings:=coverage_doc.get_array('bindings');
      FOR i IN 0..inventory_entries.get_size-1 LOOP
        inventory_item:=TREAT(inventory_entries.get(i) AS JSON_OBJECT_T);
        ident:=inventory_item.get_object('identity');
        IF inventory_item.get_string('lifecycle')='BOOTSTRAP' AND
          ident.get_string('object_name')='DEPLOY_MGR_PKG' AND
          ident.get_string('object_type') IN ('PACKAGE','PACKAGE BODY') THEN
          FOR j IN 0..bindings.get_size-1 LOOP
            binding_item:=TREAT(bindings.get(j) AS JSON_OBJECT_T);
            IF binding_item.get_string('key')=inventory_item.get_string('key') THEN
              IF NOT l_checksum_set.EXISTS(binding_item.get_string('member')) THEN
                raise_application_error(-20031,'Runtime manager member has no checksum.'); END IF;
              IF ident.get_string('object_type')='PACKAGE' THEN
                o_spec_sha256:=binding_item.get_string('payload_sha256');
              ELSE o_body_sha256:=binding_item.get_string('payload_sha256'); END IF;
            END IF;
          END LOOP;
        END IF;
      END LOOP;
      DBMS_LOB.FREETEMPORARY(coverage_text);
    END;
    l_runtime := member_text('runtime.properties');
    l_property_set.DELETE;
    l_position := 1;
    LOOP
      EXIT WHEN l_position>DBMS_LOB.GETLENGTH(l_runtime);
      l_line := next_line(l_runtime,l_position);
      IF l_line IS NULL THEN raise_application_error(-20030,'Empty runtime property.'); END IF;
      l_separator := INSTR(l_line,'=');
      IF l_separator < 2 OR INSTR(l_line,'=',l_separator+1)>0 THEN
        raise_application_error(-20030,'Invalid runtime property.');
      END IF;
      l_key := SUBSTR(l_line,1,l_separator-1);
      l_value := SUBSTR(l_line,l_separator+1);
      IF l_property_set.EXISTS(l_key) THEN raise_application_error(-20030,'Duplicate runtime property.'); END IF;
      l_property_set(l_key):=1;
      CASE l_key
        WHEN 'bootstrap.protocol' THEN l_runtime_protocol:=l_value;
        WHEN 'runtime.spec.sha256' THEN l_runtime_spec:=l_value;
        WHEN 'runtime.body.sha256' THEN l_runtime_body:=l_value;
        ELSE raise_application_error(-20030,'Unsupported runtime property.');
      END CASE;
    END LOOP;
    IF l_property_set.COUNT<>3 OR NVL(l_runtime_protocol,'?')<>protocol()
       OR NVL(l_runtime_spec,'?')<>o_spec_sha256 OR NVL(l_runtime_body,'?')<>o_body_sha256 THEN
      raise_application_error(-20030,'Runtime protocol or content identity mismatch.');
    END IF;
    DECLARE
      coverage CLOB; artifacts CLOB; payloads CLOB; contracts CLOB;
      ordering CLOB; initial_text CLOB;
    BEGIN
      verify_product_archive(p_zip,coverage);
      IF JSON_VALUE(coverage,'$.registry_run_id' RETURNING NUMBER ERROR ON ERROR)<>l_manifest_run THEN
        raise_application_error(-20031,'Product coverage run mismatch.'); END IF;
      verify_archive(p_zip,artifacts,payloads,contracts);
      ordering:=initial_plan(artifacts,payloads);
      initial_text:=member_text('db/deploy/initial-objects.txt');
      IF DBMS_LOB.COMPARE(ordering,initial_text)<>0 THEN
        raise_application_error(-20031,'INITIAL object plan differs from the verified dependency order.'); END IF;
      DBMS_LOB.FREETEMPORARY(coverage); DBMS_LOB.FREETEMPORARY(artifacts);
      DBMS_LOB.FREETEMPORARY(payloads); DBMS_LOB.FREETEMPORARY(contracts);
      DBMS_LOB.FREETEMPORARY(ordering); DBMS_LOB.FREETEMPORARY(initial_text);
    END;
    o_app_id := l_manifest_app;
    o_version_tag := l_manifest_version;
    o_registry_run_id := l_manifest_run;
    cleanup;
  EXCEPTION
    WHEN VALUE_ERROR THEN
      cleanup;
      raise_application_error(-20031, 'Bundle metadata contains an invalid numeric value.');
    WHEN OTHERS THEN cleanup; RAISE;
  END inspect;
-- BEGIN PRIVILEGE POLICY
  -- Canonical anonymous declarations; embedded in integrity package and installer.
  -- No DDL is executed. This recognizes the exporter's bounded phase dialect,
  -- not arbitrary dynamic SQL inside application package bodies.
  FUNCTION policy_allowed(p_priv VARCHAR2) RETURN BOOLEAN IS
  BEGIN
    RETURN p_priv IN ('CREATE SESSION','CREATE TABLE','CREATE PROCEDURE','CREATE JOB',
      'CREATE SEQUENCE','CREATE VIEW','CREATE MATERIALIZED VIEW','CREATE PROPERTY GRAPH',
      'CREATE TRIGGER','CREATE TYPE','CREATE SYNONYM','CREATE ANY CONTEXT');
  END;
  PROCEDURE policy_report(p_required sys.odcivarchar2list,p_objects CLOB,
    o_missing OUT PLS_INTEGER,o_sql OUT CLOB) IS
    n NUMBER; pos PLS_INTEGER:=1; eol PLS_INTEGER; a PLS_INTEGER; b PLS_INTEGER;
    line VARCHAR2(4000); owner_name VARCHAR2(128); object_name VARCHAR2(128); priv VARCHAR2(32);
    grant_name VARCHAR2(300);
  BEGIN
    o_missing:=0;
    dbms_lob.createtemporary(o_sql,true);
    FOR i IN 1..p_required.count LOOP
      IF NOT policy_allowed(p_required(i)) THEN raise_application_error(-20070,'Unsupported system grant.'); END IF;
      SELECT count(*) INTO n FROM user_sys_privs WHERE privilege=p_required(i);
      IF n=0 THEN
        dbms_output.put_line('MC_GRANT|SYSTEM|'||p_required(i)); o_missing:=o_missing+1;
        dbms_lob.append(o_sql,'GRANT '||p_required(i)||' TO '||dbms_assert.enquote_name(sys_context('USERENV','CURRENT_USER'),false)||';'||chr(10));
      END IF;
    END LOOP;
    WHILE pos<=NVL(dbms_lob.getlength(p_objects),0) LOOP
      eol:=dbms_lob.instr(p_objects,chr(10),pos);
      IF eol=0 THEN eol:=dbms_lob.getlength(p_objects)+1; END IF;
      IF eol-pos>4000 THEN raise_application_error(-20070,'Invalid object grant inventory.'); END IF;
      line:=rtrim(dbms_lob.substr(p_objects,eol-pos,pos),chr(13));
      a:=instr(line,'|'); b:=instr(line,'|',a+1);
      owner_name:=substr(line,1,a-1); object_name:=substr(line,a+1,b-a-1); priv:=substr(line,b+1);
      IF a=0 OR b=0 OR owner_name IS NULL OR object_name IS NULL OR NOT regexp_like(owner_name,'^[A-Z][A-Z0-9_$#]{0,127}$','c')
         OR NOT regexp_like(object_name,'^[A-Z][A-Z0-9_$#]{0,127}$','c')
         OR priv IS NULL OR priv NOT IN ('EXECUTE','SELECT') THEN
        raise_application_error(-20070,'Invalid object grant inventory.');
      END IF;
      grant_name:=dbms_assert.enquote_name(owner_name,false)||'.'||dbms_assert.enquote_name(object_name,false);
      -- Oracle patches replace the physical DBMS_CLOUD package independently
      -- on each database. Also accept inventories from pre-portability bundles.
      IF owner_name='C##CLOUD$SERVICE' AND priv='EXECUTE' AND
         (object_name='DBMS_CLOUD' OR regexp_like(object_name,'^DBMS_CLOUD\$PDBCS_[A-Z0-9_]+$','c')) THEN
        SELECT count(*) INTO n FROM user_objects WHERE object_name='DBMS_CLOUD'
          AND object_type IN ('SYNONYM','PACKAGE','PROCEDURE','FUNCTION','TABLE','VIEW','TYPE','SEQUENCE','MATERIALIZED VIEW');
        IF n<>0 THEN raise_application_error(-20070,'Local DBMS_CLOUD object shadows the Oracle public synonym; DBA review required.'); END IF;
        BEGIN
          SELECT table_owner,table_name INTO owner_name,object_name FROM all_synonyms
            WHERE owner='PUBLIC' AND synonym_name='DBMS_CLOUD' AND db_link IS NULL
              AND table_owner='C##CLOUD$SERVICE';
        EXCEPTION WHEN NO_DATA_FOUND THEN
          raise_application_error(-20070,'Oracle public DBMS_CLOUD synonym unavailable; DBA review required.');
        END;
        grant_name:='DBMS_CLOUD';
      END IF;
      SELECT count(*) INTO n FROM all_tab_privs WHERE table_schema=owner_name AND table_name=object_name
        AND privilege=priv AND grantee IN (sys_context('USERENV','CURRENT_USER'),'PUBLIC');
      IF n=0 THEN
        dbms_output.put_line('MC_GRANT|OBJECT|'||owner_name||'|'||case when grant_name='DBMS_CLOUD' then 'DBMS_CLOUD' else object_name end||'|'||priv); o_missing:=o_missing+1;
        dbms_lob.append(o_sql,'GRANT '||priv||' ON '||grant_name||' TO '||dbms_assert.enquote_name(sys_context('USERENV','CURRENT_USER'),false)||';'||chr(10));
      END IF;
      pos:=eol+1;
    END LOOP;
    dbms_output.put_line('MC_GRANT_TARGET|'||sys_context('USERENV','CURRENT_USER')||'|'||
      sys_context('USERENV','DB_UNIQUE_NAME')||'|'||sys_context('USERENV','CON_NAME'));
    dbms_output.put_line('MC_GRANT_COUNT|'||o_missing);
  EXCEPTION WHEN OTHERS THEN
    IF dbms_lob.istemporary(o_sql)=1 THEN dbms_lob.freetemporary(o_sql); END IF;
    RAISE;
  END;
  FUNCTION policy_baseline RETURN sys.odcivarchar2list IS
  BEGIN
    RETURN sys.odcivarchar2list('CREATE SESSION','CREATE TABLE','CREATE PROCEDURE','CREATE JOB');
  END;
  PROCEDURE policy_finish(p_required sys.odcivarchar2list,p_context_found BOOLEAN) IS
  BEGIN
    FOR i IN 1..p_required.count LOOP
      IF p_required(i)='CREATE ANY CONTEXT' AND NOT p_context_found THEN
        raise_application_error(-20070,'CREATE ANY CONTEXT requires actual context creation in the release context phase.');
      END IF;
    END LOOP;
  END;
  PROCEDURE policy_add(p_priv VARCHAR2,p_required IN OUT NOCOPY sys.odcivarchar2list) IS
  BEGIN
    IF p_priv IS NULL OR NOT policy_allowed(p_priv) THEN
      raise_application_error(-20070,'Unsupported deployment system privilege.');
    END IF;
    FOR i IN 1..p_required.count LOOP IF p_required(i)=p_priv THEN RETURN; END IF; END LOOP;
    p_required.extend; p_required(p_required.count):=p_priv;
  END;
  FUNCTION policy_has_create(p_sql CLOB,p_kind VARCHAR2,p_depth PLS_INTEGER DEFAULT 0) RETURN BOOLEAN IS
    pos PLS_INTEGER:=1; len PLS_INTEGER:=NVL(dbms_lob.getlength(p_sql),0);
    cache VARCHAR2(32767); cache_start PLS_INTEGER:=0;
    token VARCHAR2(32767); literal VARCHAR2(32767); c VARCHAR2(4); closing VARCHAR2(4);
    prev VARCHAR2(32); before_prev VARCHAR2(32); state VARCHAR2(64);
    lob_append BOOLEAN:=FALSE;
    FUNCTION ch(n PLS_INTEGER) RETURN VARCHAR2 IS
    BEGIN
      IF n>len THEN RETURN NULL; END IF;
      IF n<cache_start OR n>=cache_start+NVL(length(cache),0) THEN
        cache_start:=n; cache:=dbms_lob.substr(p_sql,8000,n);
      END IF;
      RETURN substr(cache,n-cache_start+1,1);
    END;
  BEGIN
    WHILE pos<=len LOOP
      c:=ch(pos); token:=NULL; literal:=NULL;
      IF c IN (' ',chr(9),chr(10),chr(13)) THEN pos:=pos+1; CONTINUE;
      ELSIF c='-' AND ch(pos+1)='-' THEN
        WHILE pos<=len AND ch(pos)<>chr(10) LOOP pos:=pos+1; END LOOP; CONTINUE;
      ELSIF c='/' AND ch(pos+1)='*' THEN
        pos:=pos+2;
        WHILE pos<=len AND NOT(ch(pos)='*' AND ch(pos+1)='/') LOOP pos:=pos+1; END LOOP;
        pos:=pos+2; CONTINUE;
      ELSIF c='"' THEN
        pos:=pos+1;
        WHILE pos<=len LOOP
          IF ch(pos)='"' THEN
            IF ch(pos+1)='"' THEN pos:=pos+2; ELSE pos:=pos+1; EXIT; END IF;
          ELSE pos:=pos+1; END IF;
        END LOOP;
        token:='#IDENTIFIER#';
      ELSIF c='''' OR (upper(c)='Q' AND ch(pos+1)='''') THEN
        IF upper(c)='Q' THEN
          closing:=ch(pos+2);
          closing:=CASE closing WHEN '[' THEN ']' WHEN '(' THEN ')' WHEN '{' THEN '}' WHEN '<' THEN '>' ELSE closing END;
          pos:=pos+3;
          WHILE pos<=len AND NOT(ch(pos)=closing AND ch(pos+1)='''') LOOP
            IF NVL(length(literal),0)<8000 THEN literal:=literal||ch(pos); END IF;
            pos:=pos+1;
          END LOOP;
          pos:=pos+2;
        ELSE
          pos:=pos+1;
          WHILE pos<=len LOOP
            IF ch(pos)='''' THEN
              IF ch(pos+1)='''' THEN pos:=pos+1; ELSE pos:=pos+1; EXIT; END IF;
            END IF;
            IF NVL(length(literal),0)<8000 THEN literal:=literal||ch(pos); END IF;
            pos:=pos+1;
          END LOOP;
        END IF;
        -- Canonical view/MV/graph adapters assemble their CREATE statement in
        -- a CLOB. Infer its existing allowed privilege from the literal chunk;
        -- ordinary strings (including DBMS_OUTPUT) remain non-executable.
        IF p_depth=0 AND lob_append AND policy_has_create(to_clob(literal),p_kind,1) THEN
          RETURN TRUE;
        END IF;
        IF p_depth=0 AND before_prev='EXECUTE' AND prev='IMMEDIATE' THEN
          IF policy_has_create(to_clob(literal),p_kind,1) THEN RETURN TRUE; END IF;
          IF regexp_like(literal,'^[[:space:]]*CREATE([[:space:]]|$)','i') THEN
            raise_application_error(-20070,'Unsupported dynamic CREATE in deployment phase; use the canonical exporter.');
          END IF;
        END IF;
        token:='#LITERAL#';
      ELSIF instr('ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789_$#',c)>0 THEN
        WHILE pos<=len AND instr('ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789_$#',ch(pos))>0 LOOP
          IF NVL(length(token),0)<8000 THEN token:=token||upper(ch(pos)); END IF;
          pos:=pos+1;
        END LOOP;
      ELSE token:=c; pos:=pos+1;
      END IF;
      IF p_depth=0 AND before_prev='EXECUTE' AND prev='IMMEDIATE' AND token<>'#LITERAL#' THEN
        raise_application_error(-20070,'Computed deployment DDL requires explicit reviewed privilege support.');
      END IF;
      IF token='WRITEAPPEND' AND before_prev='DBMS_LOB' AND prev='.' THEN
        lob_append:=TRUE;
      ELSIF token=';' THEN lob_append:=FALSE;
      END IF;
      IF token='CREATE' THEN state:='CREATE';
      ELSIF state='CREATE' AND token IN ('OR','REPLACE','FORCE','EDITIONABLE','NONEDITIONABLE') THEN NULL;
      ELSIF state='CREATE' THEN
        IF token=p_kind THEN RETURN TRUE;
        ELSIF token IN ('PROPERTY','MATERIALIZED') THEN state:=token;
        ELSE state:=NULL; END IF;
      ELSIF state||' '||token=p_kind THEN RETURN TRUE;
      ELSE state:=NULL;
      END IF;
      before_prev:=prev; prev:=substr(token,1,32);
    END LOOP;
    RETURN FALSE;
  END;
  PROCEDURE policy_add_file(p_path VARCHAR2,p_sql CLOB,
    p_required IN OUT NOCOPY sys.odcivarchar2list) IS
    kind VARCHAR2(32); priv VARCHAR2(32); pos PLS_INTEGER:=1; eol PLS_INTEGER;
    line VARCHAR2(128); seen sys.odcivarchar2list:=sys.odcivarchar2list();
  BEGIN
    IF p_path='db/preflight/required_system_privileges.txt' THEN
      WHILE pos<=NVL(dbms_lob.getlength(p_sql),0) LOOP
        eol:=dbms_lob.instr(p_sql,chr(10),pos);
        IF eol=0 THEN eol:=dbms_lob.getlength(p_sql)+1; END IF;
        IF eol-pos>128 THEN raise_application_error(-20070,'Invalid system privilege inventory.'); END IF;
        line:=rtrim(dbms_lob.substr(p_sql,eol-pos,pos),chr(13));
        FOR i IN 1..seen.count LOOP
          IF seen(i)=line THEN raise_application_error(-20070,'Duplicate system privilege inventory entry.'); END IF;
        END LOOP;
        policy_add(line,seen); policy_add(line,p_required); pos:=eol+1;
      END LOOP;
      RETURN;
    END IF;
    kind:=CASE p_path
      WHEN 'db/ddl/02_sequences.sql' THEN 'SEQUENCE'
      WHEN 'db/ddl/03a_views.sql' THEN 'VIEW'
      WHEN 'db/ddl/05_contexts.sql' THEN 'CONTEXT'
      WHEN 'db/ddl/08_mviews.sql' THEN 'MATERIALIZED VIEW'
      WHEN 'db/ddl/08a_property_graphs.sql' THEN 'PROPERTY GRAPH'
      WHEN 'db/ddl/09_triggers.sql' THEN 'TRIGGER' END;
    IF kind IS NOT NULL AND policy_has_create(p_sql,kind) THEN
      priv:=CASE kind WHEN 'CONTEXT' THEN 'CREATE ANY CONTEXT' ELSE 'CREATE '||kind END;
      policy_add(priv,p_required);
    END IF;
  END;
-- END PRIVILEGE POLICY
  FUNCTION privilege_protocol RETURN VARCHAR2 IS
  BEGIN RETURN 'mc-direct-grants-1'; END;
  FUNCTION system_privileges_for(p_path VARCHAR2,p_sql CLOB) RETURN sys.odcivarchar2list IS
    result sys.odcivarchar2list:=sys.odcivarchar2list();
  BEGIN
    IF p_path IS NULL THEN RETURN policy_baseline; END IF;
    policy_add_file(p_path,p_sql,result); RETURN result;
  END;
  FUNCTION required_system_privileges(p_zip BLOB) RETURN sys.odcivarchar2list IS
    entries t_members; content BLOB; decoded CLOB;
    result sys.odcivarchar2list:=policy_baseline;
    context_found BOOLEAN:=FALSE;
    PROCEDURE cleanup IS BEGIN
      IF dbms_lob.istemporary(content)=1 THEN dbms_lob.freetemporary(content); END IF;
      IF dbms_lob.istemporary(decoded)=1 THEN dbms_lob.freetemporary(decoded); END IF;
    END;
  BEGIN
    zip_inspect(p_zip,entries);
    FOR i IN 1..entries.count LOOP
      IF entries(i).name IN ('db/ddl/02_sequences.sql','db/ddl/03a_views.sql',
        'db/ddl/05_contexts.sql','db/ddl/08_mviews.sql','db/ddl/08a_property_graphs.sql',
        'db/ddl/09_triggers.sql','db/preflight/required_system_privileges.txt') THEN
        content:=get_member(p_zip,entries(i)); decoded:=blob_to_clob(content);
        IF entries(i).name='db/ddl/05_contexts.sql' THEN context_found:=policy_has_create(decoded,'CONTEXT'); END IF;
        policy_add_file(entries(i).name,decoded,result); cleanup;
      END IF;
    END LOOP;
    policy_finish(result,context_found); RETURN result;
  EXCEPTION WHEN OTHERS THEN cleanup; RAISE;
  END;
  PROCEDURE grant_report(p_zip BLOB,o_missing OUT PLS_INTEGER,o_sql OUT CLOB) IS
    entries t_members; content BLOB; decoded CLOB;
    required sys.odcivarchar2list; found BOOLEAN:=FALSE;
    PROCEDURE cleanup IS BEGIN
      IF dbms_lob.istemporary(content)=1 THEN dbms_lob.freetemporary(content); END IF;
      IF dbms_lob.istemporary(decoded)=1 THEN dbms_lob.freetemporary(decoded); END IF;
    END;
  BEGIN
    required:=required_system_privileges(p_zip);
    zip_inspect(p_zip,entries);
    FOR i IN 1..entries.count LOOP
      IF entries(i).name='db/preflight/required_privileges.txt' THEN
        content:=get_member(p_zip,entries(i),1048576);
        decoded:=blob_to_clob(content); found:=TRUE; EXIT;
      END IF;
    END LOOP;
    IF NOT found THEN raise_application_error(-20070,'Required object privilege inventory missing.'); END IF;
    policy_report(required,decoded,o_missing,o_sql); cleanup;
  EXCEPTION WHEN OTHERS THEN cleanup; RAISE;
  END;
  PROCEDURE report_privileges(p_zip BLOB,o_missing OUT PLS_INTEGER) IS
    statements CLOB;
  BEGIN
    grant_report(p_zip,o_missing,statements);
    IF dbms_lob.istemporary(statements)=1 THEN dbms_lob.freetemporary(statements); END IF;
  END;
  FUNCTION missing_grants_sql(p_zip BLOB) RETURN CLOB IS
    statements CLOB; n PLS_INTEGER;
  BEGIN grant_report(p_zip,n,statements); RETURN statements; END;
  PROCEDURE assert_system_privileges(p_zip BLOB) IS
    n PLS_INTEGER; required sys.odcivarchar2list; count_direct NUMBER; detail VARCHAR2(1800);
  BEGIN
    report_privileges(p_zip,n);
    IF n>0 THEN
      required:=required_system_privileges(p_zip);
      FOR i IN 1..required.count LOOP
        SELECT count(*) INTO count_direct FROM user_sys_privs WHERE privilege=required(i);
        IF count_direct=0 THEN detail:=detail||' GRANT '||required(i)||' TO '||
          dbms_assert.enquote_name(sys_context('USERENV','CURRENT_USER'),false)||';'; END IF;
      END LOOP;
      raise_application_error(-20070,'Missing '||n||' required direct grants.'||detail||
        ' UI cannot apply ADMIN grants. Use CLI grant remediation or ask target ADMIN; no application changes started.');
    END IF;
  END;
MC_ARCHIVE_INSPECTOR
}
mc_product_definition_early_sql() {
cat <<'MC_PRODUCT_DEFINITION_EARLY'
-- GENERATED by db/deployer/build_product_definition_early.py; do not edit.
  procedure install_product_definition(p_zip blob,p_expected_hash varchar2) is
    app number;version_value varchar2(64);registry_run number;spec_hash varchar2(64);body_hash varchar2(64);
    coverage_text clob;coverage json_object_t;entries json_array_t;bindings json_array_t;item json_object_t;ident json_object_t;
    type label_list is table of varchar2(1000) index by varchar2(64);
    labels label_list;label_key varchar2(64);label_text varchar2(1000);
    type object_list is table of json_object_t index by pls_integer;
    selected object_list;bound object_list;
    type bool_list is table of boolean index by pls_integer;
    missing bool_list;
    members t_members;payload blob;statement_text clob;actual varchar2(64);slot pls_integer;n number;c integer;ignored integer;
    function independent_fingerprint(p_identity clob,p_format varchar2) return varchar2 is

  -- Read-only definition inspection. Unsupported families fail closed.
  function fingerprint(p_identity_json clob,p_format varchar2) return varchar2;
  -- Source comparison metadata is bound to the same complete definition hash.
  function table_contract(p_identity_json clob,p_format varchar2) return clob;
  function table_compatible(p_identity_json clob,p_format varchar2,
    p_expected_sha256 varchar2,p_contract clob) return boolean;
  -- Extract one whole SQL payload from the checked definition, not by splitting
  -- a phase script. Supports PL/SQL, sequences, views, bounded jobs/graphs and
  -- CREATE-only ordinary tables/materialized views. Caller
  -- still owns registry approval, dependency scheduling and archive integrity.
  function extract_sql(p_identity_json clob,p_format varchar2,p_expected_sha256 varchar2) return clob;

  procedure fail(p_message varchar2) is
  begin raise_application_error(-20862,'Artifact definition: '||p_message); end;

  function declaration_end(p_source clob,p_name varchar2,p_type varchar2) return integer is
    pos integer:=1; finish integer; token varchar2(4000); c varchar2(4 char); after_name integer;
    function char_at(p_pos integer) return varchar2 is
    begin return substr(dbms_lob.substr(p_source,2,p_pos),1,1); end;
    function next_token return varchar2 is v varchar2(4000):=''; quoted boolean:=false;
    begin
      loop
        c:=char_at(pos);
        if c is null then fail('Incomplete source declaration.'); end if;
        if instr(' '||chr(9)||chr(10)||chr(13),c)>0 then pos:=pos+1;
        elsif dbms_lob.substr(p_source,2,pos)='--' then
          finish:=dbms_lob.instr(p_source,chr(10),pos+2);
          if finish=0 then fail('Incomplete source declaration.'); end if;
          pos:=finish+1;
        elsif dbms_lob.substr(p_source,2,pos)='/*' then
          finish:=dbms_lob.instr(p_source,'*/',pos+2);
          if finish=0 then fail('Incomplete source declaration.'); end if;
          pos:=finish+2;
        else exit; end if;
      end loop;
      if c='.' then pos:=pos+1; return '.'; end if;
      if c='"' then
        quoted:=true; pos:=pos+1;
        loop
          c:=char_at(pos);
          if c is null then fail('Incomplete quoted identifier.'); end if;
          pos:=pos+length2(c);
          if c='"' then
            if char_at(pos)='"' then pos:=pos+1; else exit; end if;
          end if;
          v:=v||c;
          if lengthb(v)>128 then fail('Invalid declaration identifier.'); end if;
        end loop;
      else
        loop
          c:=char_at(pos);
          exit when c is null or not regexp_like(c,'[[:alnum:]_$#]');
          v:=v||c; pos:=pos+length2(c);
          if lengthb(v)>128 then fail('Invalid declaration identifier.'); end if;
        end loop;
      end if;
      if v is null then fail('Unsupported source declaration.'); end if;
      if not quoted then v:=upper(v); end if;
      return v;
    end;
  begin
    if next_token<>regexp_substr(p_type,'^[A-Z]+') then fail('Unexpected declaration kind.'); end if;
    if p_type in ('PACKAGE BODY','TYPE BODY') and next_token<>'BODY' then fail('Unexpected declaration kind.'); end if;
    token:=next_token;
    after_name:=pos;
    if token=sys_context('USERENV','CURRENT_USER') then
      if next_token='.' then
        if next_token<>p_name then fail('Unexpected declaration name.'); end if;
        return pos;
      end if;
      pos:=after_name;
    end if;
    if token<>p_name then fail('Unexpected declaration name.'); end if;
    return pos;
  end;

  function code_text_hash(src clob,p_name varchar2,p_type varchar2) return varchar2 is
    normalized clob; bytes blob; result varchar2(64); body_pos integer;
    dest_pos integer:=1; src_pos integer:=1; ctx integer:=0; warning integer;
    line_pos integer; content_pos integer:=1;
  begin
    if src is null or dbms_lob.getlength(src)=0 then fail('Object is missing or unreadable.'); end if;
    body_pos:=declaration_end(src,p_name,p_type);
    dbms_lob.createtemporary(normalized,true);
    -- Header spelling is identity metadata; its line offset affects $$PLSQL_LINE.
    line_pos:=dbms_lob.instr(src,chr(10),1);
    while line_pos>0 and line_pos<body_pos loop
      dbms_lob.writeappend(normalized,1,chr(10)); content_pos:=content_pos+1;
      line_pos:=dbms_lob.instr(src,chr(10),line_pos+1);
    end loop;
    dbms_lob.copy(normalized,src,dbms_lob.getlength(src)-body_pos+1,content_pos,body_pos);
    -- Preserve literals, quoted identifiers and comments, including their spaces.
    dbms_lob.createtemporary(bytes,true);
    dbms_lob.converttoblob(bytes,normalized,dbms_lob.lobmaxsize,dest_pos,src_pos,
      nls_charset_id('AL32UTF8'),ctx,warning);
    if warning<>0 then fail('Source character conversion failed.'); end if;
    result:=lower(rawtohex(dbms_crypto.hash(bytes,dbms_crypto.hash_sh256)));
    dbms_lob.freetemporary(bytes); dbms_lob.freetemporary(normalized);
    return result;
  exception when others then
    if dbms_lob.istemporary(bytes)=1 then dbms_lob.freetemporary(bytes); end if;
    if dbms_lob.istemporary(normalized)=1 then dbms_lob.freetemporary(normalized); end if;
    raise;
  end;

  function code_hash(p_name varchar2,p_type varchar2) return varchar2 is src clob; result varchar2(64);
  begin
    dbms_lob.createtemporary(src,true);
    for r in (select text from user_source where name=p_name and type=p_type order by line) loop
      if r.text is not null then dbms_lob.writeappend(src,length2(r.text),r.text); end if;
      if dbms_lob.getlength(src)>8388608 then fail('Source exceeds reader limit.'); end if;
    end loop;
    result:=code_text_hash(src,p_name,p_type);
    dbms_lob.freetemporary(src); return result;
  exception when others then
    if dbms_lob.istemporary(src)=1 then dbms_lob.freetemporary(src); end if;
    raise;
  end;

  function compiled_code_hash(p_name varchar2,p_type varchar2,p_format varchar2,p_source_hash varchar2,
    p_settings user_plsql_object_settings%rowtype,p_trigger_state varchar2) return varchar2 is
    j json_object_t:=json_object_t(); text_value varchar2(32767);
  begin
    j.put('format',p_format); j.put('object_type',p_type); j.put('object_name',p_name);
    j.put('source_sha256',p_source_hash);
    j.put('plsql_ccflags',p_settings.plsql_ccflags);
    j.put('nls_length_semantics',p_settings.nls_length_semantics);
    j.put('plsql_optimize_level',p_settings.plsql_optimize_level);
    j.put('plsql_code_type',p_settings.plsql_code_type);
    j.put('plsql_debug',p_settings.plsql_debug);
    j.put('plsql_warnings',p_settings.plsql_warnings);
    j.put('plscope_settings',p_settings.plscope_settings);
    if p_type='TRIGGER' then j.put('trigger_status',p_trigger_state); end if;
    text_value:=j.to_string;
    return lower(rawtohex(dbms_crypto.hash(utl_i18n.string_to_raw(text_value,'AL32UTF8'),dbms_crypto.hash_sh256)));
  end;

  function json_hash(p_document json_object_t) return varchar2 is
    chars clob; bytes blob; result varchar2(64);
    dest_pos integer:=1; src_pos integer:=1; ctx integer:=0; warning integer;
  begin
    chars:=p_document.to_clob;
    dbms_lob.createtemporary(bytes,true);
    dbms_lob.converttoblob(bytes,chars,dbms_lob.lobmaxsize,dest_pos,src_pos,
      nls_charset_id('AL32UTF8'),ctx,warning);
    if warning<>0 then fail('Definition character conversion failed.'); end if;
    result:=lower(rawtohex(dbms_crypto.hash(bytes,dbms_crypto.hash_sh256)));
    dbms_lob.freetemporary(bytes); dbms_lob.freetemporary(chars);
    return result;
  exception when others then
    if dbms_lob.istemporary(bytes)=1 then dbms_lob.freetemporary(bytes); end if;
    if dbms_lob.istemporary(chars)=1 then dbms_lob.freetemporary(chars); end if;
    raise;
  end;

  function lob_policy(p_column varchar2,p_secure varchar2,p_inline number,p_in_row varchar2,
    p_cache varchar2,p_logging varchar2,p_compress varchar2,p_deduplicate varchar2,
    p_encrypt varchar2,p_retention varchar2,p_minret varchar2) return json_object_t is
    j json_object_t:=json_object_t();
  begin
    if p_secure<>'YES' or p_encrypt<>'NO' then fail('Unsupported partition LOB storage.'); end if;
    j.put('column',p_column); j.put('securefile',p_secure); j.put('max_inline',p_inline);
    j.put('in_row',p_in_row); j.put('cache',p_cache); j.put('logging',p_logging);
    j.put('compression',p_compress); j.put('deduplication',p_deduplicate);
    j.put('retention_type',p_retention);
    if p_retention='MIN' then j.put('retention_value',to_number(p_minret));
    else j.put_null('retention_value'); end if;
    return j;
  end;

  function resolved_logging(p_logging varchar2,p_tablespace varchar2,p_cache varchar2 default null)
    return varchar2 is v varchar2(20);
  begin
    if p_logging in ('YES','NO') then return p_logging; end if;
    if p_cache='YES' then return 'YES'; end if;
    select logging into v from user_tablespaces where tablespace_name=p_tablespace;
    if v='LOGGING' then return 'YES'; elsif v='NOLOGGING' then return 'NO'; end if;
    fail('Unresolved partition logging default.'); return null;
  end;

  function partition_policy(p_name varchar2) return json_object_t is
    j json_object_t:=json_object_t(); lobs json_array_t:=json_array_t();
    d user_part_tables%rowtype;
  begin
      select * into d from user_part_tables where table_name=p_name;
      if d.def_inmemory='ENABLED' then fail('Partition In-Memory policy is unsupported.'); end if;
      -- Match the portable bundle policy: segment tuning is target-owned.
      -- Partition routing and functional future LOB defaults remain managed.
      j.put('read_only',d.def_read_only); j.put('indexing',d.def_indexing);
      for l in (select * from user_part_lobs where table_name=p_name
        order by nlssort(column_name,'NLS_SORT=BINARY')) loop
        lobs.append(lob_policy(l.column_name,l.def_securefile,l.def_max_inline,l.def_in_row,l.def_cache,
          resolved_logging(l.def_logging,nvl(l.def_tablespace_name,d.def_tablespace_name),l.def_cache),
          l.def_compress,l.def_deduplicate,l.def_encrypt,l.def_retention,l.def_minret));
      end loop;
    j.put('lobs',lobs); return j;
  end;

  procedure assert_partition_routing(p_metadata xmltype) is
    nodes number; nonempty number;
  begin
    -- STORE IN is not exposed by USER_PART_TABLES. Reject routing lists until
    -- inherited policy can be resolved for every destination. Unknown metadata
    -- shapes also fail closed; never hash internal IDs or source timestamps.
    select count(*),nvl(sum(r.nonempty),0)
      into nodes,nonempty
      from xmltable('/ROWSET/ROW/TABLE_T/PART_OBJ/PARTOBJ/INSERT_TS_LIST'
        passing p_metadata columns nonempty number path
          'if (exists(*) or normalize-space(string(.)) != "") then 1 else 0') r;
    if nodes<>1 or nonempty<>0 then
      fail('Explicit or unknown interval tablespace routing requires a separate adapter.');
    end if;
  end;

  function initial_partition_layout(p_name varchar2) return json_object_t is
    j json_object_t:=json_object_t();
  begin
    -- Authored product creation rules, not inferred from retained partitions.
    -- These boundaries reproduce the portable legacy INITIAL layout. They
    -- never authorize ALTER/MOVE/DROP of any existing target partition.
    if p_name in ('FOCUS_REPORTS_PY','FOCUS_REPORTS_PY_ARCHIVE') then
      j.put('key','CHARGEPERIODSTART'); j.put('before','2024-01-01');
      j.put('name','P_BEFORE_2024');
    elsif p_name='OCI_AVAILABILITY_METRICS_PY' then
      j.put('key','TIMESTAMP'); j.put('before','2022-01-01');
      j.put('name','OCI_AVAILABILITY_METRICS_PY_BEFORE_2022');
    else return null;
    end if;
    j.put('contract','mc-initial-monthly-layout-1'); return j;
  end;

  function partition_definition(p_name varchar2) return json_object_t is
    d user_part_tables%rowtype; j json_object_t:=json_object_t();
    keys json_array_t:=json_array_t();
    metadata clob;
  begin
    select * into d from user_part_tables where table_name=p_name;
    if d.partitioning_type<>'RANGE' or d.subpartitioning_type<>'NONE'
      or d.auto='YES' then fail('Unsupported partition organization.'); end if;
    if d.interval is not null then
      begin
        metadata:=dbms_metadata.get_xml('TABLE',p_name);
        assert_partition_routing(xmltype(metadata));
        if dbms_lob.istemporary(metadata)=1 then dbms_lob.freetemporary(metadata); end if;
      exception when others then
        if dbms_lob.istemporary(metadata)=1 then dbms_lob.freetemporary(metadata); end if;
        raise;
      end;
    end if;
    j.put('type',d.partitioning_type); j.put('interval',d.interval);
    for k in (select column_name from user_part_key_columns where name=p_name and object_type='TABLE'
      order by column_position) loop keys.append(k.column_name); end loop;
    if keys.get_size<>d.partitioning_key_count then fail('Incomplete partition key metadata.'); end if;
    j.put('keys',keys); j.put('defaults',partition_policy(p_name));
    -- Authored INITIAL-only rules are integrity-bound product metadata. Live
    -- boundaries remain excluded; changing a rule needs an explicit review.
    if initial_partition_layout(p_name) is not null then
      j.put('initial_layout',initial_partition_layout(p_name)); end if;
    -- Existing partition inventory is target-owned data/storage state, including
    -- user-assigned names. Explicit application-owned layouts need a separate
    -- authored contract; never infer ownership from live partition names.
    -- Existing-partition maintenance must use its own migration verification.
    return j;
  end;

  procedure sequence_values(j in out json_object_t,s user_sequences%rowtype) is
  begin
    -- LAST_NUMBER and physical sequence name are not authored policy.
    j.put('min_value',s.min_value); j.put('max_value',s.max_value);
    j.put('increment_by',s.increment_by); j.put('cycle_flag',s.cycle_flag);
    j.put('order_flag',s.order_flag); j.put('cache_size',s.cache_size);
    j.put('scale_flag',s.scale_flag); j.put('extend_flag',s.extend_flag);
    j.put('sharded_flag',s.sharded_flag); j.put('session_flag',s.session_flag);
    j.put('keep_value',s.keep_value);
  end;

  procedure sequence_policy(j in out json_object_t,p_name varchar2) is s user_sequences%rowtype;
  begin
    select * into s from user_sequences where sequence_name=p_name;
    sequence_values(j,s);
  end;

  function has_qualified_identifier(p_text varchar2,p_owner varchar2 default null) return boolean;

  function table_document(p_name varchar2,p_format varchar2,p_mview boolean default false) return json_object_t is
    t user_tables%rowtype; j json_object_t:=json_object_t(); item json_object_t;
    cols json_array_t:=json_array_t(); lobs json_array_t:=json_array_t();
    default_text varchar2(32767); n number;
    identity_col user_tab_identity_cols%rowtype; identity_json json_object_t;
    identity_start varchar2(100);
    unused_columns number; unused_candidates number; json_storage boolean;
  begin
    select * into t from user_tables where table_name=p_name;
    -- Each family needs its own tested contract; never hash a partial definition.
    if t.iot_type is not null or t.cluster_name is not null
      or t.nested<>'NO' or t.secondary<>'N' or t.external<>'NO'
      or t.clustering='YES' or t.hybrid='YES'
      or t.sharded='Y' or t.duplicated='Y' or t.container_data='YES'
      or t.inmemory='ENABLED' then
      fail('Unsupported table organization or policy: '||p_name);
    end if;
    select count(*) into n from user_mviews where mview_name=p_name;
    if not p_mview and n>0 then
      select count(*) into n from user_mviews where mview_name=p_name and container_name=p_name and build_mode='PREBUILT';
      if n<>1 then fail('Ordinary materialized-view storage belongs to its MV artifact.'); end if;
    elsif p_mview and n<>1 then
      fail('Materialized-view storage requires its own artifact.');
    end if;
    select count(*) into n from user_object_tables where table_name=p_name;
    if n>0 then fail('Object tables require a separate adapter.'); end if;
    select count(*) into n from user_encrypted_columns where table_name=p_name;
    if n>0 then fail('Encrypted columns require a separate adapter.'); end if;
    select count(*) into n from user_lobs where table_name=p_name and value_based='YES';
    if n>0 then fail('Value-based LOBs require a separate adapter.'); end if;
    select count(*) into n from user_blockchain_tables where table_name=p_name;
    if n>0 then fail('Blockchain tables require a separate adapter.'); end if;
    select count(*) into n from user_immutable_tables where table_name=p_name;
    if n>0 then fail('Immutable tables require a separate adapter.'); end if;
    -- SET UNUSED retains inaccessible physical columns. Require dictionary count
    -- agreement as well as the generated shape; names alone never prove ownership.
    select nvl(max(count),0) into unused_columns from user_unused_col_tabs where table_name=p_name;
    select count(*) into unused_candidates from user_tab_cols
      where table_name=p_name and user_generated='NO' and hidden_column='YES'
        and virtual_column='NO' and column_id is null
        and regexp_like(column_name,'^SYS_C[0-9]+_[0-9]+:[0-9]+:[0-9]+[$]$','c');
    if unused_columns<>unused_candidates then fail('Unused column dictionary evidence mismatch.'); end if;
    -- Index expressions belong to the index. JSON IME columns are dictionary-
    -- proven acceleration storage for an existing TEXT JSON source column.
    -- Row archival, temporal validity and other generated policies still fail.
    for c in (select c.column_name,c.hidden_column,c.virtual_column,c.data_type,c.data_default
      from user_tab_cols c
      where c.table_name=p_name and c.user_generated='NO'
      and not (unused_columns>0 and c.hidden_column='YES' and c.virtual_column='NO'
        and c.column_id is null
        and regexp_like(c.column_name,'^SYS_C[0-9]+_[0-9]+:[0-9]+:[0-9]+[$]$','c'))
      and not (case when p_mview then 1 else 0 end=1 and c.column_name='M_ROW$$'
        and c.hidden_column='YES' and c.virtual_column='NO'
        and c.data_type='VARCHAR2' and c.data_length=18)
      and not
      (c.hidden_column='YES' and c.virtual_column='YES' and exists
       (select 1 from user_ind_columns ic join user_ind_expressions ie
          on ie.index_name=ic.index_name and ie.table_name=ic.table_name
          and ie.column_position=ic.column_position
        join user_indexes ix on ix.index_name=ic.index_name and ix.table_name=ic.table_name
        where ic.table_name=c.table_name and ic.column_name=c.column_name
          and ix.index_type in ('FUNCTION-BASED NORMAL','FUNCTION-BASED BITMAP')))) loop
      json_storage:=false;
      if c.hidden_column='YES' and c.virtual_column='YES' and c.data_type='RAW'
        and regexp_like(c.column_name,'^SYS_IME_OSON_[[:xdigit:]]{32}$','c') then
        for source_col in (select column_name from user_json_columns
          where table_name=p_name and format='TEXT' and data_type in ('CLOB','BLOB','VARCHAR2')) loop
          if c.data_default='OSON('||dbms_assert.enquote_name(source_col.column_name,false)||
            ' FORMAT JSON , ''ime'' RETURNING RAW(32767) NULL ON ERROR)' then
            json_storage:=true; exit;
          end if;
        end loop;
      end if;
      if not json_storage then fail('System-generated table columns require a separate adapter.'); end if;
    end loop;
    j.put('format',p_format); j.put('object_type','TABLE'); j.put('object_name',p_name);
    j.put('temporary',t.temporary); j.put('duration',t.duration);
    j.put('row_movement',t.row_movement); j.put('dependencies',t.dependencies);
    j.put('read_only',t.read_only); j.put('default_collation',t.default_collation);
    if t.partitioned='YES' then j.put('partitioning',partition_definition(p_name)); end if;
    -- Placement, segment tuning/compression/logging, IDs/extents and statistics
    -- are target/runtime state, matching the existing portable bundle policy.
    -- Constraint/index definitions are separate registry artifacts.
    for c in (select column_name,data_type,data_type_mod,data_type_owner,data_length,
      data_precision,data_scale,nullable,default_length,char_length,char_used,
      character_set_name,hidden_column,virtual_column,default_on_null,
      default_on_null_upd,collation,domain_owner,domain_name,identity_column,
      evaluation_edition,unusable_before,unusable_beginning,reservable_column,
      json_modifier,vector_info
      from user_tab_cols where table_name=p_name and user_generated='YES'
      order by column_id nulls last,nlssort(column_name,'NLS_SORT=BINARY')) loop
      if c.data_type_owner is not null or c.domain_name is not null
        or c.evaluation_edition is not null
        or c.unusable_before is not null or c.unusable_beginning is not null
        or c.reservable_column='YES' or c.data_type in ('VECTOR','JSON') then
        fail('Unsupported column policy: '||p_name||'.'||c.column_name);
      end if;
      if c.default_length>32760 then fail('Column default exceeds reader limit.'); end if;
      -- DATA_DEFAULT_VC may silently truncate. Read the LONG, with a size guard.
      if c.identity_column='YES' then
        -- The generated owner-qualified NEXTVAL is represented by the identity
        -- policy below; do not hash its environment-generated sequence name.
        default_text:=null;
      else
        select data_default into default_text from user_tab_cols
          where table_name=p_name and column_name=c.column_name;
      end if;
      -- Oracle expands sequence defaults to physical-owner-qualified text but
      -- does not expose that dependency in USER_DEPENDENCIES. Until a parsed
      -- default-expression adapter exists, conservatively reject qualified
      -- expressions; literal contents are not identifiers and remain exact.
      if has_qualified_identifier(default_text) then
        fail('Qualified column defaults require a separate adapter.');
      end if;
      item:=json_object_t(); item.put('name',c.column_name);
      item.put('type',c.data_type); item.put('type_mod',c.data_type_mod);
      -- LOB DATA_LENGTH can change after a partition move (4000 -> 8200)
      -- without changing the column's logical type or future LOB defaults.
      -- Inline capacity belongs to the LOB policy, not column length.
      if c.data_type in ('CLOB','NCLOB','BLOB') then item.put_null('length');
      else item.put('length',c.data_length); end if;
      item.put('precision',c.data_precision);
      item.put('scale',c.data_scale); item.put('nullable',c.nullable);
      item.put('char_length',c.char_length); item.put('char_used',c.char_used);
      item.put('charset',c.character_set_name); item.put('invisible',c.hidden_column);
      item.put('virtual',c.virtual_column); item.put('default',default_text);
      item.put('default_on_null',c.default_on_null);
      item.put('default_on_null_upd',c.default_on_null_upd); item.put('collation',c.collation);
      if c.identity_column='YES' then
        select * into identity_col from user_tab_identity_cols
          where table_name=p_name and column_name=c.column_name;
        identity_start:=regexp_substr(identity_col.identity_options,
          '(^|, )START WITH: ([+-]?[0-9]+)(,|$)',1,1,'c',2);
        if identity_start is null or identity_col.generation_type not in ('ALWAYS','BY DEFAULT','BY DEFAULT ON NULL') then
          fail('Unsupported identity policy: '||p_name||'.'||c.column_name);
        end if;
        identity_json:=json_object_t(); identity_json.put('generation_type',identity_col.generation_type);
        identity_json.put('start_with',to_number(identity_start));
        sequence_policy(identity_json,identity_col.sequence_name);
        item.put('identity',identity_json);
      end if;
      cols.append(item);
    end loop;
    if cols.get_size=0 then fail('No supported table columns.'); end if;
    j.put('columns',cols);
    for l in (select * from user_lobs where table_name=p_name and t.partitioned='NO'
      order by nlssort(column_name,'NLS_SORT=BINARY')) loop
      if nvl(l.securefile,'?') not in ('YES','NO')
        or (l.securefile='NO' and t.temporary<>'Y')
        or l.partitioned<>'NO' or l.encrypt='YES'
        or l.value_based='YES' then fail('Unsupported LOB policy: '||p_name||'.'||l.column_name); end if;
      item:=json_object_t(); item.put('column',l.column_name);
      item.put('securefile',l.securefile); item.put('in_row',l.in_row);
      item.put('max_inline',l.max_inline); item.put('cache',l.cache);
      item.put('logging',l.logging); item.put('compression',l.compression);
      item.put('deduplication',l.deduplication);
      if l.securefile='YES' then
        item.put('retention_type',l.retention_type); item.put('retention_value',l.retention_value);
      end if;
      -- BasicFile block allocation and undo tuning are target-owned, too.
      lobs.append(item);
    end loop;
    j.put('lobs',lobs);
    return j;
  end;

  function table_hash(p_name varchar2,p_format varchar2,p_mview boolean default false) return varchar2 is
  begin return json_hash(table_document(p_name,p_format,p_mview)); end;

  function table_contract(p_identity_json clob,p_format varchar2) return clob is
    identity json_object_t; checked_hash varchar2(64); document json_object_t;
  begin
    checked_hash:=fingerprint(p_identity_json,p_format); -- Strict identity/family validation.
    identity:=json_object_t.parse(p_identity_json);
    if identity.get_string('object_type')<>'TABLE' then fail('Table contract requires a table identity.'); end if;
    document:=table_document(identity.get_string('object_name'),p_format);
    if json_hash(document)<>checked_hash then fail('Table changed during contract extraction.'); end if;
    return document.to_clob;
  end;

  function table_compatible(p_identity_json clob,p_format varchar2,
    p_expected_sha256 varchar2,p_contract clob) return boolean is
    source_doc json_object_t; target_doc json_object_t; identity json_object_t;
    source_cols json_array_t; target_cols json_array_t; projected json_array_t:=json_array_t();
    source_col json_object_t; target_col json_object_t; source_text clob; target_text clob;
    valid number; found boolean; checked_hash varchar2(64);
    type name_set is table of boolean index by varchar2(128); required_columns name_set;
    source_part json_object_t; target_part json_object_t;
    source_defaults json_object_t; target_defaults json_object_t;
    procedure project_lobs(source_owner in out json_object_t,target_owner in out json_object_t) is
      actual json_array_t; filtered json_array_t:=json_array_t(); item json_object_t;
    begin
      actual:=target_owner.get_array('lobs');
      for i in 0..actual.get_size-1 loop
        item:=treat(actual.get(i) as json_object_t);
        if required_columns.exists(item.get_string('column')) then filtered.append(item); end if;
      end loop;
      target_owner.put('lobs',filtered);
    end;
  begin
    if p_contract is null or dbms_lob.getlength(p_contract)>8388608 then fail('Table contract size limit.'); end if;
    select case when p_contract is json strict with unique keys then 1 else 0 end into valid from dual;
    if valid<>1 then fail('Invalid source table contract.'); end if;
    source_doc:=json_object_t.parse(p_contract);
    if p_expected_sha256 is null or json_hash(source_doc)<>p_expected_sha256 then fail('Unbound source table contract.'); end if;
    checked_hash:=fingerprint(p_identity_json,p_format);
    identity:=json_object_t.parse(p_identity_json);
    if identity.get_string('object_type')<>'TABLE' or source_doc.get_string('object_type')<>'TABLE'
      or source_doc.get_string('object_name')<>identity.get_string('object_name')
      or source_doc.get_string('format')<>p_format then fail('Table contract identity conflict.'); end if;
    target_doc:=table_document(identity.get_string('object_name'),p_format);
    if json_hash(target_doc)<>checked_hash then fail('Target table changed during comparison.'); end if;
    source_cols:=source_doc.get_array('columns'); target_cols:=target_doc.get_array('columns');
    for i in 0..source_cols.get_size-1 loop
      source_col:=treat(source_cols.get(i) as json_object_t); found:=false;
      required_columns(source_col.get_string('name')):=true;
      for k in 0..target_cols.get_size-1 loop
        target_col:=treat(target_cols.get(k) as json_object_t);
        if target_col.get_string('name')=source_col.get_string('name') then found:=true; exit; end if;
      end loop;
      if not found then return false; end if;
      -- Only these explicit compatibility exceptions are permitted. Everything
      -- else, including future LOB/partition defaults, remains source-bound.
      source_col.remove('nullable');
      source_cols.put(i,source_col,true);
    end loop;
    -- Filter authorized target-only columns without rearranging required ones:
    -- positional INSERT/SELECT semantics still belong to the table definition.
    for i in 0..target_cols.get_size-1 loop
      target_col:=treat(target_cols.get(i) as json_object_t);
      if required_columns.exists(target_col.get_string('name')) then
        target_col.remove('nullable'); projected.append(target_col);
      end if;
    end loop;
    source_doc.put('columns',source_cols); target_doc.put('columns',projected);
    project_lobs(source_doc,target_doc);
    if source_doc.has('partitioning') and target_doc.has('partitioning') then
      source_part:=source_doc.get_object('partitioning'); target_part:=target_doc.get_object('partitioning');
      source_defaults:=source_part.get_object('defaults'); target_defaults:=target_part.get_object('defaults');
      project_lobs(source_defaults,target_defaults);
      target_part.put('defaults',target_defaults); target_doc.put('partitioning',target_part);
    end if;
    source_text:=source_doc.to_clob; target_text:=target_doc.to_clob;
    select case when json_equal(source_text,target_text) then 1 else 0 end into valid from dual;
    dbms_lob.freetemporary(source_text); dbms_lob.freetemporary(target_text);
    return valid=1;
  exception when others then
    if dbms_lob.istemporary(source_text)=1 then dbms_lob.freetemporary(source_text); end if;
    if dbms_lob.istemporary(target_text)=1 then dbms_lob.freetemporary(target_text); end if;
    raise;
  end;

  function portable_query(p_text varchar2) return varchar2 is
    type token_rec is record(kind varchar2(1),value_text varchar2(32767),first_pos integer,last_pos integer);
    type token_list is table of token_rec index by pls_integer;
    tokens token_list; token_count integer:=0; pos integer:=1; first_pos integer;
    finish integer; text_len integer:=length(p_text); c varchar2(4 char); delimiter varchar2(4 char);
    owner_name varchar2(128):=sys_context('USERENV','CURRENT_USER');
    result varchar2(32767); copied integer:=1; n number;
    procedure add_token(kind varchar2,value_text varchar2 default null) is
    begin
      token_count:=token_count+1; tokens(token_count).kind:=kind;
      tokens(token_count).value_text:=value_text; tokens(token_count).first_pos:=first_pos;
      tokens(token_count).last_pos:=pos-1;
    end;
  begin
    -- Tokenize without changing literals, hints, comments, quoted identifiers
    -- or external owners. Only this schema's unambiguous object qualification
    -- is removed, in BOTH the definition reader and executable payload.
    while pos<=text_len loop
      first_pos:=pos; c:=substr(p_text,pos,1);
      if regexp_like(c,'[[:space:]]') then pos:=pos+1;
      elsif substr(p_text,pos,2)='--' then
        finish:=instr(p_text,chr(10),pos+2); pos:=case when finish=0 then text_len+1 else finish+1 end;
      elsif substr(p_text,pos,2)='/*' then
        finish:=instr(p_text,'*/',pos+2); if finish=0 then fail('Unterminated query comment.'); end if; pos:=finish+2;
      elsif (upper(c)='Q' and substr(p_text,pos+1,1)='''')
        or (upper(c)='N' and upper(substr(p_text,pos+1,1))='Q' and substr(p_text,pos+2,1)='''') then
        if upper(c)='N' then pos:=pos+1; end if;
        delimiter:=substr(p_text,pos+2,1);
        delimiter:=case delimiter when '[' then ']' when '{' then '}' when '(' then ')' when '<' then '>' else delimiter end;
        finish:=instr(p_text,delimiter||'''',pos+3);
        if finish=0 then fail('Unterminated query literal.'); end if;
        pos:=finish+2; add_token('V');
      elsif c in ('''','"') then
        delimiter:=c; pos:=pos+1;
        loop
          if pos>text_len then fail('Unterminated query token.'); end if;
          if substr(p_text,pos,1)=delimiter then
            pos:=pos+1; if substr(p_text,pos,1)=delimiter then pos:=pos+1; else exit; end if;
          else pos:=pos+1; end if;
        end loop;
        if delimiter='"' then add_token('I',replace(substr(p_text,first_pos+1,pos-first_pos-2),'""','"'));
        else add_token('V'); end if;
      elsif regexp_like(c,'[[:alpha:]_$#]') then
        pos:=pos+1;
        while pos<=text_len and regexp_like(substr(p_text,pos,1),'[[:alnum:]_$#]') loop pos:=pos+1; end loop;
        add_token('I',upper(substr(p_text,first_pos,pos-first_pos)));
      else pos:=pos+1; add_token(case when c='.' then 'D' else 'O' end);
      end if;
    end loop;
    for i in 1..token_count loop
      if tokens(i).kind='I' and tokens(i).value_text=owner_name then
        if i+2>token_count or tokens(i+1).kind<>'D' or tokens(i+2).kind<>'I' then
          fail('Query uses the source schema name as an alias or other identifier; explicit relocation required.'); end if;
        select count(*) into n from user_objects where object_name=tokens(i+2).value_text
          and object_type in ('TABLE','VIEW','MATERIALIZED VIEW','PACKAGE','FUNCTION','PROCEDURE','TYPE','SEQUENCE','SYNONYM');
        if n=0 or (i>1 and tokens(i-1).kind='D') then fail('Ambiguous source-schema query qualification.'); end if;
      end if;
    end loop;
    for i in 1..token_count loop
      if tokens(i).kind='I' and tokens(i).value_text=owner_name then
        result:=result||substr(p_text,copied,tokens(i).first_pos-copied)||
          substr(p_text,tokens(i).last_pos+1,tokens(i+1).first_pos-tokens(i).last_pos-1);
        copied:=tokens(i+1).last_pos+1;
      end if;
    end loop;
    return result||substr(p_text,copied);
  end;

  function mview_document(p_name varchar2,p_format varchar2) return json_object_t is
    m user_mviews%rowtype; j json_object_t:=json_object_t(); n number;
    key_method varchar2(30); trust_policy varchar2(30); metadata xmltype;
    aliases json_array_t:=json_array_t(); reduced_precision varchar2(1);
  begin
    select query_len into n from user_mviews where mview_name=p_name;
    if n is null or n>32760 then fail('Materialized-view query exceeds reader limit or is unavailable.'); end if;
    select * into m from user_mviews where mview_name=p_name;
    -- Bound the adapter to owned ROWID/COMPLEX, COMPLETE, demand-refreshed MVs.
    -- Scheduled/fast/remote and ordinary managed index contracts need their
    -- own dependency-aware adapters, not a deceptively partial hash.
    if m.build_mode not in ('IMMEDIATE','DEFERRED','PREBUILT') or m.refresh_mode<>'DEMAND'
      or m.refresh_method<>'COMPLETE' or m.updatable<>'N'
      or m.container_name<>p_name or m.use_no_index not in ('Y','N')
      or m.master_link is not null or m.master_rollback_seg is not null
      or m.update_log is not null or m.auto<>'NO'
      or m.on_query_computation<>'N' or m.concurrent_refresh_enabled<>'N'
      or m.evaluation_edition is not null or m.unusable_before is not null
      or m.unusable_beginning is not null then fail('Unsupported materialized-view policy.'); end if;
    select refresh_method into key_method from user_snapshots where name=p_name;
    if key_method not in ('ROWID','COMPLEX') then fail('Unsupported materialized-view refresh key.'); end if;
    select count(*) into n from user_refresh_children where name=p_name;
    if n>0 then fail('Materialized-view refresh groups require a separate adapter.'); end if;
    -- Automatic indexes are database-managed runtime tuning, not authored
    -- application objects. All other indexes still require explicit ownership.
    -- PREBUILT indexes belong to its independent TABLE/key-index artifacts.
    select count(*) into n from user_indexes where table_name=p_name and nvl(auto,'NO')<>'YES' and m.build_mode<>'PREBUILT';
    if n>0 then fail('Materialized-view indexes require a separate adapter.'); end if;
    select count(*) into n from user_dependencies where name=p_name and type='MATERIALIZED VIEW'
      and (referenced_link_name is not null or
        (referenced_owner<>sys_context('USERENV','CURRENT_USER') and referenced_owner<>'SYS'));
    if n>0 then fail('External materialized-view dependencies require an ownership contract.'); end if;
    -- UNKNOWN_TRUSTED_FD describes the last refresh, not current authored
    -- policy. It can stay N after ALTER ... USING TRUSTED until a refresh.
    metadata:=xmltype(dbms_metadata.get_sxml('MATERIALIZED_VIEW',p_name,
      sys_context('USERENV','CURRENT_USER')));
    select count(*),max(policy) into n,trust_policy from xmltable(
      xmlnamespaces(default 'http://xmlns.oracle.com/ku'),
      '/MATERIALIZED_VIEW/REFRESH/CONSTRAINTS' passing metadata
      columns policy varchar2(30) path '.');
    if n<>1 or trust_policy is null or trust_policy not in ('ENFORCED','TRUSTED') then
      fail('Materialized-view constraint-trust metadata is unavailable or unsupported.');
    end if;
    j.put('format',p_format); j.put('object_type','MATERIALIZED VIEW'); j.put('object_name',p_name);
    j.put('query',portable_query(m.query)); j.put('build_mode',m.build_mode);
    j.put('refresh_mode',m.refresh_mode); j.put('refresh_method',m.refresh_method);
    j.put('refresh_key',key_method); j.put('rewrite_enabled',m.rewrite_enabled);
    j.put('constraint_trust',trust_policy);
    j.put('use_no_index',m.use_no_index); j.put('default_collation',m.default_collation);
    if m.build_mode='PREBUILT' then
      select count(*),max(policy) into n,reduced_precision from xmltable(
        xmlnamespaces(default 'http://xmlns.oracle.com/ku'),
        '/MATERIALIZED_VIEW/ON_PREBUILT_TABLE/REDUCED_PRECISION' passing metadata
        columns policy varchar2(1) path '.');
      if n<>1 or nvl(reduced_precision,'?') not in ('Y','N') then fail('Unknown PREBUILT precision policy.'); end if;
      for c in (select name from xmltable(xmlnamespaces(default 'http://xmlns.oracle.com/ku'),
        '/MATERIALIZED_VIEW/COL_LIST/COL_LIST_ITEM' passing metadata
        columns position for ordinality,name varchar2(128) path 'NAME') order by position) loop
        if c.name is null then fail('Unavailable PREBUILT column alias.'); end if;
        aliases.append(c.name);
      end loop;
      if aliases.get_size=0 then fail('Unavailable PREBUILT column list.'); end if;
      j.put('storage_table',p_name); j.put('columns',aliases); j.put('reduced_precision',reduced_precision);
      -- Its independently versioned TABLE owns column/storage semantics.
    else j.put('storage_sha256',table_hash(p_name,p_format,true)); end if;
    -- Refresh times, staleness, row contents and compile state are runtime data.
    return j;
  end;

  function mview_hash(p_name varchar2,p_format varchar2) return varchar2 is
  begin return json_hash(mview_document(p_name,p_format)); end;

  function view_document(p_name varchar2,p_format varchar2) return json_object_t is
    v user_views%rowtype; n number; j json_object_t:=json_object_t();
    cols json_array_t:=json_array_t(); item json_object_t;
  begin
    -- TEXT_VC truncates at 4KB. Guard the LONG before reading the row.
    select text_length into n from user_views where view_name=p_name;
    if n is null or n>32760 then fail('View text exceeds reader limit or is unavailable.'); end if;
    select * into v from user_views where view_name=p_name;
    if v.view_type is not null or v.superview_name is not null
      or v.editioning_view='Y' or v.container_data='Y'
      or v.containers_default='YES' or v.container_map='YES'
      or v.extended_data_link='YES' or v.duality_view='YES' then
      fail('Unsupported view family.');
    end if;
    j.put('format',p_format); j.put('object_type','VIEW'); j.put('object_name',p_name);
    j.put('query',portable_query(v.text)); j.put('read_only',v.read_only);
    j.put('bequeath',v.bequeath); j.put('default_collation',v.default_collation);
    -- Explicit aliases are not necessarily present in the stored SELECT text.
    for c in (select column_name,hidden_column,collation from user_tab_cols
      where table_name=p_name order by column_id nulls last,internal_column_id) loop
      item:=json_object_t(); item.put('name',c.column_name);
      item.put('invisible',c.hidden_column); item.put('collation',c.collation); cols.append(item);
    end loop;
    if cols.get_size=0 then fail('View column metadata is unavailable.'); end if;
    j.put('columns',cols);
    return j;
  end;

  function view_hash(p_name varchar2,p_format varchar2) return varchar2 is
  begin
    return json_hash(view_document(p_name,p_format));
  end;

  function key_columns(p_name varchar2,p_table varchar2) return json_array_t is
    a json_array_t:=json_array_t(); j json_object_t;
  begin
    for r in (select column_name,position from user_cons_columns
      where constraint_name=p_name and table_name=p_table order by position) loop
      j:=json_object_t(); j.put('position',r.position); j.put('column_name',r.column_name); a.append(j);
    end loop;
    if a.get_size=0 then fail('Constraint column metadata unavailable.'); end if;
    return a;
  end;

  function text_index_policy(p_name varchar2) return json_object_t is
    result json_object_t:=json_object_t(); doc clob; metadata json_object_t;
    objects json_array_t:=json_array_t(); vals json_array_t:=json_array_t(); item json_object_t;
    rows_ sys_refcursor; class_ varchar2(128); object_ varchar2(128);
    attribute_ varchar2(128); value_ varchar2(4000); count_ number:=0;
  begin
    -- Optional Oracle Text views are resolved only for this explicitly supported
    -- domain family. No Text runtime counters or generated segment names enter it.
    execute immediate q'~select json_object('type' value idx_type,'subtype' value idx_sub_type,
      'language_column' value idx_language_column,'format_column' value idx_format_column,
      'charset_column' value idx_charset_column,'sync_type' value idx_sync_type,
      'sync_interval' value idx_sync_interval,'auto_opt_type' value idx_auto_opt_type,
      'maintenance_type' value idx_maintenance_type returning clob)
      from ctx_user_indexes where idx_name=:name~' into doc using p_name;
    metadata:=json_object_t.parse(doc);
    if metadata.get_string('type')<>'CONTEXT' or metadata.get_string('subtype')<>'TEXT'
      or metadata.get_string('sync_type')<>'MANUAL'
      or metadata.get_string('language_column') is not null
      or metadata.get_string('format_column') is not null
      or metadata.get_string('charset_column') is not null
      or metadata.get_string('sync_interval') is not null
      or metadata.get_string('auto_opt_type') is not null then
      fail('Unsupported Oracle Text synchronization or column policy.');
    end if;
    result.put('metadata',metadata);
    open rows_ for 'select ixo_class,ixo_object from ctx_user_index_objects where ixo_index_name=:n order by nlssort(ixo_class,''NLS_SORT=BINARY''),nlssort(ixo_object,''NLS_SORT=BINARY'')' using p_name;
    loop
      fetch rows_ into class_,object_; exit when rows_%notfound;
      if class_||':'||object_ not in ('DATASTORE:DIRECT_DATASTORE','FILTER:NULL_FILTER',
        'LEXER:BASIC_LEXER','SECTION_GROUP:NULL_SECTION_GROUP','STOPLIST:BASIC_STOPLIST',
        'STORAGE:BASIC_STORAGE','WORDLIST:BASIC_WORDLIST') then
        close rows_; fail('Unsupported Oracle Text preference family.');
      end if;
      item:=json_object_t(); item.put('class',class_); item.put('object',object_);
      objects.append(item); count_:=count_+1;
    end loop;
    close rows_;
    if count_<>7 then fail('Incomplete Oracle Text preference evidence.'); end if;
    result.put('objects',objects);
    -- BASIC_STORAGE segment clauses are physical target tuning. Logical stop
    -- words, lexer and wordlist attributes must remain exact, including defaults.
    open rows_ for 'select ixv_class,ixv_object,ixv_attribute,ixv_value from ctx_user_index_values where ixv_index_name=:n and ixv_class<>''STORAGE'' order by nlssort(ixv_class,''NLS_SORT=BINARY''),nlssort(ixv_object,''NLS_SORT=BINARY''),nlssort(ixv_attribute,''NLS_SORT=BINARY''),nlssort(ixv_value,''NLS_SORT=BINARY'')' using p_name;
    loop
      fetch rows_ into class_,object_,attribute_,value_; exit when rows_%notfound;
      item:=json_object_t(); item.put('class',class_); item.put('object',object_);
      item.put('attribute',attribute_); item.put('value',value_); vals.append(item);
    end loop;
    close rows_; result.put('values',vals); return result;
  exception when others then
    if rows_%isopen then close rows_; end if;
    raise;
  end;

  function index_definition(p_name varchar2,p_table varchar2) return json_object_t is
    j json_object_t:=json_object_t(); a json_array_t:=json_array_t(); col json_object_t;
    expr varchar2(32767); partition_policy json_object_t; partition_count number;
  begin
    for r in (select index_type,uniqueness,partitioned,visibility,compression,prefix_length,
      logging,table_owner,table_type,indexing,join_index,ityp_owner,ityp_name,parameters from user_indexes where index_name=p_name and table_name=p_table) loop
      if r.partitioned not in ('NO','YES') or r.table_owner<>sys_context('USERENV','CURRENT_USER') or r.table_type<>'TABLE'
        or r.join_index='YES'
        or r.index_type not in ('NORMAL','FUNCTION-BASED NORMAL','BITMAP','FUNCTION-BASED BITMAP','DOMAIN') then
        fail('Unsupported index family or partition policy.');
      end if;
      if r.index_type='DOMAIN' then
        if r.partitioned<>'NO' or r.ityp_owner<>'CTXSYS' or r.ityp_name<>'CONTEXT'
          or r.parameters is not null then fail('Unsupported Oracle Text parameters or domain family.'); end if;
        j.put('domain_owner_role','ORACLE_TEXT'); j.put('domain_type','CONTEXT');
        j.put('text_policy',text_index_policy(p_name));
      end if;
      if r.partitioned='YES' then
        partition_count:=0;
        for ip in (select locality,alignment,partitioning_type,subpartitioning_type
          from user_part_indexes where index_name=p_name and table_name=p_table) loop
          if ip.locality<>'LOCAL' or ip.partitioning_type<>'RANGE'
            or ip.subpartitioning_type<>'NONE' or ip.alignment not in ('PREFIXED','NON_PREFIXED') then
            fail('Unsupported index family or partition policy.');
          end if;
          partition_policy:=json_object_t();
          partition_policy.put('locality',ip.locality); partition_policy.put('alignment',ip.alignment);
          partition_policy.put('partitioning_type',ip.partitioning_type);
          partition_policy.put('subpartitioning_type',ip.subpartitioning_type);
          j.put('partition_policy',partition_policy); partition_count:=partition_count+1;
        end loop;
        if partition_count<>1 then fail('Index partition policy unavailable.'); end if;
      end if;
      j.put('index_type',r.index_type); j.put('uniqueness',r.uniqueness);
      j.put('visibility',r.visibility); j.put('compression',r.compression);
      j.put('prefix_length',r.prefix_length); j.put('logging',r.logging);
      j.put('indexing',r.indexing);
    end loop;
    if not j.has('index_type') then fail('Index missing or parent mismatch.'); end if;
    for r in (select column_position,column_name,descend from user_ind_columns
      where index_name=p_name and table_name=p_table order by column_position) loop
      expr:=null;
      begin
        -- LONG, not a truncated *_VC preview; oversized expressions fail closed.
        select column_expression into expr from user_ind_expressions
          where index_name=p_name and table_name=p_table and column_position=r.column_position;
      exception when no_data_found then null;
        when value_error then fail('Index expression exceeds supported size.');
      end;
      col:=json_object_t(); col.put('position',r.column_position); col.put('descend',r.descend);
      if expr is null then col.put('column_name',r.column_name);
      else
        if regexp_like(expr,
          '([[:alpha:]_$#][[:alnum:]_$#]*|"[^"]+")[[:space:]]*[.][[:space:]]*([[:alpha:]_$#][[:alnum:]_$#]*|"[^"]+")') then
          fail('Qualified index expressions require a separate adapter.');
        end if;
        col.put('expression',expr);
      end if;
      a.append(col);
    end loop;
    if a.get_size=0 then fail('Index column metadata unavailable.'); end if;
    j.put('columns',a);
    return j;
  end;

  function constraint_hash(p_name varchar2,p_table varchar2,p_type varchar2,p_format varchar2) return varchar2 is
    j json_object_t:=json_object_t(); cond varchar2(32767); found boolean:=false;
    ref_table varchar2(128);
  begin
    j.put('format',p_format); j.put('object_type',p_type);
    j.put('object_name',p_name); j.put('parent_name',p_table);
    for r in (select constraint_type,status,deferrable,deferred,validated,rely,delete_rule,
      r_owner,r_constraint_name,index_name,index_owner from user_constraints
      where constraint_name=p_name and table_name=p_table) loop
      found:=true;
      if r.constraint_type not in ('P','U','C','R')
        or (p_type='FOREIGN KEY' and r.constraint_type<>'R') then fail('Constraint family mismatch.'); end if;
      j.put('constraint_type',r.constraint_type); j.put('status',r.status);
      j.put('deferrable',r.deferrable); j.put('deferred',r.deferred);
      j.put('validated',r.validated); j.put('rely',r.rely);
      j.put('columns',key_columns(p_name,p_table));
      if r.constraint_type='C' then
        begin
          select search_condition into cond from user_constraints
            where constraint_name=p_name and table_name=p_table;
        exception when value_error then fail('Check condition exceeds supported size.'); end;
        if cond is null then fail('Check condition unavailable.'); end if;
        j.put('condition',cond);
      elsif r.constraint_type='R' then
        if r.r_owner<>sys_context('USERENV','CURRENT_USER') then fail('External foreign key requires authored ownership contract.'); end if;
        select table_name into ref_table from user_constraints where constraint_name=r.r_constraint_name;
        j.put('reference_table',ref_table);
        j.put('reference_columns',key_columns(r.r_constraint_name,ref_table));
        j.put('delete_rule',r.delete_rule);
      elsif r.index_name is not null then
        if r.index_owner<>sys_context('USERENV','CURRENT_USER') then fail('External backing index unsupported.'); end if;
        -- Generated backing names differ across environments; compare their definition.
        j.put('backing_index',index_definition(r.index_name,p_table));
      end if;
    end loop;
    if not found then fail('Constraint missing or parent mismatch.'); end if;
    return json_hash(j);
  end;

  function portable_job_action(p_action varchar2) return varchar2 is
    a varchar2(128); b varchar2(128); c varchar2(128); link_ varchar2(128);
    next_ binary_integer; n number;
  begin
    dbms_utility.name_tokenize(p_action,a,b,c,link_,next_);
    if link_ is not null or trim(substr(p_action,next_+1)) is not null then
      fail('Unsupported Scheduler action syntax.'); end if;
    if a=sys_context('USERENV','CURRENT_USER') and b is not null then a:=b; b:=c; c:=null; end if;
    if c is not null or a is null then fail('External Scheduler action requires an authored prerequisite.'); end if;
    select count(*) into n from user_procedures where object_name=a
      and ((b is null and object_type='PROCEDURE' and procedure_name is null)
        or (b is not null and object_type='PACKAGE' and procedure_name=b));
    if n=0 then fail('Scheduler action does not resolve to a local procedure.'); end if;
    select count(*) into n from user_arguments where position=0
      and ((b is null and package_name is null and object_name=a)
        or (b is not null and package_name=a and object_name=b));
    if n>0 then fail('Scheduler action resolves to a function rather than a procedure.'); end if;
    return dbms_assert.enquote_name(a,false)||case when b is not null then '.'||dbms_assert.enquote_name(b,false) end;
  end;

  function portable_job_arguments(p_name varchar2,p_action varchar2,p_count number) return json_array_t is
    result json_array_t:=json_array_t(); item json_object_t; n number:=0; policy_ varchar2(30);
  begin
    if p_action in ('"OCI_ADB_SCALE_PKG"."SCALE_UP"','"OCI_ADB_SCALE_PKG"."SCALE_DOWN"') and p_count=2 then
      policy_:='APP_CONFIG';
    elsif p_action='"OCI_RESOURCES_LOADER_PKG"."RUN"' and p_count=1 then policy_:='RESOURCE_LOG_LABEL';
    else fail('Scheduler arguments require an authored portable binding policy.'); end if;
    for arg in (select argument_position,argument_type,value,out_argument from user_scheduler_job_args
      where job_name=p_name order by argument_position) loop
      n:=n+1;
      if arg.argument_position<>n or arg.argument_type<>'UNDEFINED' or arg.out_argument is not null then
        fail('Unsupported Scheduler argument type or direction.'); end if;
      if (policy_='APP_CONFIG' and arg.value is not null)
        or (policy_='RESOURCE_LOG_LABEL' and (arg.value is null or arg.value<>'RESOURCES_PY')) then
        fail('Scheduler argument override requires explicit portable review.'); end if;
      item:=json_object_t(); item.put('position',n); item.put('binding',policy_);
      item.put('value',arg.value); result.append(item);
    end loop;
    if n<>p_count then fail('Scheduler argument binding evidence is incomplete.'); end if;
    return result;
  end;

  function job_document(p_name varchar2,p_type varchar2,p_format varchar2) return json_object_t is
    r user_scheduler_jobs%rowtype; j json_object_t:=json_object_t();
    qualified_name varchar2(600); follows_timezone boolean; database_role varchar2(30); action_ varchar2(4000);
    function stamp(v timestamp with time zone) return varchar2 is
    begin return to_char(v,'YYYY-MM-DD"T"HH24:MI:SS.FF6 TZR TZD','NLS_DATE_LANGUAGE=AMERICAN'); end;
  begin
    select * into r from user_scheduler_jobs where job_name=p_name;
    if r.job_style<>'REGULAR' or r.job_subname is not null or r.system='TRUE'
      or r.job_type not in ('PLSQL_BLOCK','STORED_PROCEDURE')
      or r.program_name is not null or r.program_owner is not null
      or r.schedule_name is not null or r.schedule_owner is not null
      or (nvl(r.number_of_arguments,0)<>0 and p_format<>'mc-artifact-definition-2')
      or r.schedule_type not in ('IMMEDIATE','ONCE','CALENDAR','PLSQL')
      or r.event_queue_name is not null or r.event_condition is not null
      or r.file_watcher_name is not null or r.file_watcher_owner is not null
      or r.credential_name is not null or r.credential_owner is not null
      or r.connect_credential_name is not null or r.connect_credential_owner is not null
      or r.destination is not null or r.destination_owner is not null
      or nvl(r.number_of_destinations,0)>1 or r.instance_id is not null
      or r.has_constraints='TRUE' then
      fail('Unsupported Scheduler job policy: '||p_name);
    end if;
    -- Version 1 retains raw action semantics. Version 2 explicitly normalizes
    -- local stored-procedure identifiers and reviewed target-config bindings.
    j.put('format',p_format); j.put('object_type',p_type); j.put('object_name',p_name);
    action_:=r.job_action;
    if p_format='mc-artifact-definition-2' then
      if r.job_type<>'STORED_PROCEDURE' then fail('Definition v2 requires a stored-procedure job.'); end if;
      action_:=portable_job_action(action_);
      j.put('number_of_arguments',nvl(r.number_of_arguments,0));
      if nvl(r.number_of_arguments,0)>0 then
        j.put('arguments',portable_job_arguments(p_name,action_,r.number_of_arguments));
      end if;
    end if;
    j.put('job_style',r.job_style); j.put('job_type',r.job_type); j.put('job_action',action_);
    j.put('schedule_type',r.schedule_type); j.put('repeat_interval',r.repeat_interval);
    qualified_name:=dbms_assert.enquote_name(sys_context('USERENV','CURRENT_USER'),false)||'.'||dbms_assert.enquote_name(p_name,false);
    dbms_scheduler.get_attribute(qualified_name,'follow_default_timezone',follows_timezone);
    j.put('follow_default_timezone',follows_timezone);
    dbms_scheduler.get_attribute(qualified_name,'database_role',database_role);
    if database_role is null or database_role<>'PRIMARY' then
      fail('Unsupported Scheduler database role: '||p_name);
    end if;
    j.put('database_role',database_role);
    j.put('start_date',stamp(r.start_date)); j.put('end_date',stamp(r.end_date));
    j.put('job_class',r.job_class); j.put('job_priority',r.job_priority); j.put('job_weight',r.job_weight);
    j.put('auto_drop',r.auto_drop); j.put('restartable',r.restartable);
    j.put('restart_on_recovery',r.restart_on_recovery); j.put('restart_on_failure',r.restart_on_failure);
    j.put('max_runs',r.max_runs); j.put('max_failures',r.max_failures);
    j.put('schedule_limit',to_char(r.schedule_limit)); j.put('max_run_duration',to_char(r.max_run_duration));
    j.put('logging_level',r.logging_level); j.put('store_output',r.store_output);
    j.put('stop_on_window_close',r.stop_on_window_close); j.put('instance_stickiness',r.instance_stickiness);
    j.put('raise_events',r.raise_events); j.put('allow_runs_in_restricted_mode',r.allow_runs_in_restricted_mode);
    j.put('fail_on_script_error',r.fail_on_script_error); j.put('nls_env',r.nls_env);
    -- ENABLED/STATE/counters/next run are target runtime state. Comments and
    -- creator identities are not executable behavior and never enter a revision.
    return j;
  end;

  function job_hash(p_name varchar2,p_type varchar2,p_format varchar2) return varchar2 is
  begin return json_hash(job_document(p_name,p_type,p_format)); end;

  function has_qualified_identifier(p_text varchar2,p_owner varchar2) return boolean is
    pos integer:=1; last_pos integer:=length(p_text); finish integer;
    c varchar2(4 char); delimiter varchar2(4 char); kind varchar2(1);
    previous_identifier boolean:=false; qualified_dot boolean:=false;
    identifier_value varchar2(32767); start_pos integer;
    function next_kind return varchar2 is
    begin
      identifier_value:=null;
      loop
        if pos>last_pos then return 'E'; end if;
        c:=substr(p_text,pos,1);
        if regexp_like(c,'[[:space:]]') then pos:=pos+1;
        elsif substr(p_text,pos,2)='--' then
          finish:=instr(p_text,chr(10),pos+2);
          if finish=0 then pos:=last_pos+1; else pos:=finish+1; end if;
        elsif substr(p_text,pos,2)='/*' then
          finish:=instr(p_text,'*/',pos+2);
          if finish=0 then fail('Unterminated expression comment.'); end if;
          pos:=finish+2;
        else exit; end if;
      end loop;
      if (upper(c)='Q' and substr(p_text,pos+1,1)='''')
        or (upper(c)='N' and upper(substr(p_text,pos+1,1))='Q' and substr(p_text,pos+2,1)='''') then
        if upper(c)='N' then pos:=pos+1; end if;
        delimiter:=substr(p_text,pos+2,1);
        delimiter:=case delimiter when '[' then ']' when '{' then '}' when '(' then ')' when '<' then '>' else delimiter end;
        finish:=instr(p_text,delimiter||'''',pos+3);
        if finish=0 then fail('Unterminated expression literal.'); end if;
        pos:=finish+2; return 'V';
      elsif c in ('''','"') then
        delimiter:=c; pos:=pos+1;
        start_pos:=pos;
        loop
          if pos>last_pos then fail('Unterminated expression literal or identifier.'); end if;
          if substr(p_text,pos,1)=delimiter then
            pos:=pos+1;
            if substr(p_text,pos,1)=delimiter then pos:=pos+1; else exit; end if;
          else pos:=pos+1; end if;
        end loop;
        if delimiter='"' then
          identifier_value:=replace(substr(p_text,start_pos,pos-start_pos-1),'""','"'); return 'I';
        else return 'V'; end if;
      elsif regexp_like(c,'[[:alpha:]_$#]') then
        start_pos:=pos;
        pos:=pos+1;
        while pos<=last_pos and regexp_like(substr(p_text,pos,1),'[[:alnum:]_$#]') loop pos:=pos+1; end loop;
        identifier_value:=upper(substr(p_text,start_pos,pos-start_pos));
        return 'I';
      else
        pos:=pos+1;
        if c='.' then return 'D'; else return 'O'; end if;
      end if;
    end;
  begin
    if p_text is null then return false; end if;
    loop
      kind:=next_kind;
      exit when kind='E';
      if qualified_dot and kind='I' then return true; end if;
      qualified_dot:=previous_identifier and kind='D';
      previous_identifier:=kind='I' and (p_owner is null or identifier_value=p_owner);
    end loop;
    return false;
  end;

  function graph_document(p_name varchar2,p_format varchar2) return json_object_t is
    g user_property_graphs%rowtype;
    j json_object_t:=json_object_t(); item json_object_t;
    elements json_array_t:=json_array_t(); keys json_array_t; labels json_array_t;
    properties json_array_t:=json_array_t(); relationships json_array_t:=json_array_t();
    expression varchar2(32767); n number; expected number;
    metadata clob; graph_xml xmltype; element_xml xmltype;
  begin
    select * into g from user_property_graphs where graph_name=p_name;
    if g.graph_mode is null or g.graph_mode not in ('TRUSTED','ENFORCED')
      or nvl(g.inmemory,'?')<>'NO' or nvl(g.allows_mixed_types,'?')<>'NO' then
      fail('Unsupported property-graph mode, In-Memory or mixed-type policy.');
    end if;
    -- USER_PG_KEYS and USER_PG_EDGE_RELATIONSHIPS have no ordinal. Ordered
    -- metadata lists supply it; cross-check every identity against the dictionary.
    metadata:=dbms_metadata.get_xml('PROPERTY_GRAPH',p_name,sys_context('USERENV','CURRENT_USER'));
    graph_xml:=xmltype(metadata);
    select count(*) into n from xmltable('/ROWSET/ROW/PROPERTY_GRAPH_T' passing graph_xml
      columns major number path 'VERS_MAJOR', minor number path 'VERS_MINOR',
        owner_name varchar2(128) path 'SCHEMA_OBJ/OWNER_NAME', graph_name varchar2(128) path 'SCHEMA_OBJ/NAME')
      where major=1 and minor=0 and owner_name=sys_context('USERENV','CURRENT_USER') and graph_name=p_name;
    if n<>1 then fail('Unknown or mismatched property-graph metadata identity/version.'); end if;
    j.put('format',p_format); j.put('object_type','PROPERTY GRAPH'); j.put('object_name',p_name);
    j.put('mode',g.graph_mode); j.put('inmemory',g.inmemory); j.put('mixed_types',g.allows_mixed_types);
    for e in (select * from user_pg_elements where graph_name=p_name
      order by nlssort(element_name,'NLS_SORT=BINARY')) loop
      if e.object_owner<>sys_context('USERENV','CURRENT_USER')
        or e.element_kind is null or e.element_kind not in ('VERTEX','EDGE') then
        fail('External or unknown property-graph element requires an ownership contract.');
      end if;
      keys:=json_array_t();
      select fragment into element_xml from xmltable(
        '/ROWSET/ROW/PROPERTY_GRAPH_T/VERTEX_LIST/VERTEX_LIST_ITEM | /ROWSET/ROW/PROPERTY_GRAPH_T/EDGE_LIST/EDGE_LIST_ITEM'
        passing graph_xml columns element_name varchar2(128) path 'EL_NAME',
          element_kind varchar2(30) path 'local-name(.)', fragment xmltype path '.')
        where element_name=e.element_name and element_kind=e.element_kind||'_LIST_ITEM';
      for k in (select * from xmltable('/*/EL_KEY_LIST/EL_KEY_LIST_ITEM' passing element_xml
        columns ordinal for ordinality, column_name varchar2(128) path 'NAME') order by ordinal) loop
        select count(*) into n from user_pg_keys where graph_name=p_name and element_name=e.element_name
          and column_name=k.column_name;
        if n<>1 then fail('Property-graph key metadata disagrees with dictionary.'); end if;
        keys.append(k.column_name);
      end loop;
      select count(*) into n from user_pg_keys where graph_name=p_name and element_name=e.element_name;
      if keys.get_size=0 or keys.get_size<>n then fail('Property-graph key metadata is incomplete.'); end if;
      if e.element_kind='EDGE' then
        expected:=0;
        for r in (select 'SOURCE' edge_end,t.ordinal mapping_ordinal,t.vertex_name,t.edge_column,t.vertex_column from xmltable('/*/EL_SRC_VR_LIST/EL_SRC_VR_LIST_ITEM'
          passing element_xml columns ordinal for ordinality, vertex_name varchar2(128) path 'VR_NAME',
            edge_column varchar2(128) path 'VR_E_COL', vertex_column varchar2(128) path 'VR_V_COL') t
          union all
          select 'DESTINATION' edge_end,t.ordinal mapping_ordinal,t.vertex_name,t.edge_column,t.vertex_column from xmltable('/*/EL_DST_VR_LIST/EL_DST_VR_LIST_ITEM'
          passing element_xml columns ordinal for ordinality, vertex_name varchar2(128) path 'VR_NAME',
            edge_column varchar2(128) path 'VR_E_COL', vertex_column varchar2(128) path 'VR_V_COL') t
          order by 1,2) loop
          select count(*) into n from user_pg_edge_relationships where graph_name=p_name
            and edge_tab_name=e.element_name and edge_end=r.edge_end and vertex_tab_name=r.vertex_name
            and edge_col_name=r.edge_column and vertex_col_name=r.vertex_column;
          if n<>1 then fail('Property-graph endpoint metadata disagrees with dictionary.'); end if;
          item:=json_object_t(); item.put('edge',e.element_name); item.put('end',r.edge_end);
          item.put('ordinal',r.mapping_ordinal); item.put('vertex',r.vertex_name);
          item.put('edge_column',r.edge_column); item.put('vertex_column',r.vertex_column);
          relationships.append(item); expected:=expected+1;
        end loop;
        select count(*) into n from user_pg_edge_relationships where graph_name=p_name and edge_tab_name=e.element_name;
        if expected<2 or expected<>n then fail('Property-graph endpoint metadata is incomplete.'); end if;
      end if;
      item:=json_object_t(); item.put('element',e.element_name); item.put('kind',e.element_kind);
      item.put('owner_role','APPLICATION_SCHEMA'); item.put('object',e.object_name);
      labels:=json_array_t();
      for l in (select label_name from user_pg_element_labels where graph_name=p_name and element_name=e.element_name
        order by nlssort(label_name,'NLS_SORT=BINARY')) loop labels.append(l.label_name); end loop;
      if labels.get_size=0 then fail('Property-graph label metadata is unavailable.'); end if;
      item.put('keys',keys); item.put('labels',labels); elements.append(item);
    end loop;
    if elements.get_size=0 then fail('Property-graph element metadata is unavailable.'); end if;
    select count(*) into n from xmltable(
      '/ROWSET/ROW/PROPERTY_GRAPH_T/VERTEX_LIST/VERTEX_LIST_ITEM | /ROWSET/ROW/PROPERTY_GRAPH_T/EDGE_LIST/EDGE_LIST_ITEM'
      passing graph_xml columns element_name varchar2(128) path 'EL_NAME');
    if elements.get_size<>n then fail('Property-graph element metadata is incomplete.'); end if;
    for l in (select * from user_pg_label_properties where graph_name=p_name
      order by nlssort(label_name,'NLS_SORT=BINARY'),property_order) loop
      item:=json_object_t(); item.put('label',l.label_name); item.put('property',l.property_name);
      item.put('ordinal',l.property_order); item.put('data_type',l.data_type);
      item.put('data_length',l.data_length); item.put('precision',l.data_precision);
      item.put('scale',l.data_scale); item.put('char_length',l.data_char_length);
      item.put('charset',l.character_set_name); item.put('collation',l.collation);
      properties.append(item);
    end loop;
    j.put('label_properties',properties); properties:=json_array_t();
    for p in (select element_name,property_name,column_name from user_pg_prop_definitions where graph_name=p_name
      order by nlssort(element_name,'NLS_SORT=BINARY'),nlssort(property_name,'NLS_SORT=BINARY')) loop
      begin
        select column_expr into expression from user_pg_prop_definitions
          where graph_name=p_name and element_name=p.element_name and property_name=p.property_name;
      exception when value_error then fail('Property-graph expression exceeds reader limit.'); end;
      if p.column_name is null and expression is null then fail('Property-graph expression metadata is unavailable.'); end if;
      if has_qualified_identifier(expression) then
        fail('Qualified property-graph expressions require a separate adapter.');
      end if;
      item:=json_object_t(); item.put('element',p.element_name); item.put('property',p.property_name);
      item.put('column',p.column_name); item.put('expression',expression); properties.append(item);
    end loop;
    j.put('elements',elements); j.put('expressions',properties); j.put('relationships',relationships);
    -- Graph rows, internal IDs, comments and dictionary creation clocks are not
    -- executable definitions. Backing table/key changes have separate artifacts.
    if dbms_lob.istemporary(metadata)=1 then dbms_lob.freetemporary(metadata); end if;
    return j;
  exception when others then
    if dbms_lob.istemporary(metadata)=1 then dbms_lob.freetemporary(metadata); end if;
    raise;
  end;

  function graph_hash(p_name varchar2,p_format varchar2) return varchar2 is
  begin return json_hash(graph_document(p_name,p_format)); end;

  function fingerprint(p_identity_json clob,p_format varchar2) return varchar2 is
    j json_object_t; e json_element_t; keys json_key_list;
    nm varchar2(128); typ varchar2(64); parent_name varchar2(128); n number; text_value varchar2(32767);
    settings user_plsql_object_settings%rowtype;
    function field(p_key varchar2) return varchar2 is v json_element_t;
    begin
      v:=j.get(p_key);
      if v is null then fail('Missing identity field.'); end if;
      if not v.is_string then fail('Identity field must be text.'); end if;
      return j.get_string(p_key);
    end;
  begin
    if p_format is null or p_format not in ('mc-artifact-definition-1','mc-artifact-definition-2') then fail('Unsupported format.'); end if;
    select case when p_identity_json is json strict with unique keys then 1 else 0 end into n from dual;
    if n<>1 or p_identity_json is null or dbms_lob.getlength(p_identity_json)>2000 then fail('Invalid identity JSON.'); end if;
    j:=json_object_t.parse(p_identity_json); keys:=j.get_keys;
    if keys.count<>4 then fail('Identity requires exactly four fields.'); end if;
    if field('owner_role') is null or field('owner_role')<>'APPLICATION_SCHEMA' then fail('Unsupported owner role.'); end if;
    if field('object_name') is null or lengthb(field('object_name'))>128
      or field('object_type') is null or lengthb(field('object_type'))>64 then fail('Invalid identity length.'); end if;
    nm:=field('object_name'); typ:=field('object_type');
    if p_format='mc-artifact-definition-2' and typ not in ('JOB','SCHEDULER JOB') then fail('Definition v2 is reserved for stored-procedure jobs.'); end if;
    e:=j.get('parent_name');
    if e is null then fail('Missing parent identity.'); end if;
    if typ not in ('SEQUENCE','PACKAGE','PACKAGE BODY','PROCEDURE','FUNCTION','TYPE','TYPE BODY','TRIGGER','TABLE','VIEW','MATERIALIZED VIEW','CONSTRAINT','FOREIGN KEY','INDEX','JOB','SCHEDULER JOB','PROPERTY GRAPH') then fail('Unsupported object type: '||typ); end if;
    if typ in ('CONSTRAINT','FOREIGN KEY','INDEX') then
      if not e.is_string then fail('Key/index requires table parent.'); end if;
      parent_name:=field('parent_name');
      if parent_name is null or lengthb(parent_name)>128 then fail('Invalid parent identity.'); end if;
      if typ<>'INDEX' then return constraint_hash(nm,parent_name,typ,p_format); end if;
      j:=index_definition(nm,parent_name);
      j.put('format',p_format); j.put('object_type',typ); j.put('object_name',nm); j.put('parent_name',parent_name);
      return json_hash(j);
    elsif not e.is_null then fail('Object parent must be null.'); end if;

    if typ='TABLE' then return table_hash(nm,p_format); end if;
    if typ='VIEW' then return view_hash(nm,p_format); end if;
    if typ='MATERIALIZED VIEW' then return mview_hash(nm,p_format); end if;
    if typ='PROPERTY GRAPH' then return graph_hash(nm,p_format); end if;
    if typ in ('JOB','SCHEDULER JOB') then return job_hash(nm,typ,p_format); end if;

    j:=json_object_t();
    j.put('format',p_format); j.put('object_type',typ); j.put('object_name',nm);
    if typ in ('PACKAGE','PACKAGE BODY','PROCEDURE','FUNCTION','TYPE','TYPE BODY','TRIGGER') then
      select * into settings from user_plsql_object_settings where name=nm and type=typ;
      if typ='TRIGGER' then
        -- Enabled/disabled is authored behavior, unlike Scheduler runtime state.
        select status into text_value from user_triggers where trigger_name=nm;
      end if;
      return compiled_code_hash(nm,typ,p_format,code_hash(nm,typ),settings,text_value);
    end if;

    sequence_policy(j,nm);
    text_value:=j.to_string;
    return lower(rawtohex(dbms_crypto.hash(utl_i18n.string_to_raw(text_value,'AL32UTF8'),dbms_crypto.hash_sh256)));
  exception when no_data_found then
    fail('Object is missing or unreadable.'); return null;
  end;

  function job_sql(p_name varchar2,p_type varchar2,p_format varchar2,p_expected varchar2) return clob is
    j json_object_t; result clob; name_sql varchar2(300):=dbms_assert.enquote_name(p_name,false);
    action_text varchar2(4000); logging_sql varchar2(100); events_sql varchar2(2000);
    argument_count number:=0; args json_array_t; arg json_object_t;
    function quoted(v varchar2) return varchar2 is
    begin if v is null then return 'NULL'; end if; return ''''||replace(v,'''','''''')||''''; end;
    function bool_sql(k varchar2) return varchar2 is v varchar2(10):=upper(j.get_string(k));
    begin
      if v not in ('TRUE','FALSE') or v is null then raise_application_error(-20865,'Unsupported Scheduler boolean: '||k); end if;
      return v;
    end;
    function date_sql(k varchar2) return varchar2 is v varchar2(100):=j.get_string(k);
    begin
      if v is null then return 'NULL'; end if;
      return 'to_timestamp_tz('||quoted(v)||',''YYYY-MM-DD"T"HH24:MI:SS.FF6 TZR TZD'',''NLS_DATE_LANGUAGE=AMERICAN'')';
    end;
    function event_mask_sql return varchar2 is
      v varchar2(4000):=j.get_string('raise_events'); token varchar2(100); expression varchar2(2000):='0'; i integer:=1;
    begin
      if v is null then return null; end if;
      loop
        token:=trim(regexp_substr(v,'[^,]+',1,i)); exit when token is null;
        if token not in ('JOB_STARTED','JOB_SUCCEEDED','JOB_FAILED','JOB_BROKEN','JOB_COMPLETED','JOB_STOPPED',
          'JOB_SCH_LIM_REACHED','JOB_DISABLED','JOB_CHAIN_STALLED','JOB_OVER_MAX_DUR','JOB_ALL_EVENTS','JOB_RUN_COMPLETED') then
          raise_application_error(-20865,'Unsupported Scheduler event policy'); end if;
        -- JOB_OVER_MAX_DUR is automatic, not an admissible raise_events mask bit.
        if token<>'JOB_OVER_MAX_DUR' then expression:=expression||'+dbms_scheduler.'||lower(token); end if;
        i:=i+1;
      end loop;
      return expression;
    end;
    procedure append_text(v varchar2) is begin dbms_lob.writeappend(result,length2(v),v); end;
    procedure attribute(k varchar2,v varchar2) is
    begin append_text('dbms_scheduler.set_attribute('||quoted(name_sql)||','||quoted(k)||','||v||');'||chr(10)); end;
    procedure string_attribute(k varchar2) is
    begin
      if j.get_string(k) is null then
        append_text('dbms_scheduler.set_attribute_null('||quoted(name_sql)||','||quoted(k)||');'||chr(10));
      else attribute(k,quoted(j.get_string(k))); end if;
    end;
  begin
    j:=job_document(p_name,p_type,p_format);
    if json_hash(j)<>p_expected then raise_application_error(-20865,'Scheduler job changed during extraction'); end if;
    if j.get_string('schedule_type')='PLSQL' then
      raise_application_error(-20865,'PLSQL Scheduler schedule requires a separate relocation adapter'); end if;
    action_text:=j.get_string('job_action');
    if p_format='mc-artifact-definition-2' then argument_count:=j.get_number('number_of_arguments'); end if;
    if action_text is null or has_qualified_identifier(action_text,sys_context('USERENV','CURRENT_USER')) then
      raise_application_error(-20865,'Schema-bound Scheduler action requires a relocation adapter'); end if;
    if nvl(j.get_number('job_weight'),-1)<>1 or nvl(j.get_string('fail_on_script_error'),'FALSE')<>'FALSE' then
      raise_application_error(-20865,'Unsupported Scheduler weight/script policy'); end if;
    logging_sql:=case j.get_string('logging_level') when 'OFF' then 'dbms_scheduler.logging_off'
      when 'RUNS' then 'dbms_scheduler.logging_runs' when 'FAILED RUNS' then 'dbms_scheduler.logging_failed_runs'
      when 'FULL' then 'dbms_scheduler.logging_full' end;
    if logging_sql is null then raise_application_error(-20865,'Unsupported Scheduler logging policy'); end if;
    events_sql:=event_mask_sql;
    dbms_lob.createtemporary(result,true);
    append_text('declare n number; begin'||chr(10)||
      'select count(*) into n from user_scheduler_running_jobs where job_name='||quoted(p_name)||';'||chr(10)||
      'if n<>0 then raise_application_error(-20865,''Target Scheduler job is running; no job changes applied''); end if;'||chr(10)||
      'select count(*) into n from user_scheduler_jobs where job_name='||quoted(p_name)||
      ' and (enabled<>''FALSE'' or job_style<>''REGULAR'' or system<>''FALSE'' or job_subname is not null or job_type not in (''PLSQL_BLOCK'',''STORED_PROCEDURE'')'||
      ' or program_name is not null or program_owner is not null or schedule_name is not null or schedule_owner is not null or nvl(number_of_arguments,0)<>'||to_char(argument_count,'FM90')||
      ' or schedule_type not in (''IMMEDIATE'',''ONCE'',''CALENDAR'',''PLSQL'') or event_queue_name is not null or event_condition is not null'||
      ' or file_watcher_name is not null or file_watcher_owner is not null or credential_name is not null or credential_owner is not null'||
      ' or connect_credential_name is not null or connect_credential_owner is not null or destination is not null or destination_owner is not null'||
      ' or nvl(number_of_destinations,0)>1 or instance_id is not null or has_constraints=''TRUE'' or nvl(job_weight,1)<>1 or nvl(fail_on_script_error,''FALSE'')<>''FALSE'');'||chr(10)||
      'if n<>0 then raise_application_error(-20865,''Target Scheduler job must be disabled and compatible; no job changes applied''); end if;'||chr(10)||
      'select count(*) into n from user_scheduler_jobs where job_name='||quoted(p_name)||';'||chr(10)||
      'if n=0 then dbms_scheduler.create_job(job_name=>'||quoted(name_sql)||',job_type=>'||quoted(j.get_string('job_type'))||
      ',job_action=>'||quoted(action_text)||',start_date=>'||date_sql('start_date')||',repeat_interval=>'||quoted(j.get_string('repeat_interval'))||
      ',number_of_arguments=>'||to_char(argument_count,'FM90')||',end_date=>'||date_sql('end_date')||',job_class=>'||quoted(j.get_string('job_class'))||',enabled=>false,auto_drop=>'||bool_sql('auto_drop')||'); end if;'||chr(10));
    string_attribute('job_type'); string_attribute('job_action'); string_attribute('repeat_interval');
    if argument_count>0 then
      args:=j.get_array('arguments');
      for i in 0..args.get_size-1 loop
        arg:=treat(args.get(i) as json_object_t);
        append_text('dbms_scheduler.set_job_argument_value('||quoted(name_sql)||','||
          to_char(arg.get_number('position'),'FM90')||','||quoted(arg.get_string('value'))||');'||chr(10));
      end loop;
    end if;
    if j.get_string('start_date') is null then string_attribute('start_date'); else attribute('start_date',date_sql('start_date')); end if;
    if j.get_string('end_date') is null then string_attribute('end_date'); else attribute('end_date',date_sql('end_date')); end if;
    string_attribute('job_class'); string_attribute('job_priority');
    string_attribute('max_runs'); string_attribute('max_failures'); string_attribute('schedule_limit'); string_attribute('max_run_duration');
    string_attribute('nls_env'); attribute('logging_level',logging_sql);
    for k in (select column_value key_name from table(sys.odcivarchar2list('auto_drop','restartable','restart_on_recovery','restart_on_failure',
      'store_output','stop_on_window_close','instance_stickiness','allow_runs_in_restricted_mode','follow_default_timezone'))) loop
      attribute(k.key_name,bool_sql(k.key_name));
    end loop;
    if events_sql is null then string_attribute('raise_events'); else attribute('raise_events',events_sql); end if;
    string_attribute('database_role');
    append_text('end;'||chr(10)||'/'||chr(10));
    return result;
  exception when others then
    if dbms_lob.istemporary(result)=1 then dbms_lob.freetemporary(result); end if;
    raise;
  end;

  function view_sql(p_name varchar2,p_format varchar2,p_expected varchar2) return clob is
    j json_object_t; cols json_array_t; col json_object_t; statement_sql clob; result clob;
    query_text varchar2(32767); policy varchar2(30); piece varchar2(3000 char); offset_pos integer:=1;
    procedure append_text(p_text varchar2) is
    begin dbms_lob.writeappend(result,length2(p_text),p_text); end;
  begin
    j:=view_document(p_name,p_format);
    if json_hash(j)<>p_expected then raise_application_error(-20865,'View changed during extraction'); end if;
    query_text:=j.get_string('query');
    if has_qualified_identifier(query_text,sys_context('USERENV','CURRENT_USER')) then
      raise_application_error(-20865,'Schema-bound view requires a relocation adapter'); end if;
    statement_sql:=to_clob('CREATE OR REPLACE VIEW '||dbms_assert.enquote_name(p_name,false)||' (');
    cols:=j.get_array('columns');
    for i in 0..cols.get_size-1 loop
      col:=treat(cols.get(i) as json_object_t);
      if col.get_string('invisible')<>'NO' then raise_application_error(-20865,'Invisible view columns require a separate adapter'); end if;
      if i>0 then statement_sql:=statement_sql||','; end if;
      statement_sql:=statement_sql||dbms_assert.enquote_name(col.get_string('name'),false);
    end loop;
    policy:=j.get_string('bequeath');
    if policy is null or policy not in ('DEFINER','CURRENT_USER') then raise_application_error(-20865,'Unsupported bequeath policy'); end if;
    statement_sql:=statement_sql||') DEFAULT COLLATION '||dbms_assert.enquote_name(j.get_string('default_collation'),false)||
      ' BEQUEATH '||policy||' AS '||query_text;
    -- USER_VIEWS.TEXT retains WITH READ ONLY. Do not append a second clause.
    dbms_lob.createtemporary(result,true);
    append_text('declare statement_sql clob; begin dbms_lob.createtemporary(statement_sql,true);'||chr(10));
    while offset_pos<=dbms_lob.getlength(statement_sql) loop
      piece:=dbms_lob.substr(statement_sql,3000,offset_pos);
      append_text('dbms_lob.writeappend(statement_sql,'||to_char(length2(piece),'FM99990')||','''||replace(piece,'''','''''')||''');'||chr(10));
      offset_pos:=offset_pos+length2(piece);
    end loop;
    append_text('execute immediate statement_sql; dbms_lob.freetemporary(statement_sql);'||chr(10)||
      'exception when others then if dbms_lob.istemporary(statement_sql)=1 then dbms_lob.freetemporary(statement_sql); end if; raise; end;'||chr(10)||'/'||chr(10));
    dbms_lob.freetemporary(statement_sql);
    return result;
  exception when others then
    if dbms_lob.istemporary(statement_sql)=1 then dbms_lob.freetemporary(statement_sql); end if;
    if dbms_lob.istemporary(result)=1 then dbms_lob.freetemporary(result); end if;
    raise;
  end;

  function mview_sql(p_name varchar2,p_format varchar2,p_expected varchar2) return clob is
    j json_object_t; storage_doc json_object_t; cols json_array_t; col json_object_t; lobs json_array_t;
    query_text varchar2(32767); statement_sql clob; result clob; contract_text clob;
    prebuilt boolean; storage_hash varchar2(64); table_ident json_object_t:=json_object_t();
    piece varchar2(3000 char); offset_pos integer:=1;
    function identifier(v varchar2) return varchar2 is
    begin return dbms_assert.enquote_name(v,false); end;
    procedure append_text(v varchar2) is
    begin dbms_lob.writeappend(result,length2(v),v); end;
  begin
    j:=mview_document(p_name,p_format);
    prebuilt:=j.get_string('build_mode')='PREBUILT';
    if json_hash(j)<>p_expected then raise_application_error(-20865,'Materialized view changed during extraction'); end if;
    storage_doc:=table_document(p_name,p_format,true);
    storage_hash:=json_hash(storage_doc);
    if not prebuilt and storage_hash<>j.get_string('storage_sha256') then
      raise_application_error(-20865,'Materialized-view storage changed during extraction'); end if;
    lobs:=storage_doc.get_array('lobs');
    if not prebuilt and (storage_doc.has('partitioning') or lobs.get_size<>0
      or nvl(storage_doc.get_string('temporary'),'?')<>'N'
      or nvl(storage_doc.get_string('dependencies'),'?')<>'DISABLED'
      or nvl(storage_doc.get_string('row_movement'),'?')<>'DISABLED'
      or nvl(storage_doc.get_string('read_only'),'?')<>'NO') then
      raise_application_error(-20865,'Materialized-view storage requires a separate adapter'); end if;
    query_text:=j.get_string('query');
    if has_qualified_identifier(query_text,sys_context('USERENV','CURRENT_USER')) then
      raise_application_error(-20865,'Schema-bound materialized view requires a relocation adapter'); end if;
    statement_sql:=to_clob('CREATE MATERIALIZED VIEW '||identifier(p_name)||' (');
    if prebuilt then cols:=j.get_array('columns'); else cols:=storage_doc.get_array('columns'); end if;
    for i in 0..cols.get_size-1 loop
      if prebuilt then
        if i>0 then statement_sql:=statement_sql||','; end if;
        statement_sql:=statement_sql||identifier(cols.get_string(i)); continue;
      end if;
      col:=treat(cols.get(i) as json_object_t);
      if nvl(col.get_string('invisible'),'?')<>'NO' or nvl(col.get_string('virtual'),'?')<>'NO'
        or col.has('identity') or col.get_string('default') is not null then
        raise_application_error(-20865,'Materialized-view column policy requires a separate adapter'); end if;
      if i>0 then statement_sql:=statement_sql||','; end if;
      statement_sql:=statement_sql||identifier(col.get_string('name'));
    end loop;
    statement_sql:=statement_sql||') DEFAULT COLLATION '||identifier(j.get_string('default_collation'));
    if nvl(j.get_string('rewrite_enabled'),'?') not in ('Y','N') then raise_application_error(-20865,'Unknown materialized-view rewrite policy'); end if;
    statement_sql:=statement_sql||case when prebuilt then
      ' ON PREBUILT TABLE '||case j.get_string('reduced_precision') when 'Y' then 'WITH' else 'WITHOUT' end||' REDUCED PRECISION'
      else ' BUILD '||j.get_string('build_mode') end||
      case j.get_string('use_no_index') when 'Y' then ' USING NO INDEX' else ' USING INDEX' end||
      ' REFRESH COMPLETE ON DEMAND'||case j.get_string('refresh_key') when 'ROWID' then ' WITH ROWID' end||' USING '||
      j.get_string('constraint_trust')||' CONSTRAINTS'||case j.get_string('rewrite_enabled') when 'Y' then ' ENABLE' else ' DISABLE' end||
      ' QUERY REWRITE AS '||query_text;
    dbms_lob.createtemporary(result,true);
    append_text('declare statement_sql clob; storage_contract clob; n number; begin'||chr(10)||
      'if sys_context(''USERENV'',''CURRENT_SCHEMA'')<>sys_context(''USERENV'',''CURRENT_USER'') then '||
      'raise_application_error(-20865,''Target schema context must match the executing owner; no changes applied''); end if;'||chr(10)||
      'select count(*) into n from user_objects where object_name='''||replace(p_name,'''','''''')||''' and namespace=1;'||chr(10));
    if prebuilt then
      append_text('if n<>1 then raise_application_error(-20865,''PREBUILT requires its existing target table; no changes applied''); end if;'||chr(10)||
        'select count(*) into n from user_mviews where mview_name='''||replace(p_name,'''','''''')||''';'||chr(10)||
        'if n<>0 then raise_application_error(-20865,''Existing target MV blocks attach-only payload; no changes applied''); end if;'||chr(10)||
        'dbms_lob.createtemporary(storage_contract,true);'||chr(10));
      contract_text:=storage_doc.to_clob;
      while offset_pos<=dbms_lob.getlength(contract_text) loop
        piece:=dbms_lob.substr(contract_text,3000,offset_pos);
        append_text('dbms_lob.writeappend(storage_contract,'||to_char(length2(piece),'FM99990')||','''||replace(piece,'''','''''')||''');'||chr(10));
        offset_pos:=offset_pos+length2(piece);
      end loop;
      offset_pos:=1;
      table_ident.put('owner_role','APPLICATION_SCHEMA'); table_ident.put('object_type','TABLE');
      table_ident.put('object_name',p_name); table_ident.put_null('parent_name');
      append_text('begin if not mc_artifact_definition_pkg.table_compatible('''||replace(table_ident.to_string,'''','''''')||''','''||
        replace(p_format,'''','''''')||''','''||storage_hash||''',storage_contract) then '||
        'raise_application_error(-20865,''Incompatible PREBUILT target storage; no changes applied''); end if;'||chr(10)||
        'exception when others then if sqlcode=-20862 then raise_application_error(-20865,''Unsupported PREBUILT target storage; no changes applied''); else raise; end if; end;'||chr(10));
    else
      append_text('if n<>0 then raise_application_error(-20865,''Existing target name blocks CREATE-only materialized-view payload; no changes applied''); end if;'||chr(10));
    end if;
    append_text('dbms_lob.createtemporary(statement_sql,true);'||chr(10));
    while offset_pos<=dbms_lob.getlength(statement_sql) loop
      piece:=dbms_lob.substr(statement_sql,3000,offset_pos);
      append_text('dbms_lob.writeappend(statement_sql,'||to_char(length2(piece),'FM99990')||','''||replace(piece,'''','''''')||''');'||chr(10));
      offset_pos:=offset_pos+length2(piece);
    end loop;
    append_text('execute immediate statement_sql; dbms_lob.freetemporary(statement_sql);'||chr(10)||
      'if dbms_lob.istemporary(storage_contract)=1 then dbms_lob.freetemporary(storage_contract); end if;'||chr(10)||
      'exception when others then if dbms_lob.istemporary(statement_sql)=1 then dbms_lob.freetemporary(statement_sql); end if;'||chr(10)||
      'if dbms_lob.istemporary(storage_contract)=1 then dbms_lob.freetemporary(storage_contract); end if; raise; end;'||chr(10)||'/'||chr(10));
    if prebuilt and table_hash(p_name,p_format)<>storage_hash then
      raise_application_error(-20865,'PREBUILT source storage changed during extraction'); end if;
    if dbms_lob.istemporary(contract_text)=1 then dbms_lob.freetemporary(contract_text); end if;
    dbms_lob.freetemporary(statement_sql); return result;
  exception when others then
    if dbms_lob.istemporary(contract_text)=1 then dbms_lob.freetemporary(contract_text); end if;
    if dbms_lob.istemporary(statement_sql)=1 then dbms_lob.freetemporary(statement_sql); end if;
    if dbms_lob.istemporary(result)=1 then dbms_lob.freetemporary(result); end if;
    raise;
  end;

  function table_sql(p_name varchar2,p_format varchar2,p_expected varchar2) return clob is
    j json_object_t; columns_json json_array_t; lobs json_array_t;
    col json_object_t; lob_json json_object_t; identity_json json_object_t;
    partition_json json_object_t; partition_defaults json_object_t; layout_json json_object_t;
    partition_keys json_array_t; partition_key_type varchar2(128);
    statement_sql clob; result clob; typ varchar2(128); value_text varchar2(32767);
    piece varchar2(3000 char); offset_pos integer:=1; temporary_table boolean;
    function integer_sql(v number) return varchar2 is s varchar2(100);
    begin
      s:=to_char(v,'FM99999999999999999999999999999999999999','NLS_NUMERIC_CHARACTERS=''.,''');
      if v is null or v<>trunc(v) or not regexp_like(s,'^-?[0-9]+$','c') then
        raise_application_error(-20865,'Invalid table policy integer'); end if;
      return s;
    end;
    function identifier(v varchar2) return varchar2 is
    begin return dbms_assert.enquote_name(v,false); end;
    procedure append_text(v varchar2) is
    begin dbms_lob.writeappend(result,length2(v),v); end;
    function datatype(c json_object_t) return varchar2 is
      t varchar2(128):=c.get_string('type'); p number:=c.get_number('precision'); s number:=c.get_number('scale');
    begin
      if c.get_string('type_mod') is not null then raise_application_error(-20865,'Column type modifier requires a separate adapter'); end if;
      if t in ('VARCHAR2','CHAR') then
        if c.get_string('char_used') not in ('B','C') then raise_application_error(-20865,'Unknown character length policy'); end if;
        return t||'('||integer_sql(case c.get_string('char_used') when 'C' then c.get_number('char_length') else c.get_number('length') end)||
          case c.get_string('char_used') when 'C' then ' CHAR)' else ' BYTE)' end;
      elsif t in ('NVARCHAR2','NCHAR') then return t||'('||integer_sql(c.get_number('char_length'))||')';
      elsif t in ('RAW','UROWID') then return t||'('||integer_sql(c.get_number('length'))||')';
      elsif t='NUMBER' then
        if p is null and s is null then return t; end if;
        return t||'('||case when p is null then '*' else integer_sql(p) end||case when s is not null then ','||integer_sql(s) end||')';
      elsif t='FLOAT' then return t||case when p is not null then '('||integer_sql(p)||')' end;
      elsif t in ('DATE','BINARY_FLOAT','BINARY_DOUBLE','CLOB','NCLOB','BLOB','LONG','LONG RAW','ROWID','BOOLEAN')
        or regexp_like(t,'^TIMESTAMP\([0-9]+\)( WITH (LOCAL )?TIME ZONE)?$','c')
        or regexp_like(t,'^INTERVAL YEAR\([0-9]+\) TO MONTH$','c')
        or regexp_like(t,'^INTERVAL DAY\([0-9]+\) TO SECOND\([0-9]+\)$','c') then return t;
      end if;
      raise_application_error(-20865,'Column datatype requires a separate adapter: '||t);
    end;
    function identity_options(v json_object_t,p_on_null varchar2) return varchar2 is
    begin
      if v.get_string('generation_type') not in ('ALWAYS','BY DEFAULT','BY DEFAULT ON NULL')
        or v.get_string('scale_flag')<>'N' or v.get_string('extend_flag')<>'N'
        or v.get_string('sharded_flag')<>'N' or v.get_string('session_flag')<>'N' or v.get_string('keep_value')<>'N'
        or v.get_string('cycle_flag') not in ('Y','N') or v.get_string('order_flag') not in ('Y','N') then
        raise_application_error(-20865,'Identity requires a separate scalable/session/keep adapter'); end if;
      -- Oracle records BY DEFAULT ON NULL as GENERATION_TYPE=BY DEFAULT
      -- plus the column's DEFAULT_ON_NULL flag, not always in the type label.
      return ' GENERATED '||v.get_string('generation_type')||
        case when v.get_string('generation_type')='BY DEFAULT' and p_on_null='YES' then ' ON NULL' end||
        ' AS IDENTITY (START WITH '||integer_sql(v.get_number('start_with'))||
        ' INCREMENT BY '||integer_sql(v.get_number('increment_by'))||' MINVALUE '||integer_sql(v.get_number('min_value'))||
        ' MAXVALUE '||integer_sql(v.get_number('max_value'))||case v.get_string('cycle_flag') when 'Y' then ' CYCLE' else ' NOCYCLE' end||
        case v.get_string('order_flag') when 'Y' then ' ORDER' else ' NOORDER' end||
        case when v.get_number('cache_size')=0 then ' NOCACHE' else ' CACHE '||integer_sql(v.get_number('cache_size')) end||')';
    end;
  begin
    j:=table_document(p_name,p_format);
    if json_hash(j)<>p_expected then raise_application_error(-20865,'Table changed during extraction'); end if;
    if j.has('partitioning') then
      partition_json:=j.get_object('partitioning');
      if not partition_json.has('initial_layout') then
        raise_application_error(-20865,'Partitioned table creation requires an explicit INITIAL metadata contract'); end if;
      layout_json:=partition_json.get_object('initial_layout'); partition_keys:=partition_json.get_array('keys');
      if partition_json.get_string('type')<>'RANGE' or partition_keys.get_size<>1
        or partition_keys.get_string(0)<>layout_json.get_string('key')
        or nvl(regexp_replace(upper(partition_json.get_string('interval')),'[[:space:]]',''),'?')
          <>'NUMTOYMINTERVAL(1,''MONTH'')' then
        raise_application_error(-20865,'Partition routing differs from authored INITIAL monthly layout'); end if;
      partition_defaults:=partition_json.get_object('defaults');
      if nvl(partition_defaults.get_string('indexing'),'?')<>'ON'
        or nvl(partition_defaults.get_string('read_only'),'?') not in ('NO','NONE') then
        raise_application_error(-20865,'Partition defaults require a separate INITIAL adapter'); end if;
      columns_json:=j.get_array('columns');
      for i in 0..columns_json.get_size-1 loop
        col:=treat(columns_json.get(i) as json_object_t);
        if col.get_string('name')=layout_json.get_string('key') then partition_key_type:=col.get_string('type'); end if;
      end loop;
      if partition_key_type is null or not regexp_like(partition_key_type,'^TIMESTAMP\([0-9]+\)$','c') then
        raise_application_error(-20865,'Authored INITIAL layout requires a plain TIMESTAMP partition key'); end if;
    end if;
    temporary_table:=j.get_string('temporary')='Y';
    if j.get_string('temporary') not in ('N','Y') then
      raise_application_error(-20865,'Unknown temporary-table policy'); end if;
    if temporary_table and (nvl(j.get_string('duration'),'?') not in ('SYS$TRANSACTION','SYS$SESSION')
      or j.get_string('dependencies')<>'DISABLED' or j.get_string('row_movement')<>'DISABLED'
      or j.get_string('read_only')<>'NO') then
      raise_application_error(-20865,'Temporary table storage requires a separate adapter'); end if;
    -- Existing tables are never replaced/altered by this payload. Missing-column
    -- reconciliation and authored storage migrations retain separate contracts.
    statement_sql:=to_clob('CREATE '||case when temporary_table then 'GLOBAL TEMPORARY ' end||'TABLE '||identifier(p_name)||' ('); columns_json:=j.get_array('columns');
    for i in 0..columns_json.get_size-1 loop
      col:=treat(columns_json.get(i) as json_object_t); typ:=datatype(col);
      if i>0 then statement_sql:=statement_sql||','; end if;
      statement_sql:=statement_sql||identifier(col.get_string('name'))||' '||typ;
      if col.get_string('collation') is not null then statement_sql:=statement_sql||' COLLATE '||identifier(col.get_string('collation')); end if;
      if col.get_string('invisible')='YES' then statement_sql:=statement_sql||' INVISIBLE'; end if;
      value_text:=col.get_string('default');
      if col.has('identity') then
        identity_json:=col.get_object('identity'); statement_sql:=statement_sql||identity_options(identity_json,col.get_string('default_on_null'));
      elsif col.get_string('virtual')='YES' then
        if value_text is null then raise_application_error(-20865,'Missing virtual column expression'); end if;
        statement_sql:=statement_sql||' GENERATED ALWAYS AS ('||value_text||') VIRTUAL';
      elsif value_text is not null then
        statement_sql:=statement_sql||' DEFAULT'||case when col.get_string('default_on_null')='YES' then ' ON NULL'||
          case when col.get_string('default_on_null_upd')='YES' then ' FOR INSERT AND UPDATE' end end||' '||value_text;
      end if;
      -- DATA_DEFAULT includes whitespace before its following constraint. Do
      -- not add another delimiter to those authenticated expression bytes.
      if col.get_string('nullable')='N' and not col.has('identity') and col.get_string('default_on_null')<>'YES' then
        if value_text is not null and col.get_string('virtual')<>'YES'
          and not regexp_like(substr(value_text,-1),'[[:space:]]','c') then
          raise_application_error(-20865,'Non-null default needs a separate constraint/column adapter'); end if;
        statement_sql:=statement_sql||case when value_text is not null and col.get_string('virtual')<>'YES' then '' else ' ' end||'NOT NULL';
        value_text:=null;
      end if;
    end loop;
    statement_sql:=statement_sql||') DEFAULT COLLATION '||identifier(j.get_string('default_collation'));
    if temporary_table then
      statement_sql:=statement_sql||' ON COMMIT '||case j.get_string('duration') when 'SYS$SESSION' then 'PRESERVE' else 'DELETE' end||' ROWS';
    else
    if j.get_string('dependencies') not in ('ENABLED','DISABLED') or j.get_string('row_movement') not in ('ENABLED','DISABLED')
      or (not j.has('partitioning') and j.get_string('read_only') not in ('YES','NO'))
      or (j.has('partitioning') and nvl(j.get_string('read_only'),'?')<>'N/A') then
      raise_application_error(-20865,'Unknown table row policy'); end if;
    statement_sql:=statement_sql||case j.get_string('dependencies') when 'ENABLED' then ' ROWDEPENDENCIES' else ' NOROWDEPENDENCIES' end||
      case j.get_string('row_movement') when 'ENABLED' then ' ENABLE ROW MOVEMENT' else ' DISABLE ROW MOVEMENT' end;
    end if;
    if j.has('partitioning') then lobs:=partition_defaults.get_array('lobs');
    else lobs:=j.get_array('lobs'); end if;
    for i in 0..lobs.get_size-1 loop
      lob_json:=treat(lobs.get(i) as json_object_t);
      -- Extended VARCHAR2 is implemented by an internal LOB. Oracle rejects
      -- STORE AS for that logical character column (ORA-14692). Keep its full
      -- derived policy in the fingerprint, but emit only the character type.
      -- Accept only the dictionary policy reproduced by ordinary CREATE here;
      -- a different policy must not silently disappear from the payload.
      for k in 0..columns_json.get_size-1 loop
        col:=treat(columns_json.get(k) as json_object_t);
        exit when col.get_string('name')=lob_json.get_string('column');
      end loop;
      if col.get_string('name')<>lob_json.get_string('column') then
        raise_application_error(-20865,'LOB column is missing from the table contract'); end if;
      if col.get_string('type')='VARCHAR2' and col.get_number('length')>4000 then
        if temporary_table
          or nvl(lob_json.get_string('securefile'),'?')<>'YES'
          or nvl(lob_json.get_string('in_row'),'?')<>'YES'
          or nvl(lob_json.get_number('max_inline'),-1)<>4000
          or nvl(lob_json.get_string('cache'),'?')<>'YES'
          or nvl(lob_json.get_string('logging'),'?')<>'YES'
          or nvl(lob_json.get_string('compression'),'?')<>'NO'
          or nvl(lob_json.get_string('deduplication'),'?')<>'NO'
          or nvl(lob_json.get_string('retention_type'),'?')<>'DEFAULT'
          or lob_json.get_number('retention_value') is not null then
          raise_application_error(-20865,'Extended character LOB policy requires a separate adapter'); end if;
        continue;
      end if;
      if temporary_table then
        -- Global temporary LOBs use BasicFile storage on this supported
        -- contract. Undo-derived retention seconds are never copied.
        if nvl(lob_json.get_string('securefile'),'?')<>'NO'
          or nvl(lob_json.get_string('in_row'),'?')<>'YES'
          or lob_json.get_number('max_inline')<>4000
          -- Oracle derives temporary BasicFile logging from the cache mode.
          -- Do not emit a permanent-LOB LOGGING clause for a temporary LOB.
          or nvl(lob_json.get_string('logging'),'?')<>
            case lob_json.get_string('cache') when 'YES' then 'YES' else 'NO' end
          or nvl(lob_json.get_string('compression'),'?')<>'NONE'
          or nvl(lob_json.get_string('deduplication'),'?')<>'NONE'
          or nvl(lob_json.get_string('cache'),'?') not in ('YES','NO','CACHEREADS') then
          raise_application_error(-20865,'Temporary BasicFile policy requires a separate adapter'); end if;
        statement_sql:=statement_sql||' LOB ('||identifier(lob_json.get_string('column'))||') STORE AS BASICFILE ('||
          'ENABLE STORAGE IN ROW 4000'||
          case lob_json.get_string('cache') when 'YES' then ' CACHE' when 'CACHEREADS' then ' CACHE READS' else ' NOCACHE' end||')';
        continue;
      end if;
      if lob_json.get_string('securefile')<>'YES' or lob_json.get_string('in_row') not in ('YES','NO') then
        raise_application_error(-20865,'Unknown SecureFile policy'); end if;
      statement_sql:=statement_sql||' LOB ('||identifier(lob_json.get_string('column'))||') STORE AS SECUREFILE ('||
        case lob_json.get_string('in_row') when 'YES' then 'ENABLE STORAGE IN ROW '||integer_sql(lob_json.get_number('max_inline')) else 'DISABLE STORAGE IN ROW' end;
      case lob_json.get_string('cache')
        when 'YES' then statement_sql:=statement_sql||' CACHE';
        when 'NO' then statement_sql:=statement_sql||' NOCACHE';
        when 'CACHEREADS' then statement_sql:=statement_sql||' CACHE READS';
        else raise_application_error(-20865,'Unknown SecureFile cache policy');
      end case;
      if lob_json.get_string('logging') not in ('YES','NO') then raise_application_error(-20865,'Unknown SecureFile logging policy'); end if;
      statement_sql:=statement_sql||case lob_json.get_string('logging') when 'YES' then ' LOGGING' else ' NOLOGGING' end;
      value_text:=lob_json.get_string('compression');
      if value_text='NO' then statement_sql:=statement_sql||' NOCOMPRESS';
      elsif value_text in ('LOW','MEDIUM','HIGH') then statement_sql:=statement_sql||' COMPRESS '||value_text;
      else raise_application_error(-20865,'Unknown SecureFile compression policy'); end if;
      value_text:=lob_json.get_string('deduplication');
      if value_text not in ('LOB','NO') then raise_application_error(-20865,'Unknown SecureFile deduplication policy'); end if;
      statement_sql:=statement_sql||case value_text when 'LOB' then ' DEDUPLICATE' else ' KEEP_DUPLICATES' end;
      value_text:=lob_json.get_string('retention_type');
      if value_text='DEFAULT' then statement_sql:=statement_sql||' RETENTION';
      elsif value_text in ('AUTO','NONE') then statement_sql:=statement_sql||' RETENTION '||value_text;
      elsif value_text='MIN' then statement_sql:=statement_sql||' RETENTION MIN '||integer_sql(lob_json.get_number('retention_value'));
      else raise_application_error(-20865,'SecureFile retention requires a separate adapter'); end if;
      statement_sql:=statement_sql||')';
    end loop;
    if j.has('partitioning') then
      -- Preserve authenticated interval text after strict monthly validation.
      -- No live HIGH_VALUE expression,
      -- source partition name, storage override or runtime row is evaluated.
      statement_sql:=statement_sql||' PARTITION BY RANGE ('||identifier(layout_json.get_string('key'))||
        ') INTERVAL ('||partition_json.get_string('interval')||') (PARTITION '||identifier(layout_json.get_string('name'))||
        ' VALUES LESS THAN (TIMESTAMP '''||layout_json.get_string('before')||' 00:00:00''))';
    end if;
    if not temporary_table and not j.has('partitioning') then
      statement_sql:=statement_sql||case j.get_string('read_only') when 'YES' then ' READ ONLY' else ' READ WRITE' end;
    end if;
    if dbms_lob.getlength(statement_sql)>8388608 then raise_application_error(-20865,'Table payload size limit'); end if;
    dbms_lob.createtemporary(result,true);
    append_text('declare statement_sql clob; n number; begin'||chr(10)||
      'select count(*) into n from user_objects where object_name='''||replace(p_name,'''','''''')||''' and namespace=1;'||chr(10)||
      'if n<>0 then raise_application_error(-20865,''Existing target name blocks CREATE-only table payload; no table changes applied''); end if;'||chr(10)||
      'dbms_lob.createtemporary(statement_sql,true);'||chr(10));
    while offset_pos<=dbms_lob.getlength(statement_sql) loop
      piece:=dbms_lob.substr(statement_sql,3000,offset_pos);
      append_text('dbms_lob.writeappend(statement_sql,'||to_char(length2(piece),'FM99990')||','''||replace(piece,'''','''''')||''');'||chr(10));
      offset_pos:=offset_pos+length2(piece);
    end loop;
    append_text('execute immediate statement_sql; dbms_lob.freetemporary(statement_sql);'||chr(10)||
      'exception when others then if dbms_lob.istemporary(statement_sql)=1 then dbms_lob.freetemporary(statement_sql); end if; raise; end;'||chr(10)||'/'||chr(10));
    dbms_lob.freetemporary(statement_sql); return result;
  exception when others then
    if dbms_lob.istemporary(statement_sql)=1 then dbms_lob.freetemporary(statement_sql); end if;
    if dbms_lob.istemporary(result)=1 then dbms_lob.freetemporary(result); end if;
    raise;
  end;

  function graph_sql(p_name varchar2,p_format varchar2,p_expected varchar2) return clob is
    j json_object_t; elements json_array_t; relationships json_array_t;
    properties json_array_t; expressions json_array_t; keys json_array_t; labels json_array_t;
    element json_object_t; mapping json_object_t; property json_object_t; expression json_object_t;
    statement_sql clob; result clob; piece varchar2(3000 char); offset_pos integer:=1;
    first_element boolean; first_property boolean; found_expression boolean;
    vertex_name varchar2(128); edge_columns varchar2(32767); vertex_columns varchar2(32767);
    mapping_count integer; expression_text varchar2(32767);
    function identifier(v varchar2) return varchar2 is
    begin return dbms_assert.enquote_name(v,false); end;
    procedure append_text(v varchar2) is
    begin dbms_lob.writeappend(result,length2(v),v); end;
  begin
    -- Render only the authenticated logical snapshot. Never replay Oracle's
    -- physical graph metadata or source-schema-qualified DDL.
    j:=graph_document(p_name,p_format);
    if json_hash(j)<>p_expected then raise_application_error(-20865,'Property graph changed during extraction'); end if;
    elements:=j.get_array('elements'); relationships:=j.get_array('relationships');
    properties:=j.get_array('label_properties'); expressions:=j.get_array('expressions');
    statement_sql:=to_clob('CREATE OR REPLACE PROPERTY GRAPH '||identifier(p_name));
    for kind_number in 1..2 loop
      first_element:=true;
      for i in 0..elements.get_size-1 loop
        element:=treat(elements.get(i) as json_object_t);
        if element.get_string('kind')=case kind_number when 1 then 'VERTEX' else 'EDGE' end then
          if first_element then
            statement_sql:=statement_sql||case kind_number when 1 then ' VERTEX TABLES (' else ' EDGE TABLES (' end;
            first_element:=false;
          else statement_sql:=statement_sql||','; end if;
          statement_sql:=statement_sql||identifier(element.get_string('object'))||' AS '||identifier(element.get_string('element'))||' KEY (';
          keys:=element.get_array('keys');
          for k in 0..keys.get_size-1 loop
            if k>0 then statement_sql:=statement_sql||','; end if;
            statement_sql:=statement_sql||identifier(keys.get_string(k));
          end loop;
          statement_sql:=statement_sql||')';
          if kind_number=2 then
            for end_number in 1..2 loop
              vertex_name:=null; edge_columns:=null; vertex_columns:=null; mapping_count:=0;
              for r in 0..relationships.get_size-1 loop
                mapping:=treat(relationships.get(r) as json_object_t);
                if mapping.get_string('edge')=element.get_string('element')
                  and mapping.get_string('end')=case end_number when 1 then 'SOURCE' else 'DESTINATION' end then
                  mapping_count:=mapping_count+1;
                  if mapping.get_number('ordinal')<>mapping_count or
                    (vertex_name is not null and vertex_name<>mapping.get_string('vertex')) then
                    raise_application_error(-20865,'Inconsistent property-graph endpoint mapping'); end if;
                  vertex_name:=mapping.get_string('vertex');
                  if mapping_count>1 then edge_columns:=edge_columns||','; vertex_columns:=vertex_columns||','; end if;
                  edge_columns:=edge_columns||identifier(mapping.get_string('edge_column'));
                  vertex_columns:=vertex_columns||identifier(mapping.get_string('vertex_column'));
                end if;
              end loop;
              if mapping_count=0 then raise_application_error(-20865,'Missing property-graph endpoint mapping'); end if;
              statement_sql:=statement_sql||case end_number when 1 then ' SOURCE' else ' DESTINATION' end||
                ' KEY ('||edge_columns||') REFERENCES '||identifier(vertex_name)||' ('||vertex_columns||')';
            end loop;
          end if;
          labels:=element.get_array('labels');
          for l in 0..labels.get_size-1 loop
            statement_sql:=statement_sql||' LABEL '||identifier(labels.get_string(l)); first_property:=true;
            for p in 0..properties.get_size-1 loop
              property:=treat(properties.get(p) as json_object_t);
              if property.get_string('label')=labels.get_string(l) then
                if first_property then statement_sql:=statement_sql||' PROPERTIES ('; first_property:=false;
                else statement_sql:=statement_sql||','; end if;
                found_expression:=false;
                for x in 0..expressions.get_size-1 loop
                  expression:=treat(expressions.get(x) as json_object_t);
                  if expression.get_string('element')=element.get_string('element')
                    and expression.get_string('property')=property.get_string('property') then
                    if found_expression then raise_application_error(-20865,'Ambiguous property-graph expression'); end if;
                    found_expression:=true; expression_text:=expression.get_string('expression');
                    if expression_text is null then expression_text:=identifier(expression.get_string('column')); end if;
                    statement_sql:=statement_sql||expression_text||' AS '||identifier(property.get_string('property'));
                  end if;
                end loop;
                if not found_expression then raise_application_error(-20865,'Missing property-graph expression'); end if;
              end if;
            end loop;
            if first_property then statement_sql:=statement_sql||' NO PROPERTIES'; else statement_sql:=statement_sql||')'; end if;
          end loop;
        end if;
      end loop;
      if not first_element then statement_sql:=statement_sql||')';
      elsif kind_number=1 then raise_application_error(-20865,'Property graph has no vertex elements'); end if;
    end loop;
    statement_sql:=statement_sql||' OPTIONS ('||j.get_string('mode')||' MODE, DISALLOW MIXED PROPERTY TYPES)';
    if dbms_lob.getlength(statement_sql)>8388608 then raise_application_error(-20865,'Property-graph payload size limit'); end if;
    dbms_lob.createtemporary(result,true);
    append_text('declare statement_sql clob; begin dbms_lob.createtemporary(statement_sql,true);'||chr(10));
    while offset_pos<=dbms_lob.getlength(statement_sql) loop
      piece:=dbms_lob.substr(statement_sql,3000,offset_pos);
      append_text('dbms_lob.writeappend(statement_sql,'||to_char(length2(piece),'FM99990')||','''||replace(piece,'''','''''')||''');'||chr(10));
      offset_pos:=offset_pos+length2(piece);
    end loop;
    append_text('execute immediate statement_sql; dbms_lob.freetemporary(statement_sql);'||chr(10)||
      'exception when others then if dbms_lob.istemporary(statement_sql)=1 then dbms_lob.freetemporary(statement_sql); end if; raise; end;'||chr(10)||'/'||chr(10));
    dbms_lob.freetemporary(statement_sql); return result;
  exception when others then
    if dbms_lob.istemporary(statement_sql)=1 then dbms_lob.freetemporary(statement_sql); end if;
    if dbms_lob.istemporary(result)=1 then dbms_lob.freetemporary(result); end if;
    raise;
  end;

  function sequence_sql(p_name varchar2,p_format varchar2,p_expected varchar2) return clob is
    s user_sequences%rowtype; j json_object_t:=json_object_t(); ddl varchar2(32767);
    options varchar2(2000); name_sql varchar2(300):=dbms_assert.enquote_name(p_name,false);
    function integer_sql(p_value number) return varchar2 is v varchar2(100);
    begin
      v:=to_char(p_value,'FM99999999999999999999999999999999999999','NLS_NUMERIC_CHARACTERS=''.,''');
      if p_value is null or p_value<>trunc(p_value) or not regexp_like(v,'^-?[0-9]+$','c') then
        raise_application_error(-20865,'Invalid sequence integer'); end if;
      return v;
    end;
    function quote_sql(p_value varchar2) return varchar2 is
    begin return ''''||replace(p_value,'''','''''')||''''; end;
  begin
    select * into s from user_sequences where sequence_name=p_name;
    j.put('format',p_format); j.put('object_type','SEQUENCE'); j.put('object_name',p_name);
    sequence_values(j,s);
    if json_hash(j)<>p_expected then raise_application_error(-20865,'Sequence changed during extraction'); end if;
    if nvl(s.scale_flag,'?')<>'N' or nvl(s.extend_flag,'?')<>'N' or nvl(s.sharded_flag,'?')<>'N'
      or nvl(s.session_flag,'?')<>'N' or nvl(s.keep_value,'?')<>'N'
      or nvl(s.cycle_flag,'?') not in ('Y','N') or nvl(s.order_flag,'?') not in ('Y','N') then
      raise_application_error(-20865,'Sequence requires a separate scalable/session/keep adapter'); end if;
    options:=' NOKEEP INCREMENT BY '||integer_sql(s.increment_by)||
      case s.cycle_flag when 'Y' then ' CYCLE' else ' NOCYCLE' end||
      case s.order_flag when 'Y' then ' ORDER' else ' NOORDER' end||
      case when s.cache_size=0 then ' NOCACHE' else ' CACHE '||integer_sql(s.cache_size) end;
    -- Never export LAST_NUMBER, restart or drop an existing sequence. Missing
    -- sequences use the same deterministic bound default as ordinary CREATE.
    ddl:='CREATE SEQUENCE '||name_sql||' MINVALUE '||integer_sql(s.min_value)||
      ' MAXVALUE '||integer_sql(s.max_value)||options;
    return to_clob('declare target_min number; target_max number; unsupported_count number; statement_sql varchar2(32767);'||chr(10)||
      'begin'||chr(10)||'  begin select min_value,max_value into target_min,target_max from user_sequences where sequence_name='||quote_sql(p_name)||';'||chr(10)||
      '  exception when no_data_found then execute immediate '||quote_sql(ddl)||'; return; end;'||chr(10)||
      '  select count(*) into unsupported_count from user_sequences where sequence_name='||quote_sql(p_name)||
      ' and (nvl(scale_flag,''?'')<>''N'' or nvl(extend_flag,''?'')<>''N'' or nvl(sharded_flag,''?'')<>''N'' or nvl(session_flag,''?'')<>''N'');'||chr(10)||
      '  if unsupported_count<>0 then raise_application_error(-20865,''Incompatible target sequence mode; no sequence DDL applied''); end if;'||chr(10)||
      '  statement_sql:='||quote_sql('ALTER SEQUENCE '||name_sql||options)||';'||chr(10)||
      '  if target_min<>'||integer_sql(s.min_value)||' then statement_sql:=statement_sql||'||quote_sql(' MINVALUE '||integer_sql(s.min_value))||'; end if;'||chr(10)||
      '  if target_max<>'||integer_sql(s.max_value)||' then statement_sql:=statement_sql||'||quote_sql(' MAXVALUE '||integer_sql(s.max_value))||'; end if;'||chr(10)||
      '  execute immediate statement_sql;'||chr(10)||'end;'||chr(10)||'/'||chr(10));
  end;

  function extract_sql(p_identity_json clob,p_format varchar2,p_expected_sha256 varchar2) return clob is
    identity json_object_t; typ varchar2(64); nm varchar2(128); actual varchar2(64);
    source_text clob; declaration clob; result clob; body_pos integer;
    line_pos integer; offset_pos integer; piece varchar2(3000 char); trigger_state varchar2(10);
    compile_sql varchar2(32767);
    settings user_plsql_object_settings%rowtype;
    procedure append_text(p_text varchar2) is
    begin if p_text is not null then dbms_lob.writeappend(result,length2(p_text),p_text); end if; end;
    function quoted(p_text varchar2) return varchar2 is
    begin return ''''||replace(p_text,'''','''''')||''''; end;
    procedure free_lobs is
    begin
      if dbms_lob.istemporary(source_text)=1 then dbms_lob.freetemporary(source_text); end if;
      if dbms_lob.istemporary(declaration)=1 then dbms_lob.freetemporary(declaration); end if;
    end;
  begin
    if p_expected_sha256 is not null and not regexp_like(p_expected_sha256,'^[0-9a-f]{64}$','c') then
      raise_application_error(-20865,'Artifact extraction: invalid expected fingerprint.'); end if;
    if p_expected_sha256 is not null then
      actual:=fingerprint(p_identity_json,p_format);
      if actual is null or actual<>p_expected_sha256 then
      raise_application_error(-20865,'Artifact extraction: source changed since capture.'); end if;
    end if;
    identity:=json_object_t.parse(p_identity_json);
    typ:=identity.get_string('object_type'); nm:=identity.get_string('object_name');
    if typ in ('INDEX','CONSTRAINT','FOREIGN KEY') then
      -- One compact desired definition per registry identity. The deployment
      -- worker owns reconciliation; no graph executor is repeated in the ZIP.
      dbms_metadata.set_transform_param(dbms_metadata.session_transform,'DEFAULT',true);
      dbms_metadata.set_transform_param(dbms_metadata.session_transform,'EMIT_SCHEMA',false);
      dbms_metadata.set_transform_param(dbms_metadata.session_transform,'STORAGE',false);
      dbms_metadata.set_transform_param(dbms_metadata.session_transform,'SEGMENT_ATTRIBUTES',false);
      dbms_metadata.set_transform_param(dbms_metadata.session_transform,'TABLESPACE',false);
      dbms_metadata.set_transform_param(dbms_metadata.session_transform,'SQLTERMINATOR',true);
      result:=dbms_metadata.get_ddl(case typ when 'FOREIGN KEY' then 'REF_CONSTRAINT' else typ end,nm);
      if result is null then raise_application_error(-20865,'Key/index definition unavailable: '||nm); end if;
      if p_expected_sha256 is not null and fingerprint(p_identity_json,p_format)<>p_expected_sha256 then
        raise_application_error(-20865,'Key/index changed during extraction: '||nm); end if;
      return result;
    end if;
    if typ='MATERIALIZED VIEW' then
      result:=mview_sql(nm,p_format,p_expected_sha256);
      if p_expected_sha256 is not null and fingerprint(p_identity_json,p_format)<>p_expected_sha256 then
        raise_application_error(-20865,'Materialized view changed during extraction'); end if;
      return result;
    end if;
    if typ='TABLE' then
      result:=table_sql(nm,p_format,p_expected_sha256);
      if p_expected_sha256 is not null and fingerprint(p_identity_json,p_format)<>p_expected_sha256 then
        raise_application_error(-20865,'Table changed during extraction'); end if;
      return result;
    end if;
    if typ='PROPERTY GRAPH' then
      result:=graph_sql(nm,p_format,p_expected_sha256);
      if p_expected_sha256 is not null and fingerprint(p_identity_json,p_format)<>p_expected_sha256 then
        raise_application_error(-20865,'Property graph changed during extraction'); end if;
      return result;
    end if;
    if typ in ('JOB','SCHEDULER JOB') then
      result:=job_sql(nm,typ,p_format,p_expected_sha256);
      if p_expected_sha256 is not null and fingerprint(p_identity_json,p_format)<>p_expected_sha256 then raise_application_error(-20865,'Scheduler job changed during extraction'); end if;
      return result;
    end if;
    if typ='VIEW' then
      result:=view_sql(nm,p_format,p_expected_sha256);
      if p_expected_sha256 is not null and fingerprint(p_identity_json,p_format)<>p_expected_sha256 then
        raise_application_error(-20865,'View changed during extraction'); end if;
      return result;
    end if;
    if typ='SEQUENCE' then
      result:=sequence_sql(nm,p_format,p_expected_sha256);
      if p_expected_sha256 is not null and fingerprint(p_identity_json,p_format)<>p_expected_sha256 then
        raise_application_error(-20865,'Sequence changed during extraction'); end if;
      return result;
    end if;
    if typ not in ('PACKAGE','PACKAGE BODY','PROCEDURE','FUNCTION','TYPE','TYPE BODY','TRIGGER') then
      raise_application_error(-20865,'Artifact extraction: this family requires its own payload adapter.'); end if;
    -- FIXTURE CHECKPOINT: EXPECTED DEFINITION ACCEPTED
    dbms_lob.createtemporary(source_text,true);
    for r in (select text from user_source where name=nm and type=typ order by line) loop
      if r.text is not null then dbms_lob.writeappend(source_text,length2(r.text),r.text); end if;
      if dbms_lob.getlength(source_text)>8388608 then
        raise_application_error(-20865,'Artifact extraction: source size limit.'); end if;
    end loop;
    if dbms_lob.getlength(source_text)>8388608 then
      raise_application_error(-20865,'Artifact extraction: source size limit.'); end if;
    body_pos:=declaration_end(source_text,nm,typ);
    -- Relocate only the parsed declaration header. Preserve its newline count
    -- ($$PLSQL_LINE) and every byte of the body, including literals/comments.
    declaration:=to_clob('CREATE OR REPLACE '||typ||' '||dbms_assert.enquote_name(nm,false));
    line_pos:=dbms_lob.instr(source_text,chr(10),1);
    while line_pos>0 and line_pos<body_pos loop
      declaration:=declaration||chr(10);
      line_pos:=dbms_lob.instr(source_text,chr(10),line_pos+1);
    end loop;
    dbms_lob.copy(declaration,source_text,dbms_lob.getlength(source_text)-body_pos+1,
      dbms_lob.getlength(declaration)+1,body_pos);
    select * into settings from user_plsql_object_settings where name=nm and type=typ;
    if typ='TRIGGER' then
      select status into trigger_state from user_triggers where trigger_name=nm;
      if trigger_state not in ('ENABLED','DISABLED') then raise_application_error(-20865,'Unknown trigger state'); end if;
    end if;
    -- FIXTURE CHECKPOINT: PAYLOAD SNAPSHOT MATERIALIZED
    -- Endpoint checks alone miss A -> B -> A source changes. Authenticate the
    -- materialized source/settings/state that will actually become the payload.
    if p_expected_sha256 is not null then
      actual:=compiled_code_hash(nm,typ,p_format,code_text_hash(source_text,nm,typ),settings,trigger_state);
      if actual is null or actual<>p_expected_sha256 then
      raise_application_error(-20865,'Artifact extraction: captured payload differs from expected definition.'); end if;
    end if;
    compile_sql:='ALTER '||case when typ in ('PACKAGE','PACKAGE BODY') then 'PACKAGE'
      when typ in ('TYPE','TYPE BODY') then 'TYPE' else typ end||' '||dbms_assert.enquote_name(nm,false)||' COMPILE'||
      case when typ in ('PACKAGE','TYPE') then ' SPECIFICATION'
           when typ in ('PACKAGE BODY','TYPE BODY') then ' BODY' end||
      ' PLSQL_CCFLAGS='||quoted(settings.plsql_ccflags)||
      ' PLSQL_OPTIMIZE_LEVEL='||to_char(settings.plsql_optimize_level,'FM9')||
      ' PLSQL_CODE_TYPE='||settings.plsql_code_type||
      ' PLSQL_DEBUG='||settings.plsql_debug||
      ' PLSQL_WARNINGS='||quoted(settings.plsql_warnings)||
      ' PLSCOPE_SETTINGS='||quoted(settings.plscope_settings)||' REUSE SETTINGS';
    if settings.plsql_optimize_level is null or settings.plsql_optimize_level not between 0 and 3
      or settings.plsql_debug is null or settings.plsql_debug not in ('TRUE','FALSE')
      or settings.plsql_code_type is null or settings.plsql_code_type not in ('INTERPRETED','NATIVE')
      or settings.nls_length_semantics is null or settings.nls_length_semantics not in ('BYTE','CHAR') then
      raise_application_error(-20865,'Artifact extraction: unsupported compiler settings.'); end if;
    dbms_lob.createtemporary(result,true);
    append_text(q'~declare
  source_sql clob;
  old_length_semantics varchar2(4);
  procedure set_length_semantics(p_value varchar2) is
  begin
    if p_value is null or p_value not in ('BYTE','CHAR') then raise_application_error(-20865,'Invalid length semantics'); end if;
    execute immediate 'alter session set NLS_LENGTH_SEMANTICS='||p_value;
  end;
begin
  select value into old_length_semantics from nls_session_parameters where parameter='NLS_LENGTH_SEMANTICS';
~');
    append_text('  set_length_semantics('||quoted(settings.nls_length_semantics)||');'||chr(10));
    append_text('  dbms_lob.createtemporary(source_sql,true);'||chr(10));
    offset_pos:=1;
    while offset_pos<=dbms_lob.getlength(declaration) loop
      piece:=dbms_lob.substr(declaration,3000,offset_pos);
      append_text('  dbms_lob.writeappend(source_sql,'||to_char(length2(piece),'FM99990')||','||quoted(piece)||');'||chr(10));
      offset_pos:=offset_pos+length2(piece);
    end loop;
    -- CREATE stores the unit even when caller flags make it temporarily invalid.
    -- Only that compilation diagnostic is deferred to the object-local compile
    -- below; privilege, syntax and other execution failures still abort.
    append_text('  begin'||chr(10)||'  execute immediate source_sql;'||chr(10)||
      '  exception when others then if sqlcode<>-24344 then raise; end if; end;'||chr(10));
    append_text('  execute immediate '||quoted(compile_sql)||';'||chr(10));
    if typ='TRIGGER' then
      append_text('  execute immediate '||quoted('ALTER TRIGGER '||dbms_assert.enquote_name(nm,false)||
        case trigger_state when 'ENABLED' then ' ENABLE' else ' DISABLE' end)||';'||chr(10));
    end if;
    append_text(q'~  dbms_lob.freetemporary(source_sql);
  set_length_semantics(old_length_semantics);
exception when others then
  if dbms_lob.istemporary(source_sql)=1 then dbms_lob.freetemporary(source_sql); end if;
  begin if old_length_semantics is not null then set_length_semantics(old_length_semantics); end if;
  exception when others then dbms_output.put_line('MC_ARTIFACT compiler-session restore failed: '||sqlerrm); end;
  raise;
end;
/
~');
    if p_expected_sha256 is not null then
      actual:=fingerprint(p_identity_json,p_format);
      if actual is null or actual<>p_expected_sha256 then
      raise_application_error(-20865,'Artifact extraction: source changed during extraction.'); end if;
    end if;
    free_lobs;
    return result;
  exception when others then
    free_lobs;
    if dbms_lob.istemporary(result)=1 then dbms_lob.freetemporary(result); end if;
    raise;
  end;
    begin return fingerprint(p_identity,p_format);end;
    procedure fail_early(message varchar2) is begin raise_application_error(-20175,'INITIAL definition primitive: '||message);end;
    function chars(bytes blob) return clob is result clob;d integer:=1;s integer:=1;ctx integer:=0;w integer;
    begin dbms_lob.createtemporary(result,true);dbms_lob.converttoclob(result,bytes,dbms_lob.lobmaxsize,d,s,nls_charset_id('AL32UTF8'),ctx,w);
      if w<>0 then fail_early('Invalid UTF-8');end if;return result;end;
  begin
    inspect(p_zip,p_expected_hash,app,version_value,registry_run,spec_hash,body_hash);
    verify_product_archive(p_zip,coverage_text);coverage:=json_object_t.parse(coverage_text);
    entries:=coverage.get_object('inventory').get_array('entries');bindings:=coverage.get_array('bindings');
    for i in 0..entries.get_size-1 loop
      item:=treat(entries.get(i) as json_object_t);ident:=item.get_object('identity');
      if ident.get_string('object_name')='MC_ARTIFACT_DEFINITION_PKG' and ident.get_string('object_type') in ('PACKAGE','PACKAGE BODY') then
        slot:=case ident.get_string('object_type') when 'PACKAGE' then 1 else 2 end;
        if selected.exists(slot) or item.get_string('lifecycle')<>'BOOTSTRAP' or item.get_string('state')<>'PRESENT'
          or item.get_string('definition_format')<>'mc-artifact-definition-1' then fail_early('Unsupported helper binding');end if;
        selected(slot):=item;
        for j in 0..bindings.get_size-1 loop
          if treat(bindings.get(j) as json_object_t).get_string('key')=item.get_string('key') then bound(slot):=treat(bindings.get(j) as json_object_t);end if;
        end loop;
      end if;
    end loop;
    if selected.count<>2 or bound.count<>2 then fail_early('Reviewed helper specification and body required');end if;
    -- Preflight both identities before either DDL. Never invoke a target-owned
    -- implementation to decide whether that implementation is safe to replace.
    select count(*) into n from user_objects where object_name='MC_ARTIFACT_DEFINITION_PKG' and object_type not in ('PACKAGE','PACKAGE BODY');
    if n<>0 then fail_early('Helper name is owned by another object');end if;
    for i in 1..2 loop
      if bound(i).get_string('action')<>'UNIT' then fail_early('Helper must be a unit');end if;
      declare deps json_array_t:=selected(i).get_array('dependencies');dep json_object_t;
      begin
        for j in 0..deps.get_size-1 loop
          dep:=treat(deps.get(j) as json_object_t);
          if dep.has('key') and dep.get_string('key') not in (selected(1).get_string('key'),selected(2).get_string('key')) then
            fail_early('Helper has a product prerequisite');end if;
        end loop;
      end;
      select count(*) into n from user_objects where object_name='MC_ARTIFACT_DEFINITION_PKG'
        and object_type=case i when 1 then 'PACKAGE' else 'PACKAGE BODY' end;
      missing(i):=n=0;actual:=null;
      if n<>0 then actual:=independent_fingerprint(selected(i).get_object('identity').to_clob,selected(i).get_string('definition_format'));end if;
      if actual is not null and actual<>selected(i).get_string('definition_sha256') then fail_early('Existing helper differs; no replacement permitted');end if;
    end loop;
    zip_inspect(p_zip,members);
    for i in 1..2 loop
      if missing(i) then
        n:=0;
        for j in 1..members.count loop
          if members(j).name=bound(i).get_string('member') then payload:=get_member(p_zip,members(j));n:=n+1;end if;
        end loop;
        if n<>1 or lower(rawtohex(dbms_crypto.hash(payload,dbms_crypto.hash_sh256)))<>bound(i).get_string('payload_sha256') then fail_early('Bound payload changed');end if;
        statement_text:=chars(payload);c:=dbms_sql.open_cursor;
        dbms_sql.parse(c,statement_text,dbms_sql.native);ignored:=dbms_sql.execute(c);dbms_sql.close_cursor(c);c:=null;
        dbms_lob.freetemporary(statement_text);dbms_lob.freetemporary(payload);
      end if;
    end loop;
    for i in 1..2 loop
      actual:=independent_fingerprint(selected(i).get_object('identity').to_clob,selected(i).get_string('definition_format'));
      if actual is null or actual<>selected(i).get_string('definition_sha256') then fail_early('Installed helper fingerprint mismatch');end if;
      select count(*) into n from user_objects where object_name='MC_ARTIFACT_DEFINITION_PKG'
        and object_type=case i when 1 then 'PACKAGE' else 'PACKAGE BODY' end and status='VALID';
      if n<>1 then fail_early('Installed helper invalid');end if;
      dbms_output.put_line('MC_EARLY_DEFINITION|'||bound(i).get_string('member')||'|'||bound(i).get_string('payload_sha256'));
    end loop;
    for i in 0..entries.get_size-1 loop
      item:=treat(entries.get(i) as json_object_t);ident:=item.get_object('identity');
      label_text:=ident.get_string('object_type')||' '||ident.get_string('object_name');
      labels(item.get_string('key')):=replace(replace(replace(label_text,chr(10),' '),chr(13),' '),'|','/');
    end loop;
    for i in 0..bindings.get_size-1 loop
      item:=treat(bindings.get(i) as json_object_t);label_key:=item.get_string('key');
      if labels.exists(label_key) then
        dbms_output.put_line('MC_PRODUCT_LABEL|'||item.get_string('member')||'|'||labels(label_key));
      end if;
    end loop;
    dbms_lob.freetemporary(coverage_text);
  exception when others then
    if c is not null and dbms_sql.is_open(c) then dbms_sql.close_cursor(c);end if;
    if dbms_lob.istemporary(payload)=1 then dbms_lob.freetemporary(payload);end if;
    if dbms_lob.istemporary(statement_text)=1 then dbms_lob.freetemporary(statement_text);end if;
    if dbms_lob.istemporary(coverage_text)=1 then dbms_lob.freetemporary(coverage_text);end if;
    raise;
  end;
MC_PRODUCT_DEFINITION_EARLY
}
# Shared INITIAL/UPDATE grant handling. Only reviewed data reaches ADMIN.
mc_grants_sql() (
  local saved="$1" script="$2" output="$3" pid='' ticks=0 status=0
  trap 'if [[ -n "$pid" ]]; then kill -TERM -- "-$pid" 2>/dev/null || true; sleep .2; kill -KILL -- "-$pid" 2>/dev/null || true; wait "$pid" 2>/dev/null || true; fi' EXIT
  trap 'exit 130' INT
  trap 'exit 143' TERM
  set -m
  sql -s -L -name "$saved" "@$script" > "$output" 2>&1 &
  pid=$!
  set +m
  while kill -0 "$pid" 2>/dev/null; do
    ((ticks<1200)) || { echo 'ERROR: Database permission check timed out.' >&2; return 1; }
    sleep .1; ticks=$((ticks+1))
  done
  wait "$pid" || status=$?; pid=''
  return "$status"
)

mc_grants_remediate() {
  local report="$1" work="$2" line tag kind a b c extra count=0 declared='' target='' db='' con=''
  local answer script="$2/apply-missing-grants.sql" output="$2/apply-missing-grants.out"
  local statements="$2/missing-grants.sql" attempted="${3:-N}" cloud_requested=N
  : > "$statements"
  while IFS='|' read -r tag kind a b c extra; do
    case "$tag" in
      MC_GRANT_TARGET)
        [[ -z "$target" && "$kind" =~ ^[A-Z][A-Z0-9_\$#]{0,127}$ && "$a" =~ ^[A-Za-z0-9_.\$#-]+$ && "$b" =~ ^[A-Za-z0-9_.\$#-]+$ && -z "$c$extra" ]] || return 1
        target="$kind"; db="$a"; con="$b" ;;
      MC_GRANT_COUNT)
        [[ -z "$declared" && "$kind" =~ ^[0-9]+$ && -z "$a$b$c$extra" ]] || return 1
        declared="$kind" ;;
      MC_GRANT)
        case "$kind" in
          SYSTEM)
            [[ -z "$b$c$extra" ]] || return 1
            case "$a" in
              'CREATE SESSION'|'CREATE TABLE'|'CREATE PROCEDURE'|'CREATE JOB'|'CREATE SEQUENCE'|'CREATE VIEW'|'CREATE MATERIALIZED VIEW'|'CREATE PROPERTY GRAPH'|'CREATE TRIGGER'|'CREATE TYPE'|'CREATE SYNONYM'|'CREATE ANY CONTEXT') ;;
              *) echo 'ERROR: Unapproved system grant requested.' >&2; return 1 ;;
            esac
            printf "  execute immediate 'grant %s to '||dbms_assert.enquote_name(l_target,false);\n" "$a" >> "$statements"
            echo "Missing direct permission: $a" ;;
          OBJECT)
            [[ "$a" =~ ^[A-Z][A-Z0-9_\$#]{0,127}$ && "$b" =~ ^[A-Z][A-Z0-9_\$#]{0,127}$ && "$c" =~ ^(EXECUTE|SELECT)$ && -z "$extra" ]] || return 1
            if [[ "$a|$b|$c" == 'C##CLOUD$SERVICE|DBMS_CLOUD|EXECUTE' ]]; then
              cloud_requested=Y
              printf '%s\n' \
                "  execute immediate 'grant EXECUTE on DBMS_CLOUD to '||dbms_assert.enquote_name(l_target,false);" >> "$statements"
            else
              printf "  execute immediate 'grant %s on \"%s\".\"%s\" to '||dbms_assert.enquote_name(l_target,false);\n" "$c" "$a" "$b" >> "$statements"
            fi
            echo "Missing direct permission: $c ON $a.$b" ;;
          *) return 1 ;;
        esac
        count=$((count+1)) ;;
    esac
  done < "$report"
  [[ -n "$target" && "$declared" == "$count" ]] || { echo 'ERROR: Incomplete database permission report; no grants applied.' >&2; return 1; }
  ((count>0)) || return 0
  # Produce exact, reviewable instructions regardless of whether ADMIN is used.
  sed "s/execute immediate 'grant /GRANT /; s/ to '||dbms_assert.enquote_name(l_target,false);/ TO \"$target\";/" "$statements"
  [[ "$attempted" == N ]] || { echo 'ERROR: Missing direct grants remain after remediation; deployment stopped.' >&2; return 1; }
  [[ "${apply_missing_grants:-N}" == Y ]] || {
    echo 'ERROR: Missing direct grants were not applied. Supply --apply-missing-grants --admin-connection TARGET_ADMIN before starting UPDATE, or ask target ADMIN to apply the statements above.' >&2
    return 1
  }
  [[ "${admin_connection:-}" =~ ^[A-Za-z][A-Za-z0-9_.-]{0,127}$ ]] || { echo 'ERROR: A valid ADMIN saved connection is required.' >&2; return 1; }
  {
    printf '%s\n' 'whenever sqlerror exit failure rollback' 'whenever oserror exit failure rollback' 'set define off echo off verify off feedback off' 'set serveroutput on'
    printf "declare l_target varchar2(128):='%s'; n number; begin\n" "$target"
    printf "  if sys_context('USERENV','SESSION_USER')<>'ADMIN' or nvl(sys_context('USERENV','DB_UNIQUE_NAME'),'?')<>'%s' or nvl(sys_context('USERENV','CON_NAME'),'?')<>'%s' then raise_application_error(-20070,'ADMIN connection does not match target database/container'); end if;\n" "$db" "$con"
    printf '%s\n' "  select count(*) into n from dba_users where username=l_target;" "  if n<>1 then raise_application_error(-20070,'Target schema missing'); end if;"
    if [[ "$cloud_requested" == Y ]]; then
      printf '%s\n' "  select count(*) into n from user_objects where object_name='DBMS_CLOUD' and object_type in ('SYNONYM','PACKAGE','PROCEDURE','FUNCTION','TABLE','VIEW','TYPE','SEQUENCE','MATERIALIZED VIEW');" \
        "  if n<>0 then raise_application_error(-20070,'ADMIN DBMS_CLOUD shadow requires DBA review'); end if;" \
        "  select count(*) into n from all_synonyms where owner='PUBLIC' and synonym_name='DBMS_CLOUD' and table_owner='C##CLOUD\$SERVICE' and db_link is null;" \
        "  if n<>1 then raise_application_error(-20070,'Oracle public DBMS_CLOUD synonym unavailable'); end if;"
    fi
    cat "$statements"
    printf '%s\n' "  dbms_output.put_line('MC_GRANTS_APPLIED');" 'end;' '/' 'exit success'
  } > "$script"
  if ! mc_grants_sql "$admin_connection" "$script" "$output"; then
    cat "$output" >&2
    echo 'ERROR: ADMIN remediation failed; some grants may have committed. No application update was submitted.' >&2
    return 1
  fi
  grep -qx 'MC_GRANTS_APPLIED' "$output" || return 1
  echo "Required grants applied to $target; checking again as the target."
  return 2 # Caller must recheck, never treat a successful GRANT as sufficient.
}

mc_grants_write_check() {
  local script="$1" content="$2" strict="${3:-N}" file path chunk bytes
  local encoded="$(dirname "$script")/grants-encoded.txt"
  {
    printf '%s\n' 'whenever sqlerror exit failure rollback' 'whenever oserror exit failure rollback' 'set define off echo off verify off feedback off' 'set serveroutput on size unlimited' 'declare' '  required sys.odcivarchar2list; payload blob; objects clob; statements clob; missing pls_integer; context_found boolean:=false;'
    mc_privilege_policy_sql
    cat <<'SQL'
  procedure put(p_text varchar2) is r raw(32767); begin
    r:=utl_encode.base64_decode(utl_raw.cast_to_raw(p_text)); dbms_lob.writeappend(payload,utl_raw.length(r),r); end;
  procedure finish(p_path varchar2,p_bytes number) is c clob; dst integer:=1; src integer:=1; ctx integer:=0; warn integer;
  begin
    if dbms_lob.getlength(payload)<>p_bytes then raise_application_error(-20070,'Incomplete privilege payload'); end if;
    dbms_lob.createtemporary(c,true);
    dbms_lob.converttoclob(c,payload,dbms_lob.lobmaxsize,dst,src,nls_charset_id('AL32UTF8'),ctx,warn);
    if warn<>0 then raise_application_error(-20070,'Invalid privilege payload encoding'); end if;
    if p_path='db/preflight/required_privileges.txt' then objects:=c;
    else
      if p_path='db/ddl/05_contexts.sql' then context_found:=policy_has_create(c,'CONTEXT'); end if;
      policy_add_file(p_path,c,required); dbms_lob.freetemporary(c);
    end if;
    dbms_lob.trim(payload,0);
  end;
begin
  required:=policy_baseline; dbms_lob.createtemporary(payload,true);
SQL
    for path in db/ddl/{02_sequences,03a_views,05_contexts,08_mviews,08a_property_graphs,09_triggers}.sql db/preflight/required_system_privileges.txt db/preflight/required_privileges.txt; do
      file="$content/$path"
      [[ -f "$file" ]] || continue
      bytes="$(wc -c < "$file" | tr -d '[:space:]')" || return 1
      [[ "$bytes" =~ ^[0-9]+$ ]] || return 1
      (set -o pipefail; base64 < "$file" | tr -d '\r\n' | fold -w 4000) > "$encoded" || return 1
      while IFS= read -r chunk || [[ -n "$chunk" ]]; do
        [[ "$chunk" =~ ^[A-Za-z0-9+/]+={0,2}$ ]] || return 1
        printf "  put('%s');\n" "$chunk"
      done < "$encoded"
      printf "  finish('%s',%s);\n" "$path" "$bytes"
    done
    printf '%s\n' '  policy_finish(required,context_found);' '  policy_report(required,objects,missing,statements);' '  dbms_lob.freetemporary(statements);' '  dbms_lob.freetemporary(payload);' '  if dbms_lob.istemporary(objects)=1 then dbms_lob.freetemporary(objects); end if;'
    if [[ "$strict" == Y ]]; then
      printf '%s\n' "  if missing>0 then raise_application_error(-20070,'Required direct grants missing; ask target ADMIN to apply the reported grants'); end if;"
    fi
    printf '%s\n' 'end;' '/'
    # Maintenance includes this check in its existing guarded session.
    [[ "$strict" == Y ]] || printf '%s\n' 'exit success'
  } > "$script"
}

mc_grants_local() {
  local attempted="${1:-N}" status=0 script="$tmp/run-required-privileges.sql" report="$tmp/required-privileges.out"
  mc_grants_write_check "$script" "$tmp/content" || return 1
  if ! mc_grants_sql "$connection" "$script" "$report"; then cat "$report" >&2; return 1; fi
  cat "$report" >> "$log"
  mc_grants_remediate "$report" "$tmp" "$attempted" || status=$?
  if ((status==2)); then mc_grants_local Y; else return "$status"; fi
}
# UPDATE transport. The target plans from registry revisions before any payload
# transfer; SQLcl LOAD moves only the selected, compact release archive.
mc_update_contract() (
  set -euo pipefail
  local archive="$1" work="$2" contract
  [[ -f "$archive" && ! -e "$work" ]] || return 1
  command -v zip >/dev/null && command -v base64 >/dev/null || {
    echo 'ERROR: UPDATE requires zip and base64.' >&2; return 1;
  }
  mkdir -m 700 "$work"
  mc_bundle_archive "$archive" "$work" entry "$work/bundle.properties" bundle.properties 8192 || return 1
  [[ $(wc -c < "$work/bundle.properties") -le 8192 ]] || return 1
  contract="$(sed -n 's/^MC_BUNDLE_CONTRACT=//p' "$work/bundle.properties")"
  [[ "$contract" == mc-bundle-1.13.0 ]] || return 1
  printf '%s\n' "$contract"
)

mc_update_sql() {
  local label="$1" script="$2" output="$3"
  if ! sql -s -L -name "$saved" "@$script" < /dev/null > "$output" 2>&1; then
    echo "ERROR: $label failed." >&2
    tail -30 "$output" >&2
    return 1
  fi
  if grep -Eq '^ORA-[0-9]|^PLS-[0-9]|^SP2-[0-9]|[1-9][0-9]* - (ERROR|FAILURE): Load' "$output"; then
    echo "ERROR: $label failed." >&2
    tail -30 "$output" >&2
    return 1
  fi
}

mc_update_receipt() {
  local tag="$1" file="$2"
  sed -n "s/^${tag}|//p" "$file" | tail -1 | tr -d '\r'
}

mc_update_csv() {
  local source="$1" kind="$2" destination="$3" part=0 chunk
  printf 'TOKEN,STREAM_KIND,PART_NO,ENCODED\n' > "$destination"
  base64 < "$source" | tr -d '\r\n' | fold -w 4000 > "$destination.encoded"
  while IFS= read -r chunk || [[ -n "$chunk" ]]; do
    [[ "$chunk" =~ ^[A-Za-z0-9+/]+={0,2}$ && $((${#chunk}%4)) -eq 0 ]] || return 1
    part=$((part+1))
    printf '%s,%s,%s,%s\n' "$token" "$kind" "$part" "$chunk" >> "$destination"
  done < "$destination.encoded"
  rm -f -- "$destination.encoded"
  ((part>0))
}

mc_update_load() {
  local kind="$1" source="$2" suffix csv script
  case "$kind" in
    OUTER) suffix=outer ;;
    MANIFEST) suffix=manifest ;;
    ZIP) suffix=zip ;;
    *) echo "ERROR: Unsupported UPDATE stream kind: $kind" >&2; return 1 ;;
  esac
  csv="$work/$suffix.csv"
  script="$work/load-$suffix.sql"
  mc_update_csv "$source" "$kind" "$csv"
  cat > "$script" <<SQL
whenever sqlerror exit failure rollback
whenever oserror exit failure rollback
set echo off feedback off verify off
set load batch_rows 500
set load batches_per_commit 10
load MC_DELTA_UPLOAD_ROWS $csv
exit success commit
SQL
  mc_update_sql "$kind transfer" "$script" "$work/load-$suffix.out"
  echo "$kind transfer: $(wc -c < "$source" | tr -d ' ') bytes."
}

mc_update_extract() {
  local member="$1" destination="$2"
  [[ "$member" =~ ^[A-Za-z0-9_./-]+$ && "$member" != /* && "$member" != *../* && "$member" != */.. && "$member" != *//* ]] || {
    echo "ERROR: Unsafe bundle member: $member" >&2; return 1;
  }
  mc_bundle_archive "$bundle" "$work" entry "$destination" "$member" || {
    echo "ERROR: Unable to read selected bundle member: $member" >&2; return 1;
  }
}

mc_update_follow() {
  local run="$1" state='' last_bytes=0 length line
  while :; do
    cat > "$work/status.sql" <<SQL
whenever sqlerror exit failure rollback
whenever oserror exit failure rollback
set echo off verify off feedback off heading off pagesize 0 linesize 32767 trimspool on
set serveroutput on size unlimited
declare s varchar2(30); l clob; e clob; n number;
begin
  select status,log_clob,error_stack into s,l,e from deploy_runs where run_id=$run;
  n:=nvl(dbms_lob.getlength(l),0);
  dbms_output.put_line('MC_DELTA_STATUS|'||s||'|'||n);
  if n>$last_bytes then
    dbms_output.put_line('MC_DELTA_LOG|'||replace(dbms_lob.substr(l,least(n-$last_bytes,2000),$((last_bytes+1))),chr(10),'~'));
  end if;
  if s='FAILED' then dbms_output.put_line('MC_DELTA_ERROR|'||replace(dbms_lob.substr(e,3000,1),chr(10),'~')); end if;
end;
/
exit success rollback
SQL
    mc_update_sql 'delta status' "$work/status.sql" "$work/status.out" || return 1
    line="$(mc_update_receipt MC_DELTA_STATUS "$work/status.out")"
    [[ "$line" =~ ^(RUNNING|SUCCESS|FAILED)\|[0-9]+$ ]] || { echo 'ERROR: Invalid delta status response.' >&2; return 1; }
    state="${line%%|*}"; length="${line#*|}"
    if ((length>last_bytes)); then
      mc_update_receipt MC_DELTA_LOG "$work/status.out" | tr '~' '\n'
      if ((length-last_bytes>2000)); then
        last_bytes=$((last_bytes+2000))
      else
        last_bytes="$length"
      fi
    fi
    # Drain the full log before treating a terminal state as complete.
    ((length>last_bytes)) && continue
    case "$state" in
      SUCCESS) echo "UPDATE run $run completed."; return 0 ;;
      FAILED) echo "ERROR: UPDATE run $run failed: $(mc_update_receipt MC_DELTA_ERROR "$work/status.out" | tr '~' ' ')" >&2; return 1 ;;
    esac
    sleep 5
  done
}

mc_update_run() (
  set -euo pipefail
  local bundle="$1" saved="$2" work="$3" dry="$4" token='' submitted=N
  local plan_line member action total=0 run='' file
  [[ -f "$bundle" && "$saved" =~ ^[A-Za-z][A-Za-z0-9_.-]{0,127}$ && "$dry" =~ ^[YN]$ ]] || return 1
  mkdir -m 700 "$work"
  mc_bundle_archive "$bundle" "$work" list - > "$work/archive-members" || return 1
  if sort "$work/archive-members" | uniq -d | grep -q .; then
    echo 'ERROR: Release ZIP has duplicate member paths.' >&2; return 1;
  fi
  trap 'if [[ "$submitted" == N && "$token" =~ ^[0-9a-f]{32}$ ]]; then
    printf "begin mc_artifact_update_pkg.delta_cancel(\x27%s\x27); end;\n/\nexit success commit\n" "$token" > "$work/cancel.sql"
    sql -s -L -name "$saved" "@$work/cancel.sql" < /dev/null > "$work/cancel.out" 2>&1 || true
  fi' EXIT
  cat > "$work/start.sql" <<'SQL'
whenever sqlerror exit failure rollback
whenever oserror exit failure rollback
set echo off verify off feedback off heading off pagesize 0
set serveroutput on
declare t varchar2(32);
begin
  if deploy_mgr_pkg.update_engine_version<>'mc-delta-2' then
    raise_application_error(-20867,'Upgrade the target deployment manager before UPDATE.');
  end if;
  mc_artifact_update_pkg.delta_begin(t);
  dbms_output.put_line('MC_DELTA_TOKEN|'||t);
end;
/
exit success commit
SQL
  mc_update_sql 'manager version gate' "$work/start.sql" "$work/start.out" || return 1
  token="$(mc_update_receipt MC_DELTA_TOKEN "$work/start.out")"
  [[ "$token" =~ ^[0-9a-f]{32}$ ]] || { echo 'ERROR: Target did not return a delta token.' >&2; return 1; }
  mc_update_extract manifest.json "$work/manifest.json"
  mc_update_extract db/deploy/artifacts.json "$work/artifacts.json"
  mc_update_load OUTER "$work/manifest.json"
  mc_update_load MANIFEST "$work/artifacts.json"
  cat > "$work/plan.sql" <<SQL
whenever sqlerror exit failure rollback
whenever oserror exit failure rollback
set echo off verify off feedback off heading off pagesize 0 linesize 32767 trimspool on
set serveroutput on size unlimited
declare p clob; j json_object_t; a json_array_t; x json_object_t; c json_object_t;
begin
  p:=mc_artifact_update_pkg.delta_plan('$token'); j:=json_object_t.parse(p);
  c:=j.get_object('counts');
  dbms_output.put_line('MC_DELTA_COUNTS|'||c.get_number('CREATE')||'|'||c.get_number('UPDATE')||'|'||c.get_number('REMOVE')||'|'||c.get_number('SKIP')||'|'||c.get_number('BLOCK'));
  dbms_output.put_line('MC_DELTA_APEX|'||j.get_object('apex').get_string('action'));
  a:=j.get_array('artifacts');
  for i in 0..a.get_size-1 loop
    x:=treat(a.get(i) as json_object_t);
    dbms_output.put_line('MC_DELTA_OBJECT|'||x.get_string('action')||'|'||
      x.get_object('identity').get_string('object_type')||'|'||
      x.get_object('identity').get_string('object_name')||'|'||
      nvl(x.get_string('transfer_member'),'-')||'|'||x.get_string('key')||'|'||x.get_string('reason'));
  end loop;
end;
/
exit success commit
SQL
  mc_update_sql 'registry revision plan' "$work/plan.sql" "$work/plan.out" || return 1
  plan_line="$(mc_update_receipt MC_DELTA_COUNTS "$work/plan.out")"
  [[ "$plan_line" =~ ^[0-9]+\|[0-9]+\|[0-9]+\|[0-9]+\|[0-9]+$ ]] || { echo 'ERROR: Missing registry plan.' >&2; return 1; }
  echo "Registry plan (create|update|remove|unchanged|blocked): $plan_line"
  grep '^MC_DELTA_OBJECT|' "$work/plan.out" | sed 's/^MC_DELTA_OBJECT|/  /' || true
  if [[ "$plan_line" != *'|0' || "$(mc_update_receipt MC_DELTA_APEX "$work/plan.out")" == BLOCK ]]; then
    echo 'ERROR: Registry plan is blocked; no payload was transferred.' >&2; return 1
  fi
  echo "APEX: $(mc_update_receipt MC_DELTA_APEX "$work/plan.out")"
  [[ "$dry" == N ]] || { echo 'Dry-run complete; no payload was transferred.'; return 0; }
  mkdir -m 700 "$work/selected"
  printf '%s\n' 'db/deploy/artifacts.json' 'db/ddl/05_contexts.sql' 'db/ddl/95_app_config.sql' \
    'db/ddl/96_chatbot_seed.sql' 'db/ddl/97_semantic_seed.sql' > "$work/members"
  while IFS='|' read -r _ action object_type _ member key _; do
    [[ "$action" == CREATE || "$action" == UPDATE ]] || continue
    printf '%s\n' "$member" >> "$work/members"
    if [[ "$action" == UPDATE && "$object_type" == TABLE ]]; then
      printf 'db/deploy/tables/%s.json\n' "$key" >> "$work/members"
    fi
  done < <(grep '^MC_DELTA_OBJECT|' "$work/plan.out" || true)
  [[ "$(mc_update_receipt MC_DELTA_APEX "$work/plan.out")" == IMPORT ]] && printf '%s\n' 'apex/f1200.sql' >> "$work/members"
  sort -u "$work/members" -o "$work/members"
  while IFS= read -r member; do
    mc_update_extract "$member" "$work/selected/$member"
    total=$((total+1))
  done < "$work/members"
  (cd "$work/selected" && zip -q -D "$work/delta.zip" -@ < "$work/members")
  echo "Selected $total members, $(wc -c < "$work/delta.zip" | tr -d ' ') bytes compressed."
  mc_update_load ZIP "$work/delta.zip"
  cat > "$work/submit.sql" <<SQL
whenever sqlerror exit failure rollback
whenever oserror exit failure rollback
set echo off verify off feedback off heading off pagesize 0
set serveroutput on
declare r number;
begin
  mc_artifact_update_pkg.delta_submit('$token',r);
  dbms_output.put_line('MC_DELTA_RUN|'||r);
end;
/
exit success commit
SQL
  if ! mc_update_sql 'delta submission' "$work/submit.sql" "$work/submit.out"; then
    echo 'Checking the durable delta token before reporting submission failure.' >&2
  fi
  run="$(mc_update_receipt MC_DELTA_RUN "$work/submit.out")"
  if [[ ! "$run" =~ ^[1-9][0-9]*$ ]]; then
    cat > "$work/recover.sql" <<SQL
whenever sqlerror exit failure rollback
whenever oserror exit failure rollback
set echo off verify off feedback off heading off pagesize 0
set serveroutput on
declare r number;
begin
  select run_id into r from mc_delta_request where token='$token';
  dbms_output.put_line('MC_DELTA_RUN|'||nvl(to_char(r),'NONE'));
end;
/
exit success rollback
SQL
    mc_update_sql 'submission receipt lookup' "$work/recover.sql" "$work/recover.out" || return 1
    run="$(mc_update_receipt MC_DELTA_RUN "$work/recover.out")"
  fi
  [[ "$run" =~ ^[1-9][0-9]*$ ]] || { echo "ERROR: No submitted UPDATE run for token $token. Review the target request before retrying." >&2; return 1; }
  submitted=Y
  echo "Following UPDATE run $run."
  mc_update_follow "$run"
)
[[ "$admin_connection" =~ ^[A-Za-z][A-Za-z0-9_.-]{0,127}$ || -z "$admin_connection" ]] || fail 'Invalid ADMIN saved connection name'
if [[ "$mode" == UNINSTALL ]]; then
  [[ "$admin_connection" =~ ^[A-Za-z][A-Za-z0-9_.-]{0,127}$ && "$schema" =~ ^[A-Z][A-Z0-9_\$#]{0,127}$ && "$workspace" =~ ^[A-Z][A-Z0-9_]{0,254}$ && "$target_id" =~ ^[1-9][0-9]{0,9}$ ]] || fail 'UNINSTALL requires valid --admin-connection, --schema, --workspace and --target-app-id'
  [[ "$schema" != ADMIN && "$schema" != SYS && "$schema" != SYSTEM && "$workspace" != INTERNAL ]] || fail 'Protected database or workspace identity'
  [[ -z "$target_connection" || ( "$target_connection" =~ ^[A-Za-z][A-Za-z0-9_.-]{0,127}$ && "$target_connection" != "$admin_connection" ) ]] || fail 'Saved connection for removal must be valid and different from ADMIN'
  [[ -z "$bundle$connection$workspace_mode$first_admin$prerequisites$apex_offset$confirm" && "$interactive" == N && "$apply_missing_grants" == N && "$data_ts" == DATA && "$temp_ts" == TEMP ]] || fail 'UNINSTALL accepts only explicit target, ADMIN, optional progress/connection, preview and deletion-confirmation options'
  [[ "$dry" == N || ( -z "$confirm_drop_schema" && "$acknowledge_data_loss" == N ) ]] || fail 'Do not combine --dry-run with deletion confirmation'
  if command -v shasum >/dev/null; then MC_BUNDLE_HASH_TOOL=shasum; else MC_BUNDLE_HASH_TOOL=sha256sum; fi
  log="$(mktemp "${TMPDIR:-/tmp}/mc-uninstall-diagnostic.XXXXXX")"
  uninstall_run
  exit 0
fi
if [[ "$mode" == CLEANUP ]]; then
  [[ "$admin_connection" =~ ^[A-Za-z][A-Za-z0-9_.-]{0,127}$ && -n "$journal_directory" ]] || fail 'CLEANUP requires --admin-connection and --journal-directory'
  [[ -z "$bundle$connection$schema$workspace$workspace_mode$target_connection$target_id$first_admin$prerequisites$apex_offset$confirm" && "$dry" == N && "$interactive" == N && "$apply_missing_grants" == N && "$data_ts" == DATA && "$temp_ts" == TEMP ]] || fail 'CLEANUP accepts only its ADMIN connection and journal directory'
  if command -v shasum >/dev/null; then MC_BUNDLE_HASH_TOOL=shasum; else MC_BUNDLE_HASH_TOOL=sha256sum; fi
  initial_recover
  exit 0
fi
if [[ "$mode" == UPDATE ]]; then
  # UPDATE has one route. Never fall through to the INITIAL installer.
  tmp="$(cd "$tmp" && pwd -P)"
  update_contract="$(mc_update_contract "$bundle" "$tmp/contract-probe")" || fail 'Invalid or unsupported UPDATE bundle metadata'
  [[ "$update_contract" == mc-bundle-1.13.0 ]] || fail "Unsupported UPDATE bundle contract: $update_contract; export a current release"
  [[ "$connection" =~ ^[A-Za-z][A-Za-z0-9_.-]{0,127}$ ]] || fail 'UPDATE requires a valid --connection'
  [[ "$apply_missing_grants" == N && -z "$admin_connection" ]] || fail 'UPDATE uses only the target connection; provision required grants separately'
  [[ -z "$target_id$workspace$workspace_mode$schema$target_connection$first_admin$journal_directory$prerequisites$confirm" && "$apex_offset_supplied" == N && "$data_ts" == DATA && "$temp_ts" == TEMP ]] || fail 'UPDATE rejects INITIAL options'
  log="$(mktemp "${TMPDIR:-/tmp}/mc-update-diagnostic.XXXXXX")"
  mc_update_run "$bundle" "$connection" "$tmp/coordinated-update" "$dry" 2>&1 | tee -a "$log"
  exit 0
fi
[[ "$mode" == INITIAL ]] || fail "Unsupported installer mode: $mode"
admin_rights_script="$tmp/target_admin_schema_rights.sql"
cat > "$admin_rights_script" <<'MC_EMBEDDED_ADMIN_SQL'
/*
  MetisCloud target-schema ADMIN rights.

  Usage:
    sql -name TARGET_ADMIN @target_admin_schema_rights.sql TARGET_SCHEMA

  The target user must already exist. INITIAL runs these actions automatically;
  this file is the reviewable/manual equivalent for validation or repair.

  This script deliberately does not grant roles, SELECT ANY TABLE, CREATE ANY
  JOB, change a database profile, enable ORDS, or change shared database policy.
*/
whenever oserror exit failure rollback
whenever sqlerror exit sql.sqlcode rollback
set verify off
set serveroutput on size unlimited

define MC_TARGET_SCHEMA = '&1'

declare n number;
begin
  select count(*) into n from dba_tab_columns where owner='SYS' and table_name='DBA_AUTO_INDEX_CONFIG' and column_name='PARAMETER_VALUE_CLOB';
  if n<>1 then raise_application_error(-20080,'Schema-rights safety checks require Oracle 23.7+ indexing metadata.'); end if;
end;
/

declare
  l_schema varchar2(128) := upper(trim('&&MC_TARGET_SCHEMA'));
  l_count  pls_integer;
  l_mode   varchar2(4000);
begin
  if not regexp_like(l_schema, '^[A-Z][A-Z0-9_$#]{0,127}$', 'c') then
    raise_application_error(-20080, 'Target schema must be an unquoted Oracle identifier.');
  end if;

  select count(*)
    into l_count
    from dba_users
   where username = l_schema;
  if l_count <> 1 then
    raise_application_error(-20081, 'Target schema does not exist: ' || l_schema);
  end if;

  -- INITIAL owns eligibility validation/enrollment and its recovery journal.
  -- This grants-only script never edits shared indexing policy.
  select parameter_value into l_mode from dba_auto_index_config where parameter_name='AUTO_INDEX_MODE';
  if nvl(upper(trim(l_mode)),'OFF')<>'IMPLEMENT' then
    raise_application_error(-20082,'AUTO_INDEX_MODE must already be IMPLEMENT; complete shared prerequisites.');
  end if;
  select count(*) into l_count from dba_credentials
   where owner='ADMIN' and credential_name='OCI$RESOURCE_PRINCIPAL';
  if l_count<>1 then
    raise_application_error(-20082,'ADMIN resource principal must already be enabled; complete shared OCI onboarding.');
  end if;

  execute immediate
    'grant create session, create table, create sequence, create view, ' ||
    'create materialized view, create procedure, create trigger, create type, ' ||
    'create job, create property graph to ' ||
    dbms_assert.enquote_name(l_schema, false);

  -- DBMS_CLOUD external-table ingestion uses this directory under definer
  -- rights. A broad DWROLE is not a substitute for these direct grants.
  execute immediate 'grant read, write on directory DATA_PUMP_DIR to ' ||
    dbms_assert.enquote_name(l_schema, false);
  -- INITIAL workers retain a database mutex through DDL commits and disconnect.
  execute immediate 'grant execute on sys.dbms_lock to ' || dbms_assert.enquote_name(l_schema,false);

  select parameter_value
    into l_mode
    from dba_auto_index_config
   where parameter_name = 'AUTO_INDEX_MODE';
  if upper(trim(l_mode)) <> 'IMPLEMENT' then
    raise_application_error(
      -20082,
      'Database-wide AUTO_INDEX_MODE=' || nvl(l_mode, '<NULL>') ||
      '. Set it to IMPLEMENT under the database administrator''s change policy, then rerun.'
    );
  end if;
  -- No CONFIGURE call here; INITIAL verifies target eligibility separately.

  select count(*)
    into l_count
    from dba_tab_privs
   where owner = 'ADMIN'
     and table_name = 'OCI$RESOURCE_PRINCIPAL'
     and grantee = l_schema
     and privilege = 'EXECUTE';
  if l_count = 0 then
    dbms_cloud_admin.enable_resource_principal(username => l_schema);
  end if;

  -- A successful API return is not the postcondition. Verify direct target
  -- access; OCI IAM and real service access are checked later by onboarding.
  select count(*) into l_count from dba_tab_privs
   where owner = 'ADMIN'
     and table_name = 'OCI$RESOURCE_PRINCIPAL'
     and grantee = l_schema
     and privilege = 'EXECUTE';
  if l_count <> 1 then
    raise_application_error(-20082, 'Target resource-principal grant was not confirmed; review database resource-principal setup.');
  end if;

  dbms_output.put_line(
    'MC_ADMIN SUCCESS schema rights/resource-principal access applied; shared indexing preserved for ' ||
    l_schema
  );
end;
/

undefine MC_TARGET_SCHEMA
exit success
MC_EMBEDDED_ADMIN_SQL
mc_bundle_validate "$bundle" "$tmp" || exit $?
bundle_abs="$MC_BUNDLE_INPUT_ABS"
bundle_dir="$(dirname "$bundle_abs")"
bundle_hash="$MC_BUNDLE_SHA256"
contract="$MC_BUNDLE_CONTRACT"
[[ "$contract" == mc-bundle-1.13.0 ]] || fail "Unsupported bundle contract: $contract; export a current release"
supported_modes="$MC_BUNDLE_SUPPORTED_MODES"
source_id="$MC_BUNDLE_SOURCE_ID"
registry_run_id="$MC_BUNDLE_REGISTRY_RUN_ID"
echo 'Release bundle verified.'
[[ "$admin_connection" =~ ^[A-Za-z][A-Za-z0-9_.-]{0,127}$ || -z "$admin_connection" ]] || fail "invalid SQLcl admin connection name"
[[ "$target_connection" =~ ^[A-Za-z][A-Za-z0-9_.-]{0,127}$ || -z "$target_connection" ]] || fail "invalid SQLcl target connection name"
[[ "$connection" =~ ^[A-Za-z][A-Za-z0-9_.-]{0,127}$ || -z "$connection" ]] || fail "invalid SQLcl target connection name"

[[ "$dry" == Y || -n "$journal_directory" ]] || fail 'INITIAL requires --journal-directory for durable recovery receipts'
[[ -n "$workspace" && "$workspace_mode" =~ ^(CREATE|EXISTING)$ && -n "$admin_connection" && -n "$target_connection" && -n "$schema" && "$confirm" == "$schema" ]] || fail "INITIAL requires workspace name/mode, admin connection, target connection name, schema, and exact schema confirmation"
[[ "$schema" =~ ^[A-Za-z][A-Za-z0-9_\$#]{0,127}$ ]] || fail "invalid schema name"
[[ "$workspace" =~ ^[A-Za-z][A-Za-z0-9_]{0,254}$ ]] || fail "workspace name must use letters, digits, or underscores"
[[ "$data_ts" =~ ^[A-Za-z][A-Za-z0-9_\$#]{0,127}$ && "$temp_ts" =~ ^[A-Za-z][A-Za-z0-9_\$#]{0,127}$ ]] || fail "invalid tablespace name"
[[ -z "$target_id" || "$target_id" =~ ^[1-9][0-9]*$ ]] || fail "target application ID must be a positive integer"
[[ "$apex_offset_supplied" == Y ]] || fail "INITIAL requires --apex-offset AUTO or a non-negative integer"
[[ "$apex_offset" == AUTO || "$apex_offset" =~ ^[0-9]+$ ]] || fail "--apex-offset must be AUTO or a non-negative integer"
[[ -z "$prerequisites" || -f "$prerequisites" ]] || fail "prerequisite SQL file not found: $prerequisites"
target_id="${target_id:-$source_id}"
[[ "$first_admin" =~ ^[A-Za-z][A-Za-z0-9_.@-]{0,99}$ ]] || fail "INITIAL requires --first-admin with a new native APEX username (letters, digits, _, ., @, -)"
schema="$(printf '%s' "$schema" | tr '[:lower:]' '[:upper:]')"
workspace="$(printf '%s' "$workspace" | tr '[:lower:]' '[:upper:]')"
data_ts="$(printf '%s' "$data_ts" | tr '[:lower:]' '[:upper:]')"
temp_ts="$(printf '%s' "$temp_ts" | tr '[:lower:]' '[:upper:]')"
first_admin="$(printf '%s' "$first_admin" | tr '[:lower:]' '[:upper:]')"
[[ -z "$workspace_admin" ]] || initial_builder_validate
[[ "$admin_connection" != "$target_connection" ]] || fail "new target connection must not replace the ADMIN connection"
target_workspace="$workspace"
connection="$target_connection"
[[ -z "$prerequisites" ]] || fail 'Run custom ADMIN prerequisite scripts separately before INITIAL; arbitrary scripts cannot be safely compensated'

log="$(mktemp "${TMPDIR:-/tmp}/mc-deploy-diagnostic.XXXXXX")"
printf 'mode=%s contract=%s bundle_sha256=%s\n' "$mode" "$contract" "$bundle_hash" > "$log"
printf 'registry_run=%s supported_modes=%s\n' "$registry_run_id" "$supported_modes" >> "$log"
progress_number=0
progress_phase() {
  printf '\n=== %s ===\n' "$1"
}
progress_start() {
  local title
  case "$1" in
    bootstrap-zip-spec) title='Prepare release archive support' ;;
    bootstrap-zip-body) title='Install release archive support' ;;
    bootstrap-integrity-spec) title='Prepare release verification' ;;
    bootstrap-integrity-body) title='Install release verification' ;;
    bootstrap-guard-spec) title='Prepare deployment safeguards' ;;
    bootstrap-coordinator-spec) title='Prepare update coordination' ;;
    bootstrap-assets-spec) title='Prepare deployment recovery resources' ;;
    bootstrap-assets-body) title='Install deployment recovery resources' ;;
    bootstrap-storage) title='Create deployment tracking records' ;;
    bootstrap-guard-body) title='Install deployment safeguards' ;;
    bootstrap-coordinator-body) title='Install update coordination' ;;
    bootstrap-verify) title='Verify deployment and recovery tools' ;;
    bootstrap-enable) title='Activate deployment recovery monitoring' ;;
    initial-baseline) title='Record installed object revisions and application version' ;;
    product-storage) title='Install deployment tracking tables and constraints' ;;
    product-code|objects-code) title='Install application objects and deployment tools' ;;
    objects-storage) title='Install ordered application storage objects' ;;
    environment-prerequisites) title='Check required database permissions' ;;
    runtime-guard) title='Prepare installation safeguards' ;;
    deployment-runtime-spec) title='Prepare the deployment tools' ;;
    table-contract) title='Check existing database tables' ;;
    source-removals) title='Remove retired application components' ;;
    01_tables) title='Create application tables' ;;
    01a_table_alters) title='Add missing table columns' ;;
    ensure-migration-registry) title='Prepare database upgrade history' ;;
    migration-*) title='Apply a database upgrade' ;;
    record-migration-*) title='Record the completed database upgrade' ;;
    02_sequences) title='Set up record numbering' ;;
    03_keys_indexes) title='Set up data integrity and search indexes' ;;
    03a_views|artifact-03a_views-*) title='Set up database views' ;;
    04_pkg_specs|artifact-04_pkg_specs-*) title='Prepare application services' ;;
    05_contexts) title='Set up application session settings' ;;
    06_pkg_bodies|artifact-06_pkg_bodies-*) title='Install application services' ;;
    07_procs_funcs|artifact-07_procs_funcs-*) title='Install supporting database routines' ;;
    08_mviews|artifact-08_mviews-*) title='Set up stored data summaries' ;;
    08a_property_graphs|artifact-08a_property_graphs-*) title='Set up data relationships' ;;
    09_triggers|artifact-09_triggers-*) title='Set up automatic data actions' ;;
    90_jobs|artifact-90_jobs-*) title='Install scheduled tasks' ;;
    initial-registry-receipts) title='Verify installed release definitions' ;;
    95_app_config) title='Set up application configuration' ;;
    96_chatbot_seed) title='Install assistant configuration' ;;
    97_semantic_seed) title='Install assistant data definitions' ;;
    deployment-runtime-body) title='Finish installing the deployment tools' ;;
    runtime-dependencies) title='Check deployment tools' ;;
    apex-import) title='Install the APEX application' ;;
    compile-validation) title='Check installed application components' ;;
    initial-access) title='Set up application administrator access' ;;
    *) title='Apply application changes' ;;
  esac
  case "$1" in
    table-contract) progress_phase 'Database installation' ;;
    apex-import) progress_phase 'APEX installation' ;;
    compile-validation) progress_phase 'Final checks' ;;
  esac
  progress_number=$((progress_number + 1))
  progress_started_at=$SECONDS
  printf 'Step %s: %s\n' "$progress_number" "$title"
  printf 'START %s step=%s\n' "$1" "$progress_number" >> "$log"
}
progress_done() {
  local elapsed=$((SECONDS - progress_started_at))
  if [[ "$dry" == Y ]]; then echo '  Preview only; no changes made.'; else printf '  Completed in %ss.\n' "$elapsed"; fi
  printf 'SUCCESS %s elapsed_seconds=%s\n' "$1" "$elapsed" >> "$log"
}

report_sqlcl_failure() {
  local label="$1" status="$2" display_script="$3" output="$4" summary object_context object_count
  echo "FAILED $label" | tee -a "$log" >&2
  echo "ERROR: SQLcl failed during $label (exit status $status)." | tee -a "$log" >&2
  echo "SQL payload: $display_script" | tee -a "$log" >&2
  if [[ -s "$output" ]]; then
    object_context="$(grep -E '^MC_OBJECT ' "$output" || true)"
    if [[ -n "$object_context" ]]; then
      object_count="$(printf '%s\n' "$object_context" | wc -l | tr -d ' ')"
      if [[ "$object_count" -eq 1 ]]; then
        echo "Failing database object: ${object_context#MC_OBJECT }" | tee -a "$log" >&2
      else
        echo "Invalid database objects reported by validation ($object_count):" | tee -a "$log" >&2
        printf '%s\n' "$object_context" | sed 's/^MC_OBJECT /  - /' | tee -a "$log" >&2
      fi
    else
      object_context="$(grep -E "constraint_name = '[^']+'|index_name = '[^']+'|table_name = '[^']+'|CREATE OR REPLACE (PACKAGE BODY|PACKAGE|PROCEDURE|FUNCTION|TRIGGER|VIEW)" "$output" | tail -n 1 || true)"
      [[ -z "$object_context" ]] || echo "Last echoed object selector: $object_context" | tee -a "$log" >&2
    fi
    if grep -q '^MC_COMPILE_ERROR|' "$output"; then
      echo 'Invalid compiled objects:' | tee -a "$log" >&2
      grep -E '^MC_COMPILE_(ERROR|SUMMARY)[|]' "$output" | head -n 20 | tee -a "$log" >&2 || true
    fi
    summary="$(grep -En 'ORA-[0-9]{5}|PLS-[0-9]{5}|SP2-[0-9]+|TNS-[0-9]{5}|Error starting at line|Error at line|Unexpected error' "$output" || true)"
    if [[ -n "$summary" ]]; then
      echo "Oracle/SQLcl error summary:" | tee -a "$log" >&2
      printf '%s\n' "$summary" | tee -a "$log" >&2
    fi
    if grep -Eq 'ORA-20073|ORA-20074' "$output"; then
      echo "Table contract remediation:" | tee -a "$log" >&2
      grep -E 'MC_TABLE_CONTRACT DRIFT|^[[:space:]]+(source|target|expected|actual|hint|action):' "$output" \
        | tail -n 6 | tee -a "$log" >&2 || true
      echo "Inspect the failing target column in USER_TAB_COLS and its USER_CONSTRAINTS/USER_CONS_COLUMNS dependencies. It must match the source metadata shown above, or be handled by an explicit reviewed data-preserving migration." \
        | tee -a "$log" >&2
    fi
    object_context="$(grep '^MC_INITIAL_OBJECT_START|' "$output" | tail -n 1 || true)"
    if [[ -n "$object_context" ]]; then
      printf 'Failed while installing: %s\n' "$(printf '%s' "$object_context" | cut -d '|' -f 5-)" | tee -a "$log" >&2
    fi
    printf '\n----- full SQLcl output: %s -----\n' "$label" >> "$log"
    cat "$output" >> "$log"
    echo "Full SQLcl output saved in the diagnostic log: $log" >&2
  else
    echo "SQLcl returned no diagnostic output." | tee -a "$log" >&2
  fi
}

run_sqlcl_capture() {
  local label="$1" saved_connection="$2" script="$3" display_script="$4" output="$5" sql_status
  shift 5
  if [[ "${MC_INITIAL_LOCK_PID:-}" != '' ]]; then
    initial_lock_check || return 1
    initial_fence_script "$script" || return 1
    script="$MC_FENCED_SCRIPT"
  fi
  if [[ "${MC_WORK_PID:-}" != '' && "$saved_connection" == "$connection" ]]; then
    runtime_work_check || return 1
    local guarded="$tmp/guarded-$(basename "$script")"
    printf '%s\n' 'whenever sqlerror exit failure rollback' 'begin mc_runtime_guard_pkg.acquire_work; end;' / "@$script" 'exit success' > "$guarded"
    script="$guarded"
  fi
  if [[ "${MC_INITIAL_PLAN_PROGRESS:-N}" == Y ]]; then
    # Stream authored progress only; preserve private diagnostics and the
    # fenced/guarded script chosen above. pipefail retains SQLcl failures.
    if sql -s -L -name "$saved_connection" "@$script" "$@" 2>&1 | tee "$output" | awk '
      /^MC_INITIAL_OBJECT_DONE[|]/ {
        split($0,p,"|");
        if (p[2] ~ /^[0-9]+$/ && p[3] ~ /^[0-9]+$/ && (p[2]==1 || p[2]%10==0 || p[2]==p[3])) {
          printf "  Objects: %d / %d\n",p[2],p[3];fflush();
        }
      }
      /^MC_INITIAL_ARCHIVE_VALIDATING$/ { print "Validating release archive before provisioning."; fflush(); }
      /^MC_INITIAL_DEFINITION_INSTALLING$/ { print "Installing definition helpers from the verified archive."; fflush(); }
    '; then return 0; else
      sql_status=$?
      report_sqlcl_failure "$label" "$sql_status" "$display_script" "$output"
      return "$sql_status"
    fi
  fi
  if sql -s -L -name "$saved_connection" "@$script" "$@" > "$output" 2>&1; then
    return 0
  else
    sql_status=$?
    report_sqlcl_failure "$label" "$sql_status" "$display_script" "$output"
    return "$sql_status"
  fi
}

run_privilege_preflight() {
  progress_start environment-prerequisites
  if ! mc_grants_local "${1:-N}"; then
    echo 'FAILED environment-prerequisites' >&2
    return 1
  fi
  progress_done environment-prerequisites
}

run_script() {
  local label="$1" script="$2" runner phase_output display_script
  display_script="${script#"$tmp/content/"}"
  progress_start "$label"
  if [[ "$dry" == Y ]]; then
    echo "DRY-RUN $display_script" >> "$log"
    if [[ "$display_script" == db/ddl/00_source_removals.sql ]]; then
      { grep '^-- MC_REMOVAL_ENTRY ' "$script" || true; } | tee -a "$log"
      echo "DRY-RUN removals listed only; target dependency checks run during apply." | tee -a "$log"
    fi
  else
    runner="$tmp/run-${label//[^A-Za-z0-9_]/_}.sql"
    phase_output="$tmp/output-${label//[^A-Za-z0-9_]/_}.log"
    printf '%s\n' \
      'whenever oserror exit failure rollback' \
      'whenever sqlerror exit sql.sqlcode rollback' \
      'set define off' \
      'set serveroutput on size unlimited' \
      'set verify off' \
      'set echo off' \
      "@$script" \
      'exit success' > "$runner"
    run_sqlcl_capture "$label" "$connection" "$runner" "$display_script" "$phase_output" || return $?
    cat "$phase_output" >> "$log"
  fi
  progress_done "$label"
}

progress_phase 'Preparation'
if [[ "$dry" == N ]]; then initial_connection_absent; fi
initial_bootstrap_preflight
initial_provision
if [[ "$dry" == Y ]]; then
  echo "DRY-RUN: would verify required grants as target before runtime or application DDL."
else
  run_privilege_preflight Y
fi
initial_bootstrap_early

capture_scheduler_state() {
  local output="$1" query="$tmp/read-scheduler-state.sql" raw="$tmp/read-scheduler-state.out"
  printf '%s\n' \
    'whenever oserror exit failure rollback' 'whenever sqlerror exit sql.sqlcode rollback' \
    'set sqlformat default' 'set heading off' 'set feedback off' 'set pages 0' \
    'set verify off' 'set echo off' 'set trimout on' \
    "select rawtohex(utl_raw.cast_to_raw(job_name)) || '|' || enabled from user_scheduler_jobs order by job_name;" \
    'exit success' > "$query"
  run_sqlcl_capture "scheduler state read" "$connection" "$query" "scheduler state query" "$raw" || return $?
  awk -F'|' '/^[[:space:]]*[0-9A-F]+[[:space:]]*\|(TRUE|FALSE)[[:space:]]*$/ {gsub(/[[:space:]]/, "", $0); print}' "$raw" > "$output"
}

verify_initial_scheduler_state() {
  local after="$1" job_hex enabled
  while IFS='|' read -r job_hex enabled; do
    [[ "$enabled" == FALSE ]] || fail "INITIAL left a scheduler job enabled (name hex $job_hex)"
  done < "$after"
}

scheduler_after="$tmp/scheduler-after.txt"

run_scheduler_phase() {
  local label="$1" script="$2"
  run_script "$label" "$script" || return $?
  if [[ "$dry" == N ]]; then
    capture_scheduler_state "$scheduler_after"
    verify_initial_scheduler_state "$scheduler_after"
  fi
}

migration_is_applied() {
  local migration_id="$1" query="$tmp/read-migration-state.sql" raw="$tmp/read-migration-state.out" result
  printf '%s\n' \
    'whenever oserror exit failure rollback' 'whenever sqlerror exit sql.sqlcode rollback' \
    'set sqlformat default' 'set heading off' 'set feedback off' 'set pages 0' \
    'set verify off' 'set echo off' 'set trimout on' \
    "select count(*) from deploy_schema_migrations where migration_id='$migration_id';" \
    'exit success' > "$query"
  run_sqlcl_capture "migration registry read for $migration_id" "$connection" "$query" "migration registry query" "$raw" || return 2
  result="$(awk '/^[[:space:]]*[01][[:space:]]*$/ {gsub(/[[:space:]]/, "", $0); print}' "$raw" | tail -n 1)"
  [[ "$result" == 1 ]] && return 0
  [[ "$result" == 0 ]] && return 1
  return 2
}

record_migration() {
  local migration_id="$1" script="$tmp/record-migration.sql"
  printf '%s\n' \
    "insert into deploy_schema_migrations(migration_id, applied_at, applied_by, bundle_id, notes) values ('$migration_id', systimestamp, user, null, 'contract=$contract bundle_sha256=$bundle_hash');" \
    'commit;' > "$script"
  run_script "record-migration-$migration_id" "$script"
}

run_migrations() {
  local manifest_path="$1" migration migration_status
  local migration_registry="$tmp/ensure-migration-registry.sql"
  cat > "$migration_registry" <<'SQL'
declare
  l_count number;
begin
  select count(*) into l_count from user_tables where table_name='DEPLOY_SCHEMA_MIGRATIONS';
  if l_count <> 1 then
    raise_application_error(-20175,'Canonical migration registry is missing after product storage installation.');
  end if;
end;
/
SQL
  run_script ensure-migration-registry "$migration_registry"
  while IFS= read -r migration || [[ -n "$migration" ]]; do
    migration="${migration%$'\r'}"
    [[ -z "$migration" || "$migration" == \#* ]] && continue
    [[ "$migration" =~ ^[A-Za-z0-9._-]+$ ]] || fail "unsafe migration entry: $migration"
    [[ -f "$tmp/content/db/migrations/$migration" ]] || fail "missing migration payload: $migration"
    if [[ "$dry" == N ]]; then
      if migration_is_applied "$migration"; then
        echo "SKIP migration-$migration (already applied)" >> "$log"
        echo 'Database upgrade already applied; keeping it unchanged.'
        continue
      else
        migration_status=$?
        [[ "$migration_status" -eq 1 ]] || fail "unable to read migration registry for $migration"
      fi
    fi
    run_script "migration-$migration" "$tmp/content/db/migrations/$migration"
    record_migration "$migration"
  done < "$manifest_path"
}

plan_path="$tmp/content/db/deploy/plan.txt"
plan_header_seen="N"
plan_phase_count=0
while IFS='|' read -r phase_kind phase_label phase_path phase_required phase_extra \
      || [[ -n "$phase_kind${phase_label:-}${phase_path:-}${phase_required:-}${phase_extra:-}" ]]; do
  phase_kind="${phase_kind%$'\r'}"
  phase_label="${phase_label%$'\r'}"
  phase_path="${phase_path%$'\r'}"
  phase_required="${phase_required%$'\r'}"
  if [[ "$plan_header_seen" == N ]]; then
    [[ "$phase_kind" == MC_DATABASE_PLAN && "$phase_label" == 3 && -z "${phase_path:-}${phase_required:-}${phase_extra:-}" ]] \
      || fail "unsupported database deployment plan header"
    plan_header_seen="Y"
    echo "Database deployment plan accepted: version=3" >> "$log"
    continue
  fi
  [[ -n "$phase_kind" && -n "$phase_label" && -n "$phase_path" && -n "$phase_required" && -z "${phase_extra:-}" ]] \
    || fail "invalid database deployment plan entry"
  [[ "$phase_label" =~ ^[A-Za-z0-9._-]+$ ]] || fail "unsafe database deployment phase label: $phase_label"
  mc_bundle_safe_member_path "$phase_path" && [[ "$phase_path" == db/* ]] \
    || fail "unsafe database deployment phase path: $phase_path"
  [[ "$phase_required" =~ ^(Y|N)$ ]] || fail "invalid required flag for database deployment phase: $phase_label"
  [[ -f "$tmp/content/$phase_path" ]] || {
    [[ "$phase_required" == N ]] && echo "SKIP $phase_label (optional payload absent)" | tee -a "$log" && continue
    fail "required database deployment phase payload is missing: $phase_path"
  }
  plan_phase_count=$((plan_phase_count + 1))
  echo "PLAN $plan_phase_count $phase_label kind=$phase_kind path=$phase_path required=$phase_required" >> "$log"
  case "$phase_kind" in
    PREFLIGHT_GRANTS)
      [[ "$phase_path" == db/preflight/required_privileges.sql ]] \
        || fail "unsupported privilege preflight path: $phase_path"
      if [[ "$dry" == Y ]]; then
        echo "DRY-RUN: would verify source-required direct grants after creating the target schema." | tee -a "$log"
      else
        run_privilege_preflight
      fi
      ;;
    REMOVALS|SCRIPT)
      run_script "$phase_label" "$tmp/content/$phase_path"
      ;;
    MIGRATIONS)
      [[ "$phase_path" == db/migrations/manifest.txt ]] \
        || fail "unsupported migrations manifest path: $phase_path"
      run_migrations "$tmp/content/$phase_path"
      ;;
    OBJECTS)
      [[ "$phase_path" == db/deploy/product-plan.txt ]] || fail 'Unsupported ordered object plan'
      case "$phase_label" in
        objects-storage)
          initial_product_plan APPLICATION_STORAGE
          initial_bootstrap_storage
          ;;
        objects-code) initial_artifact_objects ;;
        *) fail 'Unknown ordered object stage' ;;
      esac
      ;;
    SCHEDULER)
      run_scheduler_phase "$phase_label" "$tmp/content/$phase_path"
      ;;
    *)
      fail "unsupported database deployment phase kind: $phase_kind"
      ;;
  esac
done < "$plan_path"
[[ "$plan_header_seen" == Y && "$plan_phase_count" -eq 9 ]] \
  || fail "incomplete database deployment plan: expected 9 phases, found $plan_phase_count"
echo "Database deployment plan complete: phases=$plan_phase_count" >> "$log"

initial_bootstrap_verify

if [[ "$dry" == N ]]; then
  if [[ "$apex_offset" == AUTO ]]; then
    offset_call='apex_application_install.generate_offset;'
  else
    offset_call="apex_application_install.set_offset($apex_offset);"
  fi
  import_sql="$tmp/import.sql"
  cat > "$import_sql" <<SQL
whenever oserror exit failure rollback
whenever sqlerror exit sql.sqlcode rollback
set define off
set verify off
set serveroutput on size unlimited
prompt MC_APEX WORKSPACE workspace=$target_workspace
begin
  apex_util.set_security_group_id(apex_util.find_security_group_id(p_workspace => '$target_workspace'));
end;
/
prompt MC_APEX INSTALL target_application_id=$target_id
declare n number;
begin
  select count(*) into n from apex_applications where application_id=$target_id;
  if n<>0 then raise_application_error(-20080,'INITIAL refuses to replace an existing application.'); end if;
end;
/
begin
  apex_application_install.set_schema(user);
  apex_application_install.set_application_id($target_id);
  $offset_call
end;
/
prompt MC_APEX IMPORT apex/f1200.sql
@$tmp/content/apex/f1200.sql
prompt MC_APEX AUTHENTICATION initialize local accounts
begin
  apex_application_admin.set_authentication_scheme(p_application_id=>$target_id,p_name=>'Oracle APEX Accounts');
  merge into app_config t using(select 'l_auth_scheme_name' k,'Oracle APEX Accounts' v from dual) s on(t.config_key=s.k)
    when matched then update set t.config_value=s.v when not matched then insert(config_key,config_value) values(s.k,s.v);
end;
/
prompt MC_APEX PERSIST target identity
begin
  merge into app_config t using (select 'APEX_APP_ID' k, '$target_id' v from dual) s on (t.config_key=s.k) when matched then update set t.config_value=s.v when not matched then insert (config_key,config_value) values (s.k,s.v);
  merge into app_config t using (select 'APEX_WORKSPACE_NAME' k, '$target_workspace' v from dual) s on (t.config_key=s.k) when matched then update set t.config_value=s.v when not matched then insert (config_key,config_value) values (s.k,s.v);
  merge into app_config t using (select 'APEX_APP_OFFSET' k, to_char(apex_application_install.get_offset) v from dual) s on (t.config_key=s.k) when matched then update set t.config_value=s.v when not matched then insert (config_key,config_value) values (s.k,s.v);
  commit;
end;
/
declare receipt varchar2(64);
begin
  select rawtohex(standard_hash(to_char(created_on,'YYYYMMDDHH24MISS')||'|'||to_char(last_updated_on,'YYYYMMDDHH24MISS')||'|'||owner||'|'||to_char(workspace_id,'TM9'),'SHA256')) into receipt
   from apex_applications where application_id=$target_id and owner=user;
  dbms_output.put_line('MC_INITIAL_APP|'||receipt);
end;
/
exit success
SQL
  import_output="$tmp/apex-import.out"
  initial_event INTENT_APP
  progress_start apex-import
  run_sqlcl_capture "APEX application import" "$connection" "$import_sql" "apex/f1200.sql" "$import_output" || exit $?
  progress_done apex-import
  app_receipt="$(sed -n 's/^MC_INITIAL_APP|//p' "$import_output" | tr -d '\r')"
  [[ "$app_receipt" =~ ^[0-9A-F]{64}$ ]] || fail 'APEX import ownership receipt missing'
  initial_event "APP|$app_receipt"
  cat "$import_output" >> "$log"

  validate_sql="$tmp/compile-validate.sql"
  cat > "$validate_sql" <<'SQL'
whenever oserror exit failure rollback
whenever sqlerror exit sql.sqlcode rollback
set define off
set verify off
set serveroutput on size unlimited
begin
  dbms_utility.compile_schema(user, false);
end;
/
declare
  l_warnings number := 0;
  l_fatal number := 0;
  l_severity varchar2(10);
begin
  for o in (
    select object_name, object_type
      from user_objects
     where status = 'INVALID'
       and object_type in ('PACKAGE','PACKAGE BODY','PROCEDURE','FUNCTION','VIEW','TRIGGER')
     order by object_type, object_name
  ) loop
    if o.object_type = 'TRIGGER'
       or (o.object_type in ('PACKAGE','PACKAGE BODY')
           and o.object_name in ('DEPLOY_MGR_PKG','APPLICATION_BUNDLES_AJAX_PKG'))
    then
      l_severity := 'FATAL';
      l_fatal := l_fatal + 1;
    else
      l_severity := 'WARNING';
      l_warnings := l_warnings + 1;
    end if;

    for e in (
      select line, position, text
        from user_errors
       where name = o.object_name
         and type = o.object_type
       order by sequence
    ) loop
      dbms_output.put_line(
        'MC_COMPILE_ERROR|severity=' || l_severity ||
        '|type=' || replace(o.object_type, ' ', '_') ||
        '|name="' || replace(o.object_name, '"', '""') || '"' ||
        '|line=' || e.line || '|position=' || e.position ||
        '|message="' || replace(replace(replace(e.text, '"', '""'), chr(10), ' '), chr(13), ' ') || '"'
      );
    end loop;
  end loop;
  dbms_output.put_line('MC_COMPILE_SUMMARY|warnings=' || l_warnings || '|fatal=' || l_fatal);
  if l_fatal > 0 then
    raise_application_error(-20071, 'Fatal invalid database objects after compile: ' || l_fatal || '. See MC_COMPILE_ERROR details above.');
  end if;
end;
/
exit success
SQL
  validate_output="$tmp/compile-validate.out"
  progress_start compile-validation
  run_sqlcl_capture "post-import database compile validation" "$connection" "$validate_sql" "generated post-import validation" "$validate_output" || exit $?
  progress_done compile-validation
  cat "$validate_output" >> "$log"
  compile_warnings="$(sed -n 's/^MC_COMPILE_SUMMARY|warnings=\([0-9][0-9]*\)|fatal=0.*$/\1/p' "$validate_output" | tail -n 1)"
  compile_warnings="${compile_warnings:-0}"
  if [[ "$compile_warnings" -gt 0 ]]; then
    grep -E '^MC_COMPILE_(ERROR|SUMMARY)\|' "$validate_output" || true
    warning_log="$(mktemp "${TMPDIR:-/tmp}/mc-deploy-warning.XXXXXX")"
    cp "$log" "$warning_log"
  fi
fi

initial_access
if [[ "$dry" == N ]]; then
  initial_verify_shared || fail 'Shared state verification failed'
  initial_bootstrap_enable
  initial_registry_receipts || fail 'Installed release verification failed; INITIAL cleanup is required'
  initial_connection_backup_finish N || echo 'Installation succeeded; saved connection backup retained for manual removal.' >&2
  initial_event SUCCEEDED
  MC_INITIAL_ACTIVE=N
fi

if [[ "$dry" == Y ]]; then
  echo 'INITIAL preview completed. No target changes were made.'
elif [[ "${compile_warnings:-0}" -gt 0 ]]; then
  echo "SUCCESS WITH WARNINGS: INITIAL completed with $compile_warnings invalid non-critical database object(s). Review: $warning_log"
else
  echo 'Installation completed.'
fi
if [[ "$dry" == N ]]; then
  echo 'Application schedules remain disabled. Internal deployment recovery monitoring is enabled.'
  echo "Sign in to application $target_id as $first_admin using the local application password, then complete the configuration wizard."
fi
